INSERT INTO `adhkaar` (`id`, `category_id`, `title`, `title_sw`, `arabic_text`, `transliteration`, `translation_en`, `translation_sw`, `virtue`, `virtue_sw`, `repeat_count`, `source_reference`, `audio_path`, `audio_url`, `video_path`, `video_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Alhamdullillah', 'Alhamdulillah', 'الْحَمْدُ لِله وَحْدَهُ ، وَالصَّلَاةُ وَالسَلَامُ عَلَى مَنْ لَا نَبِيَّ بَعْدَهُ', 'Alhamdulillahi wahdah, wassalaatu wassalaamu a\'laa man la nabiyya ba\'adah.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', '🍁 Anas (Radhiya Allaahu ´anh) amesimulia kwamba Mtume ﷺ amesema: ”Kukaa pamoja na watu wanaomdhukuru Allaah (Ta´ala) kuanzia swalah ya Fajr mpaka kuchomoza jua kunapendeza zaidi kwangu kuliko kuacha huru watu wanne miongoni mwa wana wa Ismaa’iyl. Na kukaa pamoja na watu wanaomdhukuru Allaah kuanzia swalah ya ´Aswr mpaka kuzama jua kunapendeza zaidi kwangu mimi kuliko kuwaacha huru watu wanne.', '🍁 Anas (Radhiya Allaahu ´anh) amesimulia kwamba Mtume ﷺ amesema: ”Kukaa pamoja na watu wanaomdhukuru Allaah (Ta´ala) kuanzia swalah ya Fajr mpaka kuchomoza jua kunapendeza zaidi kwangu kuliko kuacha huru watu wanne miongoni mwa wana wa Ismaa’iyl. Na kukaa pamoja na watu wanaomdhukuru Allaah kuanzia swalah ya ´Aswr mpaka kuzama jua kunapendeza zaidi kwangu mimi kuliko kuwaacha huru watu wanne.\r\n\r\n✍️ Abu Dawuud (3667) na ni nzuri kwa mujibu wa al-Albaaniy katika ”Swahiyh Abiy Daawuud (02/698).', 1, '', NULL, NULL, NULL, NULL, 1, 1, '2026-09-01 23:33:36', '2026-09-06 07:12:14'),
(2, 1, 'Kuomba hifadhi', 'Kuomba hifadhi', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', '\'A \'oothu billaahi minash-Shaytaanir-rajeem', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', '', '', 1, '', NULL, NULL, NULL, NULL, 2, 1, '2026-09-01 23:45:29', '2026-09-06 07:14:47'),
(3, 1, 'AAYATUL-KURSEE {02:255}', 'AAYATUL-KURSEE {02:255}', 'اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allaahu laa \'ilaaha \'illaa Huwal-Hayyul-Qayyoom, laa ta\'khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-\'ardh, man thai-lathee yashfa\'u \'indahu \'illaa bi\'ithnih, ya\'lamu maa bayna \'aydeehim wa maa khalfahum, wa laa yuheetoona bishay\'im-min \'ilmihi \'illaa bimaa shaa\'a, wasi\'a kursiyyuhus samaawaati wal\'ardh, wa laa ya\'ooduhu hifdhuhumaa, wa Huwal- \'Aliyyul- \'Adheem.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', '🍁 ”Atakayeisoma kunapoingia asubuhi itamlinda na majini mpaka itakapofika jioni. Na atakayeisoma kunapoingia jioni atalindwa na majini mpaka asubuhi.”\r\n\r\n✍️ al-Haakim (01/562) na ni Swahiyh kwa mujibu wa al-Albaaniy katika ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273). Ameiegemeza kwa an-Nasaa´iy na at-Twabaraaniy ambapo akasema: ”Cheni ya wapokezi ya at-Twabaraaniy ni nzuri.”', '🍁 ”Atakayeisoma kunapoingia asubuhi itamlinda na majini mpaka itakapofika jioni. Na atakayeisoma kunapoingia jioni atalindwa na majini mpaka asubuhi.”\r\n\r\n✍️ al-Haakim (01/562) na ni Swahiyh kwa mujibu wa al-Albaaniy katika ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273). Ameiegemeza kwa an-Nasaa´iy na at-Twabaraaniy ambapo akasema: ”Cheni ya wapokezi ya at-Twabaraaniy ni nzuri.”', 1, '', NULL, NULL, NULL, NULL, 3, 1, '2026-09-01 23:56:38', '2026-09-01 23:56:38'),
(4, 1, 'SURAH AL-IKHLAAS {112:01-04}', 'SURAH AL-IKHLAAS {112:01-04}', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ', 'Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu \'Ahad ۞ Allaahus-Samad ۞ Lam yalid wa lam yoolad ۞ Wa lam yakun lahu kufuwan \'ahad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', '', '', 1, '', NULL, NULL, NULL, NULL, 4, 1, '2026-09-01 23:57:51', '2026-09-01 23:57:51'),
(5, 1, 'SURAH AL-FALAQ {113:01-05}.', 'SURAH AL-FALAQ {113:01-05}.', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ۞', 'Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbil-falaq ۞ Min sharri ma khalaq ۞Wa min sharri ghaasiqin \'ithaa waqab ۞ Wa min sharrin-naffaathaati fil-\'uqad ۞ Wa min sharri haasidin \'ithaa hasad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', '', '', 1, '', NULL, NULL, NULL, NULL, 5, 1, '2026-09-02 00:00:05', '2026-09-02 00:00:39'),
(6, 1, 'SURAH AN-NAAS {114:01-06}.', 'SURAH AN-NAAS {114:01-06}.', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ', '✨Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbin-naas ۞ Malikin-naas. \'Ilaahin-naas ۞ Min sharril-waswaasil-khannaas ۞ Allathee yuwaswisu fee sudoorin-naas ۞ Minal-jinnati wannaas.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', '🍁 \"Atakayezisoma mara tatu kunapoingia asubuhi na jioni, basi zitamtosheleza kutokamana na kila shari.”\r\n\r\n✍️ Abu Daawuuud (04/322), at-Tirmidhiy (05/567). Tazama ”Swahiyh-ut-Tirmidhiy” (03/182).', '🍁 \"Atakayezisoma mara tatu kunapoingia asubuhi na jioni, basi zitamtosheleza kutokamana na kila shari.”\r\n\r\n✍️ Abu Daawuuud (04/322), at-Tirmidhiy (05/567). Tazama ”Swahiyh-ut-Tirmidhiy” (03/182).', 1, '', NULL, NULL, NULL, NULL, 6, 1, '2026-09-02 00:02:14', '2026-09-02 00:05:12'),
(7, 1, 'Dua', 'Dua', '🍃⚪▫️أَمْسَيْـنا وَأَمْسـى المـلكُ لله وَالحَمدُ لِله ، لا إلهَ إلاّ اللّهُ وَحدَهُ لا شَريكَ لهُ، لهُ المُـلكُ ولهُ الحَمْـد، وهُوَ على كلّ شَيءٍ قدير ، رَبِّ أسْـأَلُـكَ خَـيرَ ما في هـذهِ اللَّـيْلَةِ وَخَـيرَ ما بَعْـدَهـا ، وَأَعـوذُ بِكَ مِنْ شَـرِّ هـذهِ اللَّـيْلةِ وَشَرِّ ما بَعْـدَهـا ، رَبِّ أَعـوذُبِكَ مِنَ الْكَسَـلِ وَسـوءِ الْكِـبَر ، رَبِّ أَعـوذُبِكَ مِنْ عَـذابٍ في النّـارِ وَعَـذابٍ في القَـبْر', '🍃✨\'Amsaynaa wa \'amsal-mulku lillaahi walhamdu lillaahi, laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa \'alaa kulli shay\'in Qadeer. Rabbi \'as\'aluka khayra maa fee haathihil-laylati wa khayra maa ba\'daha wa \'a\'oothu bika min sharri maa fee haathihil-laylati wa sharri maa ba\'daha, Rabbi \'a\'oothu bika minal-kasali, wa soo\'il-kibari, Rabbi \'a\'oothu bika min \'athaabin fin-naari wa \'athaabin fil-qabri.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya usiku wa leo, na kheri ya baada yake, na najilinda Kwako kutokamana na shari ya usiku wa leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu, na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya usiku wa leo, na kheri ya baada yake, na najilinda Kwako kutokamana na shari ya usiku wa leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu, na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', '✍️ Muslim (04/2088).', '✍️ Muslim (04/2088).', 1, '', NULL, NULL, NULL, NULL, 7, 1, '2026-09-02 00:04:19', '2026-09-06 21:58:24'),
(8, 1, 'Dua2', 'Dua2', 'اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ المَصِیر', 'Allaahumma bika \'amsaynaa, wa bika \'asbahnaa, wa bika nahyaa, wa bika namootu wa \'ilaykal-maseer.', 'Ewe Mwenyezi Mungu kwa ajili yako tumefika jioni, na kwa ajili yako tumefika asubuhi, na kwa ajili yako tuko hai, na kwa ajili yako tutakufa na ni kwako tu marejeo.', 'Ewe Mwenyezi Mungu kwa ajili yako tumefika jioni, na kwa ajili yako tumefika asubuhi, na kwa ajili yako tuko hai, na kwa ajili yako tutakufa na ni kwako tu marejeo.', '✍️ at-Tirmidhiy (05/466). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', '✍️ at-Tirmidhiy (05/466). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', 1, '', NULL, NULL, NULL, NULL, 8, 1, '2026-09-06 07:20:22', '2026-09-06 07:27:56'),
(9, 1, 'Dua3', 'Dua3', '🍃⚪▫️اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'Anta Rabbee laa \'ilaaha \'illaa \'Anta, khalaqtanee wa \'anaa \'abduka, wa \'anaa \'alaa \'ahdika wa wa\'dika mas-tata\'tu, \'a\'oothu bika min sharri maa sana\'tu, \'aboo\'u laka bini\'matika \'alayya, wa \'aboo\'u bithanbee faghfir lee fa\'innahu laa yaghfiruth-thunooba \'illaa \'Anta.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', '🍁 ”Atakayeyasema mchana hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia jioni, basi ataingia Peponi. Atakayeyasema usiku hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia asubuhi, basi ataingia Peponi.”\r\n\r\n✍️ al-Bukhaariy (07/150).', '🍁 ”Atakayeyasema mchana hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia jioni, basi ataingia Peponi. Atakayeyasema usiku hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia asubuhi, basi ataingia Peponi.”\r\n\r\n✍️ al-Bukhaariy (07/150).', 1, '', NULL, NULL, NULL, NULL, 9, 1, '2026-09-06 07:33:36', '2026-09-06 07:33:36'),
(10, 1, 'Dua4', 'Dua4', '🍃⚪▫️اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ', '🍃✨Allaahumma \'innee \'amsaytu \'ush-hiduka wa \'ush-hidu hamalata \'arshika, wa malaa\'ikataka wajamee\'a khalqika, \'annaka \'Antallaahu laa \'ilaaha \'illaa \'Anta wahdaka laa shareeka laka, wa \'anna Muhammadan \'abduka wa Rasooluka.(×04)', 'Ee Allaah! Hakika mimi nimefika jioni; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 'Ee Allaah! Hakika mimi nimefika jioni; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', '🍁 \"Atakayeyasema haya mara nne pindi anapoamka asubuhi au inapoingia jioni, basi Allaah atamuepusha na Moto.” \r\n✍️ Abu Daawuud (04/317), al-Bukhaariy katika ”Aadab-ul-Mufrad (1201), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (09), Ibn-us-Sunniy (70). Shaykh Ibn Baaz ameifanya cheni ya wapokezi ya an-Nasaa´iy na Abu Daawuud kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 23.', '🍁 \"Atakayeyasema haya mara nne pindi anapoamka asubuhi au inapoingia jioni, basi Allaah atamuepusha na Moto.” \r\n✍️ Abu Daawuud (04/317), al-Bukhaariy katika ”Aadab-ul-Mufrad (1201), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (09), Ibn-us-Sunniy (70). Shaykh Ibn Baaz ameifanya cheni ya wapokezi ya an-Nasaa´iy na Abu Daawuud kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 23.', 1, '', NULL, NULL, NULL, NULL, 10, 1, '2026-09-06 07:35:29', '2026-09-06 07:35:29'),
(11, 1, 'Dua5', 'Dua5', '🍃⚪▫️اللَّهُمَّ مَا أَمْسٰی بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', '🍃✨Allaahumma maa \'amsa bee min ni\'matin \'aw bi\'ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.', 'Ewe Mwenyezi Mungu sikuamka na neema yoyote au kati ya kiumbe chako chochote, na neema ila inatoka kwako, hali ya kuwa peke yako huna mshirika wako, ni zako sifa njema na ni zako shukrani.', 'Ewe Mwenyezi Mungu sikuamka na neema yoyote au kati ya kiumbe chako chochote, na neema ila inatoka kwako, hali ya kuwa peke yako huna mshirika wako, ni zako sifa njema na ni zako shukrani.', '🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n✍️ Abu Daawuud (04/318), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah (07), Ibn-us-Sunniy (41), Ibn Hibbaan katika “Mawaarid” (2361) Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 24.', '🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n\r\n✍️ Abu Daawuud (04/318), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah (07), Ibn-us-Sunniy (41), Ibn Hibbaan katika “Mawaarid” (2361) Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 24.', 1, '', NULL, NULL, NULL, NULL, 11, 1, '2026-09-06 07:37:16', '2026-09-06 07:37:16'),
(12, 1, 'Dua6', 'Dua6', '🍃⚪▫️اللَّهُمَّ عَافِنِي فِي بَدََنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفرِ، وَالْفَقْرِ، وَ أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'aafinee fee badanee, Allaahumma \'aafinee fee sam\'ee, Allaahumma \'aafinee fee basaree, laa \'ilaaha \'illaa \'Anta. Allaahumma \'innee \'a\'oothu bika minal-kufri, walfaqri, wa \'a\'oothu bika min \'athaabil-qabri, laa \'ilaaha \'illaa \'Anta.(×03)', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', '✍️ Abu Daawuud (04/324), Ahmad (05/42), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (22), Ibn-us-Sunniy (69) na al-Bukhaariy katika ”Aadab-ul-Mufrad”. ´Allaamah Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika “Tuhfat-ul-Akhyaaar”, uk. 26.', '✍️ Abu Daawuud (04/324), Ahmad (05/42), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (22), Ibn-us-Sunniy (69) na al-Bukhaariy katika ”Aadab-ul-Mufrad”. ´Allaamah Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika “Tuhfat-ul-Akhyaaar”, uk. 26.', 3, '', NULL, NULL, NULL, NULL, 12, 1, '2026-09-06 07:38:36', '2026-09-06 07:38:36'),
(13, 1, 'Dua7', 'Dua7', '🍃⚪▫️حَسْبِيَ اللهُ لَآ إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', '🍃✨Hasbiyallaahu laa \'ilaaha \'illaa Huwa \'alayhi tawakkaltu wa Huwa Rabbul-\'Arshil-\'Adheem(×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', '🍁 ”Atakayeyasema mara saba pindi kunapopambazuka na kunapoinga jioni, basi itamtosheleza katika mambo yake yanayomtia hamu ya dunia na Aakhirah.”\r\n\r\n✍️ Ibn-us-Sunniy (71) kutoka kwa Mtume (Swalla Allaahu ´alayhi wa sallam), Abu Daawuud (04/321) kutoka kwa Swahabah. Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameisahihisha cheni ya wapokezi wake. Tazama ”Zaad-ul-Ma’aad (02/376).', '🍁 ”Atakayeyasema mara saba pindi kunapopambazuka na kunapoinga jioni, basi itamtosheleza katika mambo yake yanayomtia hamu ya dunia na Aakhirah.”\r\n\r\n✍️ Ibn-us-Sunniy (71) kutoka kwa Mtume (Swalla Allaahu ´alayhi wa sallam), Abu Daawuud (04/321) kutoka kwa Swahabah. Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameisahihisha cheni ya wapokezi wake. Tazama ”Zaad-ul-Ma’aad (02/376).', 7, '', NULL, NULL, NULL, NULL, 13, 1, '2026-09-06 07:40:09', '2026-09-06 07:49:13'),
(14, 1, 'Dua8', 'Dua8', '🍃⚪▫️اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', '🍃✨Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fid-dunyaa wal\'aakhirati, Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fee deenee wa dunyaaya wa \'ahlee, wa maalee , Allaahum-mastur \'awraatee, wa \'aamin raw\'aatee, Allaahum-mahfadhnee min bayni yadayya, wa min khalfee, wa \'an yameenee, wa \'an shimaalee, wa min fawqee, wa \'a\'oothu bi\'adhamatika \'an \'ughtaala min tahtee.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', '✍️ Abu Daawuud (5074) na Ibn Maajah (3871). Tazama ”Swahiyh Ibn Maajah (02/332).', '✍️ Abu Daawuud (5074) na Ibn Maajah (3871). Tazama ”Swahiyh Ibn Maajah (02/332).', 1, '', NULL, NULL, NULL, NULL, 14, 1, '2026-09-06 07:42:08', '2026-09-06 07:49:29'),
(15, 1, 'Dua9', 'Dua9', '🍃⚪▫️اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّماوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', '🍃✨Allaahumma \'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal\'ardhi, Rabba kulli shay \'in wa maleekahu, \'ash-hadu \'an laa \'ilaaha \'illaa \'Anta, \'a\'oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa \'an \'aqtarifa \'alaa nafsee soo\'an, \'aw \'ajurrahu \'ilaa Muslimin.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', '✍️ at-Tirmidhiy (3392) na Abu Daawuud (5067). Swahiyh-ut-Tirmidhiy (03/142).', '✍️ at-Tirmidhiy (3392) na Abu Daawuud (5067). Swahiyh-ut-Tirmidhiy (03/142).', 1, '', NULL, NULL, NULL, NULL, 15, 1, '2026-09-06 07:43:10', '2026-09-06 07:49:44'),
(17, 1, 'Dua10', 'Dua10', '🍃⚪▫️بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', '🍃✨Bismillaahil-lathee laa yadhurru ma\'as-mihi shay\'un fil-\'ardhi wa laa fis-samaa\'i wa Huwas-Samee \'ul- \'Aleem .(×03)', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', '🍁 “Atakayeyasema mara tatu kunapoingia asubuhi na jioni, basi hatodhuriwa na chochote.”\r\n✍️ Abu Daawuud (04/323), at-Tirmidhiy (05/465), Ibn Maajah (3869) na Ahmad. Tazama “Swahiyh Ibn Maajah (02/332). ‘Allaamah Ibn Baaz ameifanya cheni ya wapokezi wake kuwa nzuri katika “Tuhfat-ul-Akhyaar”, uk. 39.', '🍁 “Atakayeyasema mara tatu kunapoingia asubuhi na jioni, basi hatodhuriwa na chochote.”\r\n\r\n✍️ Abu Daawuud (04/323), at-Tirmidhiy (05/465), Ibn Maajah (3869) na Ahmad. Tazama “Swahiyh Ibn Maajah (02/332). ‘Allaamah Ibn Baaz ameifanya cheni ya wapokezi wake kuwa nzuri katika “Tuhfat-ul-Akhyaar”, uk. 39.', 3, '', NULL, NULL, NULL, NULL, 16, 1, '2026-09-06 07:45:04', '2026-09-06 07:49:57'),
(18, 1, 'Dua11', 'Dua11', '🍃⚪▫️رَضِيتُ باللهِ رَبَّاً، وَبِالْإِسْلَامِ دِيناً، وَبِمُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ نَبِيَّاً', '🍃✨Radheetu billaahi Rabban, wa bil-\'Islaami deenan, wa bi-Muhammadin (sallallaahu \'alayhi wa sallama) Nabiyyan.(×03)', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', '🍁 \"Atakayeyasema mara tatu kutapoingia asubuhi na mara tatu kutapoingia jioni, basi imekuwa ni haki kwa Allaah kumridhia siku ya Qiyaamah.”\r\n\r\n✍️ Ahmad (04/337), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (04), Ibn-us-Sunniy (68), Abu Daawuud (04/318) na at-Tirmidhiy (05/465).  Ibn Baaz ameifanya kuwa nzuri katika “Tuhfat-ul-Akhyaa, uk. 39.', '🍁 \"Atakayeyasema mara tatu kutapoingia asubuhi na mara tatu kutapoingia jioni, basi imekuwa ni haki kwa Allaah kumridhia siku ya Qiyaamah.”\r\n✍️ Ahmad (04/337), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (04), Ibn-us-Sunniy (68), Abu Daawuud (04/318) na at-Tirmidhiy (05/465).  Ibn Baaz ameifanya kuwa nzuri katika “Tuhfat-ul-Akhyaa, uk. 39.', 3, '', NULL, NULL, NULL, NULL, 17, 1, '2026-09-06 07:46:48', '2026-09-06 07:50:24'),
(19, 1, 'Dua12', 'Dua12', '🍃⚪▫️يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', '🍃✨Yaa Hayyu yaa Qayyoomu birahmatika \'astagheethu \'aslih lee sha\'nee kullahu wa laa takilnee \'ilaa nafsee tarfata \'aynin.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', '✍️ al-Haakim na ameisahihisha ambapo adh-Dhahabiy akaafikiana naye. Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', '✍️ al-Haakim na ameisahihisha ambapo adh-Dhahabiy akaafikiana naye. Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', 1, '', NULL, NULL, NULL, NULL, 18, 1, '2026-09-06 07:52:20', '2026-09-06 07:52:20'),
(20, 1, 'Dua13', 'Dua13', '🍃⚪▫️أَمْسَيْنا وَأَمْسى الْمُلْكُ للہ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ  خَيْرَ  هـَذِهِ اللَّيْلَةِ  فَتْحَهَا، وَنَصْرَهَا وَنُوْرَها، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيْهَا وَشَرِّ مَا بَعْدَهَا', '🍃✨\'Amsayna wa \'amsal-mulku lillaahi Rabbil-\'aalameen, Allaahumma \'innee \'as\'aluka khayra haathihil-laylati: Fathaha wa nasraha wa nooraha, wa barakataha, wa hudaaha, wa\'a\'oothu bika min sharri maafeeha wa sharri maa ba\'daha.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', '✍️ Abu Daawuud (04/322). Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameifanya cheni ya wapokezi wake kuwa nzuri wakati wa kuihakiki ”Zaad-ul-Ma’aad (02/273).', '✍️ Abu Daawuud (04/322). Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameifanya cheni ya wapokezi wake kuwa nzuri wakati wa kuihakiki ”Zaad-ul-Ma’aad (02/273).', 1, '', NULL, NULL, NULL, NULL, 19, 1, '2026-09-06 07:54:00', '2026-09-06 07:54:00'),
(21, 1, 'Dua14', 'Dua14', 'أَمْسَيْنا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفَاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ', '🍃✨Amsaynaa \'alaa fitratil-\'Islaami wa \'alaa kalimatil-\'ikhlaasi, wa \'alaa deeni Nabiyyinaa Muhammadin (sallallaahu \'alayhi wa sallama), wa \'alaa millati \'abeenaa \'Ibraaheema, haneefan Musliman wa maa kaana minal-mushrikeen.', 'Tumeingia jioni na maumbile ya kiislamu, na neno la ikhlasi, na dini ya Mtume wetu Muhammad(ﷺ) na mila (dini) ya Baba yetu Ibrahim iliyo sawa hali ya kuwa muislamu wala hakuwa ni mwenye kumshirikisha Mwenyezi Mungu.', 'Tumeingia jioni na maumbile ya kiislamu, na neno la ikhlasi, na dini ya Mtume wetu Muhammad(ﷺ) na mila (dini) ya Baba yetu Ibrahim iliyo sawa hali ya kuwa muislamu wala hakuwa ni mwenye kumshirikisha Mwenyezi Mungu.', '✍️ Ahmad (03/406, 407) na Ibn-us-Sunny katika ”‘Amal-ul-Yawm wal-Laylah (34). Tazama ”Swahiyh-ul-Jaamiy’” (04/209).', '✍️ Ahmad (03/406, 407) na Ibn-us-Sunny katika ”‘Amal-ul-Yawm wal-Laylah (34). Tazama ”Swahiyh-ul-Jaamiy’” (04/209).', 1, '', NULL, NULL, NULL, NULL, 20, 1, '2026-09-06 07:54:57', '2026-09-06 07:54:57'),
(25, 1, 'Dua15', 'Dua15', '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ', '🍃✨Subhaanallaahi wa bihamdihi.(×100)', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', '🍁 ”Atakayeyasema mara mia kunapopambazuka na kunapoingia jioni, basi hakuna yeyote siku ya Qiyaamah atakayekuja na kitu bora kuliko alichokuja nacho yeye isipokuwa aliyesema mfano wa haya au akazidisha.”\r\n\r\n✍️ Muslim (04/2071).', '🍁 ”Atakayeyasema mara mia kunapopambazuka na kunapoingia jioni, basi hakuna yeyote siku ya Qiyaamah atakayekuja na kitu bora kuliko alichokuja nacho yeye isipokuwa aliyesema mfano wa haya au akazidisha.”\r\n\r\n✍️ Muslim (04/2071).', 100, '', NULL, NULL, NULL, NULL, 21, 1, '2026-09-06 08:02:20', '2026-09-06 08:04:19'),
(26, 1, 'Dua16', 'Dua16', '🍃⚪▫️لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '🍃✨Laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa \'alaa kulli shay\'in Qadeer.(×10)', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', '✍️ ¹an-Nasaa´y katika ”‘Amal-ul-Yawm wal-Laylah” (24). Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/272) na ”Tuhfat-ul-Akhyaar”, uk. 255 ya Ibn Baaz. Pia tazama fadhilah zake katika ukurasa wa 146 Hadiyth nambari. 255.\r\n\r\n✍️ ²Abu Daawuud (04/319), Ibn Maajah (3867) na Ahmad (04/60). Tazama ”Swahiyh ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/270) na ”Swahiyh Abiy Daawuud” (03/957).', '✍️ ¹an-Nasaa´y katika ”‘Amal-ul-Yawm wal-Laylah” (24). Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/272) na ”Tuhfat-ul-Akhyaar”, uk. 255 ya Ibn Baaz. Pia tazama fadhilah zake katika ukurasa wa 146 Hadiyth nambari. 255.\r\n\r\n✍️ ²Abu Daawuud (04/319), Ibn Maajah (3867) na Ahmad (04/60). Tazama ”Swahiyh ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/270) na ”Swahiyh Abiy Daawuud” (03/957).', 10, '', NULL, NULL, NULL, NULL, 22, 1, '2026-09-06 08:07:25', '2026-09-06 08:07:25'),
(27, 1, 'Dua17', 'Dua17', '🍃⚪▫️أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ', '🍃✨\'Astaghfirullaaha wa \'atoobu \'ilayhi.(×100)', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', '✍️ al-Bukhaariy pamoja na al-Fath (11/101) na Muslim (4/2075).', '✍️ al-Bukhaariy pamoja na al-Fath (11/101) na Muslim (4/2075).', 100, '', NULL, NULL, NULL, NULL, 23, 1, '2026-09-06 08:09:36', '2026-09-06 08:10:05'),
(28, 1, 'Dua18', 'Dua18', '🍃⚪▫️أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', '🍃✨A\'oothu bikalimaatil-laahit-taammaati min sharri maa khalaqa.(×03)', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', '🍁 Atakayeyasema mara tatu jioni, basi hatodhuriwa na mdudu wa sumu usiku huo.”\r\n\r\n✍️ _Ahmad (02/290), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (590) na Ibn-us-Sunniy (68). Tazama “Swahiyh-ut-Tirmidhiy (03/187), “Swahiyh Ibn Maajah”', '🍁 Atakayeyasema mara tatu jioni, basi hatodhuriwa na mdudu wa sumu usiku huo.”\r\n\r\n✍️ _Ahmad (02/290), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (590) na Ibn-us-Sunniy (68). Tazama “Swahiyh-ut-Tirmidhiy (03/187), “Swahiyh Ibn Maajah”', 3, '', NULL, NULL, NULL, NULL, 24, 1, '2026-09-06 08:11:14', '2026-09-06 08:12:48'),
(29, 2, 'Alhamdullillah', 'Alhamdulillah', 'الْحَمْدُ لِله وَحْدَهُ ، وَالصَّلَاةُ وَالسَلَامُ عَلَى مَنْ لَا نَبِيَّ بَعْدَهُ', 'Alhamdulillahi wahdah, wassalaatu wassalaamu a\'laa man la nabiyya ba\'adah.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', '🍁 Anas (Radhiya Allaahu ´anh) amesimulia kwamba Mtume ﷺ amesema: ”Kukaa pamoja na watu wanaomdhukuru Allaah (Ta´ala) kuanzia swalah ya Fajr mpaka kuchomoza jua kunapendeza zaidi kwangu kuliko kuacha huru watu wanne miongoni mwa wana wa Ismaa’iyl. Na kukaa pamoja na watu wanaomdhukuru Allaah kuanzia swalah ya ´Aswr mpaka kuzama jua kunapendeza zaidi kwangu mimi kuliko kuwaacha huru watu wanne.', '🍁 Anas (Radhiya Allaahu ´anh) amesimulia kwamba Mtume ﷺ amesema: ”Kukaa pamoja na watu wanaomdhukuru Allaah (Ta´ala) kuanzia swalah ya Fajr mpaka kuchomoza jua kunapendeza zaidi kwangu kuliko kuacha huru watu wanne miongoni mwa wana wa Ismaa’iyl. Na kukaa pamoja na watu wanaomdhukuru Allaah kuanzia swalah ya ´Aswr mpaka kuzama jua kunapendeza zaidi kwangu mimi kuliko kuwaacha huru watu wanne.\r\n\r\n✍️ Abu Dawuud (3667) na ni nzuri kwa mujibu wa al-Albaaniy katika ”Swahiyh Abiy Daawuud (02/698).', 1, '', NULL, NULL, NULL, NULL, 1, 1, '2026-09-06 21:38:45', '2026-09-06 21:48:32'),
(31, 2, 'Kuomba hifadhi', 'Kuomba hifadhi', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', '\'A \'oothu billaahi minash-Shaytaanir-rajeem', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', '', '', 1, '', NULL, NULL, NULL, NULL, 2, 1, '2026-09-06 21:38:59', '2026-09-06 21:49:06'),
(32, 2, 'AAYATUL-KURSEE {02:255}', 'AAYATUL-KURSEE {02:255}', 'اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allaahu laa \'ilaaha \'illaa Huwal-Hayyul-Qayyoom, laa ta\'khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-\'ardh, man thai-lathee yashfa\'u \'indahu \'illaa bi\'ithnih, ya\'lamu maa bayna \'aydeehim wa maa khalfahum, wa laa yuheetoona bishay\'im-min \'ilmihi \'illaa bimaa shaa\'a, wasi\'a kursiyyuhus samaawaati wal\'ardh, wa laa ya\'ooduhu hifdhuhumaa, wa Huwal- \'Aliyyul- \'Adheem.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', '🍁 ”Atakayeisoma kunapoingia asubuhi itamlinda na majini mpaka itakapofika jioni. Na atakayeisoma kunapoingia jioni atalindwa na majini mpaka asubuhi.”\r\n\r\n✍️ al-Haakim (01/562) na ni Swahiyh kwa mujibu wa al-Albaaniy katika ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273). Ameiegemeza kwa an-Nasaa´iy na at-Twabaraaniy ambapo akasema: ”Cheni ya wapokezi ya at-Twabaraaniy ni nzuri.”', '🍁 ”Atakayeisoma kunapoingia asubuhi itamlinda na majini mpaka itakapofika jioni. Na atakayeisoma kunapoingia jioni atalindwa na majini mpaka asubuhi.”\r\n\r\n✍️ al-Haakim (01/562) na ni Swahiyh kwa mujibu wa al-Albaaniy katika ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273). Ameiegemeza kwa an-Nasaa´iy na at-Twabaraaniy ambapo akasema: ”Cheni ya wapokezi ya at-Twabaraaniy ni nzuri.”', 1, '', NULL, NULL, NULL, NULL, 3, 1, '2026-09-06 21:39:34', '2026-09-06 21:49:27'),
(33, 2, 'SURAH AL-IKHLAAS {112:01-04}', 'SURAH AL-IKHLAAS {112:01-04}', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ', 'Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu \'Ahad ۞ Allaahus-Samad ۞ Lam yalid wa lam yoolad ۞ Wa lam yakun lahu kufuwan \'ahad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', '', '', 1, '', NULL, NULL, NULL, NULL, 4, 1, '2026-09-06 21:44:33', '2026-09-06 21:49:51'),
(34, 2, 'SURAH AL-FALAQ {113:01-05}.', 'SURAH AL-FALAQ {113:01-05}.', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ۞', 'Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbil-falaq ۞ Min sharri ma khalaq ۞Wa min sharri ghaasiqin \'ithaa waqab ۞ Wa min sharrin-naffaathaati fil-\'uqad ۞ Wa min sharri haasidin \'ithaa hasad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', '', '', 1, '', NULL, NULL, NULL, NULL, 5, 1, '2026-09-06 21:44:43', '2026-09-06 21:50:16'),
(35, 2, 'SURAH AN-NAAS {114:01-06}.', 'SURAH AN-NAAS {114:01-06}.', 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ', '✨Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbin-naas ۞ Malikin-naas. \'Ilaahin-naas ۞ Min sharril-waswaasil-khannaas ۞ Allathee yuwaswisu fee sudoorin-naas ۞ Minal-jinnati wannaas.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', '🍁 \"Atakayezisoma mara tatu kunapoingia asubuhi na jioni, basi zitamtosheleza kutokamana na kila shari.”\r\n\r\n✍️ Abu Daawuuud (04/322), at-Tirmidhiy (05/567). Tazama ”Swahiyh-ut-Tirmidhiy” (03/182).', '🍁 \"Atakayezisoma mara tatu kunapoingia asubuhi na jioni, basi zitamtosheleza kutokamana na kila shari.”\r\n\r\n✍️ Abu Daawuuud (04/322), at-Tirmidhiy (05/567). Tazama ”Swahiyh-ut-Tirmidhiy” (03/182).', 1, '', NULL, NULL, NULL, NULL, 6, 1, '2026-09-06 21:44:51', '2026-09-06 21:50:41'),
(36, 2, 'Dua', 'Dua', '🍃⚪▫️أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ للهِ وَالْحَمْدُ للهِ، لَا إِلَهَ إِلَّا اللهُ وَحَدْهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، ربِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَومِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَومِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْر', '', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya siku ya leo, kheri ya baada yake, na najilinda Kwako kutokamana na shari ya siku ya leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya siku ya leo, kheri ya baada yake, na najilinda Kwako kutokamana na shari ya siku ya leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', '✍️ Muslim (04/2088).', '✍️ Muslim (04/2088).', 1, '', NULL, NULL, NULL, NULL, 7, 1, '2026-09-06 21:58:41', '2026-09-06 22:00:33'),
(37, 2, 'Dua2', 'Dua2', '🍃⚪▫️اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ', '', 'Ee Allaah! Kwako tumepambaukiwa, na Kwako tumeingiliwa na jioni, na kwa ajili Yako ndio tumekuwa hai, na kwa ajili Yako tutakufa na Kwako tutakusanywa.', 'Ee Allaah! Kwako tumepambaukiwa, na Kwako tumeingiliwa na jioni, na kwa ajili Yako ndio tumekuwa hai, na kwa ajili Yako tutakufa na Kwako tutakusanywa.', '✍️ at-Tirmidhiy (05/466). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', '✍️ at-Tirmidhiy (05/466). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', 1, '', NULL, NULL, NULL, NULL, 8, 1, '2026-09-06 22:00:46', '2026-09-06 22:04:25'),
(38, 2, 'Dua3', 'Dua3', '🍃⚪▫️اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'Anta Rabbee laa \'ilaaha \'illaa \'Anta, khalaqtanee wa \'anaa \'abduka, wa \'anaa \'alaa \'ahdika wa wa\'dika mas-tata\'tu, \'a\'oothu bika min sharri maa sana\'tu, \'aboo\'u laka bini\'matika \'alayya, wa \'aboo\'u bithanbee faghfir lee fa\'innahu laa yaghfiruth-thunooba \'illaa \'Anta.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', '🍁 ”Atakayeyasema mchana hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia jioni, basi ataingia Peponi. Atakayeyasema usiku hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia asubuhi, basi ataingia Peponi.”\r\n\r\n✍️ al-Bukhaariy (07/150).', '🍁 ”Atakayeyasema mchana hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia jioni, basi ataingia Peponi. Atakayeyasema usiku hali ya kuwa na yakini nayo ambapo akafariki siku hiyo kabla kuingia asubuhi, basi ataingia Peponi.”\r\n\r\n✍️ al-Bukhaariy (07/150).', 1, '', NULL, NULL, NULL, NULL, 9, 1, '2026-09-06 22:04:53', '2026-09-06 22:07:30'),
(39, 2, 'Dua4', 'Dua4', '🍃⚪▫️اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ(×04)', '', 'Ee Allaah! Hakika mimi nimeamka asubuhi; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 'Ee Allaah! Hakika mimi nimeamka asubuhi; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', '🍁 ”Atakayeyasema haya mara nne pindi anapoamka asubuhi au imapoingia jioni, basi Allaah atamuepusha na Moto.”', '🍁 ”Atakayeyasema haya mara nne pindi anapoamka asubuhi au imapoingia jioni, basi Allaah atamuepusha na Moto.”', 1, '', NULL, NULL, NULL, NULL, 10, 1, '2026-09-06 22:07:42', '2026-09-06 22:09:25'),
(40, 2, 'Dua5', 'Dua5', '🍃⚪▫️اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', '🍃✨Allaahumma maa \'amsa bee min ni\'matin \'aw bi\'ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.', 'Ee Allaah! Sikuamka na neema yoyote au kutoka kwa kiumbe Chako chochote, si vyenginevyo isipokuwa inatoka Kwako, hali ya kuwa upekee huna mshirika, ni Zako himdi zote njema na ni Zako shukurani.', 'Ee Allaah! Sikuamka na neema yoyote au kutoka kwa kiumbe Chako chochote, si vyenginevyo isipokuwa inatoka Kwako, hali ya kuwa upekee huna mshirika, ni Zako himdi zote njema na ni Zako shukurani.', '🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n✍️ Abu Daawuud (04/318), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah (07), Ibn-us-Sunniy (41), Ibn Hibbaan katika “Mawaarid” (2361) Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 24.', '🍁 ”Atakayeyasema pindi anapoamka asubuhi, basi hakika ametekeleza shukurani ya siku yake.  Na atakayesema inapoingia jioni, basi ametekeleza shukurani ya usiku wake.”\r\n\r\n✍️ Abu Daawuud (04/318), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah (07), Ibn-us-Sunniy (41), Ibn Hibbaan katika “Mawaarid” (2361) Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika ”Tuhfat-ul-Akhyaar”, uk. 24.', 1, '', NULL, NULL, NULL, NULL, 11, 1, '2026-09-06 22:09:35', '2026-09-06 22:11:41');
INSERT INTO `adhkaar` (`id`, `category_id`, `title`, `title_sw`, `arabic_text`, `transliteration`, `translation_en`, `translation_sw`, `virtue`, `virtue_sw`, `repeat_count`, `source_reference`, `audio_path`, `audio_url`, `video_path`, `video_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(41, 2, 'Dua6', 'Dua6', '🍃⚪▫️اللَّهُمَّ عَافِنِي فِي بَدََنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفرِ، وَالْفَقْرِ، وَ أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'aafinee fee badanee, Allaahumma \'aafinee fee sam\'ee, Allaahumma \'aafinee fee basaree, laa \'ilaaha \'illaa \'Anta. Allaahumma \'innee \'a\'oothu bika minal-kufri, walfaqri, wa \'a\'oothu bika min \'athaabil-qabri, laa \'ilaaha \'illaa \'Anta.(×03)', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', '✍️ Abu Daawuud (04/324), Ahmad (05/42), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (22), Ibn-us-Sunniy (69) na al-Bukhaariy katika ”Aadab-ul-Mufrad”. ´Allaamah Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika “Tuhfat-ul-Akhyaaar”, uk. 26.', '✍️ Abu Daawuud (04/324), Ahmad (05/42), an-Nasaa´iy katika ”‘Amal-ul-Yawm wal-Laylah (22), Ibn-us-Sunniy (69) na al-Bukhaariy katika ”Aadab-ul-Mufrad”. ´Allaamah Ibn Baaz ameifanya cheni ya wapokezi kuwa nzuri katika “Tuhfat-ul-Akhyaaar”, uk. 26.', 3, '', NULL, NULL, NULL, NULL, 12, 1, '2026-09-06 22:12:00', '2026-09-06 22:12:48'),
(42, 2, 'Dua7', 'Dua7', '🍃⚪▫️حَسْبِيَ اللهُ لَآ إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', '🍃✨Hasbiyallaahu laa \'ilaaha \'illaa Huwa \'alayhi tawakkaltu wa Huwa Rabbul-\'Arshil-\'Adheem(×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', '🍁 ”Atakayeyasema mara saba pindi kunapopambazuka na kunapoinga jioni, basi itamtosheleza katika mambo yake yanayomtia hamu ya dunia na Aakhirah.”\r\n\r\n✍️ Ibn-us-Sunniy (71) kutoka kwa Mtume (Swalla Allaahu ´alayhi wa sallam), Abu Daawuud (04/321) kutoka kwa Swahabah. Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameisahihisha cheni ya wapokezi wake. Tazama ”Zaad-ul-Ma’aad (02/376).', '🍁 ”Atakayeyasema mara saba pindi kunapopambazuka na kunapoinga jioni, basi itamtosheleza katika mambo yake yanayomtia hamu ya dunia na Aakhirah.”\r\n\r\n✍️ Ibn-us-Sunniy (71) kutoka kwa Mtume (Swalla Allaahu ´alayhi wa sallam), Abu Daawuud (04/321) kutoka kwa Swahabah. Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameisahihisha cheni ya wapokezi wake. Tazama ”Zaad-ul-Ma’aad (02/376).', 7, '', NULL, NULL, NULL, NULL, 13, 1, '2026-09-06 22:12:59', '2026-09-06 22:13:39'),
(43, 2, 'Dua8', 'Dua8', '🍃⚪▫️اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', '🍃✨Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fid-dunyaa wal\'aakhirati, Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fee deenee wa dunyaaya wa \'ahlee, wa maalee , Allaahum-mastur \'awraatee, wa \'aamin raw\'aatee, Allaahum-mahfadhnee min bayni yadayya, wa min khalfee, wa \'an yameenee, wa \'an shimaalee, wa min fawqee, wa \'a\'oothu bi\'adhamatika \'an \'ughtaala min tahtee.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', '✍️ Abu Daawuud (5074) na Ibn Maajah (3871). Tazama ”Swahiyh Ibn Maajah (02/332).', '✍️ Abu Daawuud (5074) na Ibn Maajah (3871). Tazama ”Swahiyh Ibn Maajah (02/332).', 1, '', NULL, NULL, NULL, NULL, 14, 1, '2026-09-06 22:13:50', '2026-09-06 22:15:09'),
(44, 2, 'Dua9', 'Dua9', '🍃⚪▫️اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّماوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', '🍃✨Allaahumma \'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal\'ardhi, Rabba kulli shay \'in wa maleekahu, \'ash-hadu \'an laa \'ilaaha \'illaa \'Anta, \'a\'oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa \'an \'aqtarifa \'alaa nafsee soo\'an, \'aw \'ajurrahu \'ilaa Muslimin.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', '✍️ at-Tirmidhiy (3392) na Abu Daawuud (5067). Swahiyh-ut-Tirmidhiy (03/142).', '✍️ at-Tirmidhiy (3392) na Abu Daawuud (5067). Swahiyh-ut-Tirmidhiy (03/142).', 1, '', NULL, NULL, NULL, NULL, 15, 1, '2026-09-06 22:15:18', '2026-09-06 22:16:10'),
(45, 2, 'Dua10', 'Dua10', '🍃⚪▫️بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', '🍃✨Bismillaahil-lathee laa yadhurru ma\'as-mihi shay\'un fil-\'ardhi wa laa fis-samaa\'i wa Huwas-Samee \'ul- \'Aleem .(×03)', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', '🍁 “Atakayeyasema mara tatu kunapoingia asubuhi na jioni, basi hatodhuriwa na chochote.”\r\n✍️ Abu Daawuud (04/323), at-Tirmidhiy (05/465), Ibn Maajah (3869) na Ahmad. Tazama “Swahiyh Ibn Maajah (02/332). ‘Allaamah Ibn Baaz ameifanya cheni ya wapokezi wake kuwa nzuri katika “Tuhfat-ul-Akhyaar”, uk. 39.', '🍁 “Atakayeyasema mara tatu kunapoingia asubuhi na jioni, basi hatodhuriwa na chochote.”\r\n\r\n✍️ Abu Daawuud (04/323), at-Tirmidhiy (05/465), Ibn Maajah (3869) na Ahmad. Tazama “Swahiyh Ibn Maajah (02/332). ‘Allaamah Ibn Baaz ameifanya cheni ya wapokezi wake kuwa nzuri katika “Tuhfat-ul-Akhyaar”, uk. 39.', 3, '', NULL, NULL, NULL, NULL, 16, 1, '2026-09-06 22:16:18', '2026-09-06 22:16:56'),
(46, 2, 'Dua11', 'Dua11', '🍃⚪▫️رَضِيتُ باللهِ رَبَّاً، وَبِالْإِسْلَامِ دِيناً، وَبِمُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ نَبِيَّاً', '🍃✨Radheetu billaahi Rabban, wa bil-\'Islaami deenan, wa bi-Muhammadin (sallallaahu \'alayhi wa sallama) Nabiyyan.(×03)', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', '🍁 \"Atakayeyasema mara tatu kutapoingia asubuhi na mara tatu kutapoingia jioni, basi imekuwa ni haki kwa Allaah kumridhia siku ya Qiyaamah.”\r\n\r\n✍️ Ahmad (04/337), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (04), Ibn-us-Sunniy (68), Abu Daawuud (04/318) na at-Tirmidhiy (05/465).  Ibn Baaz ameifanya kuwa nzuri katika “Tuhfat-ul-Akhyaa, uk. 39.', '🍁 \"Atakayeyasema mara tatu kutapoingia asubuhi na mara tatu kutapoingia jioni, basi imekuwa ni haki kwa Allaah kumridhia siku ya Qiyaamah.”\r\n✍️ Ahmad (04/337), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (04), Ibn-us-Sunniy (68), Abu Daawuud (04/318) na at-Tirmidhiy (05/465).  Ibn Baaz ameifanya kuwa nzuri katika “Tuhfat-ul-Akhyaa, uk. 39.', 3, '', NULL, NULL, NULL, NULL, 17, 1, '2026-09-06 22:17:13', '2026-09-06 22:17:37'),
(47, 2, 'Dua12', 'Dua12', '🍃⚪▫️يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', '🍃✨Yaa Hayyu yaa Qayyoomu birahmatika \'astagheethu \'aslih lee sha\'nee kullahu wa laa takilnee \'ilaa nafsee tarfata \'aynin.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', '✍️ al-Haakim na ameisahihisha ambapo adh-Dhahabiy akaafikiana naye. Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', '✍️ al-Haakim na ameisahihisha ambapo adh-Dhahabiy akaafikiana naye. Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', 1, '', NULL, NULL, NULL, NULL, 18, 1, '2026-09-06 22:18:04', '2026-09-06 22:19:56'),
(48, 2, 'Dua13', 'Dua13', '🍃⚪▫️أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ: فَتْحَهُ، وَنَصْرَهُ وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيْهِ وَشَرِّ مَا بَعْدَهُ', '', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', '✍️ Abu Daawuud (04/322). Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameifanya cheni ya wapokezi wake kuwa nzuri wakati wa kuihakiki ”Zaad-ul-Ma’aad (02/273).', '✍️ Abu Daawuud (04/322). Shu’ayb na ‘Abdul-Qaadir al-Arnauutw wameifanya cheni ya wapokezi wake kuwa nzuri wakati wa kuihakiki ”Zaad-ul-Ma’aad (02/273).', 1, '', NULL, NULL, NULL, NULL, 19, 1, '2026-09-06 22:20:08', '2026-09-06 22:21:32'),
(49, 2, 'Dua14', 'Dua14', '🍃⚪▫️أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفَاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ', '', 'Tumepambaukiwa tukiwa juu ya maumbile ya Uislamu, juu ya neno la ikhlaasw, juu ya dini ya Mtume wetu Muhammad (Swalla Allaahu ´alayhi wa sallam), juu ya mila ya baba yetu Ibraahiym, aliyejiepusha na shirki aina zote na akaielekea Tawhiyd, hali  ya kuwa muislamu wala hakuwa miongoni mwa washirikina.', 'Tumepambaukiwa tukiwa juu ya maumbile ya Uislamu, juu ya neno la ikhlaasw, juu ya dini ya Mtume wetu Muhammad (Swalla Allaahu ´alayhi wa sallam), juu ya mila ya baba yetu Ibraahiym, aliyejiepusha na shirki aina zote na akaielekea Tawhiyd, hali  ya kuwa muislamu wala hakuwa miongoni mwa washirikina.', '✍️ Ahmad (03/406, 407) na Ibn-us-Sunny katika ”‘Amal-ul-Yawm wal-Laylah (34). Tazama ”Swahiyh-ul-Jaamiy’” (04/209).', '✍️ Ahmad (03/406, 407) na Ibn-us-Sunny katika ”‘Amal-ul-Yawm wal-Laylah (34). Tazama ”Swahiyh-ul-Jaamiy’” (04/209).', 1, '', NULL, NULL, NULL, NULL, 20, 1, '2026-09-06 22:21:48', '2026-09-06 22:22:55'),
(50, 2, 'Dua15', 'Dua15', '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ', '🍃✨Subhaanallaahi wa bihamdihi.(×100)', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', '🍁 ”Atakayeyasema mara mia kunapopambazuka na kunapoingia jioni, basi hakuna yeyote siku ya Qiyaamah atakayekuja na kitu bora kuliko alichokuja nacho yeye isipokuwa aliyesema mfano wa haya au akazidisha.”\r\n\r\n✍️ Muslim (04/2071).', '🍁 ”Atakayeyasema mara mia kunapopambazuka na kunapoingia jioni, basi hakuna yeyote siku ya Qiyaamah atakayekuja na kitu bora kuliko alichokuja nacho yeye isipokuwa aliyesema mfano wa haya au akazidisha.”\r\n\r\n✍️ Muslim (04/2071).', 100, '', NULL, NULL, NULL, NULL, 21, 1, '2026-09-06 22:23:09', '2026-09-06 22:23:41'),
(51, 2, 'Dua16', 'Dua16', '🍃⚪▫️لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '🍃✨Laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa \'alaa kulli shay\'in Qadeer.(×10)', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', '✍️ ¹an-Nasaa´y katika ”‘Amal-ul-Yawm wal-Laylah” (24). Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/272) na ”Tuhfat-ul-Akhyaar”, uk. 255 ya Ibn Baaz. Pia tazama fadhilah zake katika ukurasa wa 146 Hadiyth nambari. 255.\r\n\r\n✍️ ²Abu Daawuud (04/319), Ibn Maajah (3867) na Ahmad (04/60). Tazama ”Swahiyh ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/270) na ”Swahiyh Abiy Daawuud” (03/957).', '✍️ ¹an-Nasaa´y katika ”‘Amal-ul-Yawm wal-Laylah” (24). Tazama ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/272) na ”Tuhfat-ul-Akhyaar”, uk. 255 ya Ibn Baaz. Pia tazama fadhilah zake katika ukurasa wa 146 Hadiyth nambari. 255.\r\n\r\n✍️ ²Abu Daawuud (04/319), Ibn Maajah (3867) na Ahmad (04/60). Tazama ”Swahiyh ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/270) na ”Swahiyh Abiy Daawuud” (03/957).', 100, '', NULL, NULL, NULL, NULL, 22, 1, '2026-09-06 22:23:47', '2026-09-06 22:24:26'),
(52, 2, 'Dua19', 'Dua19', '🍃⚪▫️أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ', '🍃✨\'Astaghfirullaaha wa \'atoobu \'ilayhi.(×100)', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', '✍️ al-Bukhaariy pamoja na al-Fath (11/101) na Muslim (4/2075).', '✍️ al-Bukhaariy pamoja na al-Fath (11/101) na Muslim (4/2075).', 100, '', NULL, NULL, NULL, NULL, 25, 1, '2026-09-06 22:24:41', '2026-09-06 22:48:27'),
(53, 2, 'Dua21', 'Dua21', '🍃⚪▫️أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', '🍃✨A\'oothu bikalimaatil-laahit-taammaati min sharri maa khalaqa.(×03)', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', '🍁 Atakayeyasema mara tatu jioni, basi hatodhuriwa na mdudu wa sumu usiku huo.”\r\n\r\n✍️ _Ahmad (02/290), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (590) na Ibn-us-Sunniy (68). Tazama “Swahiyh-ut-Tirmidhiy (03/187), “Swahiyh Ibn Maajah”', '🍁 Atakayeyasema mara tatu jioni, basi hatodhuriwa na mdudu wa sumu usiku huo.”\r\n\r\n✍️ _Ahmad (02/290), an-Nasaa´iy katika “‘Amal-ul-Yawm wal-Laylah” (590) na Ibn-us-Sunniy (68). Tazama “Swahiyh-ut-Tirmidhiy (03/187), “Swahiyh Ibn Maajah”', 3, '', NULL, NULL, NULL, NULL, 27, 1, '2026-09-06 22:47:19', '2026-09-06 23:07:51'),
(54, 2, 'Dua17', 'Dua17', '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ(×03)', '', 'Allaah ametakasika kutokamana na mapungufu yote na himdi zote njema ni Zake kwa idadi ya viumbe Wake, radhi Yake, uzito wa ´Arshi Yake na wino wa maneno Yake.(×03 utapoamka asubuhi)', 'Allaah ametakasika kutokamana na mapungufu yote na himdi zote njema ni Zake kwa idadi ya viumbe Wake, radhi Yake, uzito wa ´Arshi Yake na wino wa maneno Yake.(×03 utapoamka asubuhi)', '✍️ Muslim (04/2090).', '✍️ Muslim (04/2090).', 1, '', NULL, NULL, NULL, NULL, 23, 1, '2026-09-06 22:51:04', '2026-09-06 22:51:04'),
(55, 2, 'Dua18', 'Dua18', '🍃⚪▫️اللَّهُمَّ إنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً', '', 'Ee Allaah! Hakika nakuomba elimu yenye kunufaisha, riziki njema na matendo yenye kukubaliwa.(Atasema haya akiamka asubuhi)', 'Ee Allaah! Hakika nakuomba elimu yenye kunufaisha, riziki njema na matendo yenye kukubaliwa.(Atasema haya akiamka asubuhi)', '✍️ Ibn-us-Sunniy katika ”‘Amal-ul-Yawam wal-Laylah” (54), Ibn Maajah (925). ´Abdul-Qaadir al-Arnauutw na Shu´ayb wameifanya nzuri cheni ya wapokezi wake wakati wa kuihakiki ”Zaad-ul-Ma´aad” (0/375). Imekwishatangulia katika uk. 51 nambari (73).', '✍️ Ibn-us-Sunniy katika ”‘Amal-ul-Yawam wal-Laylah” (54), Ibn Maajah (925). ´Abdul-Qaadir al-Arnauutw na Shu´ayb wameifanya nzuri cheni ya wapokezi wake wakati wa kuihakiki ”Zaad-ul-Ma´aad” (0/375). Imekwishatangulia katika uk. 51 nambari (73).', 1, '', NULL, NULL, NULL, NULL, 24, 1, '2026-09-06 22:55:49', '2026-09-06 22:55:49'),
(56, 2, 'Dua20', 'Dua20', '🍃⚪▫️اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ(×10)', '', 'Ee Allaah! Msifu Muhammad, wakeze na kizazi chake, kama Ulivyowasifu jamaa zake Ibraahiym. Mbariki  Muhammad, wakeze na kizazi chake kama Ulivyowabariki jamaa zake Ibraahiym. Kwani hakika Wewe ni Mwenye kuhidimiwa na Mwenye kutukuzwa.', 'Ee Allaah! Msifu Muhammad, wakeze na kizazi chake, kama Ulivyowasifu jamaa zake Ibraahiym. Mbariki  Muhammad, wakeze na kizazi chake kama Ulivyowabariki jamaa zake Ibraahiym. Kwani hakika Wewe ni Mwenye kuhidimiwa na Mwenye kutukuzwa.', '🍁 \'\'Atakayeniswalia mara kumi kunapoingia asubuhi na mara kumi kunapoingia jioni, basi nitamuombea uombezi siku ya Qiyaamah.”\r\n\r\n✍️ Ameipokea at-Twabaraaniy kwa cheni mbili ambapo moja katika hizo mbili ni nzuri. Tazama “Majma´-uz-Zawaa-id” (10/120) na ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', '🍁 \'\'Atakayeniswalia mara kumi kunapoingia asubuhi na mara kumi kunapoingia jioni, basi nitamuombea uombezi siku ya Qiyaamah.”\r\n\r\n✍️ Ameipokea at-Twabaraaniy kwa cheni mbili ambapo moja katika hizo mbili ni nzuri. Tazama “Majma´-uz-Zawaa-id” (10/120) na ”Swahiyh-ut-Targhiyb wat-Tarhiyb” (01/273).', 10, '', NULL, NULL, NULL, NULL, 26, 1, '2026-09-06 23:12:54', '2026-09-06 23:13:26'),
(57, 3, '💫 HADIYTH NAMBA 01.', '💫 HADIYTH NAMBA 01.', '', NULL, NULL, NULL, '🍁 Alikuwa Mtume (ﷺ) akitaka kulala usiku akivikusanya viganja vyake vya mikono kisha akivipulizia na akivisomea Suratul-Ikhlas, na Suratul-Falaq, na Suratu Nnas, kisha akijipangusa kwa hivyo viganja vyake katika mwili wake kiasi anachoweza, akianza kichwani na usoni na mbele. (Akifanya hivyo mara tatu).', '🍁 Alikuwa Mtume (ﷺ) akitaka kulala usiku akivikusanya viganja vyake vya mikono kisha akivipulizia na akivisomea Suratul-Ikhlas, na Suratul-Falaq, na Suratu Nnas, kisha akijipangusa kwa hivyo viganja vyake katika mwili wake kiasi anachoweza, akianza kichwani na usoni na mbele. (Akifanya hivyo mara tatu).', 1, '✍️ al-Bukhaariy pamoja na al-Fath (09/62) na Muslim (04/1723).', NULL, NULL, NULL, NULL, 1, 1, '2026-09-06 23:59:30', '2026-09-06 23:59:30'),
(58, 3, '💫 HADIYTH NAMBA 02.', '💫 HADIYTH NAMBA 02.', '', NULL, NULL, NULL, '🍁 Mtume (ﷺ) amesema: (Ukitaka kulala soma Ayatul-Kursiy mpaka umalize kwani Mwenyezi Mungu ataendelea kukuhifadhi, wala hakukaribii shetani mpaka asubuhi.', '🍁 Mtume (ﷺ) amesema: (Ukitaka kulala soma Ayatul-Kursiy mpaka umalize kwani Mwenyezi Mungu ataendelea kukuhifadhi, wala hakukaribii shetani mpaka asubuhi.', 1, '✍️ al-Bukhaariy pamoja na al-Fath (04/487).', NULL, NULL, NULL, NULL, 2, 1, '2026-09-07 00:03:29', '2026-09-07 00:03:29'),
(59, 3, '💫 HADIYTH NAMBA 03.', '💫 HADIYTH NAMBA 03.', '', NULL, NULL, NULL, '🍁 Amesema Mtume (ﷺ) anaesoma aya mbili za mwisho wa Suratul-Baqrah usiku zinamtosheleza.(02:285-286)', '🍁 Amesema Mtume (ﷺ) anaesoma aya mbili za mwisho wa Suratul-Baqrah usiku zinamtosheleza.(02:285-286)', 1, '✍️ al-Bukhaariy pamoja na al-Fath (09/94) na Muslim (01/554).', NULL, NULL, NULL, NULL, 3, 1, '2026-09-07 00:05:28', '2026-09-07 00:05:28'),
(60, 3, '💫 HADIYTH NAMBA 04.', '💫 HADIYTH NAMBA 04.', '', NULL, NULL, NULL, '🍁 Mtume (ﷺ) pia amesema: (Akiamka mmoja wenu kutoka usingizini kisha akarudi basi akikung\'ute kitanda chake kwa shuka lake mara tatu, na amtaje Mwenyezi Mungu, kwani hajui kilichokuja baada yake. Na akilala aseme:', '🍁 Mtume (ﷺ) pia amesema: (Akiamka mmoja wenu kutoka usingizini kisha akarudi basi akikung\'ute kitanda chake kwa shuka lake mara tatu, na amtaje Mwenyezi Mungu, kwani hajui kilichokuja baada yake. Na akilala aseme:', 1, '✍️ al-Bukhaariy (11/126) na Muslim (04/2084).', NULL, NULL, NULL, NULL, 4, 1, '2026-09-07 00:07:01', '2026-09-07 00:07:01'),
