(67, 3, '💫 HADIYTH NAMBA 11.', '💫 HADIYTH NAMBA 11.', '', NULL, NULL, NULL, '', '', 1, '✍️ Abu Dawuud (04/317). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', NULL, NULL, NULL, '✍️ Abu Dawuud (04/317). Tazama ”Swahiyh-ut-Tirmidhiy” (03/142).', 11, 1, '2026-09-07 00:19:23', '2026-09-07 00:19:23'),
(68, 3, '💫 HADIYTH NAMBA 12.', '💫 HADIYTH NAMBA 12.', '', NULL, NULL, NULL, 'Mtume (ﷺ) alikuwa halali mpaka asome Suratu-Sajda na Suratul-Mulku.', 'Mtume (ﷺ) alikuwa halali mpaka asome Suratu-Sajda na Suratul-Mulku.', 1, '✍️ at-Tirmidhiy na an-Nasaa´iy. Tazama “Swahiy-ul-Jaamiy´” (04/255).', NULL, NULL, NULL, NULL, 12, 1, '2026-09-07 00:21:54', '2026-09-07 00:24:53'),
(69, 3, '💫 HADIYTH NAMBA 13.', '💫 HADIYTH NAMBA 13.', '', NULL, NULL, NULL, '🍁 ¹”Unapotaka kulala, tawadha wudhuu´ kama wa swalah kisha lalia ubavu wa kulia kisha useme… “', '🍁 ¹”Unapotaka kulala, tawadha wudhuu´ kama wa swalah kisha lalia ubavu wa kulia kisha useme… “', 1, '🍁 ²Amesema Mtume (ﷺ) kwa mwenye kuyasema hayo, kisha akafa atakuwa amekufa katika uislamu (kiislamu).  ✍️ al-Bukhaariy pamoja na al-Fath (11/113) na Muslim (04/2081).', NULL, NULL, NULL, NULL, 13, 1, '2026-09-07 00:23:37', '2026-09-07 00:23:37');

