INSERT INTO `adhkaar_verses` (`id`, `adhkaar_id`, `arabic_text`, `transliteration`, `translation_en`, `translation_sw`, `repeat_count`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'الْحَمْدُ لِله وَحْدَهُ ، وَالصَّلَاةُ وَالسَلَامُ عَلَى مَنْ لَا نَبِيَّ بَعْدَهُ', 'Alhamdulillahi wahdah, wassalaatu wassalaamu a\'laa man la nabiyya ba\'adah.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(2, 2, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', '\'A \'oothu billaahi minash-Shaytaanir-rajeem', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(3, 3, 'اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allaahu laa \'ilaaha \'illaa Huwal-Hayyul-Qayyoom, laa ta\'khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-\'ardh, man thai-lathee yashfa\'u \'indahu \'illaa bi\'ithnih, ya\'lamu maa bayna \'aydeehim wa maa khalfahum, wa laa yuheetoona bishay\'im-min \'ilmihi \'illaa bimaa shaa\'a, wasi\'a kursiyyuhus samaawaati wal\'ardh, wa laa ya\'ooduhu hifdhuhumaa, wa Huwal- \'Aliyyul- \'Adheem.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(4, 4, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ', 'Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu \'Ahad ۞ Allaahus-Samad ۞ Lam yalid wa lam yoolad ۞ Wa lam yakun lahu kufuwan \'ahad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(5, 5, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ۞', 'Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbil-falaq ۞ Min sharri ma khalaq ۞Wa min sharri ghaasiqin \'ithaa waqab ۞ Wa min sharrin-naffaathaati fil-\'uqad ۞ Wa min sharri haasidin \'ithaa hasad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(6, 6, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ', '✨Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbin-naas ۞ Malikin-naas. \'Ilaahin-naas ۞ Min sharril-waswaasil-khannaas ۞ Allathee yuwaswisu fee sudoorin-naas ۞ Minal-jinnati wannaas.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(7, 7, '🍃⚪▫️أَمْسَيْـنا وَأَمْسـى المـلكُ لله وَالحَمدُ لِله ، لا إلهَ إلاّ اللّهُ وَحدَهُ لا شَريكَ لهُ، لهُ المُـلكُ ولهُ الحَمْـد، وهُوَ على كلّ شَيءٍ قدير ، رَبِّ أسْـأَلُـكَ خَـيرَ ما في هـذهِ اللَّـيْلَةِ وَخَـيرَ ما بَعْـدَهـا ، وَأَعـوذُ بِكَ مِنْ شَـرِّ هـذهِ اللَّـيْلةِ وَشَرِّ ما بَعْـدَهـا ، رَبِّ أَعـوذُبِكَ مِنَ الْكَسَـلِ وَسـوءِ الْكِـبَر ، رَبِّ أَعـوذُبِكَ مِنْ عَـذابٍ في النّـارِ وَعَـذابٍ في القَـبْر', '🍃✨\'Amsaynaa wa \'amsal-mulku lillaahi walhamdu lillaahi, laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu wa Huwa \'alaa kulli shay\'in Qadeer. Rabbi \'as\'aluka khayra maa fee haathihil-laylati wa khayra maa ba\'daha wa \'a\'oothu bika min sharri maa fee haathihil-laylati wa sharri maa ba\'daha, Rabbi \'a\'oothu bika minal-kasali, wa soo\'il-kibari, Rabbi \'a\'oothu bika min \'athaabin fin-naari wa \'athaabin fil-qabri.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya usiku wa leo, na kheri ya baada yake, na najilinda Kwako kutokamana na shari ya usiku wa leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu, na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya usiku wa leo, na kheri ya baada yake, na najilinda Kwako kutokamana na shari ya usiku wa leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu, na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(8, 8, 'اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ المَصِیر', 'Allaahumma bika \'amsaynaa, wa bika \'asbahnaa, wa bika nahyaa, wa bika namootu wa \'ilaykal-maseer.', 'Ewe Mwenyezi Mungu kwa ajili yako tumefika jioni, na kwa ajili yako tumefika asubuhi, na kwa ajili yako tuko hai, na kwa ajili yako tutakufa na ni kwako tu marejeo.', 'Ewe Mwenyezi Mungu kwa ajili yako tumefika jioni, na kwa ajili yako tumefika asubuhi, na kwa ajili yako tuko hai, na kwa ajili yako tutakufa na ni kwako tu marejeo.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(9, 9, '🍃⚪▫️اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'Anta Rabbee laa \'ilaaha \'illaa \'Anta, khalaqtanee wa \'anaa \'abduka, wa \'anaa \'alaa \'ahdika wa wa\'dika mas-tata\'tu, \'a\'oothu bika min sharri maa sana\'tu, \'aboo\'u laka bini\'matika \'alayya, wa \'aboo\'u bithanbee faghfir lee fa\'innahu laa yaghfiruth-thunooba \'illaa \'Anta.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(10, 10, '🍃⚪▫️اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ', '🍃✨Allaahumma \'innee \'amsaytu \'ush-hiduka wa \'ush-hidu hamalata \'arshika, wa malaa\'ikataka wajamee\'a khalqika, \'annaka \'Antallaahu laa \'ilaaha \'illaa \'Anta wahdaka laa shareeka laka, wa \'anna Muhammadan \'abduka wa Rasooluka.(×04)', 'Ee Allaah! Hakika mimi nimefika jioni; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 'Ee Allaah! Hakika mimi nimefika jioni; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(11, 11, '🍃⚪▫️اللَّهُمَّ مَا أَمْسٰی بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', '🍃✨Allaahumma maa \'amsa bee min ni\'matin \'aw bi\'ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.', 'Ewe Mwenyezi Mungu sikuamka na neema yoyote au kati ya kiumbe chako chochote, na neema ila inatoka kwako, hali ya kuwa peke yako huna mshirika wako, ni zako sifa njema na ni zako shukrani.', 'Ewe Mwenyezi Mungu sikuamka na neema yoyote au kati ya kiumbe chako chochote, na neema ila inatoka kwako, hali ya kuwa peke yako huna mshirika wako, ni zako sifa njema na ni zako shukrani.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(12, 12, '🍃⚪▫️اللَّهُمَّ عَافِنِي فِي بَدََنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفرِ، وَالْفَقْرِ، وَ أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'aafinee fee badanee, Allaahumma \'aafinee fee sam\'ee, Allaahumma \'aafinee fee basaree, laa \'ilaaha \'illaa \'Anta. Allaahumma \'innee \'a\'oothu bika minal-kufri, walfaqri, wa \'a\'oothu bika min \'athaabil-qabri, laa \'ilaaha \'illaa \'Anta.(×03)', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(13, 13, '🍃⚪▫️حَسْبِيَ اللهُ لَآ إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', '🍃✨Hasbiyallaahu laa \'ilaaha \'illaa Huwa \'alayhi tawakkaltu wa Huwa Rabbul-\'Arshil-\'Adheem(×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 7, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(14, 14, '🍃⚪▫️اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', '🍃✨Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fid-dunyaa wal\'aakhirati, Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fee deenee wa dunyaaya wa \'ahlee, wa maalee , Allaahum-mastur \'awraatee, wa \'aamin raw\'aatee, Allaahum-mahfadhnee min bayni yadayya, wa min khalfee, wa \'an yameenee, wa \'an shimaalee, wa min fawqee, wa \'a\'oothu bi\'adhamatika \'an \'ughtaala min tahtee.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(15, 15, '🍃⚪▫️اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّماوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', '🍃✨Allaahumma \'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal\'ardhi, Rabba kulli shay \'in wa maleekahu, \'ash-hadu \'an laa \'ilaaha \'illaa \'Anta, \'a\'oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa \'an \'aqtarifa \'alaa nafsee soo\'an, \'aw \'ajurrahu \'ilaa Muslimin.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(16, 17, '🍃⚪▫️بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', '🍃✨Bismillaahil-lathee laa yadhurru ma\'as-mihi shay\'un fil-\'ardhi wa laa fis-samaa\'i wa Huwas-Samee \'ul- \'Aleem .(×03)', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(17, 18, '🍃⚪▫️رَضِيتُ باللهِ رَبَّاً، وَبِالْإِسْلَامِ دِيناً، وَبِمُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ نَبِيَّاً', '🍃✨Radheetu billaahi Rabban, wa bil-\'Islaami deenan, wa bi-Muhammadin (sallallaahu \'alayhi wa sallama) Nabiyyan.(×03)', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(18, 19, '🍃⚪▫️يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', '🍃✨Yaa Hayyu yaa Qayyoomu birahmatika \'astagheethu \'aslih lee sha\'nee kullahu wa laa takilnee \'ilaa nafsee tarfata \'aynin.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(19, 20, '🍃⚪▫️أَمْسَيْنا وَأَمْسى الْمُلْكُ للہ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ  خَيْرَ  هـَذِهِ اللَّيْلَةِ  فَتْحَهَا، وَنَصْرَهَا وَنُوْرَها، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيْهَا وَشَرِّ مَا بَعْدَهَا', '🍃✨\'Amsayna wa \'amsal-mulku lillaahi Rabbil-\'aalameen, Allaahumma \'innee \'as\'aluka khayra haathihil-laylati: Fathaha wa nasraha wa nooraha, wa barakataha, wa hudaaha, wa\'a\'oothu bika min sharri maafeeha wa sharri maa ba\'daha.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 'Tumeingiliwa na jioni na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(20, 21, 'أَمْسَيْنا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفَاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ', '🍃✨Amsaynaa \'alaa fitratil-\'Islaami wa \'alaa kalimatil-\'ikhlaasi, wa \'alaa deeni Nabiyyinaa Muhammadin (sallallaahu \'alayhi wa sallama), wa \'alaa millati \'abeenaa \'Ibraaheema, haneefan Musliman wa maa kaana minal-mushrikeen.', 'Tumeingia jioni na maumbile ya kiislamu, na neno la ikhlasi, na dini ya Mtume wetu Muhammad(ﷺ) na mila (dini) ya Baba yetu Ibrahim iliyo sawa hali ya kuwa muislamu wala hakuwa ni mwenye kumshirikisha Mwenyezi Mungu.', 'Tumeingia jioni na maumbile ya kiislamu, na neno la ikhlasi, na dini ya Mtume wetu Muhammad(ﷺ) na mila (dini) ya Baba yetu Ibrahim iliyo sawa hali ya kuwa muislamu wala hakuwa ni mwenye kumshirikisha Mwenyezi Mungu.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(21, 25, '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ', '🍃✨Subhaanallaahi wa bihamdihi.(×100)', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 100, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(22, 26, '🍃⚪▫️لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '🍃✨Laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa \'alaa kulli shay\'in Qadeer.(×10)', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 10, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(23, 27, '🍃⚪▫️أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ', '🍃✨\'Astaghfirullaaha wa \'atoobu \'ilayhi.(×100)', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 100, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(24, 28, '🍃⚪▫️أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', '🍃✨A\'oothu bikalimaatil-laahit-taammaati min sharri maa khalaqa.(×03)', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(25, 29, 'الْحَمْدُ لِله وَحْدَهُ ، وَالصَّلَاةُ وَالسَلَامُ عَلَى مَنْ لَا نَبِيَّ بَعْدَهُ', 'Alhamdulillahi wahdah, wassalaatu wassalaamu a\'laa man la nabiyya ba\'adah.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 'Himdi zote anastahiki Allaah pekee, swalah na salamu ziwe juu ya yule ambaye hakuna Nabii mwengine baada yake.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(26, 31, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', '\'A \'oothu billaahi minash-Shaytaanir-rajeem', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 'Najilinda kwa Allaah, kutokamana na shaytwaan aliyefukuzwa mbali.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(27, 32, 'اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allaahu laa \'ilaaha \'illaa Huwal-Hayyul-Qayyoom, laa ta\'khuthuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maa fil-\'ardh, man thai-lathee yashfa\'u \'indahu \'illaa bi\'ithnih, ya\'lamu maa bayna \'aydeehim wa maa khalfahum, wa laa yuheetoona bishay\'im-min \'ilmihi \'illaa bimaa shaa\'a, wasi\'a kursiyyuhus samaawaati wal\'ardh, wa laa ya\'ooduhu hifdhuhumaa, wa Huwal- \'Aliyyul- \'Adheem.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 'Allaah, hapana mungu wa haki mwingine isipokuwa Yeye, aliyehai daima, msimamia kila kitu. Haumchukui usingizi wala kulala. Ni Vyake pekee vilivyomo mbinguni na vilivyomo ardhini. Nani huyu ambaye anashufai mbele Yake bila ya idhini Yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawawezi kuzunguka chochote katika ujuzi Wake isipokuwa kwa alitakalo. Kursiy Yake imeenea mbingu na ardhi wala hakumchoshi kuvihifadhi viwili hivyo – Naye ni yujuu kabisa, ametukuka kabisa.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(28, 33, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ', 'Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu \'Ahad ۞ Allaahus-Samad ۞ Lam yalid wa lam yoolad ۞ Wa lam yakun lahu kufuwan \'ahad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Allaah ni Mmoja pekee ۞ Mwenye kutegemewa kwa haja zote۞ hakuzaa na wala hakuzaliwa na wala haiwi awe na yeyote anayefanana na kulingana Naye.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(29, 34, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ۞', 'Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbil-falaq ۞ Min sharri ma khalaq ۞Wa min sharri ghaasiqin \'ithaa waqab ۞ Wa min sharrin-naffaathaati fil-\'uqad ۞ Wa min sharri haasidin \'ithaa hasad.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa mapambazuko ۞ kutokamana na shari ya alivyoviumba ۞ na kutokamana na shari ya giza linapoingia۞ kutokamana na shari ya wapulizao mafundoni na kutokamana na shari ya hasidi anapohusudu.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(30, 35, 'بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ. قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ', '✨Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbin-naas ۞ Malikin-naas. \'Ilaahin-naas ۞ Min sharril-waswaasil-khannaas ۞ Allathee yuwaswisu fee sudoorin-naas ۞ Minal-jinnati wannaas.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 'Kwa jina la Allaah, Mwingi wa kurehemu, Mwenye kurehemu. Sema: Najilinda na Mola wa watu ۞ mfalme wa watu ۞ mwabudiwa wa haki wa watu ۞ kutokamana na shari za anayetia wasiwasi ۞ mwenye kurejea nyuma ۞ anayetia wasiwasi nyoyoni mwa watu miongoni mwa majini na watu.(×03)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(31, 36, '🍃⚪▫️أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ للهِ وَالْحَمْدُ للهِ، لَا إِلَهَ إِلَّا اللهُ وَحَدْهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، ربِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَومِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَومِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْر', '', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya siku ya leo, kheri ya baada yake, na najilinda Kwako kutokamana na shari ya siku ya leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah, himdi zote ni stahiki ya Allaah, hapana mungu wa haki isipokuwa Allaah, hali ya kuwa yupekee, hana mshirika. Ni Wake ufalme, na ni Zake  himdi zote njema, Naye juu ya kila jambo ni muweza.  Mola wa wangu, nakuomba kheri ya siku ya leo, kheri ya baada yake, na najilinda Kwako kutokamana na shari ya siku ya leo na shari ya baada yake. Mola wangu, najilinda Kwako kutokamana na uvivu na uzee mbaya. Mola wangu, najilinda Kwako kutokamana na adhabu ya Moto na adhabu ya kaburi.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(32, 37, '🍃⚪▫️اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ', '', 'Ee Allaah! Kwako tumepambaukiwa, na Kwako tumeingiliwa na jioni, na kwa ajili Yako ndio tumekuwa hai, na kwa ajili Yako tutakufa na Kwako tutakusanywa.', 'Ee Allaah! Kwako tumepambaukiwa, na Kwako tumeingiliwa na jioni, na kwa ajili Yako ndio tumekuwa hai, na kwa ajili Yako tutakufa na Kwako tutakusanywa.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(33, 38, '🍃⚪▫️اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'Anta Rabbee laa \'ilaaha \'illaa \'Anta, khalaqtanee wa \'anaa \'abduka, wa \'anaa \'alaa \'ahdika wa wa\'dika mas-tata\'tu, \'a\'oothu bika min sharri maa sana\'tu, \'aboo\'u laka bini\'matika \'alayya, wa \'aboo\'u bithanbee faghfir lee fa\'innahu laa yaghfiruth-thunooba \'illaa \'Anta.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 'Ewe mwenyezi Mungu Wewe ni Mola wangu, hapana Mola apasae kuabudiwa kwa haki ila Wewe, umeniumba mimi na mimi ni mja wako, nami niko juu ya ahadi yako, na agano lako, kiasi cha uwezo wangu, najilinda kwako kutokana na shari ya nilicho kifanya, nakiri kwako kwa kunineemesha, na nakiri kwa madhambi yangu, basi nakuomba unisamehe kwani hakuna mwenye kusamehe madhambi ila Wewe.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(34, 39, '🍃⚪▫️اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ(×04)', '', 'Ee Allaah! Hakika mimi nimeamka asubuhi; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 'Ee Allaah! Hakika mimi nimeamka asubuhi; ninakushuhudisha na ninawashuhudia wabeba wa ‘Arshi yako na Malaika Wako, viumbe wako wote, ya kwamba Wewe ni Allaah,  hapana mungu wa haki isipokuwa Wewe, hali ya kuwa upekee yako huna mshirika, na kwamba Muhammad ni mja na Mtume Wako.(×04)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(35, 40, '🍃⚪▫️اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', '🍃✨Allaahumma maa \'amsa bee min ni\'matin \'aw bi\'ahadin min khalqika faminka wahdaka laa shareeka laka, falakal-hamdu wa lakash-shukru.', 'Ee Allaah! Sikuamka na neema yoyote au kutoka kwa kiumbe Chako chochote, si vyenginevyo isipokuwa inatoka Kwako, hali ya kuwa upekee huna mshirika, ni Zako himdi zote njema na ni Zako shukurani.', 'Ee Allaah! Sikuamka na neema yoyote au kutoka kwa kiumbe Chako chochote, si vyenginevyo isipokuwa inatoka Kwako, hali ya kuwa upekee huna mshirika, ni Zako himdi zote njema na ni Zako shukurani.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(36, 41, '🍃⚪▫️اللَّهُمَّ عَافِنِي فِي بَدََنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفرِ، وَالْفَقْرِ، وَ أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', '🍃✨Allaahumma \'aafinee fee badanee, Allaahumma \'aafinee fee sam\'ee, Allaahumma \'aafinee fee basaree, laa \'ilaaha \'illaa \'Anta. Allaahumma \'innee \'a\'oothu bika minal-kufri, walfaqri, wa \'a\'oothu bika min \'athaabil-qabri, laa \'ilaaha \'illaa \'Anta.(×03)', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 'Ewe Mwenyezi Mungu nipe afya ya mwili wangu, Ewe Mwenyezi Mungu nipe afya ya usikizi wangu, Ewe Mwenyezi Mungu nipe afya ya uoni wangu, hapana Mola asae kuabudiwa kwa haki ila Wewe, (mara tatu). Ewe Mwenyezi Mungu hakika mimi najilinda kwako kutokana na ukafiri, na ufakiri, na najilinda kwako kutokana na adhabu ya kaburi, hapana Mola apasae kuabudiwa kwa haki ila Wewe.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(37, 42, '🍃⚪▫️حَسْبِيَ اللهُ لَآ إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', '🍃✨Hasbiyallaahu laa \'ilaaha \'illaa Huwa \'alayhi tawakkaltu wa Huwa Rabbul-\'Arshil-\'Adheem(×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 'Ananitosha Mwenyezi Mungu, hapana Mola apasae kuabudiwa kwa hakiila Yeye, kwake Yeye nimetegemea, na Yeye ni Mola wa arshi tukufu. (×07)', 7, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(38, 43, '🍃⚪▫️اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', '🍃✨Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fid-dunyaa wal\'aakhirati, Allaahumma \'innee \'as\'alukal-\'afwa wal\'aafiyata fee deenee wa dunyaaya wa \'ahlee, wa maalee , Allaahum-mastur \'awraatee, wa \'aamin raw\'aatee, Allaahum-mahfadhnee min bayni yadayya, wa min khalfee, wa \'an yameenee, wa \'an shimaalee, wa min fawqee, wa \'a\'oothu bi\'adhamatika \'an \'ughtaala min tahtee.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 'Ewe Mwenyezi Mungu nakuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi nakuomba msamaha na afya katika dini yangu na dunia yangu na jamaa zangu, na mali zangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu nihifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(39, 44, '🍃⚪▫️اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّماوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', '🍃✨Allaahumma \'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal\'ardhi, Rabba kulli shay \'in wa maleekahu, \'ash-hadu \'an laa \'ilaaha \'illaa \'Anta, \'a\'oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa \'an \'aqtarifa \'alaa nafsee soo\'an, \'aw \'ajurrahu \'ilaa Muslimin.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 'Ewe Mwenyezi Mungu, mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake (wa vitu vyote), nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(40, 45, '🍃⚪▫️بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', '🍃✨Bismillaahil-lathee laa yadhurru ma\'as-mihi shay\'un fil-\'ardhi wa laa fis-samaa\'i wa Huwas-Samee \'ul- \'Aleem .(×03)', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 'Kwa jina la Mwenyezi Mungu ambae hakidhuru kwa jina lake kitu chochote kilichopo ardhini wala mbinguni, nae ni Msikivu na Mjuzi. (×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(41, 46, '🍃⚪▫️رَضِيتُ باللهِ رَبَّاً، وَبِالْإِسْلَامِ دِيناً، وَبِمُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ نَبِيَّاً', '🍃✨Radheetu billaahi Rabban, wa bil-\'Islaami deenan, wa bi-Muhammadin (sallallaahu \'alayhi wa sallama) Nabiyyan.(×03)', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 'Nimeridhia kuwa Ewe Mwenyezi Mungu ndiye Mola wangu, na uislamu ndiyo dini yangu, na Muhammad (ﷺ) kuwa ndiye Mtume wangu.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(42, 47, '🍃⚪▫️يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', '🍃✨Yaa Hayyu yaa Qayyoomu birahmatika \'astagheethu \'aslih lee sha\'nee kullahu wa laa takilnee \'ilaa nafsee tarfata \'aynin.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 'Ewe Uliyehai, Uliyesimama kwa dhati yako, kwa rehema zako ninakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo, kama muda) wa kupepesa jicho.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(43, 48, '🍃⚪▫️أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ: فَتْحَهُ، وَنَصْرَهُ وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيْهِ وَشَرِّ مَا بَعْدَهُ', '', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 'Tumepambaukiwa na umekuwa ufalme ni wa Allaah na ufalme ni wa Allaah, Mola wa walimwengu. Ee Allaah! Hakika mimi nakuomba kheri ya siku hii ya leo, ufunguzi wake, nusura yake, nuru yake, baraka yake, uongofu wake na najilinda Kwako kutokamana na shari ya kilicho ndani  ya siku yake na shari ya baada yake.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(44, 49, '🍃⚪▫️أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَى اللهُ عَلِيهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفَاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ', '', 'Tumepambaukiwa tukiwa juu ya maumbile ya Uislamu, juu ya neno la ikhlaasw, juu ya dini ya Mtume wetu Muhammad (Swalla Allaahu ´alayhi wa sallam), juu ya mila ya baba yetu Ibraahiym, aliyejiepusha na shirki aina zote na akaielekea Tawhiyd, hali  ya kuwa muislamu wala hakuwa miongoni mwa washirikina.', 'Tumepambaukiwa tukiwa juu ya maumbile ya Uislamu, juu ya neno la ikhlaasw, juu ya dini ya Mtume wetu Muhammad (Swalla Allaahu ´alayhi wa sallam), juu ya mila ya baba yetu Ibraahiym, aliyejiepusha na shirki aina zote na akaielekea Tawhiyd, hali  ya kuwa muislamu wala hakuwa miongoni mwa washirikina.', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(45, 50, '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ', '🍃✨Subhaanallaahi wa bihamdihi.(×100)', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 'Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake.(×100).', 100, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(46, 51, '🍃⚪▫️لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '🍃✨Laa \'ilaaha \'illallaahu wahdahu laa shareeka lahu, lahul-mulku wa lahul-hamdu, wa Huwa \'alaa kulli shay\'in Qadeer.(×10)', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 'Hapana Mola apasae kuabudiwa kwa haki ila ni Mwenyezi Mungu peke yake, hana mshirika wake, niwake Ufalme, na ni zake sifa njema zote, na Yeye juu ya kila kitu ni Muweza. (×10¹, au ×01² ukisikia uvivu).', 100, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(47, 52, '🍃⚪▫️أَسْتَغْفِرُ اللهَ وَأَتُوبُ إِلَيْهِ', '🍃✨\'Astaghfirullaaha wa \'atoobu \'ilayhi.(×100)', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 'Nakuomba msamaha Mwenyezi Mungu, na ninarejea kwake. (×100 kwa siku).', 100, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(48, 53, '🍃⚪▫️أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', '🍃✨A\'oothu bikalimaatil-laahit-taammaati min sharri maa khalaqa.(×03)', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 'Alikuwa Mtume (ﷺ) akisema asubuhi na jioni: Najilinda na maneno ya Mwenyezi Mungu yaliyotimia kutokana na shari aliyoiumba.(×03).', 3, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(49, 54, '🍃⚪▫️سُبْحَانَ اللهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ(×03)', '', 'Allaah ametakasika kutokamana na mapungufu yote na himdi zote njema ni Zake kwa idadi ya viumbe Wake, radhi Yake, uzito wa ´Arshi Yake na wino wa maneno Yake.(×03 utapoamka asubuhi)', 'Allaah ametakasika kutokamana na mapungufu yote na himdi zote njema ni Zake kwa idadi ya viumbe Wake, radhi Yake, uzito wa ´Arshi Yake na wino wa maneno Yake.(×03 utapoamka asubuhi)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(50, 55, '🍃⚪▫️اللَّهُمَّ إنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً', '', 'Ee Allaah! Hakika nakuomba elimu yenye kunufaisha, riziki njema na matendo yenye kukubaliwa.(Atasema haya akiamka asubuhi)', 'Ee Allaah! Hakika nakuomba elimu yenye kunufaisha, riziki njema na matendo yenye kukubaliwa.(Atasema haya akiamka asubuhi)', 1, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(51, 56, '🍃⚪▫️اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ(×10)', '', 'Ee Allaah! Msifu Muhammad, wakeze na kizazi chake, kama Ulivyowasifu jamaa zake Ibraahiym. Mbariki  Muhammad, wakeze na kizazi chake kama Ulivyowabariki jamaa zake Ibraahiym. Kwani hakika Wewe ni Mwenye kuhidimiwa na Mwenye kutukuzwa.', 'Ee Allaah! Msifu Muhammad, wakeze na kizazi chake, kama Ulivyowasifu jamaa zake Ibraahiym. Mbariki  Muhammad, wakeze na kizazi chake kama Ulivyowabariki jamaa zake Ibraahiym. Kwani hakika Wewe ni Mwenye kuhidimiwa na Mwenye kutukuzwa.', 10, 0, '2026-09-06 23:55:03', '2026-09-06 23:55:03'),
(64, 57, '🍃🔲▫️بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ۞ قُلْ هُوَ اللهُ أَحَدٌ ۞ اللهُ الصَّمَدُ ۞ لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ۞', '🍃🔳▫️Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu \'Ahad. Allaahus-Samad. Lam yalid wa lam yoolad. Wa lam yakun lahu kufuwan \'ahad.', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Yeye Mwenyezi Mungu ni wa pekee ۞ Mwenyezi Mungu Mkusudiwa ۞ Hakuzaa wala hakuzaliwa ۞ Wala hana anaye fanana naye hata mmoja.{×03}', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Yeye Mwenyezi Mungu ni wa pekee ۞ Mwenyezi Mungu Mkusudiwa ۞ Hakuzaa wala hakuzaliwa ۞ Wala hana anaye fanana naye hata mmoja.{×03}', 3, 0, '2026-09-06 23:59:30', '2026-09-06 23:59:30'),
(65, 57, '🍃🔲▫️بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۞ مِنْ شَرِّ مَا خَلَقَ ۞ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۞ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۞ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ۞', '🍃🔳▫️Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbil-falaq. Min sharri ma khalaq. Wa min sharri ghaasiqin \'ithaa waqab. Wa min sharrin-naffaathaati fil-\'uqad. Wa min sharri haasidin \'ithaa hasad.', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Najikinga kwa Mola Mlezi wa mapambazuko ۞ Na shari ya alivyo viumba ۞ Na shari ya giza la usiku liingiapo ۞ Na shari ya wanao pulizia mafundoni ۞ Na shari ya hasidi anapo husudu.{×03}', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Najikinga kwa Mola Mlezi wa mapambazuko ۞ Na shari ya alivyo viumba ۞ Na shari ya giza la usiku liingiapo ۞ Na shari ya wanao pulizia mafundoni ۞ Na shari ya hasidi anapo husudu.{×03}', 3, 1, '2026-09-06 23:59:30', '2026-09-06 23:59:30'),
(66, 57, '🍃🔲▫️بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ.۞ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۞ مَلِكِ النَّاسِ ۞ إِلَهِ النَّاسِ ۞ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۞ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۞ مِنَ الْجِنَّةِ وَالنَّاسِ۞', '🍃🔳▫️Bismillaahir-Rahmaanir-Raheem. Qul \'a\'oothu birabbin-naas. Malikin-naas. \'Ilaahin-naas. Min sharril-waswaasil-khannaas. Allathee yuwaswisu fee sudoorin-naas. Minal-jinnati wannaas.', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Ninajikinga kwa Mola Mlezi wa wanaadamu ۞ Mfalme wa wanaadamu ۞ Mungu wa wanaadamu ۞ Na shari ya wasiwasi wa Shetani, Khannas ۞ Anaye tia wasiwasi katika vifua vya watu ۞ Kutokana na majini na wanaadamu.{×03}', 'Kwa jina la Mwenyezi Mungu mwingi wa rehema mwenye kurehemu. Sema: Ninajikinga kwa Mola Mlezi wa wanaadamu ۞ Mfalme wa wanaadamu ۞ Mungu wa wanaadamu ۞ Na shari ya wasiwasi wa Shetani, Khannas ۞ Anaye tia wasiwasi katika vifua vya watu ۞ Kutokana na majini na wanaadamu.{×03}', 1, 2, '2026-09-06 23:59:30', '2026-09-06 23:59:30'),
(67, 58, '🍃🔲▫️اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', '🍃🔳▫️Allaahu laa \'ilaaha \'illaa Huwal-Hayyul-Qayyoom, laa ta\'khudhuhu sinatun wa laa nawm, lahu maa fis-samaawaati wa maafil-\'ardh, man dhal-ladhee yashfa\'u \'indahu \'illaa bi\'ithnih, ya\'lamu maa bayna \'aydeehim wa maa khalfahum, wa laa yuheetoona bishay\'im-min \'ilmihi \'illaa bimaa shaa\'a, wasi\'a kursiyyuhus-samaawaati wal\'ardh, wa laa ya\'ooduhu hifdhuhumaa, wa Huwal-\'Aliyyul- \'Adheem.', '(Mwenyezi Mungu -hapana mungu ila Yeye Aliye hai, Msimamia mambo yote milele. Hashikwi na usingizi wala kulala. Ni vyake pekee vyote viliomo mbinguni na duniani. Ni nani huyo awezaye kuombea mbele yake bila ya idhini yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao; wala wao hawajui chochote katika vilio katika ujuzi wake, ila kwa atakalo mwenyewe. Enzi yake imetanda mbinguni na duniani; na wala haemewi na kuvilinda hivyo. Na Yeye ndiye aliye juu, na ndiye Mkuu).', '(Mwenyezi Mungu -hapana mungu ila Yeye Aliye hai, Msimamia mambo yote milele. Hashikwi na usingizi wala kulala. Ni vyake pekee vyote viliomo mbinguni na duniani. Ni nani huyo awezaye kuombea mbele yake bila ya idhini yake? Anayajua yaliyo mbele yao na yaliyo nyuma yao; wala wao hawajui chochote katika vilio katika ujuzi wake, ila kwa atakalo mwenyewe. Enzi yake imetanda mbinguni na duniani; na wala haemewi na kuvilinda hivyo. Na Yeye ndiye aliye juu, na ndiye Mkuu).', 1, 0, '2026-09-07 00:03:29', '2026-09-07 00:03:29');
INSERT INTO `adhkaar_verses` (`id`, `adhkaar_id`, `arabic_text`, `transliteration`, `translation_en`, `translation_sw`, `repeat_count`, `sort_order`, `created_at`, `updated_at`) VALUES
(68, 59, '🍃🔲▫️آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۞ لَا يُكَلِّفُ اللهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', '🍃🔳▫️\'Aamanar-Rasoolu bimaa \'unzila ilaihi mir-Rabbihi walmu\'minoon, kullun \'aamana billaahi wa malaa\'ikatihi wa Kutubihi wa Rusulihi, laa nufarriqu bayna \'ahadim-mir-Rusulihi, wa qaaloo sami\'naa wa \'ata\'naa ghufraanaka Rabbanaa wa \'ilaykal-maseer. Laa yukallifullaahu nafsan \'illaa wus\'ahaa, lahaa maa kasabat wa \'alayhaa mak-tasabat, Rabbanaa laa tu\'aakhithnaa \'in naseenaa \'aw \'akhta\'naa, Rabbanaa wa laa tahmil \'alaynaa \'isran kamaa hamaltahu \'alal-latheena min qablinaa, Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bihi, wa\'fu \'annaa, waghfir lanaa warhamnaa, \'Anta Mawlaanaa fansurnaa \'alal-qawmil-kaafireen.', '”Mtume ameamini yale yaliyoteremshwa kwake kutoka kwa Mola wake na waumini; wote wamemuamini Allaah, na Malaika Wake, na Vitabu Vyake na Mitume Yake [nao husema] ”hatutofautishi kati ya yeyote katika ya Mitume Yake” na wakasema ”Tumesikia na tumetii, tunakuomba msamaha, Mola wetu na Kwako ndiko pa kuishilia.” \'\'Mwenyezi Mungu haikalifishi nafsi yoyote ila kwa kadiri ya iwezavyho. Faida ya iliyo yachuma ni yake, na khasara ya iliyo yachuma ni juu yake pia. (Ombeni:) Mola wetu Mlezi! Usituchukulie tukisahau au tukikosea. Mola wetu Mlezi! Usitubebeshe mzigo kama ulio wabebesha wale walio kuwa kabla yetu. Mola wetu Mlezi Usitutwike tusiyo yaweza, na utusamehe, na utughufirie, na uturehemu. Wewe ndiye Mlinzi wetu. Basi tupe ushindi tuwashinde kaumu ya makafiri\'\'. (Suratul-Baqrah: 2:285-286).', '”Mtume ameamini yale yaliyoteremshwa kwake kutoka kwa Mola wake na waumini; wote wamemuamini Allaah, na Malaika Wake, na Vitabu Vyake na Mitume Yake [nao husema] ”hatutofautishi kati ya yeyote katika ya Mitume Yake” na wakasema ”Tumesikia na tumetii, tunakuomba msamaha, Mola wetu na Kwako ndiko pa kuishilia.” \'\'Mwenyezi Mungu haikalifishi nafsi yoyote ila kwa kadiri ya iwezavyho. Faida ya iliyo yachuma ni yake, na khasara ya iliyo yachuma ni juu yake pia. (Ombeni:) Mola wetu Mlezi! Usituchukulie tukisahau au tukikosea. Mola wetu Mlezi! Usitubebeshe mzigo kama ulio wabebesha wale walio kuwa kabla yetu. Mola wetu Mlezi Usitutwike tusiyo yaweza, na utusamehe, na utughufirie, na uturehemu. Wewe ndiye Mlinzi wetu. Basi tupe ushindi tuwashinde kaumu ya makafiri\'\'. (Suratul-Baqrah: 2:285-286).', 1, 0, '2026-09-07 00:05:28', '2026-09-07 00:05:28'),
(69, 60, '🍃🔲▫️بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ', '🍃🔳▫️Bismika Rabbee wadha\'tu janbee , wa bika \'arfa\'uhu, fa\'in \'amsakta nafsee farhamhaa, wa \'in \'arsaltahaa fahfadhhaa, bimaa tahfadhu bihi \'ibaadakas-saaliheen.', '\"Kwa jina lako Mola wangu, nimeweka ubavu wangu na kwa ajili yako nitaunyanyua, na ukiizuia (ukiichukuwa) roho yangu, basi irehemu, na ukiirudisha basi ihifadhi, kwa kile unacho wahifadhi nacho waja wako wema.\"', '\"Kwa jina lako Mola wangu, nimeweka ubavu wangu na kwa ajili yako nitaunyanyua, na ukiizuia (ukiichukuwa) roho yangu, basi irehemu, na ukiirudisha basi ihifadhi, kwa kile unacho wahifadhi nacho waja wako wema.\"', 1, 0, '2026-09-07 00:07:01', '2026-09-07 00:07:01'),
(70, 61, '🍃🔲▫️اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فََاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ', '🍃🔳▫️Allaahumma \'innaka khalaqta nafsee wa \'Anta tawaffaahaa, laka mamaatuhaa wa mahyaahaa, \'in \'ahyaytahaa fahfadhhaa, wa \'in \'amattahaa faghfir lahaa . Allaahumma \'innee \'as\'alukal-\'aafiyata.', '\"Ewe Mwenyezi Mungu hakika Wewe umeiumba nafsi yangu nawe utaiua, ni kwako uhai wa nafsi yangu na ufaji wake, ukiipa uhai basi ihifadhi, na ukiifisha (ukiiua) basi isamehe. Ewe Mwenyezi Mungu hakika mimi nakuomba afya njema.\"', '\"Ewe Mwenyezi Mungu hakika Wewe umeiumba nafsi yangu nawe utaiua, ni kwako uhai wa nafsi yangu na ufaji wake, ukiipa uhai basi ihifadhi, na ukiifisha (ukiiua) basi isamehe. Ewe Mwenyezi Mungu hakika mimi nakuomba afya njema.\"', 1, 0, '2026-09-07 00:08:26', '2026-09-07 00:08:26'),
(73, 63, '🍃⚪▫️بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', '🍃✨Bismika Allaahumma \'amootu wa \'ahyaa.', 'Kwa jina lako Ewe Mwenyezi Mungu ninakufa na ninakuwa hai.', 'Kwa jina lako Ewe Mwenyezi Mungu ninakufa na ninakuwa hai.', 1, 0, '2026-09-07 00:11:46', '2026-09-07 00:11:46'),
(74, 64, '🍃⚪▫️سُبْحَانَ اللهِ', '🍃✨Subhaanallaah', 'Ametakasika Mwenyezi Mungu(×33)', 'Ametakasika Mwenyezi Mungu(×33)', 33, 0, '2026-09-07 00:15:46', '2026-09-07 00:15:46'),
(75, 64, '🍃⚪▫️الْحَمْدُ للهِ', '🍃✨Alhamdu lillaah', 'Sifa njema zote ni za Mwenyezi Mungu(×33)', 'Sifa njema zote ni za Mwenyezi Mungu(×33)', 33, 1, '2026-09-07 00:15:46', '2026-09-07 00:15:46'),
(76, 64, '🍃⚪▫️اللهُ أَكْبَرُ', '🍃✨Allaahu \'Akbar', 'Mwenyezi Mungu ni mkubwa(×34)', 'Mwenyezi Mungu ni mkubwa(×34)', 34, 2, '2026-09-07 00:15:46', '2026-09-07 00:15:46'),
(79, 67, '🍃⚪▫️للَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاواتِ والْأَرْضَ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', '🍃✨Allaahumma \'Aalimal-ghaybi wash-shahaadati faatiras-samaawaati wal\'ardhi, Rabba kulli shay \'in wa maleekahu, \'ash-hadu \'an laa \'ilaaha \'illaa \'Anta, \'a\'oothu bika min sharri nafsee, wa min sharrish-shaytaani wa shirkihi, wa \'an \'aqtarifa \'alaa nafsee soo \'an, \'aw \'ajurrahu \'ilaa Muslimin.', 'Ewe Mwenyezi Mungu Mjuzi wa yaliyojificha na yaliyo wazi, Muumba wa mbingu na ardhi, Mola wa kila kitu na Mfalme wake, nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako na shari ya nafsi yangu na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 'Ewe Mwenyezi Mungu Mjuzi wa yaliyojificha na yaliyo wazi, Muumba wa mbingu na ardhi, Mola wa kila kitu na Mfalme wake, nakiri kwamba hapana Mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako na shari ya nafsi yangu na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu.', 1, 0, '2026-09-07 00:19:23', '2026-09-07 00:19:23'),
(81, 69, '🍃⚪▫️اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلّا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذی انْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ', '🍃✨Allaahumma \'aslamtu nafsee \'ilayka, wa fawwadhtu \'amree \'ilayka, wa wajjahtu wajhee \'ilayka, wa \'alja\'tu dhahree \'ilayka, raghbatan wa rahbatan \'ilayka, laa malja\' wa laa manja minka \'illaa \'ilayka, \'aamantu bikitaabikal-lathee \'anzalta wa bi-nabiyyikal-lathee \'arsalta.', 'Ewe Mwenyezi Mungu¹ nimeisalimisha nafsi yangu kwako, na nimekuachia mambo yangu Wewe, na nimeuelekeza uso wangu kwako, na nimeutegemeza mgongo wangu kwako, kwa matarajio na kwa kukuogopa, hapana sehemu ya kukimbilia wala ya kujiokoa ila kwako, nimekiamini kitabu chako ulicho kiteremsha, na Mtume wako uliyemtuma².', 'Ewe Mwenyezi Mungu¹ nimeisalimisha nafsi yangu kwako, na nimekuachia mambo yangu Wewe, na nimeuelekeza uso wangu kwako, na nimeutegemeza mgongo wangu kwako, kwa matarajio na kwa kukuogopa, hapana sehemu ya kukimbilia wala ya kujiokoa ila kwako, nimekiamini kitabu chako ulicho kiteremsha, na Mtume wako uliyemtuma².', 1, 0, '2026-09-07 00:23:37', '2026-09-07 00:23:37'),
(82, 62, '🍃⚪▫️اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ', '🍃✨Allaahumma qinee \'athaabaka yawma tab\'athu \'ibaadaka.', '\"Ewe Mwenyezi Mungu nikinge na adhabu yako siku utakayo wafufua waja wako(mara tatu).\"', '\"Ewe Mwenyezi Mungu nikinge na adhabu yako siku utakayo wafufua waja wako(mara tatu).\"', 1, 0, '2026-09-07 00:24:05', '2026-09-07 00:24:05'),
(85, 66, '🍃⚪▫️الْحَمْدُ للهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْويَ', '🍃✨Alhamdu lillaahil-lathee \'at\'amanaa wa saqaanaa, wa kafaanaa, wa \'aawaanaa, fakam mimman laa kaafiya lahu wa laa mu\'wiya.', 'Sifa njema zote ni za Mwenyezi Mungu ambaye ametulisha na ametunywesha na akatutosheleza na akatuhifadhi, ni wangapi ambao hawana wa kuwatosheleza wala wa kuwahifadhi.', 'Sifa njema zote ni za Mwenyezi Mungu ambaye ametulisha na ametunywesha na akatutosheleza na akatuhifadhi, ni wangapi ambao hawana wa kuwatosheleza wala wa kuwahifadhi.', 1, 0, '2026-09-07 00:24:35', '2026-09-07 00:24:35'),
(86, 68, 'سُورَةُ السَّجْدَةِ وَسُورَةُ الْمُلْكِ', '', '', '', 1, 0, '2026-09-07 00:24:53', '2026-09-07 00:24:53'),
(87, 65, '🍃⚪▫️اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أّنْتَ آخِذٌ بِنَاصِيَتهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ', '🍃✨Allaahumma Rabbas-samaawaatis-sab\'i wa Rabbal-\'Arshil-\'Adheem, Rabbanaa wa Rabba kulli shay \'in, faaliqal-habbi wannawaa , wa munzilat-Tawraati wal-\'Injeeli, wal-Furqaani, \'a\'oothu bika min sharri kulli shay \'in \'Anta \'aakhithun binaasiyatihi. Allaahumma \'Antal-\'Awwalu falaysa qablaka shay\'un, wa \'Antal-\'Aakhiru falaysa ba\'daka shay\'un, wa \'Antadh-Dhaahiru falaysa fawqaka shay\'un, wa \'Antal-Baatinu falaysa doonaka shay\'un, iqdhi \'annad-dayna wa \'aghninaa minal-faqri.', 'Ewe Mwenyezi Mungu, Mola wa mbingu saba, na Mola wa arshi tukufu, Mola wetu na Mola wa kila kitu, Mwenye kuichanua tembe ya mbegu na kokwa, na aliye teremsha Taurati na Injili na Qur\'an, najikinga kwako kutokana na shari ya kila kitu, Wewe ndiye mwenye kukamata utosi wake, Ewe Mwenyezi Mungu, Wewe ndiye wa mwanzo hakuna kabla yako kitu, nawe ndiwe wa mwisho, hakuna baada yako kitu, na Wewe ndiye uliye wazihakuna juu yako kitu chochote, na Wewe ndiye uliyefichika hakuna kilichojificha chini yako, tulipie madeni yetu, na utuepushe na ufakiri.', 'Ewe Mwenyezi Mungu, Mola wa mbingu saba, na Mola wa arshi tukufu, Mola wetu na Mola wa kila kitu, Mwenye kuichanua tembe ya mbegu na kokwa, na aliye teremsha Taurati na Injili na Qur\'an, najikinga kwako kutokana na shari ya kila kitu, Wewe ndiye mwenye kukamata utosi wake, Ewe Mwenyezi Mungu, Wewe ndiye wa mwanzo hakuna kabla yako kitu, nawe ndiwe wa mwisho, hakuna baada yako kitu, na Wewe ndiye uliye wazihakuna juu yako kitu chochote, na Wewe ndiye uliyefichika hakuna kilichojificha chini yako, tulipie madeni yetu, na utuepushe na ufakiri.', 1, 0, '2026-09-07 00:25:26', '2026-09-07 00:25:26');

