(121, 9, 12, 'الْحَدِيثُ الثَّامِنُ وَالْعِشْرُونَ', 'hadiyth-ya-28', 'أُوصِيكُمْ بِتَقْوَى اللهِ والسَّمْعِ والطَّاعَةِ{Nakuusieni Kumcha Allaah Na Usikivu Na Utiifu}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 28, 0, 1, 1, '2026-09-16 16:46:59', '2026-08-27 21:02:26', '2026-09-23 22:14:34'),
(122, 9, 12, 'الْحَدِيثُ التَّاسِعُ وَالْعِشْرُونَ', 'hadiyth-ya-29', 'تَعْبُدُ اللهَ لا تُشْرِكُ بِهِ شَيئاً{Muabudu Allaah Na Usimshirikishe Na Chochote}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 29, 0, 1, 1, '2026-09-16 16:47:16', '2026-08-27 21:10:45', '2026-09-23 22:14:34'),
(123, 9, 12, 'الْحَدِيثُ الثَّلَاثُونَ', 'hadiyth-ya-30', 'إنّ اللهَ تَعَالى فَرَضَ فَرَائِضَ فَلاَ تُضَيّعوها{Hakika Allaah Amefaridhisha Faraaidhw  (Mambo Ya Kuwajibika Katika Dini) Basi Msiyapoteze}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 30, 0, 1, 1, '2026-09-16 16:47:33', '2026-08-27 21:12:51', '2026-09-23 22:14:34'),
(124, 9, 12, 'الْحَدِيثُ الْحَادِي وَالثَّلَاثُونَ', 'hadiyth-ya-31', 'ازْهَدْ فِي الدُّنْيَا يُحِبُّكَ اللَّهُ{Ipe Mgongo Dunia Allaah Atakupenda}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 31, 0, 1, 1, '2026-09-16 16:47:46', '2026-08-27 21:16:06', '2026-09-23 22:14:34'),
(125, 9, 12, 'الْحَدِيثُ الثَّانِي وَالثَّلَاثُونَ', 'hadiyth-ya-32', 'لاَ ضَرَرَ وَلاَ ضِرَارَ{Kusiwe Na Kudhuriana Wala Kulipizana Madhara}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 32, 0, 1, 1, '2026-09-16 16:48:00', '2026-08-27 22:31:53', '2026-09-23 22:14:34'),
(126, 9, 12, 'الْحَدِيثُ الثَّالِثُ وَالثَّلَاثُونَ', 'hadiyth-ya-33', 'البَيِّنَةُ على المُدَّعِى والْيَمينُ على من أَنْكَرَ{Jukumu La Ushahidi Liko Kwa Yule Anayedai    Na Kula Kiapo Kunamuwajibikia Yule Anayekanusha}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 33, 0, 1, 1, '2026-09-16 16:48:15', '2026-08-27 22:34:08', '2026-09-23 22:14:34'),
(127, 9, 12, 'الْحَدِيثُ الرَّابِعُ وَالثَّلَاثُونَ', 'hadiyth-ya-34', 'مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ{Atakayeona Munkari Aondoe Kwa Mkono Wake}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 34, 0, 1, 1, '2026-09-16 16:48:34', '2026-08-27 22:36:19', '2026-09-23 22:14:34'),
(128, 9, 12, 'الْحَدِيثُ الْخَامِسُ وَالثَّلَاثُونَ', 'hadiyth-ya-35', 'لا تَحَاسَدُوا، ولا تَنَاجَشُوا، ولا تَباغَضُوا{Msihusudiane Msizidishiane Bei Msibughudhiane}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 35, 0, 1, 1, '2026-09-16 16:48:52', '2026-08-27 22:38:55', '2026-09-23 22:14:34'),
(129, 9, 12, 'الْحَدِيثُ السَّادِسُ وَالثَّلَاثُونَ', 'hadiyth-ya-36', 'مَنْ نَفَّسَ عَنْ مُؤمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيا نَفَّسَ اللهُ عَنْهُ كُرْبَةً من كُرَبِ يوْمِ القيامَةِ{Atakayemuondoshea Muumini Dhiki Za Dunia,  Allaah Atamuondoshea Dhiki Katika Dhiki Za Siku Ya Qiyaamah}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 36, 0, 1, 1, '2026-09-16 16:49:09', '2026-08-27 22:41:48', '2026-09-23 22:14:34'),
(130, 9, 12, 'الْحَدِيثُ السَّابِعُ وَالثَّلَاثُونَ', 'hadiyth-ya-37', 'إِنَّ الله كَتَبَ الحَسَنَاتِ وَالسَّيئَاتِ{Hakika Allaah Kaandika Hasanaat Na Maovu}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 37, 0, 1, 1, '2026-09-16 16:49:23', '2026-08-27 22:43:58', '2026-09-23 22:14:34'),
(131, 9, 12, 'الْحَدِيثُ الثَّامِنُ وَالثَّلَاثُونَ', 'hadiyth-ya-38', 'مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ{Atakayemfanyia Uadui Kipenzi Changu Ninatangaza Vita Dhidi Yake}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 38, 0, 1, 1, '2026-09-16 16:49:39', '2026-08-27 22:45:51', '2026-09-23 22:14:34'),
(132, 9, 12, 'الْحَدِيثُ التَّاسِعُ وَالثَّلَاثُونَ', 'hadiyth-ya-39', 'إنَّ الله تَجاوَزَ لِي عَنْ أُمَّتي الْخَطَأَ والنِّسْياَنَ{Kwa Ajili Yangu Ummah Wangu Kukosea Na Kusahau}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 39, 0, 1, 1, '2026-09-16 16:49:55', '2026-08-27 22:48:00', '2026-09-23 22:14:34'),
(133, 9, 12, 'الْحَدِيثُ الأَرْبَعُونَ', 'hadiyth-ya-40', 'كُنْ في الدُّنْيا كأنَّكَ غَرِيبٌ أو عابرُ سبِيلٍ{Kuwa Duniani Kama Vile Mgeni Au Mpita Njia}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 40, 0, 1, 1, '2026-09-16 16:50:14', '2026-08-27 22:50:21', '2026-09-23 22:14:34'),
(134, 9, 12, 'الْحَدِيثُ الْحَادِي وَالأَرْبَعُونَ', 'hadiyth-ya-41', 'لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعَاً لِمَا جِئْتُ بِهِ{Hatoamini Mmoja Wenu Mpaka Matamanio Yake Yatakapomili Yale Niliyokuja Nayo}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 41, 0, 1, 1, '2026-09-16 16:50:40', '2026-08-27 22:52:54', '2026-09-23 22:14:34'),
(135, 9, 12, 'الْحَدِيثُ الثَّانِي وَالأَرْبَعُونَ', 'hadiyth-ya-42', 'يَا ابْنَ آدَمَ إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ{Ee Bin Aadam! Madamu Utaniomba  Na Kutaraji Kwangu Nitakughufuria}', 'Content divided into parts below.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'published', 2, 2, 42, 0, 1, 1, '2026-09-24 15:45:06', '2026-08-27 22:55:19', '2026-09-24 22:45:12'),
