--
-- Table structure for table `content_parts`
--

CREATE TABLE `content_parts` (
  `id` int NOT NULL,
  `content_id` bigint NOT NULL,
  `part_number` int NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `arabic_body` longtext COLLATE utf8mb4_unicode_ci,
  `arabic_body_html` text COLLATE utf8mb4_unicode_ci,
  `swahili_body` longtext COLLATE utf8mb4_unicode_ci,
  `swahili_body_html` text COLLATE utf8mb4_unicode_ci,
  `section_order` enum('arabic_first','swahili_first') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'arabic_first',
  `audio_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int DEFAULT '0',
  `display_mode` enum('sections','combined') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sections',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

