--
-- Table structure for table `part_sections`
--

CREATE TABLE `part_sections` (
  `id` int NOT NULL,
  `part_id` int NOT NULL,
  `section_number` int NOT NULL DEFAULT '0',
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `content_html` longtext COLLATE utf8mb4_unicode_ci,
  `language` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'swahili',
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ltr',
  `sort_order` int NOT NULL DEFAULT '0',
  `text_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `background_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `video_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_caption` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_separate` tinyint(1) NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

