-- Dumping data for table `part_sections`
--

INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(16, 393, 1, 'Asili yakeJina lake ni Abul-Husayn Muhammad bin ‘Abdil-Wahhaab bin Sulaymaan bin ‘Aliy Musharrif Al-Wuhaybiy. Kabila lake ni Bani Tamiym. Amezaliwa mwaka 1115 H (1704 M) katika mji ya ‘Uyaynah kijiji cha Yamaamah ndani ya Najd, kaskazini Magharibi ya mji wa Riyadhw, Saudi Arabia. Ametoka katika familia ya Wanavyuoni kwani baba yake ‘Abdul-Wahhaab alikuwa ni Mwanachuoni maarufu wa Najd na Qaadhwi wa mji huo.', '<ol><li><strong>Asili yake</strong><br>Jina lake ni Abul-Husayn Muhammad bin ‘Abdil-Wahhaab bin Sulaymaan bin ‘Aliy Musharrif Al-Wuhaybiy. <br>Kabila lake ni Bani Tamiym. Amezaliwa mwaka 1115 H (1704 M) katika mji ya ‘Uyaynah <strong>kijiji cha Yamaamah ndani ya Najd, kaskazini Magharibi ya mji wa Riyadhw, </strong>Saudi Arabia. <br>Ametoka katika familia ya Wanavyuoni kwani baba yake ‘Abdul-Wahhaab alikuwa ni Mwanachuoni maarufu wa Najd na Qaadhwi wa mji huo.</li></ol>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 12:31:45', '2026-08-24 12:31:45', NULL, NULL, NULL, 0),
(17, 393, 2, '2.Elimu YakeAlijifunza kusoma Qur-aan alipokuwa na umri mdogo na akaihifadhi akiwa chini ya umri wa miaka kumi. Na Allaah (سبحانه وتعالى) Alimjaalia kuwa na uhodari na akili nzuri, wepesi wa kufahamu na kumaizi jambo au somo. Alipendezewa mno kusoma kazi za Shaykhul-Islaam Ibn Taymiyyah na mwanafunzi wake Ibnul-Qayyim (رحمهما الله).Alifanya bidii kwenye masomo yake na kuendelea kujifunza chini ya usimamizi wa baba yake. Akajifunza elimu ya Dini chini ya Wanavyuoni walioko mjini mwake wakiwemo baba yake na ‘ammiy yake. Alisafiri kutoka kwenda Madiynah kusoma chini ya Wanavyuoni wakubwa wa huko wakiwemo; Shaykh ‘Abdullaah bin Ibraahiym bin Ash-Shamariyyi, na Mwanachuoni maarufu wa India Shaykh Muhammad Hayaat Al-Sindi. Alikwenda Makkah pia na alitekeleza Hajj. Hatimaye akaelekea Baswrah (Kaskazini Iraq) kutafuta elimu zaidi akasoma chini ya Wanavyuoni wa huko akawa maarufu kwa mijadala baina yake na Wanavyuoni.', '<p><strong>2.Elimu Yake</strong><br>Alijifunza kusoma Qur-aan alipokuwa na umri mdogo na akaihifadhi akiwa chini ya umri wa miaka kumi. <br>Na Allaah (سبحانه وتعالى) Alimjaalia kuwa na uhodari na akili nzuri, wepesi wa kufahamu na kumaizi jambo au somo. <br>Alipendezewa mno kusoma kazi za Shaykhul-Islaam Ibn Taymiyyah na mwanafunzi wake Ibnul-Qayyim (رحمهما الله).</p><p>Alifanya bidii kwenye masomo yake na kuendelea kujifunza chini ya usimamizi wa baba yake.<br> Akajifunza elimu ya Dini chini ya Wanavyuoni walioko mjini mwake wakiwemo baba yake na ‘ammiy yake. <br>Alisafiri kutoka kwenda Madiynah kusoma chini ya Wanavyuoni wakubwa wa huko wakiwemo; Shaykh ‘Abdullaah bin Ibraahiym bin Ash-Shamariyyi, na Mwanachuoni maarufu wa India Shaykh Muhammad Hayaat Al-Sindi. <br>Alikwenda Makkah pia na alitekeleza Hajj. Hatimaye akaelekea Baswrah (Kaskazini Iraq) kutafuta elimu zaidi akasoma chini ya Wanavyuoni wa huko akawa maarufu kwa mijadala baina yake na Wanavyuoni.</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 12:31:45', '2026-08-24 12:31:45', NULL, NULL, NULL, 0),
(39, 394, 1, 'Watu wa Najd walikuwa katika shirki na bid’ah (uzushi). Walikuwa wakiabudu miungu mingi na kuabudu makaburi, miti, mawe, mapango, majini na mashaytwaan, waja wema waliojulikana kama ni mawalii. Uchawi na unajimu (utabiri wa nyota) ulisambaa pia. Hakuna aliyekataza ‘iIbaadah potofu hizo kwani watu walikuwa katika kuchuma manufaa na starehe za dunia zaidi na wakakhofia kuyapoteza hayo. Hivyo Shaykh akaona umuhimu mkubwa uliohitajika kuwarudisha watu katika manhaj ya Qur-aan na Sunnah. Akaanza kuwalingania watu katika Tawhiyd - kumpwekesha Allaah (سبحانه وتعالى) bila ya kumshirikisha na lolote katika ‘ibaadah. Akaazimia kujitumikisha peke yake kwa uvumilivu katika konde. Akajua hakuna lolote kitachofaulu kufanyika ila jihaad katika njia ya Allaah.', '<p>Watu wa Najd walikuwa katika shirki na bid’ah (uzushi). <br>Walikuwa wakiabudu miungu mingi na kuabudu makaburi, miti, mawe, mapango, majini na mashaytwaan, waja wema waliojulikana kama ni mawalii. <br><br>Uchawi na unajimu (utabiri wa nyota) ulisambaa pia. Hakuna aliyekataza ‘iIbaadah potofu hizo kwani watu walikuwa katika kuchuma manufaa na starehe za dunia zaidi na wakakhofia kuyapoteza hayo. Hivyo Shaykh akaona umuhimu mkubwa uliohitajika kuwarudisha watu katika manhaj ya Qur-aan na Sunnah. <br><br>Akaanza kuwalingania watu katika Tawhiyd - kumpwekesha Allaah (<strong>سبحانه وتعالى</strong>) bila ya kumshirikisha na lolote katika ‘ibaadah. Akaazimia kujitumikisha peke yake kwa uvumilivu katika konde. Akajua hakuna lolote kitachofaulu kufanyika ila jihaad katika njia ya Allaah.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(40, 394, 2, 'Shaykh alikumbana na mitihani, misukosuko, na vitisho, lakini alikuwa ameshategemea hali hiyo kumfikia na alikuwa tayari kukabaliana nayo kwani alitambua kuwa hilo ni jambo lisiloepukika kwa kila mlinganiaji kwani ndio hali waliyokutana nayo Manabii wote, na Salafus-Swaalih (waja wema waliotangulia).', '<p>Shaykh alikumbana na mitihani, misukosuko, na vitisho, lakini alikuwa ameshategemea hali hiyo kumfikia na alikuwa tayari kukabaliana nayo kwani alitambua kuwa hilo ni jambo lisiloepukika kwa kila mlinganiaji kwani ndio hali waliyokutana nayo Manabii wote, na Salafus-Swaalih (waja wema waliotangulia).</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(41, 395, 1, 'Miongoni mwa mitihani aliyokumbana nayo ni kutokana na Wanavyuoni wadhaifu wasiokuwa na hoja ambao walimpinga na kumfanya akabiliane na misukosuko, vitisho na kukasirikiwa. Pia alikabiliana na misukosuko na mateso chini ya mikono ya madhalimu wa Huraymilaa. Na alipowashawishi watawala wahukumu madhalimu kwa Shariy’ah ya Kiislamu, ilisababisha baadhi ya watu kuyaweka maisha yake hatiani lakini Allaah (سبحانه وتعالى) Alimnusuru.', '<p><strong>Miongoni mwa mitihani aliyokumbana nayo ni kutokana na Wanavyuoni </strong>wadhaifu wasiokuwa na hoja ambao walimpinga na kumfanya akabiliane na misukosuko, vitisho na kukasirikiwa. <br><br>Pia alikabiliana na misukosuko na mateso chini ya mikono ya madhalimu wa Huraymilaa. Na alipowashawishi watawala wahukumu madhalimu kwa Shariy’ah ya Kiislamu, ilisababisha baadhi ya watu kuyaweka maisha yake hatiani lakini Allaah (<strong>سبحانه وتعالى</strong>) Alimnusuru.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(42, 395, 2, 'Aliamua kurudi kwao ‘Uyaynah, ambako kipindi hicho kulikuwa chini ya utawala wa mtoto wa Mfalme ‘Uthmaan bin Muhammad bin Mu’ammar, ambaye alimpokea Shaykh kwa ukarimu na kumuahidi kumuunga mkono na kumsaidia kuwaita watu katika Uislam. Akaendelea kufundisha na kutoa da’wah hatimaye akashawishika kidhati na kwa vitendo kuondoa dini ya miungu mingi pale alipoona baadhi ya watu ni wagumu kurudi katika Uislamu. Aliweza kumshawishi gavana wa mji huo kulivunja zege lililojengewa juu ya kaburi la Zayd bin Al-Khattwaab ambaye alikuwa ni kaka wa ‘Umar bin Al-Khattwaab (رضي الله عنهما). Akavunjavunja mangome mengineyo, mapango, miti n.k. Akaamrisha Shariy’ah ya Kiislamu itekelezwe kama kumpiga mawe hadi afe mwanamke aliyekiri uzinifu.', '<p>Aliamua kurudi kwao ‘Uyaynah, ambako kipindi hicho kulikuwa chini ya utawala wa mtoto wa Mfalme ‘Uthmaan bin Muhammad bin Mu’ammar, ambaye alimpokea Shaykh kwa ukarimu na kumuahidi kumuunga mkono na kumsaidia kuwaita watu katika Uislam. <br><br>Akaendelea kufundisha na kutoa da’wah hatimaye akashawishika kidhati na kwa vitendo kuondoa dini ya miungu mingi pale alipoona baadhi ya watu ni wagumu kurudi katika Uislamu. Aliweza kumshawishi gavana wa mji huo kulivunja zege lililojengewa juu ya kaburi la Zayd bin Al-Khattwaab ambaye alikuwa ni kaka wa ‘Umar bin Al-Khattwaab <strong>(رضي الله عنهما)</strong>. <br><br>Akavunjavunja mangome mengineyo, mapango, miti n.k. Akaamrisha Shariy’ah ya Kiislamu itekelezwe kama kumpiga mawe hadi afe mwanamke aliyekiri uzinifu.</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(43, 395, 3, 'Shaykh aliendelea na harakati zake za kauli na ‘amali ambazo zilimfanya azidi kuwa maarufu. Hatimaye akawa Jaji (Qaadhwiy) wa mji wa ‘Uyaynah. Lakini hakuweza kuendelea hapo kwani Mfalme alishawishiwa na viongozi wa miji ya jirani amuue Shaykh kwa vile hawakupendezewa na da’wah yake. Ikabidi afukuzwe katika mji huo.', '<p>Shaykh aliendelea na harakati zake za kauli na ‘amali ambazo zilimfanya azidi kuwa maarufu. <br><br>Hatimaye akawa Jaji (Qaadhwiy) wa mji wa ‘Uyaynah. <br><br>Lakini hakuweza kuendelea hapo kwani Mfalme alishawishiwa na viongozi wa miji ya jirani amuue Shaykh kwa vile hawakupendezewa na da’wah yake. Ikabidi afukuzwe katika mji huo.</p>', 'swahili', 'ltr', 3, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(44, 396, 1, 'Akakaribishwa mji wa Ad-Dir’iyyah ambao ulikuwa ni jirani yake. Huko akakaribishwa ingawa kwanza alitiliwa shaka. Alifikia kwa mja mwema aliyempokea ila alimkhofia kutokukubaliwa na mtoto wa Mfalme Muhammad bin Sa’uwd.  Habari zikamfikia kwanza mke wa Ibn Sa’uwd ambaye alikuwa mkarimu na mwenye taqwa. Akamfahamisha mumewe kwa kumwambia, “Hii tawfiyq kubwa umeletewa kutoka kwa Allaah (سبحانه وتعالى) mtu ambaye anawaita watu katika Uislamu, anawaita katika Qur-aan na Sunnah za Rasuli wa Allaah (صلى الله عليه وآله وسلم). Tawfiyq iliyoje? Mkimbilie haraka na umuunge mkono wala usimpinge au kumkataza kwa hayo”. Muhammad Ibn Sa’uwd akakubali ushauri wa mkewe na akaenda kwa Shaykh na akafanya mkataba naye kwamba asiondoke nchini hapo. Ndipo Shaykh akaweka makazi yake hapo na kuendelea na da’wah. Akaendelea na harakati za da’awah hapo Dar’iyyah. Akaheshimika na kupendwa mno na akaungwa mkono na watu. Da’wah yake iliwaathiri na kuwapendezea mno watu. Ikaenea katika nchi za Kiislamu na nyinginezo. Wakimiminika watu kufika hapo Dar’iyyah kujifunza kwake.', '<p>Akakaribishwa mji wa Ad-Dir’iyyah ambao ulikuwa ni jirani yake. <br>Huko akakaribishwa ingawa kwanza alitiliwa shaka. Alifikia kwa mja mwema aliyempokea ila alimkhofia kutokukubaliwa na mtoto wa Mfalme Muhammad bin Sa’uwd.  <br><br>Habari zikamfikia kwanza mke wa Ibn Sa’uwd ambaye alikuwa mkarimu na mwenye taqwa. Akamfahamisha mumewe kwa kumwambia, “Hii tawfiyq kubwa umeletewa kutoka kwa Allaah (<strong>سبحانه وتعالى</strong>) mtu ambaye anawaita watu katika Uislamu, anawaita katika Qur-aan na Sunnah za Rasuli wa Allaah (<strong>صلى الله عليه وآله وسلم</strong>).</p><p><br> Tawfiyq iliyoje? Mkimbilie haraka na umuunge mkono wala usimpinge au kumkataza kwa hayo”. Muhammad Ibn Sa’uwd akakubali ushauri wa mkewe na akaenda kwa Shaykh na akafanya mkataba naye kwamba asiondoke nchini hapo.<br><br> Ndipo Shaykh akaweka makazi yake hapo na kuendelea na da’wah. A<strong>kaendelea na harakati za da’awah hapo Dar’iyyah. Akaheshimika na kupendwa mno na akaungwa mkono na watu. Da’wah yake iliwaathiri na kuwapendezea mno watu. Ikaenea katika nchi za Kiislamu na nyinginezo. Wakimiminika watu kufika hapo Dar’iyyah kujifunza kwake.</strong></p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(45, 396, 2, 'Kama ijulikanavyo kila jema halikosi mitihani. Wakatokeza wapinzani na waliokuwa na chuki naye. Kulikuweko waliompinga da’wah yake ya kuondosha shirki na bid’ah na kuwaita watu katika Tawhiyd. Na wengineo waliompinga kabisa ni kwa sababu ya kuhofu kufukuzwa katika nafasi au vyeo vyao vya kazi. Kwa hiyo wengine walimpinga kwa ajili ya Dini, na wengine walimpinga kisiasa. Wapinzani wake walimzushia ya kumzushia walifika hadi kudai kwamba Shaykh alikuwa ni mfuasi wa Khawaarij. Na mara nyingine wakimlaumu bure bila ya dalili na nje ya upeo wa elimu zao. Hivyo yakaweko malumbano na majibishano yaliyoendelea katika mijadala kadhaa. Shaykh aliwaandikia kuwajibu madai yao, na wao walimrudishia majibu na yeye akawa akiwathibitishia ufahamu wao mbaya wa shariy’ah na Dini kwa ujumla kwa dalili. Ndipo wingi wa maswali na majibu yakawajumuisha watu na wakazidi kuongezeka. Baadhi ya mijadala hiyo iliandikwa na kuchapishwa katika vitabu.', '<p><strong>Kama ijulikanavyo kila jema halikosi mitihani. Wakatokeza wapinzani na waliokuwa na chuki naye. Kulikuweko waliompinga da’wah yake ya kuondosha shirki na bid’ah na kuwaita watu katika Tawhiyd. </strong><br><br><strong>Na wengineo </strong>waliompinga kabisa ni kwa sababu ya kuhofu kufukuzwa katika nafasi au vyeo vyao vya kazi. Kwa hiyo wengine walimpinga kwa ajili ya Dini, na wengine walimpinga kisiasa. Wapinzani wake walimzushia ya kumzushia walifika hadi kudai kwamba Shaykh alikuwa ni mfuasi wa Khawaarij. <br><br>Na mara nyingine wakimlaumu bure bila ya dalili na nje ya upeo wa elimu zao. Hivyo yakaweko malumbano na majibishano yaliyoendelea katika mijadala kadhaa. Shaykh aliwaandikia kuwajibu madai yao, na wao walimrudishia majibu na yeye akawa akiwathibitishia ufahamu wao mbaya wa shariy’ah na Dini kwa ujumla kwa dalili.<br><br> Ndipo wingi wa maswali na majibu yakawajumuisha watu na wakazidi kuongezeka. Baadhi ya mijadala hiyo iliandikwa na kuchapishwa katika vitabu.</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 12:35:34', '2026-08-24 12:35:34', NULL, NULL, NULL, 0),
(54, 398, 1, 'Athari Ya Da’wah yake Da’wah yake ya takriban miaka 50 imedhihirika na kuleta athari kubwa kwanza kwa Waislamu wa zama hizo. Watu waliacha kuabudu makaburi, miti, mawe, majini, waliacha utabiri wa nyota na kila aina ya shirki. Imewatoa pia watu katika ujinga wa kufuata mila za mababu bila ya dalili.  Maamrisho ya mema na makatazo ya maovu yakalinganiwa katika Misikiti. Na hapo msimamo wa Qur-aan na Sunnah ukahuishwa na shirki na bid’ah zikatoweka. Amani na utulivu ukawafunika watu kila mahali. Na mpaka sasa da’wah yake imekuwa na umuhimu mkubwa katika jamii ya Kiislamu. Vijana khasa kutoka nchi za Magharibi na zaidi wale wanaosilimu wamekuwa na hamasa na shauku kubwa ya kujifunza Dini iliyo sahihi na si ile iliyochanganywa na shirki na bid’ah. Kwa hiyo, mafundisho ya msimamo wake wa Ahlus-Sunnah wal-Jama’ah yamekuwa kipaumbele katika lengo la kutafuta elimu kwa Waislamu watakao na wapendao haki.', '<p><strong>Athari Ya Da’wah yake</strong><br> Da’wah yake ya takriban miaka 50 imedhihirika na kuleta athari kubwa kwanza kwa Waislamu wa zama hizo. Watu waliacha kuabudu makaburi, miti, mawe, majini, waliacha utabiri wa nyota na kila aina ya shirki.<br><br> Imewatoa pia watu katika ujinga wa kufuata mila za mababu bila ya dalili.  Maamrisho ya mema na makatazo ya maovu yakalinganiwa katika Misikiti. Na hapo msimamo wa Qur-aan na Sunnah ukahuishwa na shirki na bid’ah zikatoweka.<br><br> Amani na utulivu ukawafunika watu kila mahali. Na mpaka sasa da’wah yake imekuwa na umuhimu mkubwa katika jamii ya Kiislamu. Vijana khasa kutoka nchi za Magharibi na zaidi wale wanaosilimu wamekuwa na hamasa na shauku kubwa ya kujifunza Dini iliyo sahihi na si ile iliyochanganywa na shirki na bid’ah. <br><br>Kwa hiyo, mafundisho ya msimamo wake wa Ahlus-Sunnah wal-Jama’ah yamekuwa kipaumbele katika lengo la kutafuta elimu kwa Waislamu watakao na wapendao haki.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 16:27:38', '2026-08-24 16:27:38', NULL, NULL, NULL, 0),
(55, 398, 2, 'Kazi zakeAmeandika vitabu vingi vya mafunzo mbali mbali lakini alitilia mkazo zaidi katika somo la Tawhiyd na ‘Aqiydah. Na alitumia hikmah ya kuandika vitabu vidogo vidogo lakini vilivyokusanya nukta muhimu kabisa. Vilikuwa ni mukhtasari wa maudhui aliyotaka kuidhihirisha. Na vitabu hivyo vimekuja kufafanuliwa kwa kushereheshwa na ‘Ulamaa kadhaa na vimekuwa vina umuhimu mno katika vyuo vya Kiislamu vinavyofuata mwendo wa Ahlus-Sunnah wal-Jama’ah. Vifuatavyo ni baadhi ya vitabu vyake maarufu. Vinne vya mwanzo ni ambavyo mashuhuri zaidi. Na vinginevyo vimekusanywa na kujumuishwa katika ‘Maj’muw’at Mu-allafaatil-Imaam Muhammad bin ‘Abdil-Wahhaab’.1.      Kitaabut-Tawhiyd - kitabu hiki kimekuwa mashuhuri mno na kimeenea sana na somo lake limekuwa ni lenye kutoa mafunzo muhimu kuhusu kumpwekesha Allaah na kuepukana na shirki. 2.      Al-Uswuul Ath-Thalaathah – kitabu kitoacho mafunzo kuhusu asili au misingi ya Uislamu. 3.      Al-Qawaaid Al-Arba’ - kinatoa mafunzo ya kanuni za ufahamu wa shirki kwa ujumla. 4.      Kashf Ash-Shubuhaat - kinakanusha hoja zinazojulikana na watetezi wa shirki na bid’ah. 5.      Mukhtaswar Al-Inswaaf was-Sharh Al-Kabiyr 6.      Mukhtaswar Zaad Al-Ma’aad 7.      Mukhtaswar As-Siyrah 8.      Mukhtaswar al-Fat-h 9.       Masaail Al-Jaahiliyyah 10.   Adaab Al-Mashiy ilaa as-Swalaah 11.  Nawaaqidhw Al-Islaam', '<p><strong>Kazi zake</strong><br>Ameandika vitabu vingi vya mafunzo mbali mbali lakini alitilia mkazo zaidi katika somo la Tawhiyd na ‘Aqiydah. <br><br>Na alitumia hikmah ya kuandika vitabu vidogo vidogo lakini vilivyokusanya nukta muhimu kabisa. Vilikuwa ni mukhtasari wa maudhui aliyotaka kuidhihirisha. <br>Na vitabu hivyo vimekuja kufafanuliwa kwa kushereheshwa na ‘Ulamaa kadhaa na vimekuwa vina umuhimu mno katika vyuo vya Kiislamu vinavyofuata mwendo wa Ahlus-Sunnah wal-Jama’ah.<br> </p><p>Vifuatavyo ni baadhi ya vitabu vyake maarufu. Vinne vya mwanzo ni ambavyo mashuhuri zaidi. Na vinginevyo vimekusanywa na kujumuishwa katika <i>‘Maj’muw’at Mu-allafaatil-Imaam Muhammad bin ‘Abdil-Wahhaab’.</i></p><p>1.      <i>Kitaabut-Tawhiyd</i> - kitabu hiki kimekuwa mashuhuri mno na kimeenea sana na somo lake limekuwa ni lenye kutoa mafunzo muhimu kuhusu kumpwekesha Allaah na kuepukana na shirki.<br> </p><p>2.      <i>Al-Uswuul Ath-Thalaathah</i> – kitabu kitoacho mafunzo kuhusu asili au misingi ya Uislamu.<br> </p><p>3.      <i>Al-Qawaaid Al-Arba’</i> - kinatoa mafunzo ya kanuni za ufahamu wa shirki kwa ujumla.<br> </p><p>4.      <i>Kashf Ash-Shubuhaat</i> - kinakanusha hoja zinazojulikana na watetezi wa shirki na bid’ah.<br> </p><p><i>5.      Mukhtaswar Al-Inswaaf was-Sharh Al-Kabiyr</i><br> </p><p><i>6.      Mukhtaswar Zaad Al-Ma’aad</i><br> </p><p><i>7.      Mukhtaswar As-Siyrah</i><br> </p><p><i>8.      Mukhtaswar al-Fat-h</i><br> </p><p><i>9.      </i> <i>Masaail Al-Jaahiliyyah</i><br> </p><p><i>10.  </i> <i>Adaab Al-Mashiy ilaa as-Swalaah</i><br> </p><p><i>11.  Nawaaqidhw Al-Islaam</i></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 16:27:38', '2026-08-24 16:27:38', NULL, NULL, NULL, 0),
(56, 399, 1, 'Wanafunzi wakeAlikuwa na wanafunzi wengi mno. Miongoni mwao ni watoto na wajukuu wake ambao waliendeleza kazi yake ya da’wah na Jihaad katika njia ya Allaah, walifungua vyuo karibu na kwao wakifunza watu masomo ya Dini. Kati ya watoto wake ni Husayn, ‘Aliy, ‘Abdullaah na Ibraahiym. Na kati ya wajukuu wake ni ‘Aliy bin Husayn, na pia ‘Abdur-Rahmaan bin Hasan aliyeandika kitabu cha ‘Fat-h Al-Majiyd Sharh Kitaab At-Tawhiyd’. Wanafunzi wake wengineo ni ‘Abdul-‘Aziyz bin Muhammad bin Sa’uwd, Hamad bin Naaswir bin Mu’ammar na ‘Abdul-‘Aziyz bin ‘Abdillaah bin Husayn.', '<p><strong>Wanafunzi wake</strong><br>Alikuwa na wanafunzi wengi mno. Miongoni mwao ni watoto na wajukuu wake ambao waliendeleza kazi yake ya da’wah na Jihaad katika njia ya Allaah, walifungua vyuo karibu na kwao wakifunza watu masomo ya Dini. Kati ya watoto wake ni Husayn, ‘Aliy, ‘Abdullaah na Ibraahiym.<br><br> Na kati ya wajukuu wake ni ‘Aliy bin Husayn, na pia ‘Abdur-Rahmaan bin Hasan aliyeandika kitabu cha <i>‘Fat-h Al-Majiyd Sharh Kitaab At-Tawhiyd’</i>. Wanafunzi wake wengineo ni ‘Abdul-‘Aziyz bin Muhammad bin Sa’uwd, Hamad bin Naaswir bin Mu’ammar na ‘Abdul-‘Aziyz bin ‘Abdillaah bin Husayn<strong>.</strong></p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-24 16:39:01', '2026-08-24 16:39:01', NULL, NULL, NULL, 0),
(57, 399, 2, 'Familia YakeAlikuwa na watoto sita; Husayn, ‘Abdullaah, Hasan, ‘Aliy, Ibraahiym, ‘Abdul-‘Aziyz. Shaykh anatokana na kizazi kinachojulikana kwa ‘Aal-Shaykh’ ambacho kimetoa Wanavyuoni kadhaa akiwemo Shaykh Muhammad bin Ibraahiym Aal-Shaykh aliyekuwa Mufti mkuu wa awali Saudi Arabia na Shaykh ‘Abdul-‘Aziyz Aal-Shaykh  ambaye ni Mufti mkuu wa sasa.', '<p><strong>Familia Yake</strong><br>Alikuwa na watoto sita; Husayn, ‘Abdullaah, Hasan, ‘Aliy, Ibraahiym, ‘Abdul-‘Aziyz. Shaykh anatokana na kizazi kinachojulikana kwa ‘Aal-Shaykh’ ambacho kimetoa Wanavyuoni kadhaa akiwemo Shaykh Muhammad bin Ibraahiym Aal-Shaykh aliyekuwa Mufti mkuu wa awali Saudi Arabia na Shaykh ‘Abdul-‘Aziyz Aal-Shaykh  ambaye ni Mufti mkuu wa sasa<strong>.</strong></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-24 16:39:01', '2026-08-24 16:39:01', NULL, NULL, NULL, 0),
(58, 399, 3, 'Kifo ChakeAlifariki mwaka 1206 H (1792 M) akiwa na umri wa miaka 91. Rahmah za Allaah ziwe juu yake na Allaah Amruzuku Jannah ya Firdaws. Aamiyn.', '<p><strong>Kifo Chake</strong><br>Alifariki mwaka 1206 H (1792 M) akiwa na umri wa miaka 91. Rahmah za Allaah ziwe juu yake na Allaah Amruzuku Jannah ya Firdaws. Aamiyn.</p><p><br> </p>', 'swahili', 'ltr', 3, '#1f2937', '#ffffff', '2026-08-24 16:39:01', '2026-08-24 16:39:01', NULL, NULL, NULL, 0),
(155, 329, 1, '﴿١﴾ عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:«إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.»', '<p>﴿١﴾ عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:<strong>«إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.»</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(156, 329, 2, 'Kutoka kwa Amiri wa Waumini, Abu Hafs Umar bin Al-Khattāb — Mwenyezi Mungu amemridhia — alisema:Nilimsikia Rasuli wa Mwenyezi Mungu — Mwenyezi Mungu amrehemu na amsalimie — akisema:«Hakika matendo yote yanategemea nia (makusudi ya moyo), na hakika kila mtu atapata (malipo au matokeo) ya aliyonuiya. Basi mwenye kuhamia (kwa Hijra) kwake ikiwa ni kwa ajili ya Mwenyezi Mungu na Mtume Wake, basi uhamiaji wake ni kwa ajili ya Mwenyezi Mungu na Mtume Wake (atapewa thawabu ya Hijra). Na mwenye kuhamia kwake ikiwa ni kwa ajili ya dunia atakayoipata, au kwa ajili ya mwanamke atakayemuoa, basi uhamiaji wake ni kwa kile alichohamia kwa ajili yake (hatapewa thawabu ya Hijra, bali atapata kile alichokusudia tu).»', '<p> Kutoka kwa <strong>Amiri wa Waumini, Abu Hafs Umar bin Al-Khattāb</strong> — Mwenyezi Mungu amemridhia — alisema:</p><blockquote><p>Nilimsikia <strong>Rasuli wa Mwenyezi Mungu</strong> — Mwenyezi Mungu amrehemu na amsalimie — akisema:<br>«Hakika matendo yote yanategemea nia (makusudi ya moyo), na hakika kila mtu atapata (malipo au matokeo) ya aliyonuiya. Basi mwenye kuhamia (kwa Hijra) kwake ikiwa ni kwa ajili ya Mwenyezi Mungu na Mtume Wake, basi uhamiaji wake ni kwa ajili ya Mwenyezi Mungu na Mtume Wake (atapewa thawabu ya Hijra). Na mwenye kuhamia kwake ikiwa ni kwa ajili ya dunia atakayoipata, au kwa ajili ya mwanamke atakayemuoa, basi uhamiaji wake ni kwa kile alichohamia kwa ajili yake (hatapewa thawabu ya Hijra, bali atapata kile alichokusudia tu).»</p></blockquote>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(157, 330, 1, '١ - أن مدار الأعمال على النيات، صحة، وفسادًا، وكمالًا، ونقصًا، وطاعة ومعصية، فمن قصد بعمله الرياء أثم، ومن قصد بالجهاد مثلًا إعلاء كلمة الله تعالى فقط كمل ثوابه. ومن قصد ذلك والغنيمة معه نقص ثوابه. ومن قصد الغنيمة وحدها لم يأثم ولكنه لا يعطى أجر المجاهد. فالحديث مسوق لبيان أن كل عمل طاعة كان في الصورة أو معصية يختلف باختلاف النيات.', '<p>١ - أن مدار الأعمال على النيات، صحة، وفسادًا، وكمالًا، ونقصًا، وطاعة ومعصية، فمن قصد بعمله الرياء أثم، ومن قصد بالجهاد مثلًا إعلاء كلمة الله تعالى فقط كمل ثوابه. ومن قصد ذلك والغنيمة معه نقص ثوابه. ومن قصد الغنيمة وحدها لم يأثم ولكنه لا يعطى أجر المجاهد. فالحديث مسوق لبيان أن كل عمل طاعة كان في الصورة أو معصية يختلف باختلاف النيات.</p><p> </p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(158, 330, 2, 'Hakika msingi wa matendo unatokana na nia.Kwa upande wa kuwa matendo ni sahihi au yenye kuharibika, kamili au pungufu, utiifu au maasi.Basi mwenye kukusudia kwa tendo lake kujionyesha (riyā), atapata dhambi.Na mwenye kukusudia katika jihadi, kwa mfano, kuliinua neno la Mwenyezi Mungu Aliyetukuka pekee, ujira wake unakuwa kamili.Na mwenye kukusudia hilo pamoja na kutaka ngawira, ujira wake unapungua.Na mwenye kukusudia ngawira pekee, hatapata dhambi, lakini hatapewa ujira wa mpiganaji/jihadi.Basi hadithi hii imekuja kueleza kwamba kila tendo la utiifu, au tendo ambalo kwa sura yake linaweza kuwa la utiifu au maasi, hutofautiana kulingana na tofauti za nia.', '<p>Hakika msingi wa matendo unatokana na nia.<br>Kwa upande wa kuwa matendo ni <strong>sahihi au yenye kuharibika, kamili au pungufu, utiifu au maasi.</strong><br><br>Basi mwenye kukusudia kwa tendo lake <strong>kujionyesha (riyā)</strong>, atapata dhambi.<br><br>Na mwenye kukusudia katika jihadi, kwa mfano, <strong>kuliinua neno la Mwenyezi Mungu Aliyetukuka pekee</strong>, ujira wake unakuwa kamili.Na mwenye kukusudia hilo <strong>pamoja na kutaka ngawira</strong>, ujira wake unapungua.<br><br>Na mwenye kukusudia <strong>ngawira pekee</strong>, hatapata dhambi, lakini hatapewa ujira wa mpiganaji/jihadi.<br><br>Basi hadithi hii imekuja <strong>kueleza kwamba kila tendo la utiifu, au tendo ambalo kwa sura yake linaweza kuwa la utiifu au maasi, hutofautiana kulingana na tofauti za nia.</strong><br><br> </p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(159, 330, 3, '٢ - أن النية شرط أساسي في العمل، ولكن بلا غلوّ في استحضارها يفسد على المتعبد عبادته. فإن مجرد قصد العمل يكون نية له بدون تكلف استحضارها وتحقيقها.', '<p>٢ - أن النية شرط أساسي في العمل، ولكن بلا غلوّ في استحضارها يفسد على المتعبد عبادته. فإن مجرد قصد العمل يكون نية له بدون تكلف استحضارها وتحقيقها.</p><p> </p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(160, 330, 4, 'Hakika nia ni sharti la msingi katika tendo. Lakini haifai kupindukia katika kuiweka nia hiyo akilini kiasi cha kumharibia mwenye kufanya ibada ibada yake. Kwa hakika, kukusudia tu kufanya tendo kunatosha kuwa nia yake, bila kujilazimisha kuiweka nia hiyo akilini na kuitekeleza.', '<p>Hakika nia ni sharti la msingi katika tendo. Lakini haifai kupindukia katika kuiweka nia hiyo akilini kiasi cha kumharibia mwenye kufanya ibada ibada yake. Kwa hakika, kukusudia tu kufanya tendo kunatosha kuwa nia yake, bila kujilazimisha kuiweka nia hiyo akilini na kuitekeleza.</p><p> </p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(161, 330, 5, '٣ - أن النية محلها القلب، واللفظ بها بدعة.', '<p>٣ - أن النية محلها القلب، واللفظ بها بدعة.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(162, 330, 6, 'Hakika mahali pa nia ni moyoni, na kuitamka nia kwa ulimi ni bid‘ah.', '<p>Hakika mahali pa nia ni <strong>moyoni</strong>, na kuitamka nia kwa ulimi ni <strong>bid‘ah</strong>.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(163, 330, 7, '٤ - وجوب الحذر من الرياء والسمعة، والعمل لأجل الدنيا، ما دام أن شيئًا من ذلك يفسد العبادة.', '<p>٤ - وجوب الحذر من الرياء والسمعة، والعمل لأجل الدنيا، ما دام أن شيئًا من ذلك يفسد العبادة.</p>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(164, 330, 8, 'Ni wajibu kujihadhari na riyā, kutafuta kusikika/kusifiwa na watu, na kufanya matendo kwa ajili ya dunia, maadamu chochote katika mambo hayo kinaharibu ibada', '<p>Ni wajibu kujihadhari na <strong>riyā, kutafuta kusikika/kusifiwa na watu, na kufanya matendo kwa ajili ya dunia</strong>, maadamu chochote katika mambo hayo kinaharibu ibada</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(165, 330, 9, '٥ - وجوب الاعتناء بأعمال القلوب ومراقبتها.', '<p>٥ - وجوب الاعتناء بأعمال القلوب ومراقبتها.</p>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(166, 330, 10, 'Ni wajibu kuzingatia matendo ya moyo na kuyachunguza/kuyafuatilia.', '<p>Ni wajibu <strong>kuzingatia matendo ya moyo na kuyachunguza/kuyafuatilia</strong>.</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(167, 330, 11, '٦- إن الهجرة من بلاد الشرك إلى بلاد الإسلام، من أفضل العبادات إذا قصد بها وجه الله تعالى.', '<p>٦- إن الهجرة من بلاد الشرك إلى بلاد الإسلام، من أفضل العبادات إذا قصد بها وجه الله تعالى.</p>', 'arabic', 'rtl', 11, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(168, 330, 12, '“Kuhama kutoka nchi ya shirk kwenda nchi ya Uislamu ni miongoni mwa ibada bora zaidi, ikiwa lengo lake ni kutafuta radhi za Mwenyezi Mungu.”', '<p>“Kuhama kutoka nchi ya shirk kwenda nchi ya Uislamu ni miongoni mwa ibada bora zaidi, ikiwa lengo lake ni kutafuta radhi za Mwenyezi Mungu.”</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(169, 400, 1, 'فائدة: ذكر ابن رجب أن العمل لغير الله على أقسام: فتارة يكون رياءً محضًا لا يقصد به سوى مراءاة المخلوقين لتحصيل غرض دنيوي، وهذا لا يكاد يصدر عن مؤمن، ولا شك في أنه يحبط العمل وأن صاحبه يستحق المقت من الله والعقوبة. وتارة يكون العمل لله وشريكه في العمل الرياء، فإن شاركه من أصله فإن النصوص الصحيحة تدل على بطلانه، وإن كان أصل العمل لله ثم طرأ عليه نية الرياء ودفعه صاحبه، فإن ذلك لا يضره بغير خلاف، وقد اختلف العلماء في الاسترسال في الرياء الطارئ: هل يحبط العمل أو لا يضر فاعله ويجري على أصل نيته؟ أم يتصرف', '<p>فائدة: ذكر ابن رجب أن العمل لغير الله على أقسام: فتارة يكون رياءً محضًا لا يقصد به سوى مراءاة المخلوقين لتحصيل غرض دنيوي، وهذا لا يكاد يصدر عن مؤمن، ولا شك في أنه يحبط العمل وأن صاحبه يستحق المقت من الله والعقوبة. وتارة يكون العمل لله وشريكه في العمل الرياء، فإن شاركه من أصله فإن النصوص الصحيحة تدل على بطلانه، وإن كان أصل العمل لله ثم طرأ عليه نية الرياء ودفعه صاحبه، فإن ذلك لا يضره بغير خلاف، وقد اختلف العلماء في الاسترسال في الرياء الطارئ: هل يحبط العمل أو لا يضر فاعله ويجري على أصل نيته؟ أم يتصرف</p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(170, 400, 2, 'Faida: Ibn Rajab ametaja kwamba kufanya amali kwa ajili ya asiyekuwa Allah kuna sehemu mbalimbali: wakati mwingine huwa ni riyaa tupu, ambapo mtu hakusudii chochote isipokuwa kujionyesha kwa viumbe ili apate manufaa ya kidunia, na hali hii karibu haiwezi kutoka kwa Muumini. Wala hakuna shaka kwamba riyaa hiyo hubatilisha amali, na mwenye kufanya hivyo anastahili kuchukiwa na Allah pamoja na kuadhibiwa. Na wakati mwingine mtu hufanya amali kwa ajili ya Allah, lakini akamshirikisha mwingine katika amali hiyo kwa riyaa. Ikiwa riyaa hiyo imeingia tangu mwanzo wa amali, basi dalili sahihi zinaonyesha kwamba amali hiyo hubatilika. Lakini ikiwa msingi wa amali ulikuwa kwa ajili ya Allah, kisha baadaye likamjia nia ya riyaa na mwenyewe akaiondoa na kuipinga, basi hilo halimdhuru bila khilafu. Na wanazuoni wametofautiana kuhusu kuendelea na riyaa inayotokea baadaye: je, hiyo hubatilisha amali, au haimdhuru mwenye kuifanya na amali yake itaendelea kwa kufuata nia yake ya mwanzo? Na Allah ndiye Ajuaye zaidi.', '<p><strong>Faida:</strong> Ibn Rajab ametaja kwamba kufanya amali kwa ajili ya asiyekuwa Allah kuna sehemu mbalimbali: <br>wakati mwingine huwa ni riyaa tupu, ambapo mtu hakusudii chochote isipokuwa kujionyesha kwa viumbe ili apate manufaa ya kidunia, na hali hii karibu haiwezi kutoka kwa Muumini. Wala hakuna shaka kwamba riyaa hiyo hubatilisha amali, na mwenye kufanya hivyo anastahili kuchukiwa na Allah pamoja na kuadhibiwa. <br><br>Na wakati mwingine mtu hufanya amali kwa ajili ya Allah, lakini akamshirikisha mwingine katika amali hiyo kwa riyaa. Ikiwa riyaa hiyo imeingia tangu mwanzo wa amali, basi dalili sahihi zinaonyesha kwamba amali hiyo hubatilika.<br><br> Lakini ikiwa msingi wa amali ulikuwa kwa ajili ya Allah, kisha baadaye likamjia nia ya riyaa na mwenyewe akaiondoa na kuipinga, basi hilo halimdhuru bila khilafu. <br><br>Na wanazuoni wametofautiana kuhusu kuendelea na riyaa inayotokea baadaye: je, hiyo hubatilisha amali, au haimdhuru mwenye kuifanya na amali yake itaendelea kwa kufuata nia yake ya mwanzo? Na Allah ndiye Ajuaye zaidi.</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-25 08:53:26', '2026-08-25 08:53:26', NULL, NULL, NULL, 0),
(219, 401, 1, 'الأُصُولُ ألثَّلاَثَة                 للإمامِ مُحَمَّد بِن عَبْدِالوَهَّابِ', '<p>                        الأُصُولُ ألثَّلاَثَة<br>                 للإمامِ مُحَمَّد بِن عَبْدِالوَهَّابِ<br><br> </p>', 'arabic', 'rtl', 1, '#0b439d', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(220, 401, 2, 'بِسْمِ اللَّهِ الرَّحْمًنِ الرَّحيماعْلمْ رَحِمَكَ اللهُ أَنَّهُ يَجِبُ عَلَيْنَا تَعَلُّمُ أَرْبَع مَسَائِلَ:', '<p><strong> بِسْمِ اللَّهِ الرَّحْمًنِ الرَّحيم</strong><br><strong>اعْلمْ رَحِمَكَ اللهُ أَنَّهُ يَجِبُ عَلَيْنَا تَعَلُّمُ أَرْبَع مَسَائِلَ:</strong></p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(221, 401, 3, 'المسألة الأُولَى: الْعِلْمُ:', '<p>المسألة الأُولَى: الْعِلْمُ:</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(222, 401, 4, 'Suala la kwanza: Elimu:', '<p><strong>Suala la kwanza: </strong>Elimu:</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(223, 401, 5, 'وَهُوَ مَعْرِفَةُ اللهِ، وَمَعْرِفَةُ نَبِيِّهِ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) وَمَعْرِفَةُ دِينِ الإِسْلامِ بالأَدِلَّةِ.', '<p>وَهُوَ مَعْرِفَةُ اللهِ، وَمَعْرِفَةُ نَبِيِّهِ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) وَمَعْرِفَةُ دِينِ الإِسْلامِ بالأَدِلَّةِ.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(224, 401, 6, 'Nayo ni elimu ya kumjua Allaah, na elimu ya kumjua Nabiy Wake (صلى الله عليه وآله وسلم) na elimu ya kuijua Dini ya Kiislamu kwa dalili.', '<p>Nayo ni elimu ya kumjua Allaah, na elimu ya kumjua Nabiy Wake (<strong>صلى الله عليه وآله وسلم</strong>) na elimu ya kuijua Dini ya Kiislamu kwa dalili.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(225, 401, 7, 'المسألة الثَّانِيَة :الْعَمَلُ بِهِSuala la pili:  Kuifanyia kazi.', '<p>المسألة الثَّانِيَة :الْعَمَلُ بِهِ<br><strong>Suala la pili:  </strong>Kuifanyia kazi.</p>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(226, 401, 8, 'المسألة الرَّابِعَةُ :الصَّبْرُ عَلَى الأَذَى فِيهِ.Suala la nne: Kuwa na subira katika maudhi yatakayopatikana ndani yake.', '<p>المسألة الرَّابِعَةُ :الصَّبْرُ عَلَى الأَذَى فِيهِ.<br><br><strong>Suala la nne: </strong>Kuwa na subira katika maudhi yatakayopatikana ndani yake.<br> </p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-26 19:11:25', '2026-08-26 19:11:25', NULL, NULL, NULL, 0),
(1644, 407, 1, 'الأَصْلُ الثَّالِث: مَعْرِفَةُ نَبِيِّكُمْ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:', '<p><strong>الأَصْلُ الثَّالِث: مَعْرِفَةُ نَبِيِّكُمْ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1645, 407, 2, 'Msingi Wa Tatu: Kumjua Nabiy Wenu Muhammad (صلى الله عليه وآله وسلم)', '<p><strong>Msingi Wa Tatu:</strong> Kumjua Nabiy Wenu Muhammad (صلى الله عليه وآله وسلم)</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1646, 407, 3, 'وَهُوَ مُحَمَّدُ بْنُ عَبْدِ اللهِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمٍ، وَهَاشِمٌ مِنْ قُرَيْشٍ، وَقُرَيْشٌ مِنَ الْعَرَبِ، وَالْعَرَبُ مِنْ ذُرِّيَّةِ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ الْخَلِيلِ عَلَيْهِ وَعَلَى نَبِيِّنَا أَفْضَلُ الصَّلاةِ وَالسَّلامِ، وَلَهُ مِنَ الِعُمُرِ ثَلاثٌ وَسِتُّونَ سَنَةً، مِنْهَا أَرْبَعُونَ قَبْلَ النُّبُوَّةِ، وَثَلاثٌ وَعِشْرُون َفى النبوة. نُبِّئَ ب ((إقْراء)) ، وَأُرْسِلَ ب ((الْمُدَّثِّرْ))، وَبَلَدُهُ مَكَّةُ.  بَعَثَهُ اللهُ بِالنِّذَارَةِ عَنِ الشِّرْكِ، وَبالَدْعُوة إِلَى التَّوْحِيدِ.', '<p>وَهُوَ مُحَمَّدُ بْنُ عَبْدِ اللهِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمٍ، وَهَاشِمٌ مِنْ قُرَيْشٍ، وَقُرَيْشٌ مِنَ الْعَرَبِ، وَالْعَرَبُ مِنْ ذُرِّيَّةِ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ الْخَلِيلِ عَلَيْهِ وَعَلَى نَبِيِّنَا أَفْضَلُ الصَّلاةِ وَالسَّلامِ، وَلَهُ مِنَ الِعُمُرِ ثَلاثٌ وَسِتُّونَ سَنَةً، مِنْهَا أَرْبَعُونَ قَبْلَ النُّبُوَّةِ، وَثَلاثٌ وَعِشْرُون َفى النبوة. نُبِّئَ ب ((إقْراء)) ، وَأُرْسِلَ ب ((الْمُدَّثِّرْ))، وَبَلَدُهُ مَكَّةُ.  بَعَثَهُ اللهُ بِالنِّذَارَةِ عَنِ الشِّرْكِ، وَبالَدْعُوة إِلَى التَّوْحِيدِ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1647, 407, 4, 'Naye ni Muhammad bin ‘Abdillaah bin ‘Abdil-Muttwalib bin Haashim. Na Haashim ni kutoka katika (kabila la) la Quraysh. Na Quraysh ni katika Waarabu. Na Waarabu ni kutokana na kizazi cha Ismaa’iyl bin Ibraahiym Al-Khaliyl Swalaah na salamu bora kabisa ziwafikie yeye na Nabiy wetu. Naye alikuwa na umri wa miaka sitini na tatu, miongoni mwa miaka hiyo miaka arubaini kabla ya kupewa Unabiy, na miaka ishirini na tatu akiwa katika Unabiy. Akapewa Unabiy kwa: ((Iqraa - Soma)) na akatumwa (kulingania) kwa ((Al-Muddath-thir – mwenye kujigubika)). Na nchi yake ni Makkah. Allaah Amemtuma kuonya kuhusu shirki na kulingania katika Tawhiyd.', '<p>Naye ni Muhammad bin ‘Abdillaah bin ‘Abdil-Muttwalib bin Haashim. Na Haashim ni kutoka katika (kabila la) la Quraysh. Na Quraysh ni katika Waarabu. Na Waarabu ni kutokana na kizazi cha Ismaa’iyl bin Ibraahiym Al-Khaliyl Swalaah na salamu bora kabisa ziwafikie yeye na Nabiy wetu. Naye alikuwa na umri wa miaka sitini na tatu, miongoni mwa miaka hiyo miaka arubaini kabla ya kupewa Unabiy, na miaka ishirini na tatu akiwa katika Unabiy. Akapewa Unabiy kwa: <strong>((Iqraa - Soma))</strong> na akatumwa (kulingania) kwa <strong>((Al-Muddath-thir – mwenye kujigubika)). </strong>Na nchi yake ni Makkah. Allaah Amemtuma kuonya kuhusu shirki na kulingania katika Tawhiyd.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1648, 407, 5, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1649, 407, 6, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1650, 407, 7, 'يَا أَيُّهَا الْمُدَّثِّرُ‌ ﴿١﴾ قُمْ فَأَنذِرْ‌ ﴿٢﴾ وَرَ‌بَّكَ فَكَبِّرْ‌ ﴿٣﴾ وَثِيَابَكَ فَطَهِّرْ‌ ﴿٤﴾ وَالرُّ‌جْزَ فَاهْجُرْ‌ ﴿٥﴾ وَلَا تَمْنُن تَسْتَكْثِرُ‌ ﴿٦﴾ وَلِرَ‌بِّكَ فَاصْبِرْ‌ ﴿٧﴾', '<p><strong>يَا أَيُّهَا الْمُدَّثِّرُ‌ ﴿١﴾ قُمْ فَأَنذِرْ‌ ﴿٢﴾ وَرَ‌بَّكَ فَكَبِّرْ‌ ﴿٣﴾ وَثِيَابَكَ فَطَهِّرْ‌ ﴿٤﴾ وَالرُّ‌جْزَ فَاهْجُرْ‌ ﴿٥﴾ وَلَا تَمْنُن تَسْتَكْثِرُ‌ ﴿٦﴾ وَلِرَ‌بِّكَ فَاصْبِرْ‌ ﴿٧﴾</strong></p>', 'arabic', 'rtl', 7, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1651, 407, 8, '((Ee mwenye kujigubika! Simama na uonye. Na Rabb wako mtukuze. Na nguo zako toharisha. Na najisi (masanamu) epukana nayo. Na wala usifanye fadhila kwa ajili ya kutaraji kukithirishiwa. Na kwa ajili ya Rabb wako subiri))[Al-Muddath-thir (74: 1-7).]', '<p>((Ee mwenye kujigubika! Simama na uonye. Na Rabb wako mtukuze. Na nguo zako toharisha. Na najisi (masanamu) epukana nayo. Na wala usifanye fadhila kwa ajili ya kutaraji kukithirishiwa. Na kwa ajili ya Rabb wako subiri))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn49\"><strong>[Al-Muddath-thir (74: 1-7).]</strong></a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1652, 407, 9, 'وَمَعْنَى  قُمْ فَأَنذِرْ‌ ﴿٢﴾    يُنْذِرُ عَنِ الشِّرْكِ، وَيَدْعُو إِلَى التَّوْحِيدِ.', '<p> <strong> وَمَعْنَى</strong>  <strong>قُمْ فَأَنذِرْ‌ ﴿٢﴾</strong>    <strong>يُنْذِرُ عَنِ الشِّرْكِ، وَيَدْعُو إِلَى التَّوْحِيدِ.</strong></p>', 'arabic', 'rtl', 9, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1653, 407, 10, 'Na maana ya ((Simama na uonye)):  Aonye kuhusu shirki na alinganie katika Tawhiyd.', '<p>Na maana ya ((Simama na uonye)):  Aonye kuhusu shirki na alinganie katika Tawhiyd.</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1654, 407, 11, 'وَرَ‌بَّكَ فَكَبِّرْ‌ ﴿٣﴾ أَيْ: عَظِّمْهُ بِالتَّوْحِيدِ.', '<p><strong>وَرَ‌بَّكَ فَكَبِّرْ‌ ﴿٣﴾ أَيْ: عَظِّمْهُ بِالتَّوْحِيدِ.</strong></p>', 'swahili', 'ltr', 11, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1655, 407, 12, '((Na Rabb wako mtukuze)) Yaani: Muadhimishe kwa Tawhiyd.', '<p>((Na Rabb wako mtukuze))<strong> Y</strong>aani: Muadhimishe kwa Tawhiyd.</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1656, 407, 13, 'وَثِيَابَكَ فَطَهِّرْ‌ ﴿٤﴾ أَيْ: طَهِّرْ أَعْمَالَكَ عَنِ الشِّرْكِ.', '<p><strong>وَثِيَابَكَ فَطَهِّرْ‌ ﴿٤﴾</strong> <strong>أَيْ: طَهِّرْ أَعْمَالَكَ عَنِ الشِّرْكِ.</strong></p>', 'arabic', 'rtl', 13, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1657, 407, 14, '((Na nguo zako toharisha) Yaani: Toharisha ‘amali zako kutokana na shirk.', '<p>((Na nguo zako toharisha) Yaani: Toharisha ‘amali zako kutokana na shirk.</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1658, 407, 15, 'وَالرُّ‌جْزَ فَاهْجُرْ‌ ﴿٥﴾ الرُّجْزَ: الأَصْنَامُ، وَهَجْرُهَا: تَرْكُهَا، وَالْبَرَاءَةُ مِنْهَا وَأَهْلُهَا.', '<p><strong>وَالرُّ‌جْزَ فَاهْجُرْ‌ ﴿٥﴾ الرُّجْزَ: الأَصْنَامُ، وَهَجْرُهَا: تَرْكُهَا، وَالْبَرَاءَةُ مِنْهَا وَأَهْلُهَا.</strong></p>', 'arabic', 'rtl', 15, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1659, 407, 16, '((Na najisi (masanamu) epukana nayo) Uchafu au najsi ni masanamu. Na kuyahama ni kuepukana nayo kabisa na kujiweka mbali nayo na watu wake.', '<p>((Na najisi (masanamu) epukana nayo) Uchafu au najsi ni masanamu. Na kuyahama ni kuepukana nayo kabisa na kujiweka mbali nayo na watu wake.</p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1660, 407, 17, 'أَخَذَ عَلَى هَذَا عَشْرَ سِنِينَ يَدْعُو إِلَى التَّوْحِيدِ، وَبَعْدَ الْعَشْرِ عُرِجَ بِهِ إِلَى السَّمَاءِ، وَفُرِضَتْ عَلَيْهِ الصَّلَواتُ الْخَمْسُ، وَصَلَّى فِي مَكَّةَ ثَلاثَ سِنِينَ، وَبَعْدَهَا أُمِرَ بالْهِجْرَةِ إِلَى الْمَدِينَةِ، وَالْهِجْرَةُ الانْتِقَالُ مِنْ بَلَدِ الشِّرْكِ إِلَى بَلَدِ الإِسْلامِ.', '<p>أَخَذَ عَلَى هَذَا عَشْرَ سِنِينَ يَدْعُو إِلَى التَّوْحِيدِ، وَبَعْدَ الْعَشْرِ عُرِجَ بِهِ إِلَى السَّمَاءِ، وَفُرِضَتْ عَلَيْهِ الصَّلَواتُ الْخَمْسُ، وَصَلَّى فِي مَكَّةَ ثَلاثَ سِنِينَ، وَبَعْدَهَا أُمِرَ بالْهِجْرَةِ إِلَى الْمَدِينَةِ، وَالْهِجْرَةُ الانْتِقَالُ مِنْ بَلَدِ الشِّرْكِ إِلَى بَلَدِ الإِسْلامِ.</p>', 'arabic', 'rtl', 17, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1661, 407, 18, 'Amesimamia haya miaka kumi akilingania katika Tawhiyd. Na baada ya miaka kumi, alipandishwa mbinguni (Mi’iraaj) na akafaridhishwa Swalaah tano, akaswali Makkah miaka mitatu, na baada ya hapo akaamrishwa kuhajiri kwenda Madiynah. Na hijrah ni kuhama kutoka nchi ya shirki kwenda katika nchi ya Kiislamu.', '<p>Amesimamia haya miaka kumi akilingania katika Tawhiyd. Na baada ya miaka kumi, alipandishwa mbinguni (Mi’iraaj) na akafaridhishwa Swalaah tano, akaswali Makkah miaka mitatu, na baada ya hapo akaamrishwa kuhajiri kwenda Madiynah. Na hijrah ni kuhama kutoka nchi ya shirki kwenda katika nchi ya Kiislamu.</p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1662, 407, 19, 'وَالْهِجْرَةُ فَرِيضَةٌ عَلَى هَذِهِ الأُمَّةِ مِنْ بَلَدِ الشِّرْكِ إِلَى بلد الإِسْلامِ، وَهِيَ بَاقِيَةٌ إِلَى أَنْ تَقُومَ السَّاعَةُ.', '<p>وَالْهِجْرَةُ فَرِيضَةٌ عَلَى هَذِهِ الأُمَّةِ مِنْ بَلَدِ الشِّرْكِ إِلَى بلد الإِسْلامِ، وَهِيَ بَاقِيَةٌ إِلَى أَنْ تَقُومَ السَّاعَةُ.</p>', 'arabic', 'rtl', 19, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1663, 407, 20, 'Na hijrah ni fardhi kwa Ummah huu kuhama kutoka katika nchi ya shirki kwenda nchi ya Kiislamu. Nayo itaendelea kubakia hadi itakaposimama Saa (Qiyaamah).', '<p>Na hijrah ni fardhi kwa Ummah huu kuhama kutoka katika nchi ya shirki kwenda nchi ya Kiislamu. Nayo itaendelea kubakia hadi itakaposimama Saa (Qiyaamah).</p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1664, 407, 21, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 21, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1665, 407, 22, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p><p><br> </p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1666, 407, 23, 'إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ ۖ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ ۚ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّـهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا ۚ فَأُولَـٰئِكَ مَأْوَاهُمْ جَهَنَّمُ ۖ وَسَاءَتْ مَصِيرًا ﴿٩٧﴾ إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا ﴿٩٨﴾ فَأُولَـٰئِكَ عَسَى اللَّـهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ اللَّـهُ عَفُوًّا غَفُورًا ﴿٩٩﴾', '<p><strong>إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ ۖ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ ۚ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّـهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا ۚ فَأُولَـٰئِكَ مَأْوَاهُمْ جَهَنَّمُ ۖ وَسَاءَتْ مَصِيرًا ﴿٩٧﴾ إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا ﴿٩٨﴾ فَأُولَـٰئِكَ عَسَى اللَّـهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ اللَّـهُ عَفُوًّا غَفُورًا ﴿٩٩﴾</strong></p>', 'arabic', 'rtl', 23, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1667, 407, 24, '((Hakika wale ambao Malaika wamewafisha, hali wamejidhulumu nafsi zao; (Malaika) watawaambia: “Mlikuwa katika hali gani?” Watasema: “Tulikuwa tukikandamizwa katika ardhi.”  (Malaika) Watasema: “Je, kwani ardhi ya Allaah haikuwa ya wasaa mkahajiri? Basi hao makazi yao yatakuwa ni Jahannam, na uovu ulioje mahali pa kuishia. Isipokuwa wale waliokandamizwa kati ya wanaume na wanawake na watoto ambao hawakuweza kupata (mpango wa) hila yoyote wala hawawezi kuongoza njia. Basi hao asaa Allaah Akawasamehe. Na Allaah daima ni Mwingi wa kusamehe, Mwingi wa kughufuria))[An-Nisaa (4: 97-99).]', '<p><strong>((</strong>Hakika wale ambao Malaika wamewafisha, hali wamejidhulumu nafsi zao; (Malaika) watawaambia: “Mlikuwa katika hali gani?” Watasema: “Tulikuwa tukikandamizwa katika ardhi.”  (Malaika) Watasema: “Je, kwani ardhi ya Allaah haikuwa ya wasaa mkahajiri? Basi hao makazi yao yatakuwa ni Jahannam, na uovu ulioje mahali pa kuishia. Isipokuwa wale waliokandamizwa kati ya wanaume na wanawake na watoto ambao hawakuweza kupata (mpango wa) hila yoyote wala hawawezi kuongoza njia. Basi hao asaa Allaah Akawasamehe. Na Allaah daima ni Mwingi wa kusamehe, Mwingi wa kughufuria))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn50\"><strong>[An-Nisaa (4: 97-99).]</strong></a></p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1668, 407, 25, 'وَقَوْلُهُ تَعَالَى:', '<p> وَقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 25, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1669, 407, 26, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 26, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1670, 407, 27, 'يَا عِبَادِيَ الَّذِينَ آمَنُوا إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ ﴿٥٦﴾', '<p><strong>يَا عِبَادِيَ الَّذِينَ آمَنُوا إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ ﴿٥٦﴾</strong></p>', 'arabic', 'rtl', 27, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(1671, 407, 28, '((“Enyi waja Wangu walioamini! Hakika ardhi Yangu ni pana, basi Mimi Pekee Niabuduni.”))[Al-‘Ankabuwt (29: 56).]', '<p>((“Enyi waja Wangu walioamini! Hakika ardhi Yangu ni pana, basi Mimi Pekee Niabuduni.”))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn51\">[Al-‘Ankabuwt (29: 56).]</a></p>', 'swahili', 'ltr', 28, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1672, 407, 29, 'قَالَ الْبُغَوِيُّ (رَحِمَهُ اللهُ) :نزلت هَذِهِ الآيَةِ فِي المُسْلِمِينَ الَّذِينَ بِمَكَّةَ ولَمْ يُهَاجِرُوا، نَادَاهُمُ اللهُ بِاسْمِ الإِيمَانِ.', '<p>قَالَ الْبُغَوِيُّ (رَحِمَهُ اللهُ) :نزلت هَذِهِ الآيَةِ فِي المُسْلِمِينَ الَّذِينَ بِمَكَّةَ ولَمْ يُهَاجِرُوا، نَادَاهُمُ اللهُ بِاسْمِ الإِيمَانِ.</p>', 'arabic', 'rtl', 29, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1673, 407, 30, 'Amesema Al-Baghaawiy (رحمه الله): “Aayah hii imeteremshwa kwa sababu ya Waislamu waliokuwa Makkah ambao hawakuhajiri. Allaah Amewaita kwa jina la Waumini.', '<p>Amesema Al-Baghaawiy <strong>(رحمه الله)</strong>: “Aayah hii imeteremshwa kwa sababu ya Waislamu waliokuwa Makkah ambao hawakuhajiri. Allaah Amewaita kwa jina la Waumini.</p>', 'swahili', 'ltr', 30, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1674, 407, 31, 'وَالدَّلِيلُ عَلَى الْهِجْرَةِ مِنَ السُّنَّةِ، قَوْلُهُ (صلى الله عليه وآله وسلم):', '<p>وَالدَّلِيلُ عَلَى الْهِجْرَةِ مِنَ السُّنَّةِ، قَوْلُهُ (صلى الله عليه وآله وسلم):</p>', 'arabic', 'rtl', 31, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1675, 407, 32, '((لاَ تَنْقَطِعُ الْهِجْرَةُ حَتَّى تَنْقَطِعَ التَّوْبَةُ، وَلا تَنْقَطِعُ التَّوْبَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَ))', '<p><strong>((لاَ تَنْقَطِعُ الْهِجْرَةُ حَتَّى تَنْقَطِعَ التَّوْبَةُ، وَلا تَنْقَطِعُ التَّوْبَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَ))</strong></p>', 'arabic', 'rtl', 32, '#133f7c', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1676, 407, 33, 'Na dalili ya Hijrah (kuhajiri) katika Sunnah ni kauli yake (صلى الله عليه وآله وسلم):', '<p>Na dalili ya Hijrah (kuhajiri) katika Sunnah ni kauli yake (<strong>صلى الله عليه وآله وسلم</strong>):</p>', 'swahili', 'ltr', 33, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1677, 407, 34, '((Hijrah haikatiki mpaka ikatike tawbah. Na tawbah haikatiki mpaka jua lichomoze kutoka Magharibi))[Abu Daawuwd, Ahmad, Ad-Daarimiy na ni Swahiyh kwa mujibu wa Al-Albaaniy katika Swahiyhul-Jaami’ As-Swaghiyr 7346.]', '<p><strong>((Hijrah haikatiki mpaka ikatike tawbah. Na tawbah haikatiki mpaka jua lichomoze kutoka Magharibi))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn52\"><strong>[Abu Daawuwd, Ahmad, Ad-Daarimiy na ni Swahiyh kwa mujibu wa Al-Albaaniy katika Swahiyhul-Jaami’ As-Swaghiyr 7346.]</strong></a></p>', 'swahili', 'ltr', 34, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1678, 407, 35, 'فَلَمَّا اسْتَقَرَّ فِي الْمَدِينَةِ أُمِرَ بِبَقِيَّةِ شَرَائِعِ الإِسْلامِ، مِثلِ: الزَّكَاةِ، وَالصَّوْمِ، وَالْحَجِّ، وَالأَذَانِ، وَالْجِهَادِ، وَالأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، وَغَيْرِ ذَلِكَ مِنْ شَرَائِعِ الإِسْلامِ، أَخَذَ عَلَى هَذَا عَشْرَ سِنِينَ، وَتُوُفِّيَ ـ صَلواتُ اللهِ وَسَلامُهُ عَلَيْهِ ـ وَدِينُهُ بَاقٍ.  وَهَذَا دِينُهُ، لا خَيْرَ إِلا دَلَّ الأُمَّةَ عَلَيْهِ، وَلا شَرَّ إِلا حَذَّرَهَا مِنْهُ، وَالْخَيْرُ الَّذِي دَلَّهَا عَلَيْهِ التَّوْحِيدُ، وَجَمِيعُ مَا يُحِبُّهُ اللهُ وَيَرْضَاهُ، وَالشَّرُ الَّذِي حَذَّرَهَا مِنْهُ الشِّرْكُ، وَجَمِيعُ مَا يَكْرَهُ اللهُ وَيَأْبَاهُ. بَعَثَهُ اللهُ إِلَى النَّاسِ كَافَّةً، وَافْتَرَضَ طَاعَتَهُ عَلَى جَمِيعِ الثَّقَلَيْنِ الْجِنِّ وَالإِنْسِ.', '<p>فَلَمَّا اسْتَقَرَّ فِي الْمَدِينَةِ أُمِرَ بِبَقِيَّةِ شَرَائِعِ الإِسْلامِ، مِثلِ: الزَّكَاةِ، وَالصَّوْمِ، وَالْحَجِّ، وَالأَذَانِ، وَالْجِهَادِ، وَالأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، وَغَيْرِ ذَلِكَ مِنْ شَرَائِعِ الإِسْلامِ، أَخَذَ عَلَى هَذَا عَشْرَ سِنِينَ، وَتُوُفِّيَ ـ صَلواتُ اللهِ وَسَلامُهُ عَلَيْهِ ـ وَدِينُهُ بَاقٍ.  وَهَذَا دِينُهُ، لا خَيْرَ إِلا دَلَّ الأُمَّةَ عَلَيْهِ، وَلا شَرَّ إِلا حَذَّرَهَا مِنْهُ، وَالْخَيْرُ الَّذِي دَلَّهَا عَلَيْهِ التَّوْحِيدُ، وَجَمِيعُ مَا يُحِبُّهُ اللهُ وَيَرْضَاهُ، وَالشَّرُ الَّذِي حَذَّرَهَا مِنْهُ الشِّرْكُ، وَجَمِيعُ مَا يَكْرَهُ اللهُ وَيَأْبَاهُ. بَعَثَهُ اللهُ إِلَى النَّاسِ كَافَّةً، وَافْتَرَضَ طَاعَتَهُ عَلَى جَمِيعِ الثَّقَلَيْنِ الْجِنِّ وَالإِنْسِ.</p>', 'arabic', 'rtl', 35, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1679, 407, 36, 'Baada ya kustakiri Madiynah aliamrisha Shariy’ah za Kiislamu zilobakia kama; Zakaah, Swawm, Hajj, Adhaan, Jihaad, kuamrisha mema na kukataza munkari na mengineyo ya Shariy’ah ya Kiislamu. Amefanya hayo miaka kumi akafariki baada ya hapo, Swalaah na salamu ziwe juu yake. Na Dini yake imebaki. Na hii Dini yake, hakuna kheri isipokuwa kawaelekeza kwayo Ummah, na hakuna shari ila amewatahadharisha nayo. Na kheri aliyowaongoza kwayo ni Tawhiyd na yote Anayoyapenda Allaah na Anayoyaridhia. Na shari ambazo amezitahadharisha ni shirki na yote yanayomchukiza Allaah na Asiyoyaridhia. Allaah Amemtuma kwa watu wote, na Amefaradhisha Ath-Thaqalayn (walimwengu wawili); majini na watu kumtii yeye (Nabiy).', '<p>Baada ya kustakiri Madiynah aliamrisha Shariy’ah za Kiislamu zilobakia kama; Zakaah, Swawm, Hajj, Adhaan, Jihaad, kuamrisha mema na kukataza munkari na mengineyo ya Shariy’ah ya Kiislamu. Amefanya hayo miaka kumi akafariki baada ya hapo, Swalaah na salamu ziwe juu yake. Na Dini yake imebaki. Na hii Dini yake, hakuna kheri isipokuwa kawaelekeza kwayo Ummah, na hakuna shari ila amewatahadharisha nayo. Na kheri aliyowaongoza kwayo ni Tawhiyd na yote Anayoyapenda Allaah na Anayoyaridhia. Na shari ambazo amezitahadharisha ni shirki na yote yanayomchukiza Allaah na Asiyoyaridhia. Allaah Amemtuma kwa watu wote, na Amefaradhisha <i>Ath-Thaqalayn</i> (walimwengu wawili); majini na watu kumtii yeye (Nabiy).</p>', 'swahili', 'ltr', 36, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1680, 407, 37, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 37, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1681, 407, 38, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 38, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1682, 407, 39, 'قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّـهِ إِلَيْكُمْ جَمِيعًا', '<p><strong>قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّـهِ إِلَيْكُمْ جَمِيعًا</strong></p>', 'arabic', 'rtl', 39, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1683, 407, 40, '((Sema (ee Muhammad صلى الله عليه وآله وسلم): “Hakika mimi ni Rasuli wa Allaah kwenu nyinyi nyote.))[Al-A’raaf (7: 158).]', '<p><strong>((</strong>Sema (ee Muhammad <strong>صلى الله عليه وآله وسلم</strong>): “Hakika mimi ni Rasuli wa Allaah kwenu nyinyi nyote.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn53\"><strong>[Al-A’raaf (7: 158).]</strong></a></p>', 'swahili', 'ltr', 40, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1684, 407, 41, 'وَكَمَّلَ اللهُ بِهِ الدِّينَ؛ وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p><strong>وَكَمَّلَ اللهُ بِهِ الدِّينَ؛ وَالدَّلِيلُ قَوْلُهُ تَعَالَى</strong>:</p>', 'arabic', 'rtl', 41, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1685, 407, 42, 'Na Allaah Ameikamilisha Dini hii kwa kupitia kwake. Na dalili ni kauli ya Yake Ta’aalaa:', '<p>Na Allaah Ameikamilisha Dini hii kwa kupitia kwake. Na dalili ni kauli ya Yake Ta’aalaa:</p>', 'swahili', 'ltr', 42, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1686, 407, 43, 'الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ', '<p><strong>الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ</strong></p>', 'arabic', 'rtl', 43, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1687, 407, 44, '((Leo Nimekukamilishieni Dini yenu, na Nimekutimizieni neema Yangu, na Nimekuridhieni Uislaam uwe Dini yenu.))[Al-Maaidah (5: 3).]', '<p><strong>((</strong>Leo Nimekukamilishieni Dini yenu, na Nimekutimizieni neema Yangu, na Nimekuridhieni Uislaam uwe Dini yenu.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn54\"><strong>[Al-Maaidah (5: 3).]</strong></a></p>', 'swahili', 'ltr', 44, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1688, 407, 45, 'وَالدَّلِيلُ عَلَى مَوْتِهِ (صَلَّى اللهُ عَلَيْهِ وآله  وَسَلَّمَ)) قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ عَلَى مَوْتِهِ (صَلَّى اللهُ عَلَيْهِ وآله  وَسَلَّمَ)) قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 45, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1689, 407, 46, 'Na dalili ya kifo chake (صلى الله عليه وآله وسلم) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya kifo chake (<strong>صلى الله عليه وآله وسلم</strong>) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 46, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1690, 407, 47, 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ ﴿٣٠﴾ ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ ﴿٣١﴾', '<p><strong>إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ ﴿٣٠﴾ ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ ﴿٣١﴾</strong></p>', 'arabic', 'rtl', 47, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1691, 407, 48, '((Hakika wewe (ee Muhammad صلى الله عليه وآله وسلم) utakufa nao pia watakufa. Kisha hakika nyinyi Siku ya Qiyaamah mtakhasimiana mbele ya Rabb wenu.))[55]', '<p><strong>((</strong>Hakika wewe (ee Muhammad <strong>صلى الله عليه وآله وسلم</strong>) utakufa nao pia watakufa. Kisha hakika nyinyi Siku ya Qiyaamah mtakhasimiana mbele ya Rabb wenu.))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn55\">[55]</a></p>', 'swahili', 'ltr', 48, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1692, 407, 49, 'وَالنَّاسُ إِذَا مَاتُواْ يُبْعَثُونَ.', '<p>وَالنَّاسُ إِذَا مَاتُواْ يُبْعَثُونَ.</p>', 'swahili', 'ltr', 49, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1693, 407, 50, 'Na watu watakapokufa watafufuliwa.', '<p>Na watu watakapokufa watafufuliwa. </p>', 'swahili', 'ltr', 50, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
