(1695, 407, 52, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 52, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1696, 407, 53, 'مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ ﴿٥٥﴾', '<p><strong>مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ ﴿٥٥﴾</strong></p>', 'arabic', 'rtl', 53, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1697, 407, 54, '((Kutokana nayo (ardhi) Tumekuumbeni, na humo Tutakurudisheni, na kutoka humo Tutakutoeni mara nyingine))[Twaahaa (20: 55).]', '<p>((Kutokana nayo (ardhi) Tumekuumbeni, na humo Tutakurudisheni, na kutoka humo Tutakutoeni mara nyingine<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn56\"><strong>[Twaahaa (20: 55).]</strong></a></p>', 'swahili', 'ltr', 54, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1698, 407, 55, 'وقَوْلُهُ تَعَالَى:', '<p>وقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 55, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1699, 407, 56, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 56, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1700, 407, 57, 'وَاللَّـهُ أَنبَتَكُم مِّنَ الْأَرْضِ نَبَاتًا ﴿١٧﴾ ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا ﴿١٨﴾', '<p><strong>وَاللَّـهُ أَنبَتَكُم مِّنَ الْأَرْضِ نَبَاتًا ﴿١٧﴾ ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا ﴿١٨﴾</strong></p>', 'arabic', 'rtl', 57, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1701, 407, 58, '((Na Allaah Amekuanzisheni vizuri katika (udongo wa) ardhi. Kisha Atakurudisheni humo na Atakutoeni tena mtoke (kuwa hai)) [Nuuh (71: 17-18).]', '<p>((Na Allaah Amekuanzisheni vizuri katika (udongo wa) ardhi. Kisha Atakurudisheni humo na Atakutoeni tena mtoke (kuwa hai)) <a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn57\">[Nuuh (71: 17-18).]</a></p>', 'swahili', 'ltr', 58, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1702, 407, 59, 'وَبَعْدَ الْبَعْثِ مُحَاسَبُونَ وَمَجْزِيُّونَ بِأَعْمَالِهِمْ.', '<p> وَبَعْدَ الْبَعْثِ مُحَاسَبُونَ وَمَجْزِيُّونَ بِأَعْمَالِهِمْ.</p>', 'arabic', 'rtl', 59, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1703, 407, 60, 'Na baada ya kufufuliwa watahesabiwa na watalipwa kwa ‘amali zao.', '<p>Na baada ya kufufuliwa watahesabiwa na watalipwa kwa ‘amali zao.</p>', 'swahili', 'ltr', 60, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1704, 407, 61, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'swahili', 'ltr', 61, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1705, 407, 62, 'Na dalil ni kauli Yake Ta’aalaa:', '<p>Na dalil ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 62, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1706, 407, 63, 'وَلِلَّـهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى ﴿٣١﴾', '<p><strong>وَلِلَّـهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى ﴿٣١﴾</strong></p>', 'arabic', 'rtl', 63, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1707, 407, 64, '((Na ni vya Allaah Pekee vilivyomo mbinguni na vilivyomo ardhini ili Awalipe wale waliofanya uovu kwa yale waliyoyatenda, na Awalipe wale waliofanya mema kwa mema zaidi))[An-Najm (53: 31).]', '<p>((Na ni vya Allaah Pekee vilivyomo mbinguni na vilivyomo ardhini ili Awalipe wale waliofanya uovu kwa yale waliyoyatenda, na Awalipe wale waliofanya mema kwa mema zaidi<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn58\"><strong>[An-Najm (53: 31).]</strong></a></p>', 'swahili', 'ltr', 64, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1708, 407, 65, 'وَمَنْ كَذَّبَ بِالْبَعْثِ كَفَرَ.', '<p>وَمَنْ كَذَّبَ بِالْبَعْثِ كَفَرَ.</p>', 'arabic', 'rtl', 65, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1709, 407, 66, 'Na anayekadhibisha kufufuliwa amekufuru.', '<p>Na anayekadhibisha kufufuliwa amekufuru.</p>', 'swahili', 'ltr', 66, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1710, 407, 67, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 67, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1711, 407, 68, 'Na dalili ni kauli Yake Ta’aalaa', '<p>Na dalili ni kauli Yake Ta’aalaa</p>', 'swahili', 'ltr', 68, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1712, 407, 69, 'زَعَمَ الَّذِينَ كَفَرُوا أَن لَّن يُبْعَثُوا ۚ قُلْ بَلَىٰ وَرَبِّي لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى اللَّـهِ يَسِيرٌ ﴿٧﴾', '<p><strong>زَعَمَ الَّذِينَ كَفَرُوا أَن لَّن يُبْعَثُوا ۚ قُلْ بَلَىٰ وَرَبِّي لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى اللَّـهِ يَسِيرٌ ﴿٧﴾</strong></p>', 'arabic', 'rtl', 69, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1713, 407, 70, '((Waliokufuru wamedai kwamba hawatofufuliwa kamwe. Sema: Bali hapana! Naapa kwa Rabb wangu, bila shaka mtafufuliwa, kisha mtajulishwa kwa yale mliyoyatenda, na hayo kwa Allaah ni mepesi.))[At-Taghaabun (64: 7).]', '<p><strong>((</strong>Waliokufuru wamedai kwamba hawatofufuliwa kamwe. Sema: Bali hapana! Naapa kwa Rabb wangu, bila shaka mtafufuliwa, kisha mtajulishwa kwa yale mliyoyatenda, na hayo kwa Allaah ni mepesi.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn59\"><strong>[At-Taghaabun (64: 7).]</strong></a></p>', 'swahili', 'ltr', 70, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1714, 407, 71, 'وَأَرْسَلَ اللهُ جَمِيعَ الرُّسُلِ مُبَشِّرِينَ وَمُنْذِرِينَ.', '<p>وَأَرْسَلَ اللهُ جَمِيعَ الرُّسُلِ مُبَشِّرِينَ وَمُنْذِرِينَ.</p>', 'arabic', 'rtl', 71, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1715, 407, 72, 'Na Allaah Ametuma Rasuli wote wakiwa ni wabashiriaji na waonyaji.', '<p>Na Allaah Ametuma Rasuli wote wakiwa ni wabashiriaji na waonyaji.</p>', 'swahili', 'ltr', 72, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1716, 407, 73, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 73, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1717, 407, 74, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 74, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1718, 407, 75, 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللَّـهِ حُجَّةٌ بَعْدَ الرُّسُلِ ۚ', '<p><strong>رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللَّـهِ حُجَّةٌ بَعْدَ الرُّسُلِ ۚ</strong></p>', 'arabic', 'rtl', 75, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1719, 407, 76, '((Rasuli ni wabashiriajina waonyaji ili pasikuweko kutoka kwa watu hoja yoyote juu ya Allaah baada ya (kuletwa) Rasuli))[An-Nisaa (4: 165).]', '<p>((Rasuli ni wabashiriajina waonyaji ili pasikuweko kutoka kwa watu hoja yoyote juu ya Allaah baada ya (kuletwa) Rasuli<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn60\"><strong>[An-Nisaa (4: 165).]</strong></a>   </p>', 'swahili', 'ltr', 76, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1720, 407, 77, 'وَأَّولُهُمْ نُوحٌ (عَلَيْهِ السَّلامُ)، وَآخِرُهُمْ مُحَمَّدٌ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) وَهُوَ خَاتَمُ النَّبِيِّينَ.', '<p>وَأَّولُهُمْ نُوحٌ (عَلَيْهِ السَّلامُ)، وَآخِرُهُمْ مُحَمَّدٌ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) وَهُوَ خَاتَمُ النَّبِيِّينَ.</p>', 'swahili', 'ltr', 77, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1721, 407, 78, 'Na wa kwanza wao ni Nuwh (عليه السلام) na wa mwisho wao ni Muhammad (صلى الله عليه وآله وسلم) naye ndiye Nabiy wa mwisho.', '<p>Na wa kwanza wao ni Nuwh <strong>(عليه السلام)</strong> na wa mwisho wao ni Muhammad (<strong>صلى الله عليه وآله وسلم</strong>) naye ndiye Nabiy wa mwisho.</p>', 'swahili', 'ltr', 78, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1722, 407, 79, 'وَالدَّلِيلُ عَلَى أَنَّ أَوَّلَهُمْ نُوحٌ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ عَلَى أَنَّ أَوَّلَهُمْ نُوحٌ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 79, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1723, 407, 80, 'Na dalili kwamba Nuuh ndio wa mwanzo wao ni kauli Yake Ta’aalaa:', '<p>Na dalili kwamba Nuuh ndio wa mwanzo wao ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 80, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1724, 407, 81, 'إِنَّا أَوْحَيْنَا إِلَيْكَ كَمَا أَوْحَيْنَا إِلَىٰ نُوحٍ وَالنَّبِيِّينَ مِن بَعْدِهِ ۚ', '<p><strong>إِنَّا أَوْحَيْنَا إِلَيْكَ كَمَا أَوْحَيْنَا إِلَىٰ نُوحٍ وَالنَّبِيِّينَ مِن بَعْدِهِ ۚ</strong></p>', 'arabic', 'rtl', 81, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1725, 407, 82, '((Hakika Tumekufunulia Wahy (ee Muhammad صلى الله عليه وآله وسلم) kama Tulivyomfunulia Wahy Nuwh na Nabiy baada yake))[An-Nisaa (4: 163).]', '<p><strong>((</strong>Hakika Tumekufunulia Wahy (ee Muhammad <strong>صلى الله عليه وآله وسلم</strong>) kama Tulivyomfunulia Wahy Nuwh na Nabiy baada yake<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn61\"><strong>[An-Nisaa (4: 163).]</strong></a> </p>', 'swahili', 'ltr', 82, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1726, 407, 83, 'وَكُلُّ أُمَّةٍ بَعَثَ اللهُ إِلَيْهِا رَسُولا مِنْ نُوحٍ إِلَى مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) يَأْمُرُهُمْ بِعِبَادَةِ اللهِ وَحْدَهُ، وَيَنْهَاهُمْ عَنْ عِبَادَةِ الطَّاغُوتِ.', '<p>وَكُلُّ أُمَّةٍ بَعَثَ اللهُ إِلَيْهِا رَسُولا مِنْ نُوحٍ إِلَى مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وآله وَسَلَّمَ) يَأْمُرُهُمْ بِعِبَادَةِ اللهِ وَحْدَهُ، وَيَنْهَاهُمْ عَنْ عِبَادَةِ الطَّاغُوتِ.</p>', 'swahili', 'ltr', 83, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1727, 407, 84, 'Na kila Ummah Allaah Ameupelekea Rasuli kuanzia Nuwh hadi kwa Muhammad (صلى الله عليه وآله وسلم). Akiwaamrisha kumwabudu Allaah Pekee, na Akiwakataza kuabudu twaghuti[Miungu yote ya uongo na vyote viabudiwavyo kwa batili kama mashetani, masanamu, mizimu, watu n.k.]', '<p>Na kila Ummah Allaah Ameupelekea Rasuli kuanzia Nuwh hadi kwa Muhammad (<strong>صلى الله عليه وآله وسلم</strong>). Akiwaamrisha kumwabudu Allaah Pekee, na Akiwakataza kuabudu twaghuti<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn62\"><strong>[Miungu yote ya uongo na vyote viabudiwavyo kwa batili kama mashetani, masanamu, mizimu, watu n.k.]</strong></a>  </p>', 'swahili', 'ltr', 84, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1728, 407, 85, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 85, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1729, 407, 86, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 86, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1730, 407, 87, 'وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّـهَ وَاجْتَنِبُوا الطَّاغُوتَ ۖ', '<p><strong>وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّـهَ وَاجْتَنِبُوا الطَّاغُوتَ ۖ</strong></p>', 'arabic', 'rtl', 87, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1731, 407, 88, '((Na kwa yakini Tulituma katika kila ummah Rasuli (alinganie) kwamba: “Mwabuduni Allaah na jiepusheni na taghuti))[An-Nahl (16: 36).].', '<p>((Na kwa yakini Tulituma katika kila ummah Rasuli (alinganie) kwamba: “Mwabuduni Allaah na jiepusheni na taghuti)<strong>)</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn63\"><strong>[An-Nahl (16: 36).]</strong></a>.</p>', 'swahili', 'ltr', 88, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1732, 407, 89, 'وَافْتَرَضَ اللهُ عَلَى جَمِيعِ الْعِبَادِ الْكُفْرَ بِالطَّاغُوتِ وَالإِيمَانَ بِاللهِ.', '<p> وَافْتَرَضَ اللهُ عَلَى جَمِيعِ الْعِبَادِ الْكُفْرَ بِالطَّاغُوتِ وَالإِيمَانَ بِاللهِ.</p>', 'arabic', 'rtl', 89, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1733, 407, 90, 'Na Allaah Akafaridhisha kwa waja wote wakanushe twaghuti na kumwamini Allaah (wamwabudu Yeye Pekee).', '<p>Na Allaah Akafaridhisha kwa waja wote wakanushe twaghuti na kumwamini Allaah (wamwabudu Yeye Pekee).</p>', 'swahili', 'ltr', 90, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1734, 407, 91, 'قَالَ ابْنُ الْقَيِّمِ (رَحِمَهُ اللهُ): مَعْنَى الطَّاغُوتِ مَا تَجَاوَزَ بِهِ الْعَبْدُ حَدَّهُ مِنْ مَعْبُودٍ أَوْ مَتْبُوعٍ أَوْ مُطَاعٍ. وَالطَّوَاغِيتُ كَثِيرُونَ وَرُؤُوسُهُمْ خَمْسَةٌ: إِبْلِيسُ لَعَنَهُ اللهُ، وَمَنْ عُبِدَ وَهُوَ رَاضٍ، وَمَنْ دَعَا النَّاسَ إِلَى عِبَادَةِ نَفْسِهِ، وَمَنْ ادَّعَى شَيْئًا مِنْ عِلْمِ الْغَيْبِ، وَمَنْ حَكَمَ بِغَيْرِ مَا أَنْزَلَ اللهُ.', '<p>قَالَ ابْنُ الْقَيِّمِ (رَحِمَهُ اللهُ): مَعْنَى الطَّاغُوتِ مَا تَجَاوَزَ بِهِ الْعَبْدُ حَدَّهُ مِنْ مَعْبُودٍ أَوْ مَتْبُوعٍ أَوْ مُطَاعٍ. وَالطَّوَاغِيتُ كَثِيرُونَ وَرُؤُوسُهُمْ خَمْسَةٌ: إِبْلِيسُ لَعَنَهُ اللهُ، وَمَنْ عُبِدَ وَهُوَ رَاضٍ، وَمَنْ دَعَا النَّاسَ إِلَى عِبَادَةِ نَفْسِهِ، وَمَنْ ادَّعَى شَيْئًا مِنْ عِلْمِ الْغَيْبِ، وَمَنْ حَكَمَ بِغَيْرِ مَا أَنْزَلَ اللهُ.</p>', 'arabic', 'rtl', 91, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1735, 407, 92, 'Ibnul Qayyim (رحمه الله) amesema: “Maana ya twaghuti ni kila anachopindukia mja mipaka yake; ikiwa ni kinachoabudiwa, au kinachofuatwa au kinachotiiwa. Na matwaghuti ni wengi. Wakuu wao ni watano; Ibliys laana za Allaah ziwe juu yake, na anayeabudiwa hali ya kuwa yeye yuko radhi, na anayeita watu wamwabudu yeye, na anayedai kujua elimu ya ghayb (isiyoonekana na kujulikana isipokuwa na Allaah), na anayehukumu yale ambayo Hakuyateremsha Allaah.”', '<p>Ibnul Qayyim <strong>(رحمه الله)</strong> amesema: “Maana ya twaghuti ni kila anachopindukia mja mipaka yake; ikiwa ni kinachoabudiwa, au kinachofuatwa au kinachotiiwa. Na matwaghuti ni wengi. Wakuu wao ni watano; Ibliys laana za Allaah ziwe juu yake, na anayeabudiwa hali ya kuwa yeye yuko radhi, na anayeita watu wamwabudu yeye, na anayedai kujua elimu ya ghayb (isiyoonekana na kujulikana isipokuwa na Allaah), na anayehukumu yale ambayo Hakuyateremsha Allaah.” </p>', 'swahili', 'ltr', 92, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1736, 407, 93, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 93, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1737, 407, 94, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 94, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1738, 407, 95, 'لَا إِكْرَاهَ فِي الدِّينِ ۖ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۚ فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّـهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّـهُ سَمِيعٌ عَلِيمٌ ﴿٢٥٦﴾', '<p> <strong>لَا إِكْرَاهَ فِي الدِّينِ ۖ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۚ فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّـهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّـهُ سَمِيعٌ عَلِيمٌ ﴿٢٥٦﴾</strong></p>', 'arabic', 'rtl', 95, '#b99137', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1739, 407, 96, '((Hapana kulazimisha katika (kuingia) Dini, kwani imekwishabainika kati ya uongofu na upotofu. Basi atakayemkanusha twaaghuwt (miungu ya uongo) na akamwamini Allaah kwa hakika atakuwa ameshikilia imara kishikilio madhubuti kisichovunjika, na Allaah ni Mwenye kusikia yote, Mjuzi wa yote))[Al-Baqarah (2: 256).]', '<p>((Hapana kulazimisha katika (kuingia) Dini, kwani imekwishabainika kati ya uongofu na upotofu. Basi atakayemkanusha twaaghuwt (miungu ya uongo) na akamwamini Allaah kwa hakika atakuwa ameshikilia imara kishikilio madhubuti kisichovunjika, na Allaah ni Mwenye kusikia yote, Mjuzi wa yote))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn64\"><strong>[</strong></a><strong>Al-Baqarah (2: 256).</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn64\"><strong>]</strong></a></p>', 'swahili', 'ltr', 96, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1740, 407, 97, 'وَهَذَا هُوَ مَعْنَى لا إلٰه إِلا اللهُ.', '<p>وَهَذَا هُوَ مَعْنَى لا إلٰه إِلا اللهُ.</p>', 'arabic', 'rtl', 97, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1741, 407, 98, 'Na hii ndio maana ya Laa ilaaha illa-Allaah (hapana Muabudiwa wa haki isipokuwa Allaah).', '<p>Na hii ndio maana ya <i>Laa ilaaha illa-Allaah</i> (hapana Muabudiwa wa haki isipokuwa Allaah).</p>', 'swahili', 'ltr', 98, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1742, 407, 99, 'وَفِي الْحَدِيث: ((رَأْسُ الأَمْرِ الإِسْلامِ، وَعَمُودُهُ الصَّلاةُ، وَذِرْوَةُ سَنَامِهِ الْجِهَادُ فِي سَبِيلِ اللهِ))', '<p>وَفِي الْحَدِيث<strong>: ((رَأْسُ الأَمْرِ الإِسْلامِ، وَعَمُودُهُ الصَّلاةُ، وَذِرْوَةُ سَنَامِهِ الْجِهَادُ فِي سَبِيلِ اللهِ))</strong></p>', 'arabic', 'rtl', 99, '#1b59b1', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1743, 407, 100, 'Na katika Hadiyth: ((Msingi wa mambo ni Uislamu, na nguzo yake ni Swalaah na kilele cha nundu yake ni kupigana katika njia ya Allaah))[At-Tirmidhiy, Ibn Maajah na ni Swahiyh kwa mujibu wa Al-Albaaniy katika Swahiyh Sunan At-Tirmidhiy (2110)]', '<p>Na katika Hadiyth: <strong>((Msingi wa mambo ni Uislamu, na nguzo yake ni Swalaah na kilele cha nundu yake ni kupigana katika njia ya Allaah))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn65\"><i><strong>[At-Tirmidhiy, Ibn Maajah na ni Swahiyh kwa mujibu wa Al-Albaaniy katika Swahiyh Sunan At-Tirmidhiy (2110)]</strong></i></a><strong>  </strong></p>', 'swahili', 'ltr', 100, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1744, 407, 101, 'وَاللهُ أَعْلَمُ. وَصَلَّى اللهُ عَلَى مُحَمَّدٍ وَعلى آلٰه وَصَحْبِهِ وَسَلَّمَ', '<p>وَاللهُ أَعْلَمُ. وَصَلَّى اللهُ عَلَى مُحَمَّدٍ وَعلى آلٰه وَصَحْبِهِ وَسَلَّمَ</p>', 'arabic', 'rtl', 101, '#b48c00', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1745, 407, 102, 'Na Allaah Anajua zaidi wa Swalla Allaahu ‘alaa Muhammadi wa ‘alaa aalihi wa Swahabihi wa sallam.', '<p>Na Allaah Anajua zaidi wa Swalla Allaahu ‘alaa Muhammadi wa ‘alaa aalihi wa Swahabihi wa sallam.</p>', 'swahili', 'ltr', 102, '#1f2937', '#ffffff', '2026-08-27 08:50:11', '2026-08-27 08:50:11', NULL, NULL, NULL, 0),
(1746, 404, 1, 'الأَصْلُ الثَّانِي: مَعْرِفَةُ دِينِ الإِسْلامِ بِالأَدِلَّةِ.', '<p><strong>الأَصْلُ الثَّانِي: مَعْرِفَةُ دِينِ الإِسْلامِ بِالأَدِلَّةِ.</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1747, 404, 2, 'Msingi Wa Pili: Kuijua Dini Ya Kiislamu Kwa Dalili', '<p><strong>Msingi Wa Pili: </strong>Kuijua Dini Ya Kiislamu Kwa Dalili</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1748, 404, 3, 'وَهُوَ :الاسْتِسْلامُ للهِ بِالتَّوْحِيدِ، وَالانْقِيَادُ لَهُ بِالطَّاعَةِ، وَالْبَرَاءَةُ مِنَ الشِّرْكِ وَأَهْلِهِ، وَهُوَ ثَلاثُ مَرَاتِبَ: الإسْلامُ، وَالإِيمَانُ، وَالإِحْسَانُ. وَكُلُّ مَرْتَبَةٍ لَهَا أَرْكَانٌ.', '<p><strong>وَهُوَ</strong> :<strong>الاسْتِسْلامُ للهِ بِالتَّوْحِيدِ، وَالانْقِيَادُ لَهُ بِالطَّاعَةِ،</strong> <strong>وَالْبَرَاءَةُ مِنَ الشِّرْكِ وَأَهْلِهِ، وَهُوَ ثَلاثُ مَرَاتِبَ:</strong> <strong>الإسْلامُ، وَالإِيمَانُ، وَالإِحْسَانُ. وَكُلُّ مَرْتَبَةٍ لَهَا</strong> <strong>أَرْكَانٌ.</strong></p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1749, 404, 4, 'Nayo ni kujisalimisha kwa Allaah kwa Tawhiyd, na kunyenyekea katika utiifu, na kujiweka mbali na shirki pamoja na watu wake (wa shirki), nao (huo Msingi wa pili) umegawanyika katika daraja tatu; Uislamu, Iymaan, Ihsaan. Na kila daraja ina nguzo.', '<p>Nayo ni kujisalimisha kwa Allaah kwa Tawhiyd, na kunyenyekea katika utiifu, na kujiweka mbali na shirki pamoja na watu wake (wa shirki), nao (huo Msingi wa pili) umegawanyika katika daraja tatu; Uislamu, Iymaan, Ihsaan. Na kila daraja ina nguzo.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1750, 404, 5, 'المرتبة الأولى: الإسلام.', '<p>المرتبة الأولى: الإسلام.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1751, 404, 6, 'Daraja Ya Kwanza: Uislamu', '<p>Daraja Ya Kwanza: Uislamu</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1752, 404, 7, 'فَأَرْكَانُ الإِسْلامِ خَمْسَةٌ: ((شَهَادَةُ أَن لا إلٰه إِلا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامُ الصَّلاةِ، وَإِيتَاء الزَّكَاةِ، وَصَوْمُ رَمَضَانَ، وَحَجُّ بَيْتِ اللهِ الْحَرَام))', '<p>فَأَرْكَانُ الإِسْلامِ خَمْسَةٌ:<br><strong> ((شَهَادَةُ أَن لا إلٰه إِلا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامُ الصَّلاةِ، وَإِيتَاء الزَّكَاةِ، وَصَوْمُ رَمَضَانَ، وَحَجُّ بَيْتِ اللهِ الْحَرَام))</strong></p>', 'arabic', 'rtl', 7, '#0b5bcb', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1753, 404, 8, 'Na nguzo za Kiislamu ni tano: ((Kushuhudia kwa kukiri kwa moyo na kutamka kwamba laa ilaaha illa-Allaah - hakuna Muabudiwa wa haki isipokuwa Allaah, na kwamba Muhammad ni Rasuli wa Allaah, na kusimamisha Swalaah, na kutoa Zakaah, na kufunga Swawm Ramadhwaan, na kuhiji Nyumba Tukufu ya Allaah))[Muslim.]', '<p>Na nguzo za Kiislamu ni tano:</p><p> ((Kushuhudia kwa kukiri kwa moyo na kutamka kwamba laa ilaaha illa-Allaah - hakuna Muabudiwa wa haki isipokuwa Allaah, na kwamba Muhammad ni Rasuli wa Allaah, na kusimamisha Swalaah, na kutoa Zakaah, na kufunga Swawm Ramadhwaan, na kuhiji Nyumba Tukufu ya Allaah))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn32\">[Muslim.]</a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1754, 404, 9, 'فَدَلِيلُ الشَّهَادَةِ قَوْلُهُ تَعَالَى:', '<p>فَدَلِيلُ الشَّهَادَةِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1755, 404, 10, 'Na dalili ya Shahada ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Shahada ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1756, 404, 11, 'شَهِدَ اللَّـهُ أَنَّهُ لَا إِلَـٰهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ ۚ لَا إِلَـٰهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ ﴿١٨﴾', '<p><strong>شَهِدَ اللَّـهُ أَنَّهُ لَا إِلَـٰهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ ۚ لَا إِلَـٰهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ ﴿١٨﴾</strong></p>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1757, 404, 12, '((Allaah Ameshuhudia kwamba hapana Muabudiwa wa haki ila Yeye; na Malaika, na wenye elimu (wameshuhudia kwamba Allaah) ni Mwenye kusimamisha (uumbaji Wake) kwa uadilifu. Hapana Muabudiwa wa haki ila Yeye Mwenye enzi ya nguvu Asiyeshindika, Mwenye hikmah wa yote))[Aal-‘Imraan (3: 18).]', '<p><strong> ((</strong>Allaah Ameshuhudia kwamba hapana Muabudiwa wa haki ila Yeye; na Malaika, na wenye elimu (wameshuhudia kwamba Allaah) ni Mwenye kusimamisha (uumbaji Wake) kwa uadilifu. Hapana Muabudiwa wa haki ila Yeye Mwenye enzi ya nguvu Asiyeshindika, Mwenye hikmah wa yote))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn33\"><strong>[Aal-‘Imraan (3: 18).]</strong></a></p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1758, 404, 13, 'وَمَعْنَاهَا :لا مَعْبُودَ بِحَقٍّ إلا اللهُ، وَحَدُّ النَّفْيِ مِنْ الإِثْبَاتِ ((لَا إِلَـٰهَ)) نَافِيًا جَمِيعَ مَا يُعْبَدُ مِنْ دُونِ اللهِ ((إلاَّ الله))  مُثْبِتًا الْعِبَادَةَ للهِ وَحْدَهُ لا شَرِيكَ لَهُ فِي عِبَادَتِهِ، كَمَا أَنَّهُ لَيْسَ لَهُ شَرِيكٌ فِي مُلْكِهِ.', '<p>وَمَعْنَاهَا :لا مَعْبُودَ بِحَقٍّ إلا اللهُ، وَحَدُّ النَّفْيِ مِنْ الإِثْبَاتِ ((لَا إِلَـٰهَ)) نَافِيًا جَمِيعَ مَا يُعْبَدُ مِنْ دُونِ اللهِ ((إلاَّ الله))  مُثْبِتًا الْعِبَادَةَ للهِ وَحْدَهُ لا شَرِيكَ لَهُ فِي عِبَادَتِهِ، كَمَا أَنَّهُ لَيْسَ لَهُ شَرِيكٌ فِي مُلْكِهِ.</p>', 'arabic', 'rtl', 13, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1759, 404, 14, 'Na maana yake ni: Hakuna Muabudiwa wa haki ila Allaah Pekee. ((Laa ilaaha – hakuna muabudiwa wa haki)) inakanusha kila kinachoabudiwa pasi na Allaah. Ama ((illa-Allaah – isipokuwa Allaah)) inathibitisha ‘ibaadah zote ni kwa ajili ya Allaah Pekee. Hana mshirika katika ‘ibaadah Zake kama Alivyokuwa hana mshirika katika Ufalme Wake.', '<p>Na maana yake ni: Hakuna Muabudiwa wa haki ila Allaah Pekee. ((<strong>Laa ilaaha – hakuna muabudiwa wa haki))</strong> inakanusha kila kinachoabudiwa pasi na Allaah. Ama ((<strong>illa-Allaah – isipokuwa Allaah</strong>)) inathibitisha ‘ibaadah zote ni kwa ajili ya Allaah Pekee. Hana mshirika katika ‘ibaadah Zake kama Alivyokuwa hana mshirika katika Ufalme Wake.</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1760, 404, 15, 'وَتَفْسِيرُهَا الَّذِي يُوَضِّحُهَا قَوْلُهُ تَعَالَى:', '<p>وَتَفْسِيرُهَا الَّذِي يُوَضِّحُهَا قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 15, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1761, 404, 16, 'Na tafsiri inayobainisha wazi (Shahaadah), ni kauli Yake Ta’aalaa:', '<p>Na tafsiri inayobainisha wazi (Shahaadah), ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1762, 404, 17, 'وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَرَاءٌ مِّمَّا تَعْبُدُونَ ﴿٢٦﴾ إِلَّا الَّذِي فَطَرَنِي فَإِنَّهُ سَيَهْدِينِ ﴿٢٧﴾ وَجَعَلَهَا كَلِمَةً بَاقِيَةً فِي عَقِبِهِ لَعَلَّهُمْ يَرْجِعُونَ ﴿٢٨﴾', '<p><strong>وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَرَاءٌ مِّمَّا تَعْبُدُونَ ﴿٢٦﴾ إِلَّا الَّذِي فَطَرَنِي فَإِنَّهُ سَيَهْدِينِ ﴿٢٧﴾ وَجَعَلَهَا كَلِمَةً بَاقِيَةً فِي عَقِبِهِ لَعَلَّهُمْ يَرْجِعُونَ ﴿٢٨﴾</strong></p>', 'arabic', 'rtl', 17, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1763, 404, 18, '((Na Ibraahiym alipomwambia baba yake na kaumu yake: “Hakika mimi nimejitoa katika dhima na yale mnayoyaabudu. “Isipokuwa Ambaye Ameniumba, basi hakika Yeye Ataniongoza.” Na akalifanya neno (la ilaaha illaa-Allaah) lenye kubakia katika kizazi chake ili wapate kurejea.))[Az-Zukhruf (43: 26-28).]', '<p>((Na Ibraahiym alipomwambia baba yake na kaumu yake: “Hakika mimi nimejitoa katika dhima na yale mnayoyaabudu. “Isipokuwa Ambaye Ameniumba, basi hakika Yeye Ataniongoza.” Na akalifanya neno (la ilaaha illaa-Allaah) lenye kubakia katika kizazi chake ili wapate kurejea.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn34\"><strong>[Az-Zukhruf (43: 26-28).]</strong></a></p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1764, 404, 19, 'وقَوْلُهُ تَعَالَى:', '<p>وقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 19, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1765, 404, 20, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1766, 404, 21, 'قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّـهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ اللَّـهِ ۚ فَإِن تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ ﴿٦٤﴾', '<p><strong>قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّـهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ اللَّـهِ ۚ فَإِن تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ ﴿٦٤﴾</strong></p>', 'arabic', 'rtl', 21, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1767, 404, 22, '((Sema: “Enyi Ahlal-Kitaabi! Njooni katika neno lililo sawa baina yetu na baina yenu, kwamba tusiabudu isipokuwa Allaah Pekee, na wala tusimshirikishe na chochote, na wala wasichukue baadhi yetu wengine kuwa waungu badala ya Allaah.” Wakikengeuka; basi semeni: “Shuhudieni kwamba sisi ni Waislaam tunajisalimisha kwa Allaah.”))[Aal-‘Imraan (3: 64).]', '<p><strong>((</strong>Sema: “<i>Enyi Ahlal-Kitaabi! </i>Njooni katika neno lililo sawa baina yetu na baina yenu, kwamba tusiabudu isipokuwa Allaah Pekee, na wala tusimshirikishe na chochote, na wala wasichukue baadhi yetu wengine kuwa waungu badala ya Allaah.” Wakikengeuka; basi semeni: “Shuhudieni kwamba sisi ni Waislaam tunajisalimisha kwa Allaah.”))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn35\"><strong>[Aal-‘Imraan (3: 64).]</strong></a></p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1768, 404, 23, 'وَدِليلُ شَهَادَةِ أَنَّ مُحَمَّدًا رَسُولُ اللهِ قَوْلُهُ تَعَالَى:', '<p>وَدِليلُ شَهَادَةِ أَنَّ مُحَمَّدًا رَسُولُ اللهِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 23, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1769, 404, 24, 'Na dalili ya kushuhudia kwamba Muhammad ni Rasuli wa Allaah ni kauli Yake Ta’aalaa:', '<p>Na dalili ya kushuhudia kwamba Muhammad ni Rasuli wa Allaah ni kauli Yake Ta’aalaa: <strong> </strong></p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1770, 404, 25, 'لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ ﴿١٢٨﴾', '<p><strong>لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ ﴿١٢٨﴾</strong></p>', 'arabic', 'rtl', 25, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1771, 404, 26, '((Kwa yakini amekujieni Rasuli anayetokana na nyinyi wenyewe, yanamtia mashaka (na huzuni) yanayokutaabisheni, anakujalini (muongoke) mwenye huruma kwa Waumini ni mwenye huruma mno, mwenye rahmah))[At-Tawbah (9: 128).]', '<p><strong>((</strong>Kwa yakini amekujieni Rasuli anayetokana na nyinyi wenyewe, yanamtia mashaka (na huzuni) yanayokutaabisheni, anakujalini (muongoke) mwenye huruma kwa Waumini ni mwenye huruma mno, mwenye rahmah<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn36\"><strong>[At-Tawbah (9: 128).]</strong></a></p>', 'swahili', 'ltr', 26, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1772, 404, 27, 'وَمَعْنَى شَهَادَة أَنَّ مُحَمَّدًا رَسُولُ الله: طَاعَتُهُ فِيمَا أَمَرَ، وَتَصْدِيقُهُ فِيمَا أَخْبَرَ، واجْتِنَابُ مَا نَهَى عَنْهُ وَزَجَرَ وأَلا يُعْبَدَ اللهُ إِلا بِمَا شَرَعَ.', '<p>وَمَعْنَى شَهَادَة أَنَّ مُحَمَّدًا رَسُولُ الله: طَاعَتُهُ فِيمَا أَمَرَ، وَتَصْدِيقُهُ فِيمَا أَخْبَرَ، واجْتِنَابُ مَا نَهَى عَنْهُ وَزَجَرَ وأَلا يُعْبَدَ اللهُ إِلا بِمَا شَرَعَ.</p>', 'arabic', 'rtl', 27, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1773, 404, 28, 'Na maana ya kushuhudia kwamba Muhammad ni Rasuli wa Allaah, ni kumtii yale aliyoyaamrisha, na kumsadikisha katika aliyoyajulisha, na kujiepusha na ambayo ameyakataza na aliyoyatahadharisha, na kwamba Allaah asiabudiwe isipokuwa kwa kufuata yale yaliyowekewa Shariy’ah.', '<p>Na maana ya kushuhudia kwamba Muhammad ni Rasuli wa Allaah, ni kumtii yale aliyoyaamrisha, na kumsadikisha katika aliyoyajulisha, na kujiepusha na ambayo ameyakataza na aliyoyatahadharisha, na kwamba Allaah asiabudiwe isipokuwa kwa kufuata yale yaliyowekewa Shariy’ah.</p>', 'swahili', 'ltr', 28, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1774, 404, 29, 'وَدَلِيلُ الصَّلاةِ، وَالزَّكَاةِ، وَتَفْسِيرُ التَّوْحِيدِ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الصَّلاةِ، وَالزَّكَاةِ، وَتَفْسِيرُ التَّوْحِيدِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 29, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1775, 404, 30, 'Na dalili ya Swalaah na Zakaah na tafsiri ya At-Tawhiyd ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Swalaah na Zakaah na tafsiri ya At-Tawhiyd ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 30, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1776, 404, 31, 'وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّـهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ ﴿٥﴾', '<p><strong>وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّـهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ ﴿٥﴾</strong></p>', 'arabic', 'rtl', 31, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1777, 404, 32, '((Na hawakuamrishwa isipokuwa wamwabudu Allaah wenye kumtakasia Dini, wenye kujiengua na upotofu kuelemea Dini ya haki na wasimamishe Swalaah na watoe Zakaah; na hiyo ndiyo Dini iliyosimama imara.))[Al-Bayyinah (98: 5).]', '<p><strong> </strong>((Na hawakuamrishwa isipokuwa wamwabudu Allaah wenye kumtakasia Dini, wenye kujiengua na upotofu kuelemea Dini ya haki na wasimamishe Swalaah na watoe Zakaah; na hiyo ndiyo Dini iliyosimama imara.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn37\"><strong>[Al-Bayyinah (98: 5).]</strong></a></p>', 'swahili', 'ltr', 32, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1778, 404, 33, 'وَدَلِيلُ الصِّيَامِ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الصِّيَامِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 33, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1779, 404, 34, 'Na dalili ya Swiyaam ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Swiyaam ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 34, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1780, 404, 35, 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿١٨٣﴾', '<p><strong>يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿١٨٣﴾</strong></p>', 'arabic', 'rtl', 35, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(1781, 404, 36, '((Enyi walioamini! Mmeandikiwa shariy’ah ya kufunga Swiyaam kama ilivyoandikwa kwa walio kabla yenu mpate kuwa na taqwa.))[Al-Baqarah (2: 183).]', '<p><strong>((</strong>Enyi walioamini! Mmeandikiwa shariy’ah ya kufunga Swiyaam kama ilivyoandikwa kwa walio kabla yenu mpate kuwa na taqwa.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn38\"><strong>[Al-Baqarah (2: 183).]</strong></a></p>', 'swahili', 'ltr', 36, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1782, 404, 37, 'وَدَلِيلُ الْحَجِّ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الْحَجِّ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 37, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1783, 404, 38, 'Na dalili ya Hajj ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Hajj ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 38, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1784, 404, 39, 'وَلِلَّـهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ اللَّـهَ غَنِيٌّ عَنِ الْعَالَمِينَ ﴿٩٧﴾', '<p><strong>وَلِلَّـهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ اللَّـهَ غَنِيٌّ عَنِ الْعَالَمِينَ ﴿٩٧﴾</strong> </p>', 'arabic', 'rtl', 39, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1785, 404, 40, '((Na kwa ajili ya Allaah ni wajibu kwa watu watekeleze Hajj katika Nyumba hiyo kwa mwenye uwezo. Na atakayekufuru, basi hakika Allaah ni Mkwasi kwa walimwengu.))[Aal-‘Imraan (3: 97).]', '<p><strong>((</strong>Na kwa ajili ya Allaah ni wajibu kwa watu watekeleze Hajj katika Nyumba hiyo kwa mwenye uwezo. Na atakayekufuru, basi hakika Allaah ni Mkwasi kwa walimwengu.<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn39\"><strong>[Aal-‘Imraan (3: 97).]</strong></a></p>', 'swahili', 'ltr', 40, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1786, 405, 1, 'الْمَرْتَبَةُ الثَّانِيَةُ: الإِيمَانُ', '<p><strong>                       الْمَرْتَبَةُ الثَّانِيَةُ: الإِيمَانُ</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1787, 405, 2, 'Daraja Ya Pili: Iymaan', '<p><strong>Daraja Ya Pili:</strong> Iymaan</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1788, 405, 3, 'وَهُوَ: ((بِضْعٌ وَسَبْعُونَ شُعْبَةً، فَأَعْلاهَا قَوْلُ لا إلٰه إِلا اللهُ، وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنْ الإِيمَانِ))', '<p><strong>وَهُوَ:</strong><br><strong> ((بِضْعٌ وَسَبْعُونَ شُعْبَةً، فَأَعْلاهَا قَوْلُ لا إلٰه إِلا اللهُ، وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنْ الإِيمَانِ))</strong></p>', 'arabic', 'rtl', 3, '#1458b8', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1789, 405, 4, 'Nayo ni:((Ina tanzu [matawi] sabiini na kitu. Ya juu yake ni kauli ya “laa ilaaha illa-Allaah” [hapana Muabudiwa wa haki ila Allaah], na ya chini yake kabisa ni kuondosha uchafu njiani. Na kuona hayaa ni utanzu [tawi] katika tanzu za imani))[Al-Bukhaariy na Muslim.]', '<p>Nayo ni:</p><p>((Ina tanzu [matawi] sabiini na kitu. Ya juu yake ni kauli ya “laa ilaaha illa-Allaah” [hapana Muabudiwa wa haki ila Allaah], na ya chini yake kabisa ni kuondosha uchafu njiani. Na kuona hayaa ni utanzu [tawi] katika tanzu za imani))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn40\">[Al-Bukhaariy na Muslim.]</a></p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1790, 405, 5, 'وَأَرْكَانُهُ سِتَّةٌ كما فى الحديث:((أَنْ تُؤْمِنَ بِاللهِ، وَمَلائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ))', '<p>وَأَرْكَانُهُ سِتَّةٌ كما فى الحديث:<br><strong>((أَنْ تُؤْمِنَ بِاللهِ، وَمَلائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ))</strong></p>', 'arabic', 'rtl', 5, '#154e9d', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1791, 405, 6, 'Na nguzo zake ni sita kama katika Hadiyth:((Ni kumwamini Allaah, na Malaika Wake, na Vitabu Vyake, na Rasuli Wake na Siku ya Mwisho, na kuamini Al-Qadr [majaaliwa] ya kheri na shari zake)).[Muslim.]', '<p>Na nguzo zake ni sita kama katika Hadiyth:</p><p>((Ni kumwamini Allaah, na Malaika Wake, na Vitabu Vyake, na Rasuli Wake na Siku ya Mwisho, na kuamini Al-Qadr [majaaliwa] ya kheri na shari zake))<i>.</i><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn41\">[Muslim.]</a></p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1792, 405, 7, 'وَالدَّلِيلُ عَلَى هَذِهِ الأَرْكَانِ السِّتَةِ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ عَلَى هَذِهِ الأَرْكَانِ السِّتَةِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1793, 405, 8, 'Na dalili ya hizi nguzo sita ni kauli Yake Ta’aalaa:', '<p>Na dalili ya hizi nguzo sita ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1794, 405, 9, 'لَّيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَـٰكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّـهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ', '<p><strong>لَّيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَـٰكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّـهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ</strong></p>', 'arabic', 'rtl', 9, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1795, 405, 10, '((Si wema (pekee) kuwa mnaelekeza nyuso zenu upande wa Mashariki na Magharibi lakini wema (khaswa) ni mwenye kuamini Allaah na Siku ya Mwisho na Malaika na Kitabu na Manabii))[Al-Baqarah (2: 177).]', '<p><strong>((</strong>Si wema (pekee) kuwa mnaelekeza nyuso zenu upande wa Mashariki na Magharibi lakini wema (khaswa) ni mwenye kuamini Allaah na Siku ya Mwisho na Malaika na Kitabu na Manabii<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn42\"><strong>[Al-Baqarah (2: 177).]</strong></a></p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1796, 405, 11, 'ودليل القدر قَوْلُهُ تَعَالَى:', '<p> ودليل القدر قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 11, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1797, 405, 12, 'Na dalili ya Al-Qadr (majaaliwa) ni kauli ya Allaah:', '<p>Na dalili ya Al-Qadr (majaaliwa) ni kauli ya Allaah:</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1798, 405, 13, 'إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ ﴿٤٩﴾', '<p><strong>إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ ﴿٤٩﴾</strong></p>', 'arabic', 'rtl', 13, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1799, 405, 14, '((Hakika sisi Tumekiumba kila kitu kwa makadirio))[Al-Qamar (54: 49).]', '<p>((Hakika sisi Tumekiumba kila kitu kwa makadirio<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn43\"><strong>[Al-Qamar (54: 49).]</strong></a></p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
