(1803, 406, 3, 'رُكْنٌ وَاحِدٌ  كما فى الحديث:  ((أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِن لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ))', '<p><strong>رُكْنٌ وَاحِدٌ  كما فى الحديث:</strong>  <strong>((أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِن لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ))</strong></p>', 'arabic', 'rtl', 3, '#155fc6', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1804, 406, 4, 'Nguzo yake ni moja kama katika Hadiyth:  ((Umwabudu Allaah kama kwamba unamuona, na hata kama humuoni, basi Yeye Anakuona))[Muslim -Hadiyth mashuhuri ya kuja Jibrily kumfunza Mtume (صلى الله عليه وآله وسلم) mas-alah ya Dini yake.]', '<p>Nguzo yake ni moja kama katika Hadiyth:<strong>  </strong>((<strong>Umwabudu Allaah kama kwamba unamuona, na hata kama humuoni, basi Yeye Anakuona))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn44\">[Muslim -Hadiyth mashuhuri ya kuja Jibrily kumfunza Mtume (صلى الله عليه وآله وسلم) mas-alah ya Dini yake.]</a></p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1805, 406, 5, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
