(1810, 406, 10, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1811, 406, 11, 'وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ ﴿٢١٧﴾ الَّذِي يَرَاكَ حِينَ تَقُومُ ﴿٢١٨﴾ وَتَقَلُّبَكَ فِي السَّاجِدِينَ ﴿٢١٩﴾ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ ﴿٢٢٠﴾', '<p><strong>وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ ﴿٢١٧﴾ الَّذِي يَرَاكَ حِينَ تَقُومُ ﴿٢١٨﴾ وَتَقَلُّبَكَ فِي السَّاجِدِينَ ﴿٢١٩﴾ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ ﴿٢٢٠﴾</strong></p>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1812, 406, 12, '((Na tawakali kwa Mwenye enzi ya nguvu Asiyeshindika, Mwenye kurehemu. Ambaye Anakuona wakati unaposimama. Na mageuko yako katika wenye kusujudu. Hakika Yeye Ndiye Mwenye kusikia yote, Mjuzi wa yote))[Ash-Shu’araa (26: 217-220).]', '<p>((Na tawakali kwa Mwenye enzi ya nguvu Asiyeshindika, Mwenye kurehemu. Ambaye Anakuona wakati unaposimama. Na mageuko yako katika wenye kusujudu. Hakika Yeye Ndiye Mwenye kusikia yote, Mjuzi wa yote))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn46\"><strong>[Ash-Shu’araa (26: 217-220).]</strong></a></p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1813, 406, 13, 'وقَوْلُهُ تَعَالَى:', '<p>وقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 13, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1814, 406, 14, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1815, 406, 15, 'وَمَا تَكُونُ فِي شَأْنٍ وَمَا تَتْلُو مِنْهُ مِن قُرْآنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ', '<p><strong>وَمَا تَكُونُ فِي شَأْنٍ وَمَا تَتْلُو مِنْهُ مِن قُرْآنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ</strong></p>', 'arabic', 'rtl', 15, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1816, 406, 16, '((Na hushughuliki katika jambo lolote, na wala husomi humo katika Qur-aan, na wala hamtendi ‘amali yoyote isipokuwa Tunakuwa Mashahidi juu yenu mnaposhughulika nayo))[Yuwnus (10: 61).].', '<p>((Na hushughuliki katika jambo lolote, na wala husomi humo katika Qur-aan, na wala hamtendi ‘amali yoyote isipokuwa Tunakuwa Mashahidi juu yenu mnaposhughulika nayo<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn47\"><strong>[Yuwnus (10: 61).]</strong></a>. </p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1817, 406, 17, 'وَالدَّلِيلُ مِنَ السُّنَّةِ حَدِيثُ جِبْرِيلَ الْمَشْهُورُ:', '<p>وَالدَّلِيلُ مِنَ السُّنَّةِ حَدِيثُ جِبْرِيلَ الْمَشْهُورُ:</p>', 'arabic', 'rtl', 17, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1818, 406, 18, 'Na dalili katika Sunnah ni Hadiyth mashuhuri ya Jibriyl:', '<p>Na dalili katika Sunnah ni Hadiyth mashuhuri ya Jibriyl:</p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1819, 406, 19, 'عَنْ عُمَرَ بنِ الْخَطَّابِ (رضي الله عنه) قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ  (صلى الله عليه وآله وسلم) إِذْ طَلَعَ عَلَيْنَا رَجُلٌ، شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعْرِ، لا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلا يَعْرِفُهُ مِنَّا أَحَدٌ، فَجَلَسَ إِلَى النَّبِيِّ (صلى الله عليه وآله وسلم) فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلامِ فَقَالَ: ((أَنْ تَشْهَدَ أَنْ لا إلٰه إِلا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَتُقِيمَ الصَّلاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنْ اسْتَطَعْتَ إِلَيْهِ سَبِيلا)) .قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ. قَالَ: أَخْبِرْنِي عَنِ الإِيمَانِ. قَال: ((أَنْ تُؤْمِنَ بِاللهِ، وَمَلائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ)) قَالَ: صَدَقْتَ. قَالَ: أَخْبِرْنِي عَنِ الإِحْسَانِ. قَال: ((أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ)) قَالَ: أَخْبِرْنِي عَنِ السَّاعَةِ. قَالَ: ((مَا الْمَسْؤُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ)) .قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا. قَالَ: ((أَنْ تَلِدَ الأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ)) .قَالَ: فَمَضَى، فَلَبِثْنَا مَلِيَّا، فَقَالَ: ((يَا عُمَرُ أَتَدْرُونَ مَنِ السَّائِلِ؟))  قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ((هَذَا جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ أَمْرَ دِينِكُم)).', '<p><strong>عَنْ عُمَرَ بنِ الْخَطَّابِ (رضي الله عنه) قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ  (صلى الله عليه وآله وسلم) إِذْ طَلَعَ عَلَيْنَا رَجُلٌ، شَدِيدُ</strong> <strong>بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعْرِ، لا يُرَى عَلَيْهِ أَثَرُ</strong> <strong>السَّفَرِ، وَلا يَعْرِفُهُ مِنَّا أَحَدٌ، فَجَلَسَ إِلَى النَّبِيِّ (صلى الله عليه وآله وسلم) فَأَسْنَدَ رُكْبَتَيْهِ إِلَى</strong> <strong>رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا</strong> <strong>مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلامِ فَقَالَ</strong>:<strong> ((أَنْ تَشْهَدَ أَنْ لا إلٰه إِلا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَتُقِيمَ الصَّلاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنْ اسْتَطَعْتَ إِلَيْهِ سَبِيلا))</strong> .<strong>قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ. قَالَ: أَخْبِرْنِي عَنِ الإِيمَانِ. قَال: ((أَنْ تُؤْمِنَ بِاللهِ، وَمَلائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ)) قَالَ: صَدَقْتَ. قَالَ: أَخْبِرْنِي عَنِ الإِحْسَانِ. قَال: ((أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ))</strong> <strong>قَالَ: أَخْبِرْنِي عَنِ السَّاعَةِ. قَالَ: ((مَا الْمَسْؤُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ)) </strong>.<strong>قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا. قَالَ: ((أَنْ تَلِدَ الأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ))</strong> .<strong>قَالَ: فَمَضَى، فَلَبِثْنَا مَلِيَّا، فَقَالَ: ((يَا عُمَرُ أَتَدْرُونَ مَنِ السَّائِلِ؟))  قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ((هَذَا جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ أَمْرَ دِينِكُم)).</strong></p>', 'arabic', 'rtl', 19, '#b99137', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1820, 406, 20, 'Imepokelewa kutoka kwa \'Umar  (رضي الله عنه) amesema: Siku moja tulikuwa tumekaa na Nabiy (صلى الله عليه وآله وسلم), hapo alitokea  mtu ambaye  nguo zake zilikuwa nyeupe pepe na nywele zake zilikuwa nyeusi sana; hakuwa na alama  ya machofu ya safari na wala hapakuwa na hata mmoja katika sisi aliyemtambua. Alienda akakaa karibu na Nabiy (صلى الله عليه وآله وسلم) akaweka magoti yake karibu na magoti yake na akaweka viganja vyake juu ya mapaja yake, kisha akasema; Ee Muhammad! Niambie kuhusu Uislamu.  Akasema: ((Ni kushuhudia kwa kukiri na kwa moyo kuwa hakuna Muabudiwa wa haki isipokuwa Allaah, na Muhammad ni Rasuli Wake, kusimamisha Swalaah, kutoa Zakaah, kufunga Swawm Ramadhwaan na kwenda kuhiji [Makkah] ukiweza)) Akasema yule mtu yaani Jibriyl: Umesema kweli. Tulipigwa na mshangao kwa kumuuliza kwake na kumsadikisha.  Na akasema tena: Niambie kuhusu Iymaan. Akasema: ((Ni kumwamini Allaah, Malaika Wake, Vitabu Vyake, Rasuli Wake na Siku ya Mwisho, na kuamini Al-Qadr kheri na shari zake)) Akasema: Umesema kweli. Akasema: Hebu nielezee kuhusu Ihsaan.  Akasema: ((Ni kumuabudu Allaah kama vile unamuona na hata kama humuoni basi Yeye Anakuona)).  Akasema: Niambie kuhusu Qiyaamah. Akajibu: ((Muulizwaji si mjuzi kama asivyo vilevile muulizaji)) Kisha akamwambia: Nijulishe alama zake: Akajibu: ((Kijakazi atazaa bibi yake, na utaona wachunga wenda miguu chini, wenda uchi [wasio na uwezo wa kumiliki hata mavazi], mafukara [wasiokuwa hata na sehemu ya kuishi kwa umaskini] wakishindana kujenga majumba ya fahari.)). Kisha [Jibriyl] akaondoka na nilitulia kidogo [nikitafakari]. Kisha Nabiy (صلى الله عليه وآله وسلم) akasema: ((Ee \'Umar! Je, mnamjua ni nani yule aliyekuwa akiuliza?)) Nikasema: Allaah na Rasuli Wake wanajua zaidi.  Akasema: ((Ni Jibriyl, alikuja kuwafundisha Dini yenu))[Muslim]', '<p>Imepokelewa kutoka kwa \'Umar <strong> (رضي الله عنه) </strong>amesema: Siku moja tulikuwa tumekaa na Nabiy <i>(</i><strong>صلى الله عليه وآله وسلم),</strong> hapo alitokea  mtu ambaye  nguo zake zilikuwa nyeupe pepe na nywele zake zilikuwa nyeusi sana; hakuwa na alama  ya machofu ya safari na wala hapakuwa na hata mmoja katika sisi aliyemtambua. Alienda akakaa karibu na Nabiy <i>(</i><strong>صلى الله عليه وآله وسلم) </strong>akaweka magoti yake karibu na magoti yake na akaweka viganja vyake juu ya mapaja yake, kisha akasema; Ee Muhammad! Niambie kuhusu Uislamu.  Akasema:<i> </i>((Ni kushuhudia kwa kukiri na kwa moyo kuwa hakuna Muabudiwa wa haki isipokuwa Allaah, na Muhammad ni Rasuli Wake, kusimamisha Swalaah, kutoa Zakaah, kufunga Swawm Ramadhwaan na kwenda kuhiji [Makkah] ukiweza))<i> </i>Akasema yule mtu yaani Jibriyl: Umesema kweli. Tulipigwa na mshangao kwa kumuuliza kwake na kumsadikisha.  Na akasema tena: Niambie kuhusu Iymaan. Akasema: ((Ni kumwamini Allaah, Malaika Wake, Vitabu Vyake, Rasuli Wake na Siku ya Mwisho, na kuamini Al-Qadr kheri na shari zake))<i> </i>Akasema: Umesema kweli. Akasema: Hebu nielezee kuhusu Ihsaan.  Akasema: ((Ni kumuabudu Allaah kama vile unamuona na hata kama humuoni basi Yeye Anakuona)).<i> </i> Akasema: Niambie kuhusu Qiyaamah. Akajibu: ((Muulizwaji si mjuzi kama asivyo vilevile muulizaji))<i> </i>Kisha akamwambia: Nijulishe alama zake: Akajibu:<i> ((</i>Kijakazi atazaa bibi yake, na utaona wachunga wenda miguu chini, wenda uchi [wasio na uwezo wa kumiliki hata mavazi], mafukara [wasiokuwa hata na sehemu ya kuishi kwa umaskini] wakishindana kujenga majumba ya fahari.<i>)). </i>Kisha [Jibriyl] akaondoka na nilitulia kidogo [nikitafakari]. Kisha Nabiy (صلى الله عليه وآله وسلم)<i> </i>akasema: ((Ee \'Umar! Je, mnamjua ni nani yule aliyekuwa akiuliza?)<i>) </i>Nikasema: Allaah na Rasuli Wake wanajua zaidi.  Akasema: ((Ni Jibriyl, alikuja kuwafundisha Dini yenu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn48\">[Muslim]</a> </p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 08:57:46', '2026-08-27 08:57:46', NULL, NULL, NULL, 0),
(1919, 403, 1, 'الأصْلُ الأوَّلُ: مَعْرِفَةُ الرَّب', '<p><strong>               الأصْلُ الأوَّلُ: مَعْرِفَةُ الرَّب</strong></p>', 'arabic', 'rtl', 1, '#0a5c1e', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
