(1921, 403, 3, 'فَإِذَا قِيلَ لَكَ :مَنْ رَبُّكَ؟', '<p>فَإِذَا قِيلَ لَكَ :مَنْ رَبُّكَ؟</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1922, 403, 4, 'Basi utakapoulizwa: “Nani Rabb wako?”', '<p><strong>Basi utakapoulizwa</strong>: “Nani Rabb wako?”</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1923, 403, 5, 'فَقُلْ: رَبِّيَ اللهُ الَّذِي رَبَّانِي، وَرَبَّى جَمِيعَ الْعَالَمِينَ بِنِعَمِهِ، وَهُوَ مَعْبُودِي لَيْسَ لِي مَعْبُودٌ سِوَاهُ.', '<p>فَقُلْ: رَبِّيَ اللهُ الَّذِي رَبَّانِي، وَرَبَّى جَمِيعَ الْعَالَمِينَ بِنِعَمِهِ، وَهُوَ مَعْبُودِي لَيْسَ لِي مَعْبُودٌ سِوَاهُ.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1924, 403, 6, 'Sema: “Rabb wangu ni Allaah Aliyenilea na Aliyewalea walimwengu wote kwa neema Zake. Naye Ndiye Ninayemwabudu, na sina mwengine ninayemwabudu.', '<p><strong>Sema:</strong> “Rabb wangu ni Allaah Aliyenilea na Aliyewalea walimwengu wote kwa neema Zake. Naye Ndiye Ninayemwabudu, na sina mwengine ninayemwabudu.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1925, 403, 7, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1926, 403, 8, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1927, 403, 9, 'الْحَمْدُ لِلَّـهِ رَبِّ الْعَالَمِينَ ﴿٢﴾', '<p><strong>الْحَمْدُ لِلَّـهِ رَبِّ الْعَالَمِينَ ﴿٢﴾</strong></p>', 'arabic', 'rtl', 9, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1928, 403, 10, '((AlhamduliLLaah Himidi Anastahiki Allaah Rabb wa walimwengu))[Al-Faatihah: (1: 2).]', '<p>((AlhamduliLLaah Himidi Anastahiki Allaah Rabb wa walimwengu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn9\">[Al-Faatihah: (1: 2).]</a></p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1929, 403, 11, 'وَكُلُّ مَنْ سِوَى اللهِ عَالَمٌ، وَأَنَا وَاحِدٌ مِنْ ذَلِكَ الْعَالَمِ.', '<p>وَكُلُّ مَنْ سِوَى اللهِ عَالَمٌ، وَأَنَا وَاحِدٌ مِنْ ذَلِكَ الْعَالَمِ.</p>', 'arabic', 'rtl', 11, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1930, 403, 12, 'Na kila kitu kisichokuwa Allaah, ni kilichoumbwa nami ni mmojawapo katika kilichoumbwa.', '<p>Na kila kitu kisichokuwa Allaah, ni kilichoumbwa nami ni mmojawapo katika kilichoumbwa.</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
