(1932, 403, 14, 'Basi utakapoulizwa: “Umemjuaje Rabb wako?”', '<p><strong>Basi utakapoulizwa</strong>: “Umemjuaje Rabb wako?”</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1933, 403, 15, 'فَقُلْ: آيَاتِهِ وَمَخْلُوقَاتِهِ، وَمِنْ آيَاتِهِ: اللَّيْلُ، وَالنَّهَارُ، وَالشَّمْسُ، وَالْقَمَرُ، وَمِنْ مَخْلُوقَاتِهِ السَّمَاوَاتُ السَّبْعُ وَالأَرَضُونَ السَّبْعُ وَمَنْ فِيهِنَّ، وَمَا بَيْنَهُمَا.', '<p>فَقُلْ: آيَاتِهِ وَمَخْلُوقَاتِهِ، وَمِنْ آيَاتِهِ: اللَّيْلُ، وَالنَّهَارُ، وَالشَّمْسُ، وَالْقَمَرُ، وَمِنْ مَخْلُوقَاتِهِ السَّمَاوَاتُ السَّبْعُ وَالأَرَضُونَ السَّبْعُ وَمَنْ فِيهِنَّ، وَمَا بَيْنَهُمَا.</p>', 'arabic', 'rtl', 15, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1934, 403, 16, 'Sema: “Kutokana na Aayaat (ishara) Zake na Alivyoviumba. Na miongoni mwa Aayaat Zake ni: Usiku, mchana, jua, mwezi. Na miongoni mwa Alivyoviumba ni mbingu saba na ardhi saba, na kila kilichokuwemo ndani yake na baina yake”', '<p><strong>Sema</strong>: “Kutokana na Aayaat (ishara) Zake na Alivyoviumba. Na miongoni mwa Aayaat Zake ni: Usiku, mchana, jua, mwezi. Na miongoni mwa Alivyoviumba ni mbingu saba na ardhi saba, na kila kilichokuwemo ndani yake na baina yake”</p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1935, 403, 17, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 17, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1936, 403, 18, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1937, 403, 19, 'وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ ۚ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلَّـهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ ﴿٣٧﴾', '<p><strong>وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ ۚ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلَّـهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ ﴿٣٧﴾</strong></p>', 'arabic', 'rtl', 19, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1938, 403, 20, '((Na katika Aayaat (ishara, dalili) Zake, ni usiku na mchana, na jua na mwezi.  Msisujudie jua wala mwezi; bali msujudieni Allaah Ambaye Aliyeviumba ikiwa Yeye Pekee mnawambudu))[Fusswilat (41: 37).]', '<p>((Na katika Aayaat (ishara, dalili) Zake, ni usiku na mchana, na jua na mwezi.  Msisujudie jua wala mwezi; bali msujudieni Allaah Ambaye Aliyeviumba ikiwa Yeye Pekee mnawambudu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn10\">[Fusswilat (41: 37).]</a></p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1939, 403, 21, 'وَقَوْلُهُ تَعَالَى:', '<p>وَقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 21, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1940, 403, 22, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1941, 403, 23, 'إِنَّ رَبَّكُمُ اللَّـهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ ۗ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ ۗ تَبَارَكَ اللَّـهُ رَبُّ الْعَالَمِينَ ﴿٥٤﴾', '<p><strong>إِنَّ رَبَّكُمُ اللَّـهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ ۗ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ ۗ تَبَارَكَ اللَّـهُ رَبُّ الْعَالَمِينَ ﴿٥٤﴾</strong></p>', 'arabic', 'rtl', 23, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1942, 403, 24, '((Hakika Rabb wenu ni Allaah Ambaye Ameumba mbingu na ardhi katika siku sita, kisha Istawaa juu ya ‘Arshi;[11] Anafunika usiku kwa mchana, unaufuatia upesi upesi na (Ameumba) jua na mwezi na nyota (vyote) vimetiishwa kwa amri Yake. Tanabahi! Ni Vyake Pekee uumbaji na amri. Tabaaraka Allaah, Amebarikika Allaah Rabb wa walimwengu))[Al-A’raaf (7: 54).]', '<p>((Hakika Rabb wenu ni Allaah Ambaye Ameumba mbingu na ardhi katika siku sita, kisha Istawaa juu ya ‘Arshi;<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn11\">[11]</a> Anafunika usiku kwa mchana, unaufuatia upesi upesi na (Ameumba) jua na mwezi na nyota (vyote) vimetiishwa kwa amri Yake. Tanabahi! Ni Vyake Pekee uumbaji na amri. Tabaaraka Allaah, Amebarikika Allaah Rabb wa walimwengu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn12\">[Al-A’raaf (7: 54).]</a></p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1943, 403, 25, 'وَالرَّبُ هُوَ الْمَعْبُودُ.', '<p>وَالرَّبُ هُوَ الْمَعْبُودُ.</p>', 'arabic', 'rtl', 25, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1944, 403, 26, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 26, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1945, 403, 27, 'يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿٢١﴾ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا لِلَّـهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ ﴿٢٢﴾', '<p><strong>يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴿٢١﴾ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا لِلَّـهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ ﴿٢٢﴾</strong></p>', 'arabic', 'rtl', 27, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1946, 403, 28, '((Enyi watu! Mwabuduni Rabb wenu Ambaye Amekuumbeni na wale wa kabla yenu mpate kuwa na taqwa. Ambaye Amewafanyieni ardhi kuwa ni tandiko na mbingu kuwa ni paa, na Akateremsha kutoka mbinguni maji, Akawatolea kwayo matunda kuwa ni riziki zenu. Basi msimfanyie Allaah waliolingana naye na hali ya kuwa nyinyi mnajua))[Al-Baqarah (2: 21-22).]', '<p><strong>((</strong>Enyi watu! Mwabuduni Rabb wenu Ambaye Amekuumbeni na wale wa kabla yenu mpate kuwa na taqwa. Ambaye Amewafanyieni ardhi kuwa ni tandiko na mbingu kuwa ni paa, na Akateremsha kutoka mbinguni maji, Akawatolea kwayo matunda kuwa ni riziki zenu. Basi msimfanyie Allaah waliolingana naye na hali ya kuwa nyinyi mnajua<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn13\"><strong>[Al-Baqarah (2: 21-22).]</strong></a></p>', 'swahili', 'ltr', 28, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1947, 403, 29, 'قَالَ ابْنُ كَثِيرٍ (رَحِمَهُ اللهُ): الخَالِقُ لِهَذِهِ الأَشْيَاءَ هُوَ الْمُسْتَحِقُّ لِلْعِبَادَةِ. وَأَنْوَاعُ الْعِبَادَةِ الَّتِي أَمَرَ اللهُ بِهَا مِثْلُ: الإِسْلامِ، وَالإِيمَانِ، وَالإِحْسَانِ، وَمِنْهُ: الدُّعَاءُ، وَالْخَوْفُ، وَالرَّجَاءُ، وَالتَّوَكُّلُ، وَالرَّغْبَةُ، وَالرَّهْبَةُ، وَالْخُشُوعُ، وَالْخَشْيَةُ، وَالإِنَابَةُ، وَالاسْتِعَانَةُ، وَالاسْتِعَاذَةُ، وَالاسْتِغَاثَةُ، وَالذَّبْحُ، وَالنَّذْرُ، وَغَيْرُ ذَلَكَ مِنْ أَنْوَاعِ الْعِبَادَةِ الَّتِي أَمَرَ اللهُ بِهَا. كُلُّهَا للهِ تَعَالَى.', '<p>قَالَ ابْنُ كَثِيرٍ (رَحِمَهُ اللهُ): الخَالِقُ لِهَذِهِ الأَشْيَاءَ هُوَ الْمُسْتَحِقُّ لِلْعِبَادَةِ. وَأَنْوَاعُ الْعِبَادَةِ الَّتِي أَمَرَ اللهُ بِهَا مِثْلُ: الإِسْلامِ، وَالإِيمَانِ، وَالإِحْسَانِ، وَمِنْهُ: الدُّعَاءُ، وَالْخَوْفُ، وَالرَّجَاءُ، وَالتَّوَكُّلُ، وَالرَّغْبَةُ، وَالرَّهْبَةُ، وَالْخُشُوعُ، وَالْخَشْيَةُ، وَالإِنَابَةُ، وَالاسْتِعَانَةُ، وَالاسْتِعَاذَةُ، وَالاسْتِغَاثَةُ، وَالذَّبْحُ، وَالنَّذْرُ، وَغَيْرُ ذَلَكَ مِنْ أَنْوَاعِ الْعِبَادَةِ الَّتِي أَمَرَ اللهُ بِهَا. كُلُّهَا للهِ تَعَالَى.</p>', 'arabic', 'rtl', 29, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1948, 403, 30, 'Ibn Kathiyr (رحمه الله) amesema: “Muumbaji wa vitu hivi Ndiye Anayestahiki kuabudiwa. Na aina za ‘ibaadah ambazo Allaah Ameziamrisha ni mfano: Al-Islaam (Uislamu), Al-Iymaan (Imani), Al-Ihsaan (Ihsani).  Miongoni mwazo ni: Ad-Du’aa (du’aa), Al-Khawf  (khofu ya kuogopa mtu au adhabu au kitu), Ar-Rajaa (kutarajai), At-Tawakkul  (kutawakali kwa Allaah),  Ar-Raghbah (shauku, utashi na matumaini ya jambo la kupendwa), Ar-Rahbah (tisho au kuogopa), Al-Khushuu’ (unyenyekevu),   Al-Khashyah (khofu kutokana na utukufu wa Allaah nayo inahusiana na elimu), At-Taqwa (uchaji), Al-Inaabah (kurejea kutubu na utiifu), Al-Isti’aanah (kuomba msaada wa mambo ya kidunia au ya Aakhirah), Al-Isti’aadhah (kuomba kinga), Al-Istighaathah (kuomba msaada, kuokolewa, au kufarijiwa jambo au haja wakati wa shida au kuokolewa), Adh-Dhab-hu (kuchinja), An-Nadhru (kuweka nadhiri), na mengineyo ya aina za ‘ibaadah ambazo Allaah Ameziamrisha. Zote ziwe kwa ajili ya Allaah Ta’aalaa.', '<p>Ibn Kathiyr <strong>(رحمه الله)</strong> amesema: “Muumbaji wa vitu hivi Ndiye Anayestahiki kuabudiwa. Na aina za ‘ibaadah ambazo Allaah Ameziamrisha ni mfano: <i>Al-Islaam</i> (Uislamu), <i>Al-Iymaan</i> (Imani), <i>Al-Ihsaan</i> (Ihsani).  Miongoni mwazo ni: <i>Ad-Du’aa</i> (du’aa), <i>Al-Khawf</i>  (khofu ya kuogopa mtu au adhabu au kitu), <i>Ar-Rajaa (</i>kutarajai), <i>At-Tawakkul </i> (kutawakali kwa Allaah),  <i>Ar-Raghbah</i> (shauku, utashi na matumaini ya jambo la kupendwa), <i>Ar-Rahb</i><strong>ah</strong> (tisho au kuogopa), <i>Al-Khushuu’</i> (unyenyekevu),   <i>Al-Khashyah</i> (khofu kutokana na utukufu wa Allaah nayo inahusiana na elimu), At-Taqwa (uchaji), <i>Al-Inaabah</i> (kurejea kutubu na utiifu), <i>Al</i>-<i>Isti’aanah (</i>kuomba msaada wa mambo ya kidunia au ya Aakhirah), <i>Al-Isti’aadhah (</i>kuomba kinga), <i>Al-Istighaathah</i> (kuomba msaada, kuokolewa, au kufarijiwa jambo au haja wakati wa shida au kuokolewa), <i>Adh-Dhab-hu</i> (kuchinja), <i>An-Nadhru</i> (kuweka nadhiri), na mengineyo ya aina za ‘ibaadah ambazo Allaah Ameziamrisha. Zote ziwe kwa ajili ya Allaah Ta’aalaa.</p>', 'swahili', 'ltr', 30, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1949, 403, 31, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 31, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1950, 403, 32, 'Na dalili ni kauli Yake:', '<p>Na dalili ni kauli Yake:</p>', 'swahili', 'ltr', 32, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1951, 403, 33, 'وَأَنَّ الْمَسَاجِدَ لِلَّـهِ فَلَا تَدْعُوا مَعَ اللَّـهِ أَحَدًا ﴿١٨﴾', '<p><strong>وَأَنَّ الْمَسَاجِدَ لِلَّـهِ فَلَا تَدْعُوا مَعَ اللَّـهِ أَحَدًا ﴿١٨﴾</strong></p>', 'arabic', 'rtl', 33, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1952, 403, 34, '((Na kwamba Misikiti ni kwa ajili ya Allaah, basi msiombe yeyote pamoja na Allaah))[Al-Jinn (72: 18).]', '<p>((Na kwamba Misikiti ni kwa ajili ya Allaah, basi msiombe yeyote pamoja na Allaah))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn14\">[Al-Jinn (72: 18).]</a></p>', 'swahili', 'ltr', 34, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1953, 403, 35, 'فَمَنْ صَرَفَ مِنْهَا شَيْئًا لِغَيْرِ اللهِ؛ فَهُوَ مُشْرِكٌ كَافِرٌ.', '<p>فَمَنْ صَرَفَ مِنْهَا شَيْئًا لِغَيْرِ اللهِ؛ فَهُوَ مُشْرِكٌ كَافِرٌ.</p>', 'arabic', 'rtl', 35, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1954, 403, 36, 'Basi atakayeelekeza chochote katika hizo (‘ibaadah) kwa asiyekuwa Allaah, basi yeye ni mshirikina, kafiri.', '<p>Basi atakayeelekeza chochote katika hizo (‘ibaadah) kwa asiyekuwa Allaah, basi yeye ni mshirikina, kafiri.</p>', 'swahili', 'ltr', 36, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1955, 403, 37, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 37, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1956, 403, 38, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 38, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1957, 403, 39, 'وَمَن يَدْعُ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ ۚ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ ﴿١١٧﴾', '<p><strong>وَمَن يَدْعُ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ ۚ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ ﴿١١٧﴾</strong></p>', 'arabic', 'rtl', 39, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1958, 403, 40, '((Na yeyote yule anayeomba du’aa (au kuabudu) pamoja na Allaah mungu mwengine hana ushahidi wa wazi wa hilo; basi hakika hesabu yake iko kwa Rabb wake. Hakika hawafaulu makafiri))[Al-Muuminuwn (23: 117)]', '<p><strong> ((</strong>Na yeyote yule anayeomba du’aa (au kuabudu) pamoja na Allaah mungu mwengine hana ushahidi wa wazi wa hilo; basi hakika hesabu yake iko kwa Rabb wake. Hakika hawafaulu makafiri))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn15\">[Al-Muuminuwn (23: 117)]</a></p>', 'swahili', 'ltr', 40, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1959, 403, 41, 'وَفِي الْحَدِيثِ: ((الدُّعَاءُ مخ الْعِبَادَة))', '<p>وَفِي الْحَدِيثِ: ((الدُّعَاءُ مخ الْعِبَادَة))</p>', 'arabic', 'rtl', 41, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1960, 403, 42, 'Na katika Hadiyth:  ((Du’aa ni ubongo wa ‘Ibaadah))  [Hadiyth hii ni dhaifu. Ameipokea At-Tirmidhiy - Taz Al-Mishkaat (2331). Lakini ipo Hadiyth kama hiyo ambayo ni sahihi isemayo ((Du’aa ni ‘Ibaadah)) Taz. Swahiyh Al-Jaami’ Asw-Swaghiyr (3407)]', '<p>Na katika Hadiyth:  <strong>((Du’aa ni ubongo wa ‘Ibaadah))  </strong><br>[Hadiyth hii ni dhaifu. Ameipokea At-Tirmidhiy - Taz Al-Mishkaat (2331). Lakini ipo Hadiyth kama hiyo ambayo ni sahihi isemayo <i><strong>((Du’aa ni ‘Ibaadah))</strong></i> Taz. Swahiyh Al-Jaami’ Asw-Swaghiyr (3407)]</p>', 'swahili', 'ltr', 42, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1961, 403, 43, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 43, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1962, 403, 44, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 44, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1963, 403, 45, 'وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ ۚ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴿٦٠﴾', '<p><strong>وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ ۚ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴿٦٠﴾</strong></p>', 'arabic', 'rtl', 45, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1964, 403, 46, '((Na Rabb wenu Amesema: “Niombeni, Nitakuitikieni. Hakika wale wanaotakabari katika kuniabudu wataingika Jahanam wadhalilike))[Ghaafir (40: 60).]', '<p>((Na Rabb wenu Amesema: “Niombeni, Nitakuitikieni. Hakika wale wanaotakabari katika kuniabudu wataingika Jahanam wadhalilike<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn16\"><strong>[Ghaafir (40: 60).]</strong></a></p>', 'swahili', 'ltr', 46, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
