(1966, 403, 48, 'Na dalili ya Al-Khawf (kukhofu) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya <i>Al-Khawf</i> (kukhofu) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 48, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1967, 403, 49, 'فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ ﴿١٧٥﴾', '<p><strong>فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ ﴿١٧٥﴾</strong></p>', 'arabic', 'rtl', 49, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
