(1969, 403, 51, 'وَدَلِيلُ الرَّجَاءِ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الرَّجَاءِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 51, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1970, 403, 52, 'Na dalili ya Ar-Rajaa (kutaraji) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya <i>Ar-Rajaa</i> (kutaraji) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 52, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1971, 403, 53, 'فَمَن كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا ﴿١١٠﴾', '<p><strong>فَمَن كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا ﴿١١٠﴾</strong></p>', 'arabic', 'rtl', 53, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1972, 403, 54, '((Hivyo anayetaraji kukutana na Rabb wake, basi na atende ‘amali njema na wala asishirikishe yeyote katika ‘ibaadah za Rabb wake”))[Al-Kahf (18: 110).]', '<p>((Hivyo anayetaraji kukutana na Rabb wake, basi na atende ‘amali njema na wala asishirikishe yeyote katika ‘ibaadah za Rabb wake”))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn18\">[Al-Kahf (18: 110).]</a></p>', 'swahili', 'ltr', 54, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1973, 403, 55, 'وَدَلِيلُ التَّوَكُلِ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ التَّوَكُلِ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 55, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1974, 403, 56, 'Na dalili ya At-Tawakkul (kutawakali, kutegemea) kauli Yake Ta’aalaa:', '<p>Na dalili ya <i>At-Tawakkul</i> (kutawakali, kutegemea) kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 56, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1975, 403, 57, 'وَعَلَى اللَّـهِ فَتَوَكَّلُوا إِن كُنتُم مُّؤْمِنِينَ ﴿٢٣﴾', '<p><strong>وَعَلَى اللَّـهِ فَتَوَكَّلُوا إِن كُنتُم مُّؤْمِنِينَ ﴿٢٣﴾</strong></p>', 'arabic', 'rtl', 57, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1976, 403, 58, '((Na kwa Allaah Pekee tawakalini ikiwa nyinyi ni Waumini))[Al-Maaidah (5: 23).]', '<p>((Na kwa Allaah Pekee tawakalini ikiwa nyinyi ni Waumini))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn19\">[Al-Maaidah (5: 23).]</a></p>', 'swahili', 'ltr', 58, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
