(1979, 403, 61, 'وَمَن يَتَوَكَّلْ عَلَى اللَّـهِ فَهُوَ حَسْبُهُ ۚ', '<p><strong>وَمَن يَتَوَكَّلْ عَلَى اللَّـهِ فَهُوَ حَسْبُهُ ۚ</strong></p>', 'arabic', 'rtl', 61, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1980, 403, 62, '((Na yeyote anayetawakali kwa Allaah, basi Yeye Humtosheleza))[Atw-Twalaaq (65: 3).]', '<p>((Na yeyote anayetawakali kwa Allaah, basi Yeye Humtosheleza))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn20\">[Atw-Twalaaq (65: 3).]</a></p>', 'swahili', 'ltr', 62, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1981, 403, 63, 'وَدَلِيلُ الرَّغْبَةِ، وَالرَّهْبَةِ، وَالْخُشُوعِ، قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الرَّغْبَةِ، وَالرَّهْبَةِ، وَالْخُشُوعِ، قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 63, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1982, 403, 64, 'Na dalili ya Ar-Raghbah (shauku, utashi na matumaini ya jambo la kupendwa) na Ar-Rahbah (tisho au kuogopa) na Al-Khushuu’ (unyenyekevu) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya <i>Ar-Raghbah</i> (shauku, utashi na matumaini ya jambo la kupendwa) na <i>Ar-Rahbah</i> (tisho au kuogopa) na <i>Al-Khushuu’</i> (unyenyekevu) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 64, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1983, 403, 65, 'إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا ۖ وَكَانُوا لَنَا خَاشِعِينَ ﴿٩٠﴾', '<p><strong>إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا ۖ وَكَانُوا لَنَا خَاشِعِينَ ﴿٩٠﴾</strong></p>', 'arabic', 'rtl', 65, '#b99137', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0),
(1984, 403, 66, '((Hakika wao walikuwa wakikimbilia katika mambo ya kheri, na wakituomba kwa raghba na khofu, na walikuwa wenye kutunyenyekea))[Al-Anbiyaa (21: 90).]', '<p>((Hakika wao walikuwa wakikimbilia katika mambo ya kheri, na wakituomba kwa raghba na khofu, na walikuwa wenye kutunyenyekea<strong>))</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn21\"><strong>[Al-Anbiyaa (21: 90).]</strong></a></p>', 'swahili', 'ltr', 66, '#1f2937', '#ffffff', '2026-08-27 09:07:34', '2026-08-27 09:07:34', NULL, NULL, NULL, 0);
