(2154, 402, 14, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 14, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2155, 402, 15, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 15, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2156, 402, 16, 'بِسْمِ اللَّـهِ الرَّ‌حْمَـٰنِ الرَّ‌حِيمِوَالْعَصْرِ‌ ﴿١﴾ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ‌ ﴿٢﴾ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ‌ ﴿٣﴾', '<p><strong> بِسْمِ اللَّـهِ الرَّ‌حْمَـٰنِ الرَّ‌حِيمِ</strong></p><p><strong>وَالْعَصْرِ‌ ﴿١﴾ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ‌ ﴿٢﴾ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ‌ ﴿٣﴾</strong></p>', 'arabic', 'rtl', 16, '#b49113', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2157, 402, 17, 'Kwa Jina la Allaah, Ar-Rahmaan, Mwenye kurehemu.((Naapa kwa Al-‘Aswr (zama). Hakika mwana wa Aadam bila shaka yumo katika khasara. Isipokuwa wale walioamini na wakatenda mema na wakausiana haki na wakausiana subira)) [Al-‘Aswr (103).]', '<p>Kwa Jina la Allaah, Ar-Rahmaan, Mwenye kurehemu.</p><p>((Naapa kwa Al-‘Aswr (zama). Hakika mwana wa Aadam bila shaka yumo katika khasara. Isipokuwa wale walioamini na wakatenda mema na wakausiana haki na wakausiana subira)) <a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn2\">[Al-‘Aswr (103).]</a></p>', 'swahili', 'ltr', 17, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2158, 402, 18, 'قَالَ الشَّافِعيُّ (رَحِمَهُ اللهُ): لَوْ مَا أَنْزَلَ اللهُ حُجَّةً عَلَى خَلْقِهِ إِلا هَذِهِ السُّورَةَ لَكَفَتْهُمْ.', '<p>قَالَ الشَّافِعيُّ (رَحِمَهُ اللهُ): لَوْ مَا أَنْزَلَ اللهُ حُجَّةً عَلَى خَلْقِهِ إِلا هَذِهِ السُّورَةَ لَكَفَتْهُمْ.</p>', 'arabic', 'rtl', 18, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2159, 402, 19, 'Imaam Ash-Shaafi\'iyy(رحمه الله)  amesema: “Lau kama Allaah Asingeliteremsha hoja kwa viumbe Vyake isipokuwa Suwrah hii, basi ingeliwatosheleza.”', '<p>Imaam Ash-Shaafi\'iyy(رحمه الله)  amesema: “Lau kama Allaah Asingeliteremsha hoja kwa viumbe Vyake isipokuwa Suwrah hii, basi ingeliwatosheleza.”</p>', 'swahili', 'ltr', 19, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2160, 402, 20, 'وَقَالَ البُخَارِيُّ رَحِمَهُ اللهُ: بَابُ: العِلْمُ قَبْلَ القَوْلِ وَالْعَمَلِ.', '<p>وَقَالَ البُخَارِيُّ رَحِمَهُ اللهُ: بَابُ: العِلْمُ قَبْلَ القَوْلِ وَالْعَمَلِ.</p>', 'arabic', 'rtl', 20, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2161, 402, 21, 'Na Al-Bukhaariy(رحمه الله)  amesema katika Baabul-’Ilm qablal-qawli wal-‘amal “Mlango wa elimu kabla ya kauli na ‘amali”.', '<p>Na Al-Bukhaariy<strong>(رحمه الله) </strong> amesema katika <i>Baabul-’Ilm qablal-qawli wal-‘amal</i> “Mlango wa elimu kabla ya kauli na ‘amali”.</p>', 'swahili', 'ltr', 21, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2162, 402, 22, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 22, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2163, 402, 23, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 23, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2164, 402, 24, 'فَاعْلَمْ أَنَّهُ لَا إِلَـٰهَ إِلَّا اللَّـهُ وَاسْتَغْفِرْ‌ لِذَنبِكَ', '<p><strong>فَاعْلَمْ أَنَّهُ لَا إِلَـٰهَ إِلَّا اللَّـهُ وَاسْتَغْفِرْ‌ لِذَنبِكَ</strong></p>', 'arabic', 'rtl', 24, '#b68825', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2165, 402, 25, '((Basi jua kwamba laa ilaaha illa-Allaah, hapana muabudiwa wa haki ila Allaah na omba maghfirah kwa dhambi zako.))[Muhammad (47: 19).]', '<p>((Basi jua kwamba laa ilaaha illa-Allaah, hapana muabudiwa wa haki ila Allaah na omba maghfirah kwa dhambi zako.))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn3\">[Muhammad (47: 19).]</a></p>', 'swahili', 'ltr', 25, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2166, 402, 26, 'فَبَدَأَ بِالْعِلْمِ قَبْلَ القَوْلِ وَالعَمَلِ.', '<p>فَبَدَأَ بِالْعِلْمِ قَبْلَ القَوْلِ وَالعَمَلِ.</p>', 'arabic', 'rtl', 26, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2167, 402, 27, 'Akaanza kwa elimu kwanza kabla ya kauli na ‘amali.', '<p>Akaanza kwa elimu kwanza kabla ya kauli na ‘amali.</p>', 'swahili', 'ltr', 27, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2168, 402, 28, 'اعْلَمْ رَحِمَكَ اللهُ أَنَّه يَجِبُ عَلَى كُلِّ مُسْلِمٍ وَمُسْلِمَةٍ، تَعَلُّمُ هَذِهِ الثَّلاثِ مَسَائِل، والْعَمَلُ بِهِنّ:', '<p>اعْلَمْ رَحِمَكَ اللهُ أَنَّه يَجِبُ عَلَى كُلِّ مُسْلِمٍ وَمُسْلِمَةٍ، تَعَلُّمُ هَذِهِ الثَّلاثِ مَسَائِل، والْعَمَلُ بِهِنّ:</p>', 'arabic', 'rtl', 28, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2169, 402, 29, 'Fahamu Allaah Akurehemu, kwamba ni wajibu kwa kila Muislamu mwanamme na Muislamu mwanamke, kujifunza mas-alah haya matatu na kuyafanyia kazi:', '<p>Fahamu Allaah Akurehemu, kwamba ni wajibu kwa kila Muislamu mwanamme na Muislamu mwanamke, kujifunza mas-alah haya matatu na kuyafanyia kazi:</p>', 'swahili', 'ltr', 29, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2170, 402, 30, 'الأُولَى: أَنَّ اللهَ خَلَقَنَا، وَرَزَقَنَا، وَلَمْ يَتْرُكْنَا هَمَلا، بَلْ أَرْسَلَ إِلَيْنَا رَسُولاً، فَمَنْ أَطَاعَهُ دَخَلَ الجَنَّةَ، وَمَنْ عَصَاهُ دَخَلَ النَّارَ.', '<p>الأُولَى: أَنَّ اللهَ خَلَقَنَا، وَرَزَقَنَا، وَلَمْ يَتْرُكْنَا هَمَلا، بَلْ أَرْسَلَ إِلَيْنَا رَسُولاً، فَمَنْ أَطَاعَهُ دَخَلَ الجَنَّةَ، وَمَنْ عَصَاهُ دَخَلَ النَّارَ.</p>', 'arabic', 'rtl', 30, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2171, 402, 31, 'La kwanza: Kwamba Allaah Ametuumba, na Anaturuzuku, na Hakutuacha bure bali Ametutumia Rasuli. Basi atakayemtii ataingia Jannah, na atakayemuasi ataingia motoni.', '<p><strong>La kwanza: </strong>Kwamba Allaah Ametuumba, na Anaturuzuku, na Hakutuacha bure bali Ametutumia Rasuli. Basi atakayemtii ataingia Jannah, na atakayemuasi ataingia motoni.</p>', 'swahili', 'ltr', 31, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2172, 402, 32, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 32, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2173, 402, 33, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 33, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2174, 402, 34, 'إِنَّا أَرْ‌سَلْنَا إِلَيْكُمْ رَ‌سُولًا شَاهِدًا عَلَيْكُمْ كَمَا أَرْ‌سَلْنَا إِلَىٰ فِرْ‌عَوْنَ رَ‌سُولًا ﴿١٥﴾ فَعَصَىٰ فِرْ‌عَوْنُ الرَّ‌سُولَ فَأَخَذْنَاهُ أَخْذًا وَبِيلًا ﴿١٦﴾', '<p><strong>إِنَّا أَرْ‌سَلْنَا إِلَيْكُمْ رَ‌سُولًا شَاهِدًا عَلَيْكُمْ كَمَا أَرْ‌سَلْنَا إِلَىٰ فِرْ‌عَوْنَ رَ‌سُولًا ﴿١٥﴾ فَعَصَىٰ فِرْ‌عَوْنُ الرَّ‌سُولَ فَأَخَذْنَاهُ أَخْذًا وَبِيلًا ﴿١٦﴾</strong></p>', 'arabic', 'rtl', 34, '#b99131', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2175, 402, 35, '((Hakika Sisi Tumekutumieni Rasuli awe shahidi juu yenu, kama Tulivyotuma Rasuli kwa Fir’awn. Lakini Fir’awn alimuasi huyo Rasuli, Tukamshika kwa maangamizi makali mno))[Al-Muz-zzammil (73: 15-16).]', '<p>((Hakika Sisi Tumekutumieni Rasuli awe shahidi juu yenu, kama Tulivyotuma Rasuli kwa Fir’awn. Lakini Fir’awn alimuasi huyo Rasuli, Tukamshika kwa maangamizi makali mno))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn4\">[Al-Muz-zzammil (73: 15-16).]</a></p>', 'swahili', 'ltr', 35, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2176, 402, 36, 'الثَّانِيَةُ: أَنَّ الله لا يَرْضَى أَنْ يُشْرَكَ مَعَهُ أَحَدُ فِي عِبَادَتِهِ، لا مَلَكٌ مُقَرَّبٌ، وَلا نَبِيٌّ مُرْسَلٌ.', '<p>الثَّانِيَةُ: أَنَّ الله لا يَرْضَى أَنْ يُشْرَكَ مَعَهُ أَحَدُ فِي عِبَادَتِهِ، لا مَلَكٌ مُقَرَّبٌ، وَلا نَبِيٌّ مُرْسَلٌ.</p>', 'arabic', 'rtl', 36, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2177, 402, 37, 'La pili: Kwamba Allaah Haridhii kushirikishwa pamoja Naye yeyote yule katika ‘ibaadah Yake, ikiwa ni Malaika aliyekurubishwa, wala Nabiy aliyetumwa kuwa Rasuli.', '<p><strong>La pili: </strong>Kwamba Allaah Haridhii kushirikishwa pamoja Naye yeyote yule katika ‘ibaadah Yake, ikiwa ni Malaika aliyekurubishwa, wala Nabiy aliyetumwa kuwa Rasuli.</p>', 'swahili', 'ltr', 37, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2178, 402, 38, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 38, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2179, 402, 39, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 39, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2180, 402, 40, 'وَأَنَّ الْمَسَاجِدَ لِلَّـهِ فَلَا تَدْعُوا مَعَ اللَّـهِ أَحَدًا ﴿١٨﴾', '<p><strong>وَأَنَّ الْمَسَاجِدَ لِلَّـهِ فَلَا تَدْعُوا مَعَ اللَّـهِ أَحَدًا ﴿١٨﴾</strong></p>', 'swahili', 'ltr', 40, '#b99137', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2181, 402, 41, '((Na kwamba Misikiti ni kwa ajili ya Allaah, basi msiombe yeyote pamoja na Allaah))[Al-Jinn (72: 18).]', '<p>((Na kwamba Misikiti ni kwa ajili ya Allaah, basi msiombe yeyote pamoja na Allaah))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn5\">[Al-Jinn (72: 18).]</a></p>', 'swahili', 'ltr', 41, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2182, 402, 42, 'الثَّالِثَةُ ُ: أَنَّ مَنْ أَطَاعَ الرَّسُولَ، وَوَحَّدَ اللهَ لا يَجُوزُ لَهُ مُوَالاةُ مَنْ حَادَّ اللهَ وَرَسُولَهُ، وَلَوْ كَانَ أَقْرَبَ قَرِيبٍ.', '<p>الثَّالِثَةُ ُ: أَنَّ مَنْ أَطَاعَ الرَّسُولَ، وَوَحَّدَ اللهَ لا يَجُوزُ لَهُ مُوَالاةُ مَنْ حَادَّ اللهَ وَرَسُولَهُ، وَلَوْ كَانَ أَقْرَبَ قَرِيبٍ.</p>', 'arabic', 'rtl', 42, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2183, 402, 43, 'La Tatu: Kwamba Atakayemtii Rasuli, na Akampwekesha Allaah, haijuzu kwake kufanya urafiki na ushirikiano na yule anayempinga Allaah na Rasuli Wake hata akiwa ni jamaa wa karibu.', '<p><strong>La Tatu: </strong>Kwamba Atakayemtii Rasuli, na Akampwekesha Allaah, haijuzu kwake kufanya urafiki na ushirikiano na yule anayempinga Allaah na Rasuli Wake hata akiwa ni jamaa wa karibu.</p>', 'swahili', 'ltr', 43, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2184, 402, 44, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 44, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2185, 402, 45, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 45, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2186, 402, 46, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّـهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّـهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُولَـٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ رَضِيَ اللَّـهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ أُولَـٰئِكَ حِزْبُ اللَّـهِ ۚ أَلَا إِنَّ حِزْبَ اللَّـهِ هُمُ الْمُفْلِحُونَ ﴿٢٢﴾', '<p><strong>لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّـهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّـهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُولَـٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ رَضِيَ اللَّـهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ أُولَـٰئِكَ حِزْبُ اللَّـهِ ۚ أَلَا إِنَّ حِزْبَ اللَّـهِ هُمُ الْمُفْلِحُونَ ﴿٢٢﴾</strong></p>', 'arabic', 'rtl', 46, '#b99137', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2187, 402, 47, '((Hutokuta watu wanaomuamini Allaah na Siku ya Mwisho kuwa wanafanya urafiki na kuwapenda ambaye anapinzana na Allaah na Rasuli Wake, japo wakiwa ni baba zao, au watoto wao, au ndugu zao, au jamaa zao. Hao (Allaah) Amewaandikia katika nyoyo zao iymaan, na Akawatia nguvu kwa Ruwh (Wahyi) kutoka Kwake, na Atawaingiza Jannaat zipitazo chini yake mito ni wenye kudumu humo. Allaah Ameridhika nao, nao wameridhika Naye. Hao ndio kundi la Allaah. Tanabahi! Hakika kundi la Allaah ndio lenye kufaulu))[Al-Mujaadilah (58: 22).]', '<p>((Hutokuta watu wanaomuamini Allaah na Siku ya Mwisho kuwa wanafanya urafiki na kuwapenda ambaye anapinzana na Allaah na Rasuli Wake, japo wakiwa ni baba zao, au watoto wao, au ndugu zao, au jamaa zao. Hao (Allaah) Amewaandikia katika nyoyo zao iymaan, na Akawatia nguvu kwa Ruwh (Wahyi) kutoka Kwake, na Atawaingiza Jannaat zipitazo chini yake mito ni wenye kudumu humo. Allaah Ameridhika nao, nao wameridhika Naye. Hao ndio kundi la Allaah. Tanabahi! Hakika kundi la Allaah ndio lenye kufaulu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn6\">[</a><strong>Al-Mujaadilah (58: 22).</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn6\">]</a></p>', 'swahili', 'ltr', 47, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2188, 402, 48, 'اعْلَمْ أَرْشَدَكَ اللهُ لِطَاعَتِهِ، أَنَّ الْحَنِيفِيَّةَ مِلَّةَ إِبْرَاهِيمَ: أَنْ تَعْبُدَ اللهَ وَحْدَهُ، مُخْلِصًا لَهُ الدِّينَ. وَبِذَلِكَ أَمَرَ اللهُ جَمِيعَ النَّاسِ، وَخَلَقَهُمْ لَهَا.', '<p>اعْلَمْ أَرْشَدَكَ اللهُ لِطَاعَتِهِ، أَنَّ الْحَنِيفِيَّةَ مِلَّةَ إِبْرَاهِيمَ: أَنْ تَعْبُدَ اللهَ وَحْدَهُ، مُخْلِصًا لَهُ الدِّينَ. وَبِذَلِكَ أَمَرَ اللهُ جَمِيعَ النَّاسِ، وَخَلَقَهُمْ لَهَا.</p>', 'arabic', 'rtl', 48, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2189, 402, 49, 'Fahamu, Allaah Akuongoze katika utiifu Wake, kwamba al-Hanifiyyah (kuelemea Dini ya haki na kujiepusha na dini potofu) ni Dini ya Ibraahiym. Umwabudu Allaah Pekee ukimtakasia Dini Yake, na kwa hilo Allaah Amewaamrisha watu wote, na Amewaumba kwa sababu hiyo.', '<p>Fahamu, Allaah Akuongoze katika utiifu Wake, kwamba <i>al-Hanifiyyah</i> (kuelemea Dini ya haki na kujiepusha na dini potofu) ni Dini ya Ibraahiym. Umwabudu Allaah Pekee ukimtakasia Dini Yake, na kwa hilo Allaah Amewaamrisha watu wote, na Amewaumba kwa sababu hiyo.</p>', 'swahili', 'ltr', 49, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2190, 402, 50, 'كَمَا قَالَ تَعَالَى:', '<p>كَمَا قَالَ تَعَالَى:</p>', 'arabic', 'rtl', 50, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2191, 402, 51, 'Kama Anavyosema Ta’aalaa:', '<p>Kama Anavyosema Ta’aalaa:</p>', 'swahili', 'ltr', 51, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2192, 402, 52, 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾', '<p><strong>وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾</strong></p>', 'arabic', 'rtl', 52, '#b99137', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2193, 402, 53, '((Na Sikuumba majini na wanadamu isipokuwa waniabudu))[Adh-Dhaariyaat (51: 56).]', '<p>((Na Sikuumba majini na wanadamu isipokuwa waniabudu))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn7\">[</a><strong>Adh-Dhaariyaat (51: 56).</strong><a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn7\">]</a></p>', 'swahili', 'ltr', 53, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2194, 402, 54, 'وَمَعْنَى  ((يَعْبُدُونِ)) :يُوَحِّدُونِ، وَأَعْظَمُ مَا أَمَرَ اللهُ بِهِ التَّوْحيِدُ، وَهُوَ :إِفْرَادُ اللهِ بِالْعِبَادَةِ. وَأَعْظَمُ مَا نَهَى عَنْه الشِّركُ، وَهُوَ: دَعْوَةُ غَيْرِهِ مَعَهُ.', '<p>وَمَعْنَى  ((يَعْبُدُونِ)) :يُوَحِّدُونِ، وَأَعْظَمُ مَا أَمَرَ اللهُ بِهِ التَّوْحيِدُ، وَهُوَ :إِفْرَادُ اللهِ بِالْعِبَادَةِ. وَأَعْظَمُ مَا نَهَى عَنْه الشِّركُ، وَهُوَ: دَعْوَةُ غَيْرِهِ مَعَهُ.</p>', 'arabic', 'rtl', 54, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2195, 402, 55, 'Na maana ya ((waniabudu)) ni: Wanipwekeshe. Na jambo kuu kabisa Aloamrisha Allaah ni At-Tawhiyd ambayo ni: Kumpwekesha Allaah katika ‘ibaadah. Na jambo kuu kabisa Alokataza ni shirki, ambayo ni: kumuomba mwengine pamoja Naye.', '<p>Na maana ya ((waniabudu)) ni: Wanipwekeshe. Na jambo kuu kabisa Aloamrisha Allaah ni At-Tawhiyd ambayo ni: Kumpwekesha Allaah katika ‘ibaadah. Na jambo kuu kabisa Alokataza ni shirki, ambayo ni: kumuomba mwengine pamoja Naye.</p>', 'swahili', 'ltr', 55, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2196, 402, 56, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 56, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2197, 402, 57, 'وَاعْبُدُوا اللَّـهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا ۖ', '<p><strong>وَاعْبُدُوا اللَّـهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا ۖ</strong></p>', 'swahili', 'ltr', 57, '#b99137', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2198, 402, 58, '((Na mwabuduni Allaah na wala msimshirikishe na chochote))[An-Nisaa (4: 36).]', '<p>((Na mwabuduni Allaah na wala msimshirikishe na chochote))<a href=\"https://www.alhidaaya.com/sw/al-uswuwl-ath-thalaathah-misingi-mitatu-alausanwlu-althwalatht-word-doc-chapisho-la-4-kimehaririwa#_ftn8\">[An-Nisaa (4: 36).]</a></p>', 'swahili', 'ltr', 58, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2199, 402, 59, 'فَإِذَا قِيلَ لَكَ: مَا الأُصُولُ الثَّلاثَةُ التِي يَجِبُ عَلَى الإِنْسَانِ مَعْرِفَتُهَا؟', '<p>فَإِذَا قِيلَ لَكَ: مَا الأُصُولُ الثَّلاثَةُ التِي يَجِبُ عَلَى الإِنْسَانِ مَعْرِفَتُهَا؟</p>', 'arabic', 'rtl', 59, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2200, 402, 60, 'Basi utakapoulizwa: “Nini Al-Uswuwul ath-Thalaathah (misingi mitatu) ambayo mwana wa Aadam anawajibika kuifahamu?”', '<p><strong>Basi utakapoulizwa</strong>: “Nini Al-<i>Uswuwul ath-Thalaathah</i> (misingi mitatu) ambayo mwana wa Aadam anawajibika kuifahamu?” </p>', 'swahili', 'ltr', 60, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2201, 402, 61, 'فَقُلْ :مَعْرِفَةُ الْعَبْدِ رَبَّهُ، وَدِينَهُ، وَنَبِيَّهُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.', '<p> فَقُلْ :مَعْرِفَةُ الْعَبْدِ رَبَّهُ، وَدِينَهُ، وَنَبِيَّهُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.</p>', 'arabic', 'rtl', 61, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2202, 402, 62, 'Sema: “Mja kumjua Rabb wake, na Dini yake, na Nabiy wake Muhammad (صلى الله عليه وآله وسلم).', '<p><strong>Sema:</strong> “Mja kumjua Rabb wake, na Dini yake, na Nabiy wake Muhammad (<strong>صلى الله عليه وآله وسلم</strong>).</p>', 'swahili', 'ltr', 62, '#1f2937', '#ffffff', '2026-08-27 09:12:26', '2026-08-27 09:12:26', NULL, NULL, NULL, 0),
(2430, 409, 1, 'الْقَاعِدَةُ الأُولَى:', '<p><strong>                                 الْقَاعِدَةُ الأُولَى:</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2431, 409, 2, 'Kanuni Ya Kwanza:', '<p><strong>                               Kanuni Ya Kwanza:</strong></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2432, 409, 3, 'أَنْ تَعْلَمَ أَنَّ الْكُفَّارَ الَّذِينَ قَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) مُقِرُّونَ بِأَنَّ اللهَ تَعَالَى هُوُ الْخَالِقُ، الْمُدَبِّرُ، وَأَنَّ ذَلِكَ لَمْ يُدْخِلَهُمْ فِي الإِسْلامِ.', '<p>أَنْ تَعْلَمَ أَنَّ الْكُفَّارَ الَّذِينَ قَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) مُقِرُّونَ بِأَنَّ اللهَ تَعَالَى هُوُ الْخَالِقُ، الْمُدَبِّرُ، وَأَنَّ ذَلِكَ لَمْ يُدْخِلَهُمْ فِي الإِسْلامِ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2433, 409, 4, 'Ujue kwamba makafiri, ambao Rasuli wa Allaah (صلى الله عليه وآله وسلم) alipigana nao, walikiri kwamba Allaah Ta’aalaa ni Muumbaji na Mwendeshaji wa mambo yote. Lakini (kukiri) hivyo hakukuwaingiza katika Uislamu.', '<p>Ujue kwamba makafiri, ambao Rasuli wa Allaah (<strong>صلى الله عليه وآله وسلم</strong>) alipigana nao, walikiri kwamba Allaah Ta’aalaa ni Muumbaji na Mwendeshaji wa mambo yote. Lakini (kukiri) hivyo hakukuwaingiza katika Uislamu.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2434, 409, 5, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2435, 409, 6, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2436, 409, 7, 'قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَمَّن يَمْلِكُ السَّمْعَ وَالْأَبْصَارَ وَمَن يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَن يُدَبِّرُ الْأَمْرَ ۚ فَسَيَقُولُونَ اللَّـهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ﴿٣١﴾', '<p> <strong>قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَمَّن يَمْلِكُ السَّمْعَ وَالْأَبْصَارَ وَمَن يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَن يُدَبِّرُ الْأَمْرَ ۚ فَسَيَقُولُونَ اللَّـهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ﴿٣١﴾</strong></p>', 'arabic', 'rtl', 7, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2437, 409, 8, '((Sema: (ee Muhammad صلى الله عليه وآله وسلم) “Nani anayekuruzukuni kutoka mbinguni na ardhini. Au nani anayemiliki kusikia na kuona; na nani anayemtoa aliye hai kutoka mfu, na anayemtoa mfu kutoka aliye uhai; na nani anayeendesha mambo (yote)?  Watasema: “Ni Allaah”; basi sema: “Je basi hamuwi na taqwa?”))[Yuwnus (10: 31)]', '<p>((Sema: (ee Muhammad <strong>صلى الله عليه وآله وسلم</strong>) “Nani anayekuruzukuni kutoka mbinguni na ardhini. Au nani anayemiliki kusikia na kuona; na nani anayemtoa aliye hai kutoka mfu, na anayemtoa mfu kutoka aliye uhai; na nani anayeendesha mambo (yote)?  Watasema: “Ni Allaah”; basi sema: “Je basi hamuwi na taqwa?”))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn4\">[Yuwnus (10: 31)]</a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2438, 410, 1, 'الْقَاعِدَةُ الثَّانِيَةُ:', '<p><strong>                                 الْقَاعِدَةُ الثَّانِيَةُ:</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2439, 410, 2, 'Kanuni Ya Pili:', '<p><strong>                         Kanuni Ya Pili:</strong></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2440, 410, 3, 'أُنَّهُمْ يَقُولُونَ: مَا دَعَوْنَاهُمْ وَتَوَجَّهْنَا إِلَيْهِمْ إِلا لِطَلَبِ الْقُرْبَةِ وَالشَّفَاعَةِ.', '<p>أُنَّهُمْ يَقُولُونَ: مَا دَعَوْنَاهُمْ وَتَوَجَّهْنَا إِلَيْهِمْ إِلا لِطَلَبِ الْقُرْبَةِ وَالشَّفَاعَةِ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2441, 410, 4, 'Kwamba wao (washirikina) wamesema: “Hatukuwaabudu wala kuelekea kwao isipokuwa tu kuomba kukurubia na shafaa’ah (uombezi wa Allaah).', '<p>Kwamba wao (washirikina) wamesema: “Hatukuwaabudu wala kuelekea kwao isipokuwa tu kuomba kukurubia na shafaa’ah (uombezi wa Allaah).</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2442, 410, 5, 'فَدَلِيلُ الْقُرْبَةِ؛ قَوْلُهُ تَعَالَى:', '<p>فَدَلِيلُ الْقُرْبَةِ؛ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2443, 410, 6, 'Na dalili ya kutafuta ukaribu ni kauli Yake Ta’aalaa:', '<p>Na dalili ya kutafuta ukaribu ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2444, 410, 7, 'وَالَّذِينَ اتَّخَذُوا مِن دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّـهِ زُلْفَىٰ إِنَّ اللَّـهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ اللَّـهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ ﴿٣﴾', '<p> <strong>وَالَّذِينَ اتَّخَذُوا مِن دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّـهِ زُلْفَىٰ إِنَّ اللَّـهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ اللَّـهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ ﴿٣﴾</strong></p>', 'arabic', 'rtl', 7, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2445, 410, 8, '((Na wale waliojichukulia badala Yake walinzi (wakisema): “Hatuwaabudu isipokuwa ili wapate kutukurubisha kwa Allaah tumkaribie” Hakika Allaah Atahukumu baina yao katika yale waliyokhitilafiana nayo. Hakika Allaah Hamwongoi aliye muongo, kafiri)) [Az- Zumar (39: 3)]', '<p>((Na wale waliojichukulia badala Yake walinzi (wakisema): “Hatuwaabudu isipokuwa ili wapate kutukurubisha kwa Allaah tumkaribie” Hakika Allaah Atahukumu baina yao katika yale waliyokhitilafiana nayo. Hakika Allaah Hamwongoi aliye muongo, kafiri))<strong> </strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn5\"><strong>[Az- Zumar (39: 3)]</strong></a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2446, 410, 9, 'وَدَلِيلُ الشَّفَاعَةِ، قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الشَّفَاعَةِ، قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2447, 410, 10, 'Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2448, 410, 11, 'وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ', '<p> <strong>وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ</strong></p>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2449, 410, 12, '((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))[Yuwnus (10: 18)]', '<p>((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn6\">[Yuwnus (10: 18)]</a></p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2450, 410, 13, 'وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.', '<p>وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.</p>', 'arabic', 'rtl', 13, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2451, 410, 14, 'Na ash-shafaa’ah (uombezi) ni aina mbili:i.                    Shafaa’ah iliyokatazwa (iliyoharamishwa katika Qur-aan na Sunnah)[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)] ii.                  Shafaa’ah iliyothibitishwa (inayokubalika katika Qur-aan na Sunnah)[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]', '<p>Na ash-shafaa’ah (uombezi) ni aina mbili:</p><p>i.                    <strong>Shafaa’ah iliyokatazwa</strong> (iliyoharamishwa katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn7\">[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)]</a> </p><p>ii.                 <strong> Shafaa’ah iliyothibitishwa</strong> (inayokubalika katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn8\">[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]</a></p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2452, 410, 15, 'فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.', '<p>فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.</p>', 'arabic', 'rtl', 15, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2453, 410, 16, 'Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.', '<p>Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.<br> </p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2454, 410, 17, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p> وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 17, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2455, 410, 18, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2456, 410, 19, 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَاعَةٌ ۗ وَالْكَافِرُونَ هُمُ الظَّالِمُونَ ﴿٢٥٤﴾', '<p><strong>يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَاعَةٌ ۗ وَالْكَافِرُونَ هُمُ الظَّالِمُونَ ﴿٢٥٤﴾</strong></p>', 'arabic', 'rtl', 19, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2457, 410, 20, '((Enyi walioamini! Toeni katika Tulivyokuruzukuni kabla haijafika Siku (ambayo) hakutokuweko mapatano humo wala urafiki wala shafaa’ah (uombezi). Na makafiri wao ndio madhalimu))[Al-Baqarah (2: 254).]', '<p>((Enyi walioamini! Toeni katika Tulivyokuruzukuni kabla haijafika Siku (ambayo) hakutokuweko mapatano humo wala urafiki wala shafaa’ah (uombezi). Na makafiri wao ndio madhalimu))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn9\">[Al-Baqarah (2: 254).]</a></p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2458, 410, 21, 'وَالشَّفَاعَةُ الْمُثْبَتَةُ: هِيَ الَّتِي تُطْلَبُ مِنَ اللهِ، وَالشَّافِعُ مُكَرَّمٌ بِالشَّفَاعَةِ، وَالْمَشْفُوعُ لَهُ مَنْ رَضِيَ اللهُ قَوْلَهُ وَعَمَلَهُ بَعْدَ الإِذْنِ', '<p>وَالشَّفَاعَةُ الْمُثْبَتَةُ: هِيَ الَّتِي تُطْلَبُ مِنَ اللهِ، وَالشَّافِعُ مُكَرَّمٌ بِالشَّفَاعَةِ، وَالْمَشْفُوعُ لَهُ مَنْ رَضِيَ اللهُ قَوْلَهُ وَعَمَلَهُ بَعْدَ الإِذْنِ</p>', 'arabic', 'rtl', 21, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2459, 410, 22, 'Na Ash-Shafaa’ah iliyothibitishwa ni ambayo inaombwa baada ya idhini ya Allaah, na mwombezi amekirimiwa kwa ash-shafaa’ah na anayeombewa ni ambaye Allaah Ameridhika naye kwa kauli zake na vitendo vyake.', '<p>Na Ash-Shafaa’ah iliyothibitishwa ni ambayo inaombwa baada ya idhini ya Allaah, na mwombezi amekirimiwa kwa ash-shafaa’ah na anayeombewa ni ambaye Allaah Ameridhika naye kwa kauli zake na vitendo vyake.</p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2460, 410, 23, 'كَمَا قَالَ تَعَالَى:', '<p>  كَمَا قَالَ تَعَالَى:</p>', 'arabic', 'rtl', 23, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2461, 410, 24, 'Kama Anavyosema Ta’aalaa:', '<p>Kama Anavyosema Ta’aalaa:</p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0);
