(2462, 410, 25, 'مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ', '<p><strong>مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ</strong></p>', 'arabic', 'rtl', 25, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
