(2466, 411, 3, 'أَنَّ النَّبِيَّ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) ظَهَرَ عَلَى أُنَاسٍ مُتَفَرِّقِينَ فِي عِبَادَاتِهِمْ، مِنْهُمْ مَنْ يَعْبُدُ الْمَلائِكَةَ، وَمِنْهُمْ مَنْ يَعْبُدُ الأَنْبِيَاءَ وَالصَّالِحِينَ، وَمِنْهُمْ مَنْ يَعْبُدُ الأَشْجَارَ وَالأَحْجَارَ، وَمِنْهُمْ مَنْ يَعْبُدُ الشَّمْسَ وَالْقَمَرَ، وَقَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) وَلَمْ يُفَرِّقْ بَيْنَهُمْ.', '<p>أَنَّ النَّبِيَّ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) ظَهَرَ عَلَى أُنَاسٍ مُتَفَرِّقِينَ فِي عِبَادَاتِهِمْ، مِنْهُمْ مَنْ يَعْبُدُ الْمَلائِكَةَ، وَمِنْهُمْ مَنْ يَعْبُدُ الأَنْبِيَاءَ وَالصَّالِحِينَ، وَمِنْهُمْ مَنْ يَعْبُدُ الأَشْجَارَ وَالأَحْجَارَ، وَمِنْهُمْ مَنْ يَعْبُدُ الشَّمْسَ وَالْقَمَرَ، وَقَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) وَلَمْ يُفَرِّقْ بَيْنَهُمْ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2467, 411, 4, 'KwambaNabiy (صلى الله عليه وآله وسلم) alikuta watu wakitofautiana katika ibaada zao. Kuna waliokuwa wanaabudu Malaika, wanaoabudu Manabii na Swalihina (waja wema), wanaoabudu miti na mawe, na wanaoabudu jua na mwezi. Rasuli wa Allaah (صلى الله عليه وآله وسلم) akapigana nao na wala hakutofautisha baina yao (katika walivyoviabudu).', '<p><strong>Kwamba</strong></p><p><strong>Nabiy (صلى الله عليه وآله وسلم) alikuta watu wakitofautiana katika ibaada zao. Kuna waliokuwa wanaabudu Malaika, wanaoabudu Manabii na Swalihina (waja wema), wanaoabudu miti na mawe, na wanaoabudu jua na mwezi. Rasuli wa Allaah (صلى الله عليه وآله وسلم) akapigana nao na wala hakutofautisha baina yao (katika walivyoviabudu).</strong></p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2468, 411, 5, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<p><strong>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</strong></p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2469, 411, 6, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2470, 411, 7, 'وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّـهِ ۚ', '<p><strong>وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّـهِ ۚ</strong></p>', 'arabic', 'rtl', 7, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2471, 411, 8, '((Na piganeni nao mpaka kusiweko fitnah (shirki na mateso) na Dini yote iwe kwa ajili ya Allaah))[Al-Anfaal (8: 39)]', '<p>((Na piganeni nao mpaka kusiweko fitnah (shirki na mateso) na Dini yote iwe kwa ajili ya Allaah))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn11\">[Al-Anfaal (8: 39)]</a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2472, 411, 9, 'وَدَلِيلُ الشَّمْسِ وَالْقَمَرِ؛ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الشَّمْسِ وَالْقَمَرِ؛ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2473, 411, 10, 'Na dalili ya jua na mwezi (kuabudiwa) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya jua na mwezi (kuabudiwa) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2474, 411, 11, 'وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ ۚ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلَّـهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ ﴿٣٧﴾', '<p><strong>وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ ۚ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلَّـهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ ﴿٣٧﴾</strong></p>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2475, 411, 12, '((Na katika Aayaat (ishara, dalili) Zake, ni usiku na mchana, na jua na mwezi.  Msisujudie jua wala mwezi; bali msujudieni Allaah Ambaye Aliyeviumba ikiwa Yeye Pekee mnawambudu))[Fusswilat: (41: 37)]', '<p>((Na katika Aayaat (ishara, dalili) Zake, ni usiku na mchana, na jua na mwezi.  Msisujudie jua wala mwezi; bali msujudieni Allaah Ambaye Aliyeviumba ikiwa Yeye Pekee mnawambudu))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn12\">[Fusswilat: (41: 37)]</a></p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2476, 411, 13, 'وَدَلِيلُ الْمَلائِكَةِ؛ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الْمَلائِكَةِ؛ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 13, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
