(2478, 411, 15, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا الْمَلَائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا ۗ', '<p> <strong>وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا الْمَلَائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا ۗ</strong></p>', 'arabic', 'rtl', 15, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2479, 411, 16, '((Na wala hakuamuruni kuwachukua Malaika na Manabii kuwafanya miungu))[Aal-‘Imraan (3: 80)]', '<p>((Na wala hakuamuruni kuwachukua Malaika na Manabii kuwafanya miungu))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn13\">[Aal-‘Imraan (3: 80)]</a></p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2480, 411, 17, 'وَدَلِيلُ الأَنْبِيَاءِ؛ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الأَنْبِيَاءِ؛ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 17, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2481, 411, 18, 'Na dalili ya Manabii (kuabudiwa) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Manabii (kuabudiwa) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2482, 411, 19, 'وَإِذْ قَالَ اللَّـهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَـٰهَيْنِ مِن دُونِ اللَّـهِ ۖ قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ ۚ تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ ﴿١١٦﴾', '<p><strong>وَإِذْ قَالَ اللَّـهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَـٰهَيْنِ مِن دُونِ اللَّـهِ ۖ قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ ۚ تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ ﴿١١٦﴾</strong></p>', 'arabic', 'rtl', 19, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2483, 411, 20, '((Na (kumbuka) Allaah Atakaposema: “Ee ‘Iysaa mwana wa Maryam!  Je, wewe uliwaambia watu: “Nifanyeni mimi na mama yangu kuwa ni miungu miwili badala ya Allaah?” (‘Iysaa) Atasema: “Subhaanak Utakasifu ni Wako! Hainipasi mimi kusema yasiyokuwa haki kwangu; ikiwa nimesema hayo basi kwa yakini Ungeliyajua; Unayajua yale yote yaliyomo katika nafsi yangu; na wala mimi sijui yale yaliyomo katika Nafsi Yako; hakika Wewe ni Mjuzi wa ghayb))[Al-Maaidah (5: 116)]', '<p>((Na (kumbuka) Allaah Atakaposema: “Ee ‘Iysaa mwana wa Maryam!  Je, wewe uliwaambia watu: “Nifanyeni mimi na mama yangu kuwa ni miungu miwili badala ya Allaah?” (‘Iysaa) Atasema: “Subhaanak Utakasifu ni Wako! Hainipasi mimi kusema yasiyokuwa haki kwangu; ikiwa nimesema hayo basi kwa yakini Ungeliyajua; Unayajua yale yote yaliyomo katika nafsi yangu; na wala mimi sijui yale yaliyomo katika Nafsi Yako; hakika Wewe ni Mjuzi wa ghayb))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn14\">[Al-Maaidah (5: 116)]</a></p>', 'swahili', 'ltr', 20, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2484, 411, 21, 'وَدَلِيلُ الصَّالِحِينَ؛ قَوْلُهُ تَعَالَى:', '<p>وَدَلِيلُ الصَّالِحِينَ؛ قَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 21, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2485, 411, 22, 'Na dalili ya Swalihiyna (kuabudiwa) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya Swalihiyna (kuabudiwa) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2486, 411, 23, 'أُولَـٰئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ ۚ', '<p> <strong>أُولَـٰئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ ۚ</strong></p>', 'arabic', 'rtl', 23, '#b99137', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
(2487, 411, 24, '((Hao wanaowaomba (wao wenyewe) wanatafuta kwa Rabb wao njia ya kujikurubisha, yupi miongoni mwao awe karibu zaidi na wanataraji rahmah Yake, na wanakhofu adhabu Yake)) [Al-Israa (17: 57)]', '<p><strong>((Hao wanaowaomba (wao wenyewe) wanatafuta kwa Rabb wao njia ya kujikurubisha, yupi miongoni mwao awe karibu zaidi na wanataraji rahmah Yake, na wanakhofu adhabu Yake)) </strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn15\"><strong>[Al-Israa (17: 57)]</strong></a><strong>  </strong></p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-27 15:56:18', '2026-08-27 15:56:18', NULL, NULL, NULL, 0),
