(2969, 458, 3, '1.عَنْ أَبِي هُرَيْرَةَ رضى الله عنه قَالَ: قَالَ رَسُولُ اَللَّهِ صلى الله عليه وسلم ‏فِي اَلْبَحْرِ:   ‏{ هُوَ اَلطُّهُورُ مَاؤُهُ، اَلْحِلُّ مَيْتَتُهُ }', '<p><strong>1.</strong></p><p><strong>عَنْ أَبِي هُرَيْرَةَ رضى الله عنه قَالَ: قَالَ رَسُولُ اَللَّهِ صلى الله عليه وسلم ‏فِي اَلْبَحْرِ:   ‏{ هُوَ اَلطُّهُورُ مَاؤُهُ، اَلْحِلُّ مَيْتَتُهُ }</strong></p>', 'arabic', 'rtl', 3, '#1356b4', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2970, 458, 4, 'أَخْرَجَهُ اَلْأَرْبَعَةُ، وَابْنُ أَبِي شَيْبَةَ وَاللَّفْظُ لَهُ، وَصَحَّحَهُ اِبْنُ خُزَيْمَةَ وَاَلتِّرْمِذِيُّ', '<p><strong>أَخْرَجَهُ اَلْأَرْبَعَةُ، وَابْنُ أَبِي شَيْبَةَ وَاللَّفْظُ لَهُ، وَصَحَّحَهُ اِبْنُ خُزَيْمَةَ وَاَلتِّرْمِذِيُّ</strong></p>', 'arabic', 'rtl', 4, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2971, 458, 5, 'Kutoka kwa Abuu Hurayrah[1] (رَضِيَ اللهُ عَنْهُ) amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu bahari: “Maji yake yanatwaharisha, na maiti wake ni halaal (kuliwa).', '<p><strong>Kutoka kwa Abuu Hurayrah</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn1\"><strong>[1]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ) amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu bahari: “Maji yake yanatwaharisha, na maiti wake ni halaal (kuliwa).</strong></p>', 'swahili', 'ltr', 5, '#1b5ebb', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2972, 458, 6, '[Imetolewa na Al-Arba’ah: Abuu Daawuwd, At-Tirmidhiy, An-Nasaaiy na Ibn Maajah  na Ibn Abiy Shaybah na tamshi la Hadiyth hii ni lake Ibn Khuzaymah akaisahihisha na At-Tirmidhiy]', '<p><strong>[Imetolewa na Al-Arba’ah: Abuu Daawuwd, At-Tirmidhiy, An-Nasaaiy na Ibn Maajah  na Ibn Abiy Shaybah na tamshi la Hadiyth hii ni lake Ibn Khuzaymah akaisahihisha na At-Tirmidhiy]</strong></p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2973, 458, 7, '2.وَعَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رضى الله عنه قَالَ: قَالَ رَسُولُ اَللَّهِ صلى الله عليه وسلم: {إِنَّ اَلْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ))', '<p><strong>2.</strong></p><p><strong>وَعَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رضى الله عنه قَالَ: قَالَ رَسُولُ اَللَّهِ صلى الله عليه وسلم: {إِنَّ اَلْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ))</strong></p>', 'arabic', 'rtl', 7, '#1053b2', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2974, 458, 8, 'أَخْرَجَهُ اَلثَّلَاثَةُ  ‏ وَصَحَّحَهُ أَحْمَدُ', '<p><strong>أَخْرَجَهُ اَلثَّلَاثَةُ  ‏ وَصَحَّحَهُ أَحْمَدُ</strong></p>', 'arabic', 'rtl', 8, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2975, 458, 9, 'Kutoka kwa Sa’iyd Al-Khudriyy[2] (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Hakika maji ni masafi[3], hayanajisiwi na akaisahihisha Ahmad]', '<p><strong>Kutoka kwa Sa’iyd Al-Khudriyy</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn2\"><strong>[2]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Hakika maji ni masafi</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn3\"><strong>[3]</strong></a><strong>, hayanajisiwi na akaisahihisha Ahmad]</strong></p>', 'swahili', 'ltr', 9, '#0a57c2', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2976, 458, 10, '3.وَعَنْ أَبِي أُمَامَةَ اَلْبَاهِلِيِّ رضى الله عنه  قَالَ: قَالَ رَسُولُ صلى الله عليه وسلم: {إِنَّ اَلْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ، إِلَّا مَا غَلَبَ عَلَى رِيحِهِ وَطَعْمِهِ، وَلَوْنِهِ}', '<p><strong>3.</strong></p><p><strong>وَعَنْ أَبِي أُمَامَةَ اَلْبَاهِلِيِّ رضى الله عنه  قَالَ: قَالَ رَسُولُ صلى الله عليه وسلم: {إِنَّ اَلْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ، إِلَّا مَا غَلَبَ عَلَى رِيحِهِ وَطَعْمِهِ، وَلَوْنِهِ}</strong></p>', 'arabic', 'rtl', 10, '#1563d1', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2977, 458, 11, 'أَخْرَجَهُ اِبْنُ مَاجَهْ ‏ وَضَعَّفَهُ أَبُو حَاتِمٍ', '<p><strong>أَخْرَجَهُ اِبْنُ مَاجَهْ ‏ وَضَعَّفَهُ أَبُو حَاتِمٍ</strong></p>', 'arabic', 'rtl', 11, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2978, 458, 12, 'Kutoka kwa Abuu Umaamah Al-Baahiliyy[4] (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Hakika maji hayanajisiwi na chochote isipokuwa kinachozidi harufu yake, ladha yake na rangi.”', '<p><strong>Kutoka kwa Abuu Umaamah Al-Baahiliyy</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn4\"><strong>[4]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Hakika maji hayanajisiwi na chochote isipokuwa kinachozidi harufu yake, ladha yake na rangi.”  </strong></p>', 'swahili', 'ltr', 12, '#1768d9', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2979, 458, 13, '[Imetolewa na Ibn Maajah na Abuu Haatim akaidhoofisha]Aliyepokea Al-Bayhaqiyy:', '<p><strong> [Imetolewa na Ibn Maajah na Abuu Haatim akaidhoofisha]</strong><br><strong>Aliyepokea Al-Bayhaqiyy:</strong></p>', 'swahili', 'ltr', 13, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2980, 458, 14, '“Maji ni yenye kutwahirisha isipokuwa yakiingia najsi na kuyabadilisha harufu, ladha au rangi[5] yake.”', '<p><strong>“Maji ni yenye kutwahirisha isipokuwa yakiingia najsi na kuyabadilisha harufu, ladha au rangi</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn5\"><strong>[5]</strong></a><strong> yake.”</strong></p>', 'swahili', 'ltr', 14, '#0e62d8', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2981, 458, 15, '4.وَعَنْ عَبْدِ اَللَّهِ بْنِ عُمَرَ رَضِيَ اَللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اَللَّهِ صَلَّى عَلَيْهِ وَسَلَّمَ: {إِذَا كَانَ اَلْمَاءَ قُلَّتَيْنِ لَمْ يَحْمِلْ اَلْخَبَثَ}', '<p><strong>4.</strong></p><p><strong>وَعَنْ عَبْدِ اَللَّهِ بْنِ عُمَرَ رَضِيَ اَللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اَللَّهِ صَلَّى عَلَيْهِ وَسَلَّمَ: {إِذَا كَانَ اَلْمَاءَ قُلَّتَيْنِ لَمْ يَحْمِلْ اَلْخَبَثَ}</strong></p>', 'arabic', 'rtl', 15, '#2272e2', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2982, 458, 16, 'وَفِي لَفْظٍ: {لَمْ يَنْجُسْ}   أَخْرَجَهُ اَلْأَرْبَعَةُ، وَصَحَّحَهُ اِبْنُ خُزَيْمَةَ‏ وَابْنُ حِبَّانَ', '<p><strong> وَفِي لَفْظٍ: </strong>{لَمْ يَنْجُسْ}<strong>   أَخْرَجَهُ اَلْأَرْبَعَةُ، وَصَحَّحَهُ اِبْنُ خُزَيْمَةَ‏ وَابْنُ حِبَّانَ </strong></p>', 'arabic', 'rtl', 16, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2983, 458, 17, 'Kutoka kwa ‘Abdullaahi bin ‘Umar[6] (رَضِيَ اللهُ عَنْهُمَا)  amesema:  Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Pindi maji yakiwa qullatayn[7] (viriba au mitungi miwili) huwa hayachukui uchafu.”', '<p><strong>Kutoka kwa ‘Abdullaahi bin ‘Umar</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn6\"><strong>[6]</strong></a><strong> (رَضِيَ اللهُ عَنْهُمَا)  amesema:  Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Pindi maji yakiwa qullatayn</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn7\"><strong>[7]</strong></a><strong> (viriba au mitungi miwili) huwa hayachukui uchafu.”</strong></p>', 'swahili', 'ltr', 17, '#2877e6', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2984, 458, 18, 'Na katika tamshi: “Haifanyi kuwa najisi.” [Imetolewa na Al-Arba’ah na ameisahihisha Ibn Khuzaymah na Ibn Maajah]', '<p><strong>Na katika tamshi:</strong> “Haifanyi kuwa najisi.”<strong> [Imetolewa na Al-Arba’ah na ameisahihisha Ibn Khuzaymah na Ibn Maajah]</strong></p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2985, 458, 19, '5.وَعَنْ أَبِي هُرَيْرَةَ رضى الله عنه ‏ قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم:  { لَا يَغْتَسِلُ أَحَدُكُمْ فِي اَلْمَاءِ اَلدَّائِمِ وَهُوَ جُنُبٌ}', '<p><strong>5.</strong></p><p><strong>وَعَنْ أَبِي هُرَيْرَةَ رضى الله عنه ‏ قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم:  { لَا يَغْتَسِلُ أَحَدُكُمْ فِي اَلْمَاءِ اَلدَّائِمِ وَهُوَ جُنُبٌ}</strong></p>', 'arabic', 'rtl', 19, '#2368c7', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2986, 458, 20, 'أَخْرَجَهُ مُسْلِمٌ وَلِلْبُخَارِيِّ:', '<p><strong> أَخْرَجَهُ مُسْلِمٌ </strong><br><strong>وَلِلْبُخَارِيِّ:</strong></p>', 'arabic', 'rtl', 20, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2987, 458, 21, '{لَا يَبُولَنَّ أَحَدُكُمْ فِي اَلْمَاءِ اَلدَّائِمِ اَلَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ فِيه}', '<p><strong>{لَا يَبُولَنَّ أَحَدُكُمْ فِي اَلْمَاءِ اَلدَّائِمِ اَلَّذِي لَا يَجْرِي، ثُمَّ يَغْتَسِلُ فِيه}</strong></p>', 'arabic', 'rtl', 21, '#2a6fcf', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2988, 458, 22, 'وَلِمُسْلِمٍ: {مِنْهُ}‏وَلِأَبِي دَاوُدَ: {وَلَا يَغْتَسِلُ فِيهِ مِنْ اَلْجَنَابَةِ}', '<p>وَلِمُسْلِمٍ<strong>: {مِنْهُ}‏</strong><br>وَلِأَبِي دَاوُدَ<strong>: {وَلَا يَغْتَسِلُ فِيهِ مِنْ اَلْجَنَابَةِ}</strong></p>', 'arabic', 'rtl', 22, '#2a7ef4', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2989, 458, 23, 'Kutoka kwa Abuu Hurayrah (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Asioge mmoja wenu katika maji yaliyotuwama ilhali ana janaba.”', '<p><strong>Kutoka kwa Abuu Hurayrah (رَضِيَ اللهُ عَنْهُ)  amesema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Asioge mmoja wenu katika maji yaliyotuwama ilhali ana janaba.”</strong></p>', 'swahili', 'ltr', 23, '#115ac0', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2990, 458, 24, '[Imetolewa na Muslim] Na katika Al-Bukhaariy:', '<p><strong>[Imetolewa na Muslim]</strong><br><strong> Na katika Al-Bukhaariy:</strong></p>', 'swahili', 'ltr', 24, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2991, 458, 25, '“Asikojoe mmoja wenu katika maji yaliyotuwama ambayo hayaendi kisha akaoga ndani yake[8].”', '<p><strong>“Asikojoe mmoja wenu katika maji yaliyotuwama ambayo hayaendi kisha akaoga ndani yake</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn8\"><strong>[8]</strong></a><strong>.”</strong></p>', 'swahili', 'ltr', 25, '#1966d2', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2992, 458, 26, 'Na katika riwaayah nyengine ya Muslim: “Kutoka humo” (yaani kutoka kwenye maji hayo).Na kwa Abuu Daawuwd: “Mtu asioge humo janaba.”', '<p><strong>Na katika riwaayah nyengine ya Muslim: “</strong>Kutoka humo” <strong>(yaani kutoka kwenye maji hayo).</strong><br><br><strong>Na kwa Abuu Daawuwd: “</strong>Mtu asioge humo janaba.”  </p>', 'swahili', 'ltr', 26, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2993, 458, 27, 'وَعَنْ رَجُلٍ صَحِبَ اَلنَّبِيَّ ‏ صلى الله عليه وسلم ‏قَالَ: نَهَى رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏\"أَنْ تَغْتَسِلَ اَلْمَرْأَةُ بِفَضْلِ اَلرَّجُلِ، أَوْ اَلرَّجُلُ بِفَضْلِ اَلْمَرْأَةِ، وَلْيَغْتَرِفَا جَمِيعًا', '<p><strong>وَعَنْ رَجُلٍ صَحِبَ اَلنَّبِيَّ ‏ صلى الله عليه وسلم ‏قَالَ: نَهَى رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏\"أَنْ تَغْتَسِلَ اَلْمَرْأَةُ بِفَضْلِ اَلرَّجُلِ، أَوْ اَلرَّجُلُ بِفَضْلِ اَلْمَرْأَةِ، وَلْيَغْتَرِفَا جَمِيعًا</strong></p>', 'arabic', 'rtl', 27, '#116be8', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2994, 458, 28, '.أَخْرَجَهُ أَبُو دَاوُدَ.‏ وَالنَّسَائِيُّ، وَإِسْنَادُهُ صَحِيحٌ.‏', '<p><strong>.أَخْرَجَهُ أَبُو دَاوُدَ.‏ وَالنَّسَائِيُّ، وَإِسْنَادُهُ صَحِيحٌ.‏</strong></p>', 'arabic', 'rtl', 28, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2995, 458, 29, 'Mtu mmoja[9] aliyesuhubiana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alisema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amekataza mwanamke kuoga mabaki ya maji ya mwanamume  na mwanamume kuoga mabaki ya maji ya mwanamke, wachote pamoja.”', '<p><strong>Mtu mmoja</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn9\"><strong>[9]</strong></a><strong> aliyesuhubiana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alisema: Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amekataza mwanamke kuoga mabaki ya maji ya mwanamume  na mwanamume kuoga mabaki ya maji ya mwanamke, wachote pamoja.”</strong></p>', 'arabic', 'rtl', 29, '#105ecb', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2996, 458, 30, '[Imetolewa na Abuu Daawuwd na An-Nasaaiy na Isnaad yake ni Swahiyh]', '<p><strong>[Imetolewa na Abuu Daawuwd na An-Nasaaiy na Isnaad yake ni Swahiyh]</strong></p>', 'swahili', 'ltr', 30, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2997, 458, 31, '7.عَنْ اِبْنِ عَبَّاسٍ رَضِيَ اَللَّهُ عَنْهُمَا، أَنَّ اَلنَّبِيَّ ‏ صلى الله عليه وسلم ‏كَانَ يَغْتَسِلُ بِفَضْلِ مَيْمُونَةَ رَضِيَ اَللَّهُ عَنْهَا.', '<p><strong>7.</strong></p><p><strong>عَنْ اِبْنِ عَبَّاسٍ رَضِيَ اَللَّهُ عَنْهُمَا، أَنَّ اَلنَّبِيَّ ‏ صلى الله عليه وسلم ‏كَانَ يَغْتَسِلُ بِفَضْلِ مَيْمُونَةَ رَضِيَ اَللَّهُ عَنْهَا.</strong></p>', 'arabic', 'rtl', 31, '#166ce3', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2998, 458, 32, 'أَخْرَجَهُ مُسْلِمٌ .‏وَلِأَصْحَابِ \"اَلسُّنَنِ:', '<p><strong>  أَخْرَجَهُ مُسْلِمٌ .‏</strong><br><strong>وَلِأَصْحَابِ \"اَلسُّنَنِ:</strong></p>', 'arabic', 'rtl', 32, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(2999, 458, 33, 'اِغْتَسَلَ بَعْضُ أَزْوَاجِ اَلنَّبِيِّ ‏ صلى الله عليه وسلم ‏فِي جَفْنَةٍ، فَجَاءَ لِيَغْتَسِلَ مِنْهَا ، فَقَالَتْ لَهُ: إِنِّي كُنْتُ جُنُبًا، فَقَالَ: {إِنَّ اَلْمَاءَ لَا يُجْنِبُ}', '<p><strong> اِغْتَسَلَ بَعْضُ أَزْوَاجِ اَلنَّبِيِّ ‏ صلى الله عليه وسلم ‏فِي جَفْنَةٍ، فَجَاءَ لِيَغْتَسِلَ مِنْهَا ، فَقَالَتْ لَهُ: إِنِّي كُنْتُ جُنُبًا، فَقَالَ: {إِنَّ اَلْمَاءَ لَا يُجْنِبُ}</strong></p>', 'arabic', 'rtl', 33, '#1d69d3', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3000, 458, 34, 'وَصَحَّحَهُ اَلتِّرْمِذِيُّ، وَابْنُ خُزَيْمَةَ‏', '<p><strong>وَصَحَّحَهُ اَلتِّرْمِذِيُّ، وَابْنُ خُزَيْمَةَ‏</strong></p>', 'arabic', 'rtl', 34, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3001, 458, 35, 'Kutoka kwa Ibn ‘Abbaas[10] (رَضِيَ اللهُ عَنْهُمَا)  kwamba Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  alikuwa akioga kwa maji yaliyoacha na Maymuwnah (رَضِيَ اللَّهُ عَنْهَا).”', '<p><strong>Kutoka kwa Ibn ‘Abbaas</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn10\"><strong>[10]</strong></a><strong> (رَضِيَ اللهُ عَنْهُمَا)  kwamba Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  alikuwa akioga kwa maji yaliyoacha na Maymuwnah (رَضِيَ اللَّهُ عَنْهَا).”</strong></p>', 'swahili', 'ltr', 35, '#1563d1', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3002, 458, 36, '[Imetolewa na Muslim]Na katika mapokezi ya Aswhaab As-Sunan]:', '<p><strong>[Imetolewa na Muslim]</strong></p><p><strong>Na katika mapokezi ya Aswhaab As-Sunan]:</strong></p>', 'swahili', 'ltr', 36, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3003, 458, 37, '“Mmoja katika ya wake wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  alioga kwenye beseni kisha Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akaja kuoga katika chombo hicho, huyo mkewe[11] akamwambia: “Mimi nilikuwa na janaba.”  Akasema: “Hakika maji hayapati janaba.”', '<p><strong>“Mmoja katika ya wake wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  alioga kwenye beseni kisha Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akaja kuoga katika chombo hicho, huyo mkewe</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn11\"><strong>[11]</strong></a><strong> akamwambia: “Mimi nilikuwa na janaba.”  Akasema: “Hakika maji hayapati janaba.”</strong></p>', 'swahili', 'ltr', 37, '#165fc5', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3004, 458, 38, '[Ameisahihisha At-Tirmidhiy na Ibn Khuzaymah]', '<p><strong>[Ameisahihisha At-Tirmidhiy na Ibn Khuzaymah]</strong></p>', 'swahili', 'ltr', 38, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3005, 458, 39, '8. وَعَنْ أَبِي هُرَيْرَةَ ‏ رضى الله عنه ‏ قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم: {طَهُورُ إِنَاءِ أَحَدِكُمْ إِذْ وَلَغَ فِيهِ اَلْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ}', '<p><strong>8.</strong></p><p><strong> وَعَنْ أَبِي هُرَيْرَةَ ‏ رضى الله عنه ‏ قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم: {طَهُورُ إِنَاءِ أَحَدِكُمْ إِذْ وَلَغَ فِيهِ اَلْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ}</strong></p>', 'arabic', 'rtl', 39, '#1260ce', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3006, 458, 40, 'أَخْرَجَهُ مُسْلِمٌ.‏وَفِي لَفْظٍ لَهُ', '<p><strong>أَخْرَجَهُ مُسْلِمٌ.‏</strong></p><p><strong>وَفِي لَفْظٍ لَهُ</strong></p>', 'arabic', 'rtl', 40, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3007, 458, 41, '{ فَلْيُرِقْهُ }وَلِلتِّرْمِذِيِّ: { أُخْرَاهُنَّ، أَوْ أُولَاهُنَّ بِالتُّرَابِ }‏ .‏‏', '<p><strong>{ فَلْيُرِقْهُ }</strong><br>وَلِلتِّرْمِذِيِّ<strong>: { أُخْرَاهُنَّ، أَوْ أُولَاهُنَّ بِالتُّرَابِ }‏ .‏‏</strong></p>', 'arabic', 'rtl', 41, '#0963e1', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3008, 458, 42, 'Kutoka kwa Abuu Hurayrah (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Kutwaharisha chombo cha mmoja wenu ikiwa kimelambwa na mbwa, ni ki kukiosha mara saba[12].”', '<p><strong>Kutoka kwa Abuu Hurayrah (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Kutwaharisha chombo cha mmoja wenu ikiwa kimelambwa na mbwa, ni ki kukiosha mara saba</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn12\"><strong>[12]</strong></a><strong>.” </strong></p>', 'swahili', 'ltr', 42, '#1e5eb8', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3009, 458, 43, '[Imetolewa na Muslim].Tamshi jengine la Muslim: “Basi amwage.”Na katika riwaayah ya Imaam At-Tirmidhiy: “Kwanza au mwisho wake kwa mchanga.”', '<p><strong>[Imetolewa na Muslim].</strong></p><p><strong>Tamshi jengine la Muslim: </strong>“Basi amwage<strong>.”</strong></p><p><strong>Na katika riwaayah ya Imaam At-Tirmidhiy:</strong> “Kwanza au mwisho wake kwa mchanga.” </p>', 'swahili', 'ltr', 43, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3010, 458, 44, '9.وَعَنْ أَبِي قَتَادَةَ ‏ رضى الله عنه  أَنَّ رَسُولَ اَللَّهِ ‏ صلى الله عليه وسلم ‏قَالَ ‏فِي اَلْهِرَّةِ‏: { إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنْ اَلطَّوَّافِينَ عَلَيْكُمْ }', '<p><strong>9.</strong></p><p><strong>وَعَنْ أَبِي قَتَادَةَ ‏ رضى الله عنه  أَنَّ رَسُولَ اَللَّهِ ‏ صلى الله عليه وسلم ‏قَالَ ‏فِي اَلْهِرَّةِ‏: { إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنْ اَلطَّوَّافِينَ عَلَيْكُمْ }</strong></p>', 'arabic', 'rtl', 44, '#1062d5', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(3011, 458, 45, '} أَخْرَجَهُ اَلْأَرْبَعَةُ، وَصَحَّحَهُ اَلتِّرْمِذِيُّ.‏ وَابْنُ خُزَيْمَةَ‏.', '<p><strong>} أَخْرَجَهُ اَلْأَرْبَعَةُ، وَصَحَّحَهُ اَلتِّرْمِذِيُّ.‏ وَابْنُ خُزَيْمَةَ‏.</strong></p>', 'arabic', 'rtl', 45, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3012, 458, 46, 'Kutoka kwa Abuu Qataadah[13] (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu paka: “Huyo si najsi bali ni mmoja wa wananchanganyika nanyi.', '<p><strong>Kutoka kwa Abuu Qataadah</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn13\"><strong>[13]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu paka: “Huyo si najsi bali ni mmoja wa wananchanganyika nanyi.</strong></p>', 'swahili', 'ltr', 46, '#206ed9', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3013, 458, 47, '[Imetolewa na Al-Arba’ah: Abuu Daawuwd, At-Tirmidhiy, An-Nasaaiy na Ibn Maajah  na ameisahihisha At-Tirmidhiy na Ibn Khuzaymah]', '<p><strong>[Imetolewa na Al-Arba’ah: Abuu Daawuwd, At-Tirmidhiy, An-Nasaaiy na Ibn Maajah  na ameisahihisha At-Tirmidhiy na Ibn Khuzaymah]</strong></p>', 'swahili', 'ltr', 47, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3014, 458, 48, 'عَنْ أَنَسِ بْنِ مَالِكٍ ‏ رضى الله عنه ‏ قَالَ: { جَاءَ أَعْرَابِيٌّ فَبَالَ فِي طَائِفَةِ اَلْمَسْجِدِ، فَزَجَرَهُ اَلنَّاسُ، فَنَهَاهُمْ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏فَلَمَّا قَضَى بَوْلَهُ أَمَرَ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏بِذَنُوبٍ مِنْ مَاءٍ، فَأُهْرِيقَ عَلَيْهِ}.‏', '<p><strong>عَنْ أَنَسِ بْنِ مَالِكٍ ‏ رضى الله عنه ‏ قَالَ: { جَاءَ أَعْرَابِيٌّ فَبَالَ فِي طَائِفَةِ اَلْمَسْجِدِ، فَزَجَرَهُ اَلنَّاسُ، فَنَهَاهُمْ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏فَلَمَّا قَضَى بَوْلَهُ أَمَرَ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏بِذَنُوبٍ مِنْ مَاءٍ، فَأُهْرِيقَ عَلَيْهِ}.‏ </strong></p>', 'arabic', 'rtl', 48, '#1864cd', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3015, 458, 49, 'مُتَّفَقٌ عَلَيْهِ.‏', '<p><strong>مُتَّفَقٌ عَلَيْهِ.‏</strong></p>', 'arabic', 'rtl', 49, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3016, 458, 50, 'Kutoka kwa Anas bin Maalik[14] (رَضِيَ اللهُ عَنْهُ) amesema: Bedui mmoja alikuja akakojoa katika pembe ya Msikiti, watu wakamkemea Lakini Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  akawakataza.  Alipomaliza mkojo wake, Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  akaamrisha iletwe ndoo ya maji, ikamwagiwa[15] juu yake (huo mkojo).', '<p><strong>Kutoka kwa Anas bin Maalik</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn14\"><strong>[14]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ) amesema: Bedui mmoja alikuja akakojoa katika pembe ya Msikiti, watu wakamkemea Lakini Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  akawakataza.  Alipomaliza mkojo wake, Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  akaamrisha iletwe ndoo ya maji, ikamwagiwa</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn15\"><strong>[15]</strong></a><strong> juu yake (huo mkojo).</strong></p>', 'swahili', 'ltr', 50, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3017, 458, 51, '[Al-Bukhaariy, Muslim]', '<p><strong>[Al-Bukhaariy, Muslim]</strong></p>', 'swahili', 'ltr', 51, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3018, 458, 52, 'وَعَنْ اِبْنِ عُمَرَ رَضِيَ اَللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏{ أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ، فَأَمَّا الْمَيْتَتَانِ: فَالْجَرَادُ وَالْحُوتُ، وَأَمَّا الدَّمَانُ: فَالطِّحَالُ وَالْكَبِدُ }', '<p><strong>وَعَنْ اِبْنِ عُمَرَ رَضِيَ اَللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏{ أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ، فَأَمَّا الْمَيْتَتَانِ: فَالْجَرَادُ وَالْحُوتُ، وَأَمَّا الدَّمَانُ: فَالطِّحَالُ وَالْكَبِدُ }</strong></p>', 'arabic', 'rtl', 52, '#1c5eba', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3019, 458, 53, 'أَخْرَجَهُ أَحْمَدُ، وَابْنُ مَاجَهْ، وَفِيهِ ضَعْفٌ', '<p><strong>أَخْرَجَهُ أَحْمَدُ، وَابْنُ مَاجَهْ، وَفِيهِ ضَعْفٌ</strong></p>', 'arabic', 'rtl', 53, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3020, 458, 54, 'Kutoka kwa Ibn ‘Umar (رَضِيَ اللهُ عَنْهُمَا)  kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Tumehalalishiwa maiti za aina bili na damu za aina mbili. Ama maiti mbili ni nzige na samaki ، na ama damu mbili  ni bandama na ini.”', '<p><strong>Kutoka kwa Ibn ‘Umar (رَضِيَ اللهُ عَنْهُمَا)  kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Tumehalalishiwa maiti za aina bili na damu za aina mbili. Ama maiti mbili ni nzige na samaki ، na ama damu mbili  ni bandama na ini.”</strong></p>', 'swahili', 'ltr', 54, '#135ec9', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3021, 458, 55, '[Imetolewa na Ahmad na Ibn Maajah na Hadiyth hii ina yaliyo dhaifu]', '<p><strong>[Imetolewa na Ahmad na Ibn Maajah na Hadiyth hii ina yaliyo dhaifu]</strong></p>', 'swahili', 'ltr', 55, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3022, 458, 56, '12.وَعَنْ أَبِي هُرَيْرَةَ  رضى الله عنه  قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏} إِذَا وَقَعَ اَلذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ، ثُمَّ لِيَنْزِعْهُ، فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً، وَفِي اَلْآخَرِ شِفَاءً }', '<p><strong>12.</strong></p><p><strong>وَعَنْ أَبِي هُرَيْرَةَ  رضى الله عنه  قَالَ: قَالَ رَسُولُ اَللَّهِ ‏ صلى الله عليه وسلم ‏} إِذَا وَقَعَ اَلذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ، ثُمَّ لِيَنْزِعْهُ، فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً، وَفِي اَلْآخَرِ شِفَاءً }</strong></p>', 'arabic', 'rtl', 56, '#226ed8', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3023, 458, 57, 'أَخْرَجَهُ اَلْبُخَارِيُّ.‏وَأَبُو دَاوُدَ ، وَزَادَ:', '<p><strong>أَخْرَجَهُ اَلْبُخَارِيُّ.‏</strong></p><p><strong>وَأَبُو دَاوُدَ ، وَزَادَ:</strong></p>', 'arabic', 'rtl', 57, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3024, 458, 58, '{ وَإِنَّهُ يَتَّقِي بِجَنَاحِهِ اَلَّذِي فِيهِ اَلدَّاءُ }', '<p><strong>{ وَإِنَّهُ يَتَّقِي بِجَنَاحِهِ اَلَّذِي فِيهِ اَلدَّاءُ }</strong></p>', 'arabic', 'rtl', 58, '#1b5ebb', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3025, 458, 59, 'Kutoka kwa Abuu  Hurayrah (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Pindi nzi akiangukia katika kinywaji cha mmoja wenu, basi amazmishe kisha amtoe , kwani kuna ugonjwa katika moja ya bawa lake na tiba katika bawa jengine[16].”', '<p><strong>Kutoka kwa Abuu  Hurayrah (رَضِيَ اللهُ عَنْهُ) kwamba Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ)  amesema: “Pindi nzi akiangukia katika kinywaji cha mmoja wenu, basi amazmishe kisha amtoe , kwani kuna ugonjwa katika moja ya bawa lake na tiba katika bawa jengine</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn16\"><strong>[16]</strong></a><strong>.” </strong></p>', 'swahili', 'ltr', 59, '#186adc', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3026, 458, 60, '[Imetolewa na Al-Bukhaariy ]Na Abuu Daawuwd ambaye aliongeza:', '<p><strong>[Imetolewa na Al-Bukhaariy ]</strong></p><p><strong>Na Abuu Daawuwd ambaye aliongeza:</strong></p>', 'swahili', 'ltr', 60, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3027, 458, 61, '“Kwani yeye (inzi) huangulikia kwa bawa lake lenye ugonjwa.”', '<p><strong>“Kwani yeye (inzi) huangulikia kwa bawa lake lenye ugonjwa.”</strong></p>', 'swahili', 'ltr', 61, '#0f5ac2', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3028, 458, 62, '13.عَنْ أَبِي وَاقِدٍ اَللَّيْثِيِّ ‏ رضى الله عنه ‏ قَالَ: قَالَ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏{ مَا قُطِعَ مِنْ اَلْبَهِيمَةِ ‏وَهِيَ حَيَّةٌ‏ فَهُوَ مَيِّتٌ }', '<p><strong>13.</strong></p><p><strong>عَنْ أَبِي وَاقِدٍ اَللَّيْثِيِّ ‏ رضى الله عنه ‏ قَالَ: قَالَ اَلنَّبِيُّ ‏ صلى الله عليه وسلم ‏{ مَا قُطِعَ مِنْ اَلْبَهِيمَةِ ‏وَهِيَ حَيَّةٌ‏ فَهُوَ مَيِّتٌ }</strong></p>', 'arabic', 'rtl', 62, '#1563d1', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3029, 458, 63, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَاَلتِّرْمِذِيُّ وَحَسَّنَهُ، وَاللَّفْظُ لَهُ.‏', '<p><strong>أَخْرَجَهُ أَبُو دَاوُدَ، وَاَلتِّرْمِذِيُّ وَحَسَّنَهُ، وَاللَّفْظُ لَهُ.‏</strong></p>', 'arabic', 'rtl', 63, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3030, 458, 64, 'Kutoka kwa Abuu Waaqid Al-Laythiyy[17] (رَضِيَ اللهُ عَنْهُ) kwamba Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Kilichokatwa kutoka kwa mnyama aliye hai basi hicho ni maiti.”', '<p><strong>Kutoka kwa Abuu Waaqid Al-Laythiyy</strong><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftn17\"><strong>[17]</strong></a><strong> (رَضِيَ اللهُ عَنْهُ) kwamba Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Kilichokatwa kutoka kwa mnyama aliye hai basi hicho ni maiti.”</strong></p>', 'swahili', 'ltr', 64, '#105ac1', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3031, 458, 65, '[Imetolewa na Abuu Daawuwd na At-Tirmidhiy na ameipa daraja ya Hasan na tamashi hili ni lake]', '<p><strong>[Imetolewa na Abuu Daawuwd na At-Tirmidhiy na ameipa daraja ya Hasan na tamashi hili ni lake]</strong></p>', 'swahili', 'ltr', 65, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3032, 459, 1, '[1] Abuu Hurayrah: Jina lake halisi ni ni ‘Abdullaah au ‘Abdur-Rahmaan bin Sakhr Ad-Daws, mmoja wa Swahaba wakubwa wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) na alipokea Hadiyth nyingi kuliko wote. Zaidi ya watu 800 walipokea kutoka kwake. Alisilimu katika mwaka wa Khaybar (7H) na akawa karibu na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) mpaka Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alipofariki. Akateuliwa kuwa Mufti (Mwanazuoni wa hukumu za Kiislaam) wakati wa Ukhalifa wa ‘Umar (رَضِيَ اللهُ عَنْهُ) na baadaye akawa gavana wa Madiynah wakati wa utawala wa Marwaan bin Al-Hakam. Alifariki mwaka 59 H na akazikwa Al-Baqi’.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref1\"><strong>[1]</strong></a> Abuu Hurayrah: Jina lake halisi ni ni ‘Abdullaah au ‘Abdur-Rahmaan bin Sakhr Ad-Daws, mmoja wa Swahaba wakubwa wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) na alipokea Hadiyth nyingi kuliko wote. Zaidi ya watu 800 walipokea kutoka kwake. Alisilimu katika mwaka wa Khaybar (7H) na akawa karibu na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) mpaka Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alipofariki. Akateuliwa kuwa Mufti (Mwanazuoni wa hukumu za Kiislaam) wakati wa Ukhalifa wa ‘Umar (رَضِيَ اللهُ عَنْهُ) na baadaye akawa gavana wa Madiynah wakati wa utawala wa Marwaan bin Al-Hakam. Alifariki mwaka 59 H na akazikwa Al-Baqi’.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3033, 459, 2, '[2] Abuu Sa’iyd Al-Khudriyy: Jina lake ni Sa’d bin Maalik bin Sinan Al-Khazraj Al-Answaar. Alikuwa miongoni mwa Swahaba wasomi. Alipokea Hadiyth nyingi, na alitoa rai za kidini kwa muda fulani. Alifariki mwanzoni mwa mwaka wa 74H akiwa na umri wa miaka 86.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref2\"><strong>[2]</strong></a> Abuu Sa’iyd Al-Khudriyy: Jina lake ni Sa’d bin Maalik bin Sinan Al-Khazraj Al-Answaar. Alikuwa miongoni mwa Swahaba wasomi. Alipokea Hadiyth nyingi, na alitoa rai za kidini kwa muda fulani. Alifariki mwanzoni mwa mwaka wa 74H akiwa na umri wa miaka 86.</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3034, 459, 3, '[3] Imepokewa na Ahmad, At-Tirmidhiy, na Abuu Daawud kuwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alisema maneno hayo katika kujibu swali kuhusu kisima cha Buda’a, kilicho karibu na Madiynah, na daima kilijaa uchafu. Kilikuwa kwenye eneo lililo chini, na maji ya mvua yalikuwa yanapeleka uchafu na takataka kisimani. Maneno haya bila shaka yanakihusu.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref3\"><strong>[3]</strong></a> Imepokewa na Ahmad, At-Tirmidhiy, na Abuu Daawud kuwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alisema maneno hayo katika kujibu swali kuhusu kisima cha Buda’a, kilicho karibu na Madiynah, na daima kilijaa uchafu. Kilikuwa kwenye eneo lililo chini, na maji ya mvua yalikuwa yanapeleka uchafu na takataka kisimani. Maneno haya bila shaka yanakihusu.</p>', 'swahili', 'ltr', 3, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3035, 459, 4, '[4] Abuu Umaamah Al-Baahiliy: Jina lake halisi ni Suday bin Ajlaan akiwa ni mmoja wa Swahaba waliopokea Hadiyth nyingi. Aliishi Misri, kisha akahamia Hims (sasa iko Syria), na akafia kule akiwa na umri wa miaka 81 au 86.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref4\"><strong>[4]</strong></a> Abuu Umaamah Al-Baahiliy: Jina lake halisi ni Suday bin Ajlaan akiwa ni mmoja wa Swahaba waliopokea Hadiyth nyingi. Aliishi Misri, kisha akahamia Hims (sasa iko Syria), na akafia kule akiwa na umri wa miaka 81 au 86.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3036, 459, 5, '[5] Baadhi ya watu wamehoji kwamba, maji yanaweza kupunguka au kuongezeka wingi wake ikiwa huo uchafu au taka zitabadili moja ya sifa zake hizo tatu (rangi, harufu na ladha), na hapo maji yatanajisika. Lakini maoni sahihi katika maudhui haya ni kuwa, iwapo maji yako chini ya kilo 227 (Qulla mbili), basi taka yoyote inayanajisi maji, iwe imebadilisha moja ya sifa zake au laa. Lakini ikiwa maji yana kilo 227, hayanajisiki mpaka ibadilike mojawapo kati ya sifa zake hizo tatu.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref5\"><strong>[5]</strong></a> Baadhi ya watu wamehoji kwamba, maji yanaweza kupunguka au kuongezeka wingi wake ikiwa huo uchafu au taka zitabadili moja ya sifa zake hizo tatu (rangi, harufu na ladha), na hapo maji yatanajisika. Lakini maoni sahihi katika maudhui haya ni kuwa, iwapo maji yako chini ya kilo 227 (Qulla mbili), basi taka yoyote inayanajisi maji, iwe imebadilisha moja ya sifa zake au laa. Lakini ikiwa maji yana kilo 227, hayanajisiki mpaka ibadilike mojawapo kati ya sifa zake hizo tatu.</p>', 'swahili', 'ltr', 5, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3037, 459, 6, '[6] ‘Abdullaah bin ‘Umar alikuwa miongoni mwa wenye kuipa nyongo dunia na mwenye elimu kubwa sana. Alisilimu Makkah wakati akingali kijana mdogo na akahamia Madiynah. Kwanza alishiriki katika vita vya Khandaq, na akafariki mnamo mwaka 73H, akazikwa kule Dhi-Twuwaa.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref6\"><strong>[6]</strong></a> ‘Abdullaah bin ‘Umar alikuwa miongoni mwa wenye kuipa nyongo dunia na mwenye elimu kubwa sana. Alisilimu Makkah wakati akingali kijana mdogo na akahamia Madiynah. Kwanza alishiriki katika vita vya Khandaq, na akafariki mnamo mwaka 73H, akazikwa kule Dhi-Twuwaa.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3038, 459, 7, '[7] Qulla ni mtungi mkubwa wa udongo unaoweza kuwa na maji yapatayo viriba viwili na nusu, yaani kilo 113.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref7\"><strong>[7]</strong></a> Qulla ni mtungi mkubwa wa udongo unaoweza kuwa na maji yapatayo viriba viwili na nusu, yaani kilo 113.</p>', 'swahili', 'ltr', 7, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3039, 459, 8, '[8] Hii inahusu maji kidogo. Iwapo maji ni mengi, yatahesabika kama maji yanayokwenda au kutiririka, ambayo si machafu na ni mazuri kwa kuogea. Imekatazwa kukojolea maji yaliyosimama ardhini, na kwamba mtu asifanye hivyo ili asizowee kuchafua maji. Maji yanayotiririka kila mara huwa masafi; na hayanajisiki kwa kutiwa takataka au uchafu.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref8\"><strong>[8]</strong></a> Hii inahusu maji kidogo. Iwapo maji ni mengi, yatahesabika kama maji yanayokwenda au kutiririka, ambayo si machafu na ni mazuri kwa kuogea. Imekatazwa kukojolea maji yaliyosimama ardhini, na kwamba mtu asifanye hivyo ili asizowee kuchafua maji. Maji yanayotiririka kila mara huwa masafi; na hayanajisiki kwa kutiwa takataka au uchafu.</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3040, 459, 9, '[9] Huyu ni mmoja wa Swahaba, na kutokutajwa jina lake hakuiathiri Hadiyth kwa kuwa Swahaba wote walikuwa waaminifu kabisa.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref9\"><strong>[9]</strong></a> Huyu ni mmoja wa Swahaba, na kutokutajwa jina lake hakuiathiri Hadiyth kwa kuwa Swahaba wote walikuwa waaminifu kabisa.</p>', 'swahili', 'ltr', 9, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3041, 459, 10, '[10] Ibn ‘Abbaas: Huyu ndiye ‘Abdullaah bin ‘Abbaas bin ‘Abdul-Mutwalib, binammi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) na Mwanazuoni wa Ummah wa Kiislaam, aliyezaliwa miaka 3 kabla ya Hijrah na akafariki mnamo mwaka 67 A.H.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref10\"><strong>[10]</strong></a> Ibn ‘Abbaas: Huyu ndiye ‘Abdullaah bin ‘Abbaas bin ‘Abdul-Mutwalib, binammi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) na Mwanazuoni wa Ummah wa Kiislaam, aliyezaliwa miaka 3 kabla ya Hijrah na akafariki mnamo mwaka 67 A.H.</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3042, 459, 11, '[11] Hadiyth hii inaonekana kama inapingana na ya kwanza, lakini sivyo, kwani amri si ya kukataza moja kwa moja, bali ni mapendekezo ya kukataza ili kuepuka mabaki yoyote ya uchafu.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref11\"><strong>[11]</strong></a> Hadiyth hii inaonekana kama inapingana na ya kwanza, lakini sivyo, kwani amri si ya kukataza moja kwa moja, bali ni mapendekezo ya kukataza ili kuepuka mabaki yoyote ya uchafu.</p>', 'swahili', 'ltr', 11, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3043, 459, 12, '[12] Ieleweke kwamba, kukosha tu uchafu katika chombo, si lazima kuwe mara saba. Falsafa ya kukiosha kitu kikawaida ni tofauti na kukiosha uchafu mahsusi. Madaktari wa zama hizi wanasema kuwa aghalabu katika matumbo ya mbwa huwa kuna viini vya maradhi na minyoo ipatayo urefu wa milimita 4, na hivi hutoka pamoja na kinyesi na hujishikiza kwenye nywele zizungukazo duburi ya mbwa. Mbwa hujisafisha duburi kwa ndimi zao, huchukua viini na minyoo hiyo, na pindi anapolamba chombo au ukimbusu kinywa chake (kama wazungu wafanyavyo). Viini hivi huhamia kwenye chombo au kwenye mdomo wa mtu anayembusu mbwa, na hatimaye huingia tumboni mwa mwana Aadam, na huweza kupenya mpaka kwenye seli za damu na kusababisha magonjwa yanayoweza hata kuua. Kwa kuwa viini hivi havionekani bila darubini. Shariy’ah ya Kiislaam iliamuru kuwa mate ya mbwa kwa ujumla ni najsi, na chochote kinachonajisiwa na mate ya mbwa ni sharti kioshwe mara saba (7), moja ya mara hizi saba, iwe kwa udongo ili kuwa na hakika wa usafi wake. Ili uyajue vyema maudhui haya, tafadhali soma tanbihi chini ya ukurasa wa kitabu cha Ahkaamul-Ahsan, Sharh ’Umdatul Ahkaam.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref12\"><strong>[12]</strong></a> Ieleweke kwamba, kukosha tu uchafu katika chombo, si lazima kuwe mara saba. Falsafa ya kukiosha kitu kikawaida ni tofauti na kukiosha uchafu mahsusi. Madaktari wa zama hizi wanasema kuwa aghalabu katika matumbo ya mbwa huwa kuna viini vya maradhi na minyoo ipatayo urefu wa milimita 4, na hivi hutoka pamoja na kinyesi na hujishikiza kwenye nywele zizungukazo duburi ya mbwa. Mbwa hujisafisha duburi kwa ndimi zao, huchukua viini na minyoo hiyo, na pindi anapolamba chombo au ukimbusu kinywa chake (kama wazungu wafanyavyo). Viini hivi huhamia kwenye chombo au kwenye mdomo wa mtu anayembusu mbwa, na hatimaye huingia tumboni mwa mwana Aadam, na huweza kupenya mpaka kwenye seli za damu na kusababisha magonjwa yanayoweza hata kuua. Kwa kuwa viini hivi havionekani bila darubini. Shariy’ah ya Kiislaam iliamuru kuwa mate ya mbwa kwa ujumla ni najsi, na chochote kinachonajisiwa na mate ya mbwa ni sharti kioshwe mara saba (7), moja ya mara hizi saba, iwe kwa udongo ili kuwa na hakika wa usafi wake. Ili uyajue vyema maudhui haya, tafadhali soma tanbihi chini ya ukurasa wa kitabu cha Ahkaamul-Ahsan, Sharh ’Umdatul Ahkaam.</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3044, 459, 13, '[13] Huyu Abuu Qatada ndiye Al-Haarith bin Rib’I Al Answaar, mwangalizi wa farasi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ). Alipigana katika vita vya Uhud, na vita vingine vilivyofuatia. Inasemekana kuwa alifariki Madiynah au Kufa mnamo mwaka 54 A.H.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref13\"><strong>[13]</strong></a> Huyu Abuu Qatada ndiye Al-Haarith bin Rib’I Al Answaar, mwangalizi wa farasi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ). Alipigana katika vita vya Uhud, na vita vingine vilivyofuatia. Inasemekana kuwa alifariki Madiynah au Kufa mnamo mwaka 54 A.H.</p>', 'swahili', 'ltr', 13, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3045, 459, 14, '[14] Anas bin Maalik alikuwa mtumishi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kutoka wakati alipokwenda Madiynah mpaka alipofariki. Anajulikana kwa jina la Abuu Hamzah na alikuwa Mkhazrajiy. Aliishi kule Basra wakati wa ukhalifa wa ‘Umar (رَضِيَ اللهُ عَنْهُ), na akafariki kule akiwa na umri wa miaka 99 au 103, mnamo mwaka wa 91 au 92 au 93 A.H.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref14\"><strong>[14]</strong></a> Anas bin Maalik alikuwa mtumishi wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kutoka wakati alipokwenda Madiynah mpaka alipofariki. Anajulikana kwa jina la Abuu Hamzah na alikuwa Mkhazrajiy. Aliishi kule Basra wakati wa ukhalifa wa ‘Umar (رَضِيَ اللهُ عَنْهُ), na akafariki kule akiwa na umri wa miaka 99 au 103, mnamo mwaka wa 91 au 92 au 93 A.H.</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3046, 459, 15, '[15] Hadiyth hii inathibitisha kwamba, mchanga au udongo husafika ukikauka, kama Abuu Shaybah alivyopokea, hususan iwapo utamwagia maji na yatiririke juu ya mahali palipokojolewa.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref15\"><strong>[15]</strong></a> Hadiyth hii inathibitisha kwamba, mchanga au udongo husafika ukikauka, kama Abuu Shaybah alivyopokea, hususan iwapo utamwagia maji na yatiririke juu ya mahali palipokojolewa.</p>', 'swahili', 'ltr', 15, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3047, 459, 16, '[16] Ni wazi kutoka katika Hadiyth hii kwamba endapo inzi kadondokea katika maji au kinywaji, hakitafanywa kichafu, sawa na viumbe vya familia hii ambayo damu yake haitembei, kama mbu, dondola na buibui, hawakifanyi kinywaji kiwe kichafu wakidondokea au kufia humo.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref16\"><strong>[16]</strong></a> Ni wazi kutoka katika Hadiyth hii kwamba endapo inzi kadondokea katika maji au kinywaji, hakitafanywa kichafu, sawa na viumbe vya familia hii ambayo damu yake haitembei, kama mbu, dondola na buibui, hawakifanyi kinywaji kiwe kichafu wakidondokea au kufia humo.</p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3048, 459, 17, '[17] Jina halisi la Abuu Waqiyd ni Al-Haarith bin ‘Awf, na kizazi cha Banu ‘Aamir bin Layth. Alisilimu mapema sana na anahesabika kuwa ni mtu wa Madiynah. Inasemekana kwamba alipigana katika vita vya Badr, aliishi Makkah, na akafariki Makkah mnamo mwaka 65 au 68 A.H alipokuwa na miaka 57, na akazikwa Funj.', '<p><a href=\"https://www.alhidaaya.com/sw/01-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-maji#_ftnref17\"><strong>[17]</strong></a> Jina halisi la Abuu Waqiyd ni Al-Haarith bin ‘Awf, na kizazi cha Banu ‘Aamir bin Layth. Alisilimu mapema sana na anahesabika kuwa ni mtu wa Madiynah. Inasemekana kwamba alipigana katika vita vya Badr, aliishi Makkah, na akafariki Makkah mnamo mwaka 65 au 68 A.H alipokuwa na miaka 57, na akazikwa Funj.</p>', 'swahili', 'ltr', 17, '#1f2937', '#ffffff', '2026-08-29 06:54:59', '2026-08-29 06:54:59', NULL, NULL, NULL, 0),
(3180, 461, 1, '[1] Istihaadhwah (damu imtokayo mwanamke ukeni) ni damu inayodumu muda mrefu na inaweza kuwa ni damu ya uzazi au ya hedhi, na huhesabika kuwa ni kutokwa na damu kati kati ya vipindi. Kipindi cha hedhi, kwa mujibu wa ‘Ulamaa ni kutoka siku moja mpaka siku kumi na tano; na kwa mujibu wa wengine ni kutoka siku tatu mpaka siku kumi. Uzoefu unaonyesha kuwa huo usemi wa pili ni sahihi zaidi. Kila mwanamke huwa anafahamu vipindi vyake, na akitokwa damu zaidi ya wakati wake, basi hiyo ni Istihaadhwah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref1\"><strong>[1]</strong></a> Istihaadhwah (damu imtokayo mwanamke ukeni) ni damu inayodumu muda mrefu na inaweza kuwa ni damu ya uzazi au ya hedhi, na huhesabika kuwa ni kutokwa na damu kati kati ya vipindi. Kipindi cha hedhi, kwa mujibu wa ‘Ulamaa ni kutoka siku moja mpaka siku kumi na tano; na kwa mujibu wa wengine ni kutoka siku tatu mpaka siku kumi. Uzoefu unaonyesha kuwa huo usemi wa pili ni sahihi zaidi. Kila mwanamke huwa anafahamu vipindi vyake, na akitokwa damu zaidi ya wakati wake, basi hiyo ni Istihaadhwah.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3181, 461, 2, '[2] Asmaa alikuwa mke wa Ja’far bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ). Alihajiri pamoja naye hadi Habashah (Abyssinia   Ethiopia), na alimzalia watoto watatu, na kati ya hao ni ‘Abdullaah. Baada ya Ja’far (رَضِيَ اللهُ عَنْهُ) kufa Shahidi katika vita vya Mut’a, Abuu Bakar Swiddiyq (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia mtoto mmoja Muhammad. Na baada ya kufariki Abuu Bakar (رَضِيَ اللهُ عَنْهُ), ‘Aliy bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia Yahyaa. ‘Umar (رَضِيَ اللهُ عَنْهُ) alizowea kumuuliza Asmaa tafsiri ya ndoto. Alikufa baada ya kifo cha ‘Aliy (رَضِيَ اللهُ عَنْهُ).', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref2\"><strong>[2]</strong></a> Asmaa alikuwa mke wa Ja’far bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ). Alihajiri pamoja naye hadi Habashah (Abyssinia   Ethiopia), na alimzalia watoto watatu, na kati ya hao ni ‘Abdullaah. Baada ya Ja’far (رَضِيَ اللهُ عَنْهُ) kufa Shahidi katika vita vya Mut’a, Abuu Bakar Swiddiyq (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia mtoto mmoja Muhammad. Na baada ya kufariki Abuu Bakar (رَضِيَ اللهُ عَنْهُ), ‘Aliy bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia Yahyaa. ‘Umar (رَضِيَ اللهُ عَنْهُ) alizowea kumuuliza Asmaa tafsiri ya ndoto. Alikufa baada ya kifo cha ‘Aliy (رَضِيَ اللهُ عَنْهُ).</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3182, 461, 3, '[3] Hamnah bint Jahsh ni dada wa “Mama wa Waumini”, Zaynab bint Jahsh. Alioelewa na Musw’ab bin ‘Umayr ambaye alikufa Shahidi katika  vita vya Uhud, na baada ya hivyo akaolewa na Twalhah bin ‘Ubaydillaah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref3\"><strong>[3]</strong></a> Hamnah bint Jahsh ni dada wa “Mama wa Waumini”, Zaynab bint Jahsh. Alioelewa na Musw’ab bin ‘Umayr ambaye alikufa Shahidi katika  vita vya Uhud, na baada ya hivyo akaolewa na Twalhah bin ‘Ubaydillaah.</p>', 'swahili', 'ltr', 3, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3183, 461, 4, '[4] Katika Hadiyth hii Hamnah aliamriwa kuoga mara tatu kila siku. Aoge mara moja kwa ajili ya Swalaah za Adhuhuri na Alasiri, na aoge mara ya pili kwa Swalaah za Magharibi na ‘Ishaa, na aoge mara ya tatu kwa Swalaah ya Alfajiri. Katika Hadiyth iliyopita, Faatwimah binti Abiy Hubaysh aliamuriwa achukue wudhuu tu kabla ya kila Swalaah. Hii inamaanisha kuwa, kwa mwanamke anayekuwa na Istihaadhwah kuoga siyo lazima, lakini kuchukuwa wudhuu ni lazima kwa kila Swalaah. Kuoga ni bora ikiwa hali ya afya na ya hewa itaruhusu, vinginevyo hakuna haja ya kuoga.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref4\"><strong>[4]</strong></a> Katika Hadiyth hii Hamnah aliamriwa kuoga mara tatu kila siku. Aoge mara moja kwa ajili ya Swalaah za Adhuhuri na Alasiri, na aoge mara ya pili kwa Swalaah za Magharibi na ‘Ishaa, na aoge mara ya tatu kwa Swalaah ya Alfajiri. Katika Hadiyth iliyopita, Faatwimah binti Abiy Hubaysh aliamuriwa achukue wudhuu tu kabla ya kila Swalaah. Hii inamaanisha kuwa, kwa mwanamke anayekuwa na Istihaadhwah kuoga siyo lazima, lakini kuchukuwa wudhuu ni lazima kwa kila Swalaah. Kuoga ni bora ikiwa hali ya afya na ya hewa itaruhusu, vinginevyo hakuna haja ya kuoga.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3184, 461, 5, '[5] Habiybah bint Jahsh alikuwa dada mwingine wa “Mama wa Waumini” Zaynab bint Jahsh, naye aliolewa na ‘Abdur-Rahmaan bin ‘Awf. Mulsim alisimulia kuwa alikuwa na damu iliyodumu miaka saba. Alifariki mnamo mwaka wa 44 A.H.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref5\"><strong>[5]</strong></a> Habiybah bint Jahsh alikuwa dada mwingine wa “Mama wa Waumini” Zaynab bint Jahsh, naye aliolewa na ‘Abdur-Rahmaan bin ‘Awf. Mulsim alisimulia kuwa alikuwa na damu iliyodumu miaka saba. Alifariki mnamo mwaka wa 44 A.H.</p>', 'swahili', 'ltr', 5, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3185, 461, 6, '[6] Ilikuwa ni hatua ya hiari na ya tahadhari tu kwa Umm Habiybah kuoga kwa kila Swalaah. Uamuzi sahihi kuhusu kadhia hii ni kuoga baada ya hedhi na atawadhe. Kuhusu kutokwa damu kwa muda mrefu mno, ipo amri ya kuosha damu na kuchukua wudhuu katika kila Swalaah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref6\"><strong>[6]</strong></a> Ilikuwa ni hatua ya hiari na ya tahadhari tu kwa Umm Habiybah kuoga kwa kila Swalaah. Uamuzi sahihi kuhusu kadhia hii ni kuoga baada ya hedhi na atawadhe. Kuhusu kutokwa damu kwa muda mrefu mno, ipo amri ya kuosha damu na kuchukua wudhuu katika kila Swalaah.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3186, 461, 7, '[7] Ummu ‘Atwiyyah ni jina la Nusaybah Ka’b bint Al-Haarith Al-Ansariyya. Alikuwa ni miongoni mwa Swahaba wa kike maarufu, na alikuwa akiongozana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) vitani akiwauguza wagonjwa na kuwatibu majeruhi. Alipigana katika Vita vya Uhud kama shujaa. Alishuhudia kuoshwa kwa maiti ya binti wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) ambako alieleza na alitusimulia, na Swahaba, Taabi’, ‘Ulamaa wa Basra walirikodi kutoka kwake. Hadiyth yake inahesabika kuwa ndiyo msingi wa kuosha maiti. Alikuwa mmoja wa Swahaba wa kike waliolowea kule Basra.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref7\"><strong>[7]</strong></a> Ummu ‘Atwiyyah ni jina la Nusaybah Ka’b bint Al-Haarith Al-Ansariyya. Alikuwa ni miongoni mwa Swahaba wa kike maarufu, na alikuwa akiongozana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) vitani akiwauguza wagonjwa na kuwatibu majeruhi. Alipigana katika Vita vya Uhud kama shujaa. Alishuhudia kuoshwa kwa maiti ya binti wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) ambako alieleza na alitusimulia, na Swahaba, Taabi’, ‘Ulamaa wa Basra walirikodi kutoka kwake. Hadiyth yake inahesabika kuwa ndiyo msingi wa kuosha maiti. Alikuwa mmoja wa Swahaba wa kike waliolowea kule Basra.</p>', 'swahili', 'ltr', 7, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3187, 461, 8, '[8] Katika usimulizi wa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) majimaji ya rangi ya njano au na vumbi yanahesabika kuwa ni damu ya hedhi, lakini Hadiyth hii inasema: “Tuliyahesabu kuwa siyo kitu.” Hadiyth hizi mbili zaelekea kujipinga, lakini zote mbili ni sahihi katika muktadha wa kila moja. Ikiwa majimaji ya rangi ya njano au ya vumbi yatajitokeza wakati wa kipindi cha hedhi, yatahesabika kuwa ni “damu ya hedhi.” Lakini yakijitokeza baada ya kipindi cha hedhi basi si chochote kama maneno ya Kiarabu ya بَعْدَ اَلطُّهْرِ yanavyodokeza.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref8\"><strong>[8]</strong></a> Katika usimulizi wa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) majimaji ya rangi ya njano au na vumbi yanahesabika kuwa ni damu ya hedhi, lakini Hadiyth hii inasema: “Tuliyahesabu kuwa siyo kitu.” Hadiyth hizi mbili zaelekea kujipinga, lakini zote mbili ni sahihi katika muktadha wa kila moja. Ikiwa majimaji ya rangi ya njano au ya vumbi yatajitokeza wakati wa kipindi cha hedhi, yatahesabika kuwa ni “damu ya hedhi.” Lakini yakijitokeza baada ya kipindi cha hedhi basi si chochote kama maneno ya Kiarabu ya بَعْدَ اَلطُّهْرِ yanavyodokeza.</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3188, 461, 9, '[9] Vazi linalovaliwa kutoka kiunoni kuenda chini kama gagulo au sketi.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref9\"><strong>[9]</strong></a> Vazi linalovaliwa kutoka kiunoni kuenda chini kama gagulo au sketi.</p>', 'swahili', 'ltr', 9, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3189, 461, 10, '[10] Wale ambao hawazisadiki Hadiyth, yaani wakanushaji wa Sunnah, wanaleta utata na mashaka hapa, na wanawafanya watu wazishuku Hadiyth. Wanasema kuwa tendo la ndoa katika kipindi cha hedhi limekatazwa na Qur-aan lakini kwa mujibu wa Hadiyth hii Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alifanya wakati ule, kwa hiyo Hadiyth hiyo siyo sahihi. Maana ya maneno ya ‘Mubaasharat’ ni kugusa na kuukanda mwili kwa mwili, na kwa kifumbo maana yake ni kufanya tendo la ndoa. Katika Hadiyth imewekwa wazi kwamba tendo la ndoa limekatazwa wakati ya hedhi ya mwanamke. Kwa hivyo ni udanganyifu tu kutafsiri neno hilo ‘mubashaarat’ kuwa ni ‘tendo la ndoa’ badala ya kulitafsiri kuwa ni ‘kushikashika kwa mahaba’ na kuleta mashaka.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref10\"><strong>[10]</strong></a> Wale ambao hawazisadiki Hadiyth, yaani wakanushaji wa Sunnah, wanaleta utata na mashaka hapa, na wanawafanya watu wazishuku Hadiyth. Wanasema kuwa tendo la ndoa katika kipindi cha hedhi limekatazwa na Qur-aan lakini kwa mujibu wa Hadiyth hii Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alifanya wakati ule, kwa hiyo Hadiyth hiyo siyo sahihi. Maana ya maneno ya ‘Mubaasharat’ ni kugusa na kuukanda mwili kwa mwili, na kwa kifumbo maana yake ni kufanya tendo la ndoa. Katika Hadiyth imewekwa wazi kwamba tendo la ndoa limekatazwa wakati ya hedhi ya mwanamke. Kwa hivyo ni udanganyifu tu kutafsiri neno hilo ‘mubashaarat’ kuwa ni ‘tendo la ndoa’ badala ya kulitafsiri kuwa ni ‘kushikashika kwa mahaba’ na kuleta mashaka.</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3190, 461, 11, '[11] Hii ni Hadiyth dhaifu, kwa hivyo wengi wa ‘Ulamaa hawadhani kuwa ni lazima kufidia, ingawa baadhi ya ‘Ulamaa hudhani inafaa kufidia, lakini rai ya kwanza ni sahihi kwa kuwa amri hiyo ni kwa kuhamasisha Swadaqah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref11\"><strong>[11]</strong></a> Hii ni Hadiyth dhaifu, kwa hivyo wengi wa ‘Ulamaa hawadhani kuwa ni lazima kufidia, ingawa baadhi ya ‘Ulamaa hudhani inafaa kufidia, lakini rai ya kwanza ni sahihi kwa kuwa amri hiyo ni kwa kuhamasisha Swadaqah.</p>', 'swahili', 'ltr', 11, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3191, 461, 12, '[12] Hii ni sehemu ndogo tu ya Hadiyth ndefu. Alipokuwa akitoa khutbah kwa wanawake Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) aliwaambia kuwa dini yao haijakamilika. Walipouliza kwa namna gani, kwa kusema maneno yanayomaanisha kuwa wanawake walio na hedhi wasiswali wala wasifunge Swawm.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref12\"><strong>[12]</strong></a> Hii ni sehemu ndogo tu ya Hadiyth ndefu. Alipokuwa akitoa khutbah kwa wanawake Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) aliwaambia kuwa dini yao haijakamilika. Walipouliza kwa namna gani, kwa kusema maneno yanayomaanisha kuwa wanawake walio na hedhi wasiswali wala wasifunge Swawm.</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3192, 461, 13, '[13] Kila kilicho juu ya Izaar (Nguo inayovaliwa chini ya kiuno) inaweza kuwa na maana mbili: kwanza inaweza kuwa na maana ya jimai. Kwa maneno mengine, kila kitu kinaruhusiwa isipokuwa jimai. Pili: ina maana ya ile sehemu inayovaliwa Izaar. Ila maana hii inaweza kupingana na Hadiyth isemayo: “Fanyeni kila kitu isipokuwa jimai.” Kwa hivyo basi ni vizuri kutumia maana ya kwanza.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref13\"><strong>[13]</strong></a> Kila kilicho juu ya Izaar (Nguo inayovaliwa chini ya kiuno) inaweza kuwa na maana mbili: kwanza inaweza kuwa na maana ya jimai. Kwa maneno mengine, kila kitu kinaruhusiwa isipokuwa jimai. Pili: ina maana ya ile sehemu inayovaliwa Izaar. Ila maana hii inaweza kupingana na Hadiyth isemayo: “Fanyeni kila kitu isipokuwa jimai.” Kwa hivyo basi ni vizuri kutumia maana ya kwanza.</p>', 'swahili', 'ltr', 13, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3193, 461, 14, '[14] Hii inamaanisha ni kile kiwango cha juu cha siku za damu ya uzazi, na hakuna kiwango chake cha chini. Laiti ikiendelea zaidi ya siku arubaini, basi itakuwa ni Istihaadhwah (damu ya ugonjwa), ambayo siyo kizuizi kwa Swalaah, wala kufunga Swawm, wala kufanya tendo la ndoa. Kila amri kuhusu damu na uzazi ni sawa na ile ya damu ya hedhi', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref14\"><strong>[14]</strong></a> Hii inamaanisha ni kile kiwango cha juu cha siku za damu ya uzazi, na hakuna kiwango chake cha chini. Laiti ikiendelea zaidi ya siku arubaini, basi itakuwa ni Istihaadhwah (damu ya ugonjwa), ambayo siyo kizuizi kwa Swalaah, wala kufunga Swawm, wala kufanya tendo la ndoa. Kila amri kuhusu damu na uzazi ni sawa na ile ya damu ya hedhi</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3194, 460, 1, '116.عَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {إِنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ كَانَتْ تُسْتَحَاضُ، فَقَالَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم  \"إِنَّ دَمَ اَلْحَيْضِ دَمٌ أَسْوَدُ يُعْرَفُ، فَإِذَا كَانَ ذَلِكَ فَأَمْسِكِي مِنَ اَلصَّلَاةِ، فَإِذَا كَانَ اَلْآخَرُ فَتَوَضَّئِي، وَصَلِّي\"}', '<p><strong>116.</strong></p><p><strong>عَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {إِنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ كَانَتْ تُسْتَحَاضُ، فَقَالَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم  \"إِنَّ دَمَ اَلْحَيْضِ دَمٌ أَسْوَدُ يُعْرَفُ، فَإِذَا كَانَ ذَلِكَ فَأَمْسِكِي مِنَ اَلصَّلَاةِ، فَإِذَا كَانَ اَلْآخَرُ فَتَوَضَّئِي، وَصَلِّي\"}</strong></p>', 'arabic', 'rtl', 1, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3195, 460, 2, 'رَوَاهُ أَبُو دَاوُدَ، وَالنَّسَائِيُّ، وَصَحَّحَهُ اِبْنُ حِبَّانَ، وَالْحَاكِمُ، وَاسْتَنْكَرَهُ أَبُو حَاتِمٍ', '<p><strong>رَوَاهُ أَبُو دَاوُدَ، وَالنَّسَائِيُّ، وَصَحَّحَهُ اِبْنُ حِبَّانَ، وَالْحَاكِمُ، وَاسْتَنْكَرَهُ أَبُو حَاتِمٍ</strong></p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3196, 460, 3, 'وَفِي حَدِيثِ أَسْمَاءَ بِنْتِ عُمَيْسٍ عِنْدَ أَبِي دَاوُدَ: {لِتَجْلِسْ فِي مِرْكَنٍ، فَإِذَا رَأَتْ صُفْرَةً فَوْقَ اَلْمَاءِ، فَلْتَغْتَسِلْ لِلظُّهْرِ وَالْعَصْرِ غُسْلاً وَاحِدًا، وَتَغْتَسِلْ لِلْمَغْرِبِ وَالْعِشَاءِ غُسْلاً وَاحِدًا، وَتَغْتَسِلْ لِلْفَجْرِ غُسْلاً، وَتَتَوَضَّأْ فِيمَا بَيْنَ ذَلِكَ }', '<p><strong>وَفِي حَدِيثِ أَسْمَاءَ بِنْتِ عُمَيْسٍ </strong>عِنْدَ أَبِي دَاوُدَ<strong>: {لِتَجْلِسْ فِي مِرْكَنٍ، فَإِذَا رَأَتْ صُفْرَةً فَوْقَ اَلْمَاءِ، فَلْتَغْتَسِلْ لِلظُّهْرِ وَالْعَصْرِ غُسْلاً وَاحِدًا، وَتَغْتَسِلْ لِلْمَغْرِبِ وَالْعِشَاءِ غُسْلاً وَاحِدًا، وَتَغْتَسِلْ لِلْفَجْرِ غُسْلاً، وَتَتَوَضَّأْ فِيمَا بَيْنَ ذَلِكَ }</strong></p>', 'arabic', 'rtl', 3, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3197, 460, 4, 'Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema: Fatwmah bint Abiy Hubaysh alikuwa na hedhi ya kudumu[1], Rasulu wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akasema: “Damu ya hedhi ni nyeusi inatambulika, kwa hivyo ikiwa ndiyo hiyo, jizuie kuswali, na ikiwa ni nyingine (iliyopauka), basi tawadha na uswali.”', '<p><strong>Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema: Fatwmah bint Abiy Hubaysh alikuwa na hedhi ya kudumu</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn1\"><strong>[1]</strong></a><strong>, Rasulu wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akasema: “Damu ya hedhi ni nyeusi inatambulika, kwa hivyo ikiwa ndiyo hiyo, jizuie kuswali, na ikiwa ni nyingine (iliyopauka), basi tawadha na uswali.”</strong></p>', 'swahili', 'ltr', 4, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3198, 460, 5, '[Imetolewa na Abuu Daawuwd na An-Nasaaiy, wakaisahihisha Ibn Hibbaan na Al Haakim, na akaiita Munkar (si ya kawaida) Abuu Haatim]', '<p><strong>[Imetolewa na Abuu Daawuwd na An-Nasaaiy, wakaisahihisha Ibn Hibbaan na Al Haakim, na akaiita Munkar (si ya kawaida) Abuu Haatim]</strong></p>', 'swahili', 'ltr', 5, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3199, 460, 6, 'Na katika Hadiyth ya Asmaa bint ‘Umays[2] (رَضِيَ اللَّهُ عَنْهَا) iliyopokewa na Abuu Daawuwd, amesema Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ): “(Mwanamke) Akae ndani ya bafu lenye maji, na akiona rangi ya njano hivi juu ya maji, basi afanye ghuslu moja kwa Swalaah ya Adhuhuri na Alasiri na afanye ghuslu moja tena kwa Swalaah ya Magharibi na ‘Ishaa, na afanye ghuslu kwa Swalaah ya Alfajiri, na baina ya nyakati hizi atawadhe.”', '<p><strong>Na katika Hadiyth ya Asmaa bint ‘Umays</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn2\"><strong>[2]</strong></a><strong> (رَضِيَ اللَّهُ عَنْهَا)</strong> iliyopokewa na Abuu Daawuwd, <strong>amesema Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ): “(Mwanamke) Akae ndani ya bafu lenye maji, na akiona rangi ya njano hivi juu ya maji, basi afanye ghuslu moja kwa Swalaah ya Adhuhuri na Alasiri na afanye ghuslu moja tena kwa Swalaah ya Magharibi na ‘Ishaa, na afanye ghuslu kwa Swalaah ya Alfajiri, na baina ya nyakati hizi atawadhe.”</strong></p>', 'swahili', 'ltr', 6, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3200, 460, 7, '117.وَعَنْ حَمْنَةَ بِنْتِ جَحْشٍ قَالَتْ: {كُنْتُ أُسْتَحَاضُ حَيْضَةً كَبِيرَةً شَدِيدَةً، فَأَتَيْتُ اَلنَّبِيَّ  صلى الله عليه وسلم أَسْتَفْتِيهِ، فَقَالَ: \"إِنَّمَا هِيَ رَكْضَةٌ مِنَ اَلشَّيْطَانِ، فَتَحَيَّضِي سِتَّةَ أَيَّامٍ، أَوْ سَبْعَةً، ثُمَّ اِغْتَسِلِي، فَإِذَا اسْتَنْقَأْتِ فَصَلِّي أَرْبَعَةً وَعِشْرِينَ، أَوْ ثَلَاثَةً وَعِشْرِينَ، وَصُومِي وَصَلِّي، فَإِنَّ ذَلِكَ يُجْزِئُكَ، وَكَذَلِكَ فَافْعَلِي كَمَا تَحِيضُ اَلنِّسَاءُ، فَإِنْ قَوِيتِ عَلَى أَنْ تُؤَخِّرِي اَلظُّهْرَ وَتُعَجِّلِي اَلْعَصْرَ، ثُمَّ تَغْتَسِلِي حِينَ تَطْهُرِينَ وَتُصَلِّينَ اَلظُّهْرَ وَالْعَصْرِ جَمِيعًا، ثُمَّ تُؤَخِّرِينَ اَلْمَغْرِبَ وَتُعَجِّلِينَ اَلْعِشَاءِ، ثُمَّ تَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ اَلصَّلَاتَيْنِ، فَافْعَلِي.‏ وَتَغْتَسِلِينَ مَعَ اَلصُّبْحِ وَتُصَلِّينَ.‏ قَالَ: وَهُوَ أَعْجَبُ اَلْأَمْرَيْنِ إِلَيَّ}', '<p><strong>117.</strong></p><p><strong>وَعَنْ حَمْنَةَ بِنْتِ جَحْشٍ قَالَتْ: {كُنْتُ أُسْتَحَاضُ حَيْضَةً كَبِيرَةً شَدِيدَةً، فَأَتَيْتُ اَلنَّبِيَّ  صلى الله عليه وسلم أَسْتَفْتِيهِ، فَقَالَ: \"إِنَّمَا هِيَ رَكْضَةٌ مِنَ اَلشَّيْطَانِ، فَتَحَيَّضِي سِتَّةَ أَيَّامٍ، أَوْ سَبْعَةً، ثُمَّ اِغْتَسِلِي، فَإِذَا اسْتَنْقَأْتِ فَصَلِّي أَرْبَعَةً وَعِشْرِينَ، أَوْ ثَلَاثَةً وَعِشْرِينَ، وَصُومِي وَصَلِّي، فَإِنَّ ذَلِكَ يُجْزِئُكَ، وَكَذَلِكَ فَافْعَلِي كَمَا تَحِيضُ اَلنِّسَاءُ، فَإِنْ قَوِيتِ عَلَى أَنْ تُؤَخِّرِي اَلظُّهْرَ وَتُعَجِّلِي اَلْعَصْرَ، ثُمَّ تَغْتَسِلِي حِينَ تَطْهُرِينَ وَتُصَلِّينَ اَلظُّهْرَ وَالْعَصْرِ جَمِيعًا، ثُمَّ تُؤَخِّرِينَ اَلْمَغْرِبَ وَتُعَجِّلِينَ اَلْعِشَاءِ، ثُمَّ تَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ اَلصَّلَاتَيْنِ، فَافْعَلِي.‏ وَتَغْتَسِلِينَ مَعَ اَلصُّبْحِ وَتُصَلِّينَ.‏ قَالَ: وَهُوَ أَعْجَبُ اَلْأَمْرَيْنِ إِلَيَّ}</strong></p>', 'arabic', 'rtl', 7, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3201, 460, 8, 'رَوَاهُ اَلْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ اَلتِّرْمِذِيُّ، وَحَسَّنَهُ اَلْبُخَارِيُّ', '<p><strong>رَوَاهُ اَلْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ اَلتِّرْمِذِيُّ، وَحَسَّنَهُ اَلْبُخَارِيُّ</strong></p>', 'arabic', 'rtl', 8, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(3202, 460, 9, 'Kutoka kwa Hamnah bint Jahsh[3] (رَضِيَ اللَّهُ عَنْهَا) amesema: Nilikuwa na hedhi yangu ilikuwa nyingi mno na kali, kwa hivyo nilikwenda kwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kumtaka fatwa, akasema: “Hii ni athari ya shaytwaan, kwa hivyo wewe zingatia hedhi yako kwa siku sita au saba, kisha fanya ghuslu na ukitwaharika, swali kwa siku ishirini na tatu au ishirini na nne, na ufunge na uswali, kwani hiyo itakutosheleza wewe, na ufanye hivyo hivyo kila mwezi kama wanavyopata hedhi wanawake wengine.  Lakini ukiwa na nguvu[4] unaweza kuakhirisha Swalaah ya Adhuhuri na kutanguliza Alasiri, kisha fanya ghuslu na uswali Adhuhuri na Alasiri pamoja kisha akhirisha Magharibi na kutanguliza ‘Ishaa, fanya hivyo, na ufanye ghuslu na ukusanye baina ya Swalaah mbili, fanya hivyo na fanya ghuslu asubuhi na uswali Alfajiri.” Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Mimi hii ninaipendelea zaidi, (yaani kufanya ghuslu kwa kila Swalaah).”', '<p><strong>Kutoka kwa Hamnah bint Jahsh</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn3\"><strong>[3]</strong></a><strong> (رَضِيَ اللَّهُ عَنْهَا) amesema: Nilikuwa na hedhi yangu ilikuwa nyingi mno na kali, kwa hivyo nilikwenda kwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kumtaka fatwa, akasema: “Hii ni athari ya shaytwaan, kwa hivyo wewe zingatia hedhi yako kwa siku sita au saba, kisha fanya ghuslu na ukitwaharika, swali kwa siku ishirini na tatu au ishirini na nne, na ufunge na uswali, kwani hiyo itakutosheleza wewe, na ufanye hivyo hivyo kila mwezi kama wanavyopata hedhi wanawake wengine.  Lakini ukiwa na nguvu</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn4\"><strong>[4]</strong></a><strong> unaweza kuakhirisha Swalaah ya Adhuhuri na kutanguliza Alasiri, kisha fanya ghuslu na uswali Adhuhuri na Alasiri pamoja kisha akhirisha Magharibi na kutanguliza ‘Ishaa, fanya hivyo, na ufanye ghuslu na ukusanye baina ya Swalaah mbili, fanya hivyo na fanya ghuslu asubuhi na uswali Alfajiri.” Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Mimi hii ninaipendelea zaidi, (yaani kufanya ghuslu kwa kila Swalaah).”</strong></p>', 'swahili', 'ltr', 9, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3203, 460, 10, '[Imetolewa na Al Khamsah (Maimaam watano wa Hadiyth) ila An-Nasaaiy. Na akaisahihisha At-Tirmidhiy, na akaipa daraja la Hasan, Al-Bukhaariy]', '<p><strong>[Imetolewa na Al Khamsah (Maimaam watano wa Hadiyth) ila An-Nasaaiy. Na akaisahihisha At-Tirmidhiy, na akaipa daraja la Hasan, Al-Bukhaariy]</strong></p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3204, 460, 11, '118.وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا; {أَنَّ أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ شَكَتْ إِلَى رَسُولِ اَللَّهِ  صلى الله عليه وسلم اَلدَّمَ، فَقَالَ: \"اُمْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اِغْتَسِلِي\" فَكَانَتْ تَغْتَسِلُ كُلَّ صَلَاةٍ}', '<p><strong>118.</strong></p><p><strong>وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا; {أَنَّ أُمَّ حَبِيبَةَ بِنْتَ جَحْشٍ شَكَتْ إِلَى رَسُولِ اَللَّهِ  صلى الله عليه وسلم اَلدَّمَ، فَقَالَ: \"اُمْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اِغْتَسِلِي\" فَكَانَتْ تَغْتَسِلُ كُلَّ صَلَاةٍ}</strong></p>', 'arabic', 'rtl', 11, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3205, 460, 12, 'رَوَاهُ مُسْلِمٌوَفِي رِوَايَةٍ لِلْبُخَارِيِّ: {وَتَوَضَّئِي لِكُلِّ صَلَاةٍ} وَهِيَ لِأَبِي دَاوُدَ وَغَيْرِهِ مِنْ وَجْهٍ آخَرَ.', '<p><strong>رَوَاهُ مُسْلِمٌ</strong><br><br><strong>وَفِي رِوَايَةٍ لِلْبُخَارِيِّ: </strong>{وَتَوَضَّئِي لِكُلِّ صَلَاةٍ}<strong> وَهِيَ لِأَبِي دَاوُدَ وَغَيْرِهِ مِنْ وَجْهٍ آخَرَ.</strong></p>', 'arabic', 'rtl', 12, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3206, 460, 13, 'Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema kuwa Ummu Habiybah bint Jahsh[5] alimshtakia Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) damu (iliyokuwa ikitoka zaidi ya kipindi cha hedhi); akasema: “Kaa kadiri ilivyokuwa hedhi yako inakuzuia kuswali, kisha fanya ghuslu.” Akawa anafanya ghuslu kila Swalaah[6].', '<p><strong>Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema kuwa Ummu Habiybah bint Jahsh</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn5\"><strong>[5]</strong></a><strong> alimshtakia Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) damu (iliyokuwa ikitoka zaidi ya kipindi cha hedhi); akasema: “Kaa kadiri ilivyokuwa hedhi yako inakuzuia kuswali, kisha fanya ghuslu.” Akawa anafanya ghuslu kila Swalaah</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn6\"><strong>[6]</strong></a><strong>.</strong></p>', 'swahili', 'ltr', 13, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3207, 460, 14, '[Imetolewa na Muslim]Na katika Riwaayah ya Al-Bukhaariy: “Tawadha kwa kila Swalaah.” [Pia ameipokea na Abuu Daawuwd na wengine kwa namna nyingine.]', '<p><strong> [Imetolewa na Muslim]</strong><br><br><strong>Na katika Riwaayah ya Al-Bukhaariy: “Tawadha kwa kila Swalaah.” [Pia ameipokea na Abuu Daawuwd na wengine kwa namna nyingine.]</strong></p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3208, 460, 15, '119.وَعَنْ أُمِّ عَطِيَّةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كُنَّا لَا نَعُدُّ اَلْكُدْرَةَ وَالصُّفْرَةَ بَعْدَ اَلطُّهْرِ شَيْئًا}', '<p><strong>119.</strong></p><p><strong>وَعَنْ أُمِّ عَطِيَّةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كُنَّا لَا نَعُدُّ اَلْكُدْرَةَ وَالصُّفْرَةَ بَعْدَ اَلطُّهْرِ شَيْئًا}</strong></p>', 'arabic', 'rtl', 15, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3209, 460, 16, 'رَوَاهُ اَلْبُخَارِيُّ، وَأَبُو دَاوُدَ وَاللَّفْظُ لَهُ', '<p><strong>رَوَاهُ اَلْبُخَارِيُّ، وَأَبُو دَاوُدَ وَاللَّفْظُ لَهُ</strong></p>', 'arabic', 'rtl', 16, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3210, 460, 17, 'Kutoka kwa Ummu ‘Aatwiyyah[7] (رَضِيَ اللَّهُ عَنْهَا) amesema: “Hatukuwa tukihesabu unjano na ukahawia kuwa ni chochote (majimaji yanayotokea ukeni[8]) baada ya Twahaarah.”', '<p><strong>Kutoka kwa Ummu ‘Aatwiyyah</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn7\"><strong>[7]</strong></a><strong> (رَضِيَ اللَّهُ عَنْهَا) amesema: “Hatukuwa tukihesabu unjano na ukahawia kuwa ni chochote (majimaji yanayotokea ukeni</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn8\"><strong>[8]</strong></a><strong>) baada ya Twahaarah.”</strong></p>', 'swahili', 'ltr', 17, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3211, 460, 18, '[Imetolewa na Al-Bukhaariy na Abuu Daawuwd, na tamshi hili ni lake]', '<p><strong>[Imetolewa na Al-Bukhaariy na Abuu Daawuwd, na tamshi hili ni lake]</strong></p>', 'swahili', 'ltr', 18, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3212, 460, 19, '120.وَعَنْ أَنَسٍ  رضى الله عنه  {أَنَّ اَلْيَهُودَ كَانُوا إِذَا حَاضَتْ اَلْمَرْأَةُ لَمْ يُؤَاكِلُوهَا، فَقَالَ اَلنَّبِيُّ  صلى الله عليه وسلم  \"اِصْنَعُوا كُلَّ شَيْءٍ إِلَّا اَلنِّكَاحَ\"}', '<p><strong>120.</strong></p><p><strong>وَعَنْ أَنَسٍ  رضى الله عنه  {أَنَّ اَلْيَهُودَ كَانُوا إِذَا حَاضَتْ اَلْمَرْأَةُ لَمْ يُؤَاكِلُوهَا، فَقَالَ اَلنَّبِيُّ  صلى الله عليه وسلم  \"اِصْنَعُوا كُلَّ شَيْءٍ إِلَّا اَلنِّكَاحَ\"}</strong></p>', 'arabic', 'rtl', 19, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3213, 460, 20, 'رَوَاهُ مُسْلِمٌ', '<p><strong>رَوَاهُ مُسْلِمٌ</strong></p>', 'arabic', 'rtl', 20, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3214, 460, 21, 'Kutoka kwa Anas (رَضِيَ اللهُ عَنْهُ) amesema kuwa Mayahudi walikuwa hawali na mwanamke wakati ana hedhi, kwa hivyo Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akasema: “Fanyeni kila kitu (na wake zenu) isipokuwa kujamiiana.”', '<p><strong>Kutoka kwa Anas (رَضِيَ اللهُ عَنْهُ) amesema kuwa Mayahudi walikuwa hawali na mwanamke wakati ana hedhi, kwa hivyo Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akasema: “Fanyeni kila kitu (na wake zenu) isipokuwa kujamiiana.”</strong></p>', 'swahili', 'ltr', 21, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3215, 460, 22, '[Imetolewa na Muslim]', '<p><strong>[Imetolewa na Muslim]</strong></p>', 'swahili', 'ltr', 22, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3216, 460, 23, '121.وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كَانَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم يَأْمُرُنِي فَأَتَّزِرُ، فَيُبَاشِرُنِي وَأَنَا حَائِضٌ}', '<p><strong>121.</strong></p><p><strong>وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كَانَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم يَأْمُرُنِي فَأَتَّزِرُ، فَيُبَاشِرُنِي وَأَنَا حَائِضٌ}</strong></p>', 'arabic', 'rtl', 23, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3217, 460, 24, 'مُتَّفَقٌ عَلَيْهِ', '<p><strong>مُتَّفَقٌ عَلَيْهِ</strong></p>', 'arabic', 'rtl', 24, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3218, 460, 25, 'Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema: “Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alikuwa akiniamrisha kuvaa Izaar[9] (gagulo) kisha ananipapasa kwa mahaba[10] wakati nina hedhi.”', '<p><strong>Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema: “Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alikuwa akiniamrisha kuvaa Izaar</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn9\"><strong>[9]</strong></a><strong> (gagulo) kisha ananipapasa kwa mahaba</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn10\"><strong>[10]</strong></a><strong> wakati nina hedhi.”</strong></p>', 'swahili', 'ltr', 25, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3219, 460, 26, '[Al-Bukhaariy, Muslim]', '<p><strong>[Al-Bukhaariy, Muslim]</strong></p>', 'swahili', 'ltr', 26, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3220, 460, 27, '122.وَعَنِ اِبْنِ عَبَّاسٍ رَضِيَ اَللَّهُ عَنْهُمَا، عَنِ اَلنَّبِيِّ  صلى الله عليه وسلم فِي اَلَّذِي يَأْتِي اِمْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ: {يَتَصَدَّقُ بِدِينَارٍ، أَوْ نِصْفِ دِينَارٍ}', '<p><strong>122.</strong></p><p><strong>وَعَنِ اِبْنِ عَبَّاسٍ رَضِيَ اَللَّهُ عَنْهُمَا، عَنِ اَلنَّبِيِّ  صلى الله عليه وسلم فِي اَلَّذِي يَأْتِي اِمْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ: {يَتَصَدَّقُ بِدِينَارٍ، أَوْ نِصْفِ دِينَارٍ}</strong></p>', 'arabic', 'rtl', 27, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3221, 460, 28, 'رَوَاهُ اَلْخَمْسَةُ، وَصَحَّحَهُ اَلْحَاكِمُ وَابْنُ اَلْقَطَّانِ، وَرَجَّحَ غَيْرَهُمَا وَقْفَهُ', '<p><strong>رَوَاهُ اَلْخَمْسَةُ، وَصَحَّحَهُ اَلْحَاكِمُ وَابْنُ اَلْقَطَّانِ، وَرَجَّحَ غَيْرَهُمَا وَقْفَهُ</strong></p>', 'arabic', 'rtl', 28, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3222, 460, 29, 'Kutoka kwa Ibn ‘Abbaas (رَضِيَ اللهُ عَنْهُمَا) amesema kuwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu mume anayejamiiana na mkewe akiwa na hedhi: “Atoe dinari moja au nusu dinari kama Swadaqah.”', '<p><strong>Kutoka kwa Ibn ‘Abbaas (رَضِيَ اللهُ عَنْهُمَا) amesema kuwa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema kuhusu mume anayejamiiana na mkewe akiwa na hedhi: “Atoe dinari moja au nusu dinari kama Swadaqah.”</strong></p>', 'swahili', 'ltr', 29, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3223, 460, 30, '[Imetolewa na Al-Khamsah (watano). Wakaisahihisha Al-Haakim na Ibn Al-Qatwaan, na wengine waliita kuwa Mawquwf[11]]', '<p><strong>[Imetolewa na Al-Khamsah (watano). Wakaisahihisha Al-Haakim na Ibn Al-Qatwaan, na wengine waliita kuwa Mawquwf</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn11\"><strong>[11]</strong></a><strong>]</strong></p>', 'swahili', 'ltr', 30, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3224, 460, 31, '123.وَعَنْ أَبِي سَعِيدٍ  رضى الله عنه  قَالَ: قَالَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم {أَلَيْسَ إِذَا حَاضَتْ لَمْ تُصَلِّ وَلَمْ تَصُمْ؟}', '<p><strong>123.</strong></p><p><strong>وَعَنْ أَبِي سَعِيدٍ  رضى الله عنه  قَالَ: قَالَ رَسُولُ اَللَّهِ  صلى الله عليه وسلم {أَلَيْسَ إِذَا حَاضَتْ لَمْ تُصَلِّ وَلَمْ تَصُمْ؟}</strong></p>', 'arabic', 'rtl', 31, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3225, 460, 32, 'مُتَّفَقٌ عَلَيْهِ فِي حَدِيثٍ', '<p><strong>مُتَّفَقٌ عَلَيْهِ فِي حَدِيثٍ</strong></p>', 'arabic', 'rtl', 32, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3226, 460, 33, 'Kutoka kwa Abuu Sa’iyd (رَضِيَ اللهُ عَنْهُ) amesema Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Je si kweli kuwa mwanamke aliye katika hedhi haswali wala hafungi[12]?”', '<p><strong>Kutoka kwa Abuu Sa’iyd (رَضِيَ اللهُ عَنْهُ) amesema Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) amesema: “Je si kweli kuwa mwanamke aliye katika hedhi haswali wala hafungi</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn12\"><strong>[12]</strong></a><strong>?”</strong></p>', 'swahili', 'ltr', 33, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3227, 460, 34, '[Al-Bukhaariy, Muslim na ni sehemu ya Hadiyth ndefu]', '<p><strong>[Al-Bukhaariy, Muslim na ni sehemu ya Hadiyth ndefu]</strong></p>', 'swahili', 'ltr', 34, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3228, 460, 35, 'وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {لَمَّا جِئْنَا سَرِفَ حِضْتُ، فَقَالَ اَلنَّبِيُّ  صلى الله عليه وسلم  \"اِفْعَلِي مَا يَفْعَلُ اَلْحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي\"}', '<p><strong>وَعَنْ عَائِشَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {لَمَّا جِئْنَا سَرِفَ حِضْتُ، فَقَالَ اَلنَّبِيُّ  صلى الله عليه وسلم  \"اِفْعَلِي مَا يَفْعَلُ اَلْحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي\"}</strong></p>', 'arabic', 'rtl', 35, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3229, 460, 36, 'مُتَّفَقٌ عَلَيْهِ فِي حَدِيثٍ', '<p><strong>مُتَّفَقٌ عَلَيْهِ فِي حَدِيثٍ</strong></p>', 'arabic', 'rtl', 36, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3230, 460, 37, 'Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema Tulipofika mahali paitwapo Sarif, mimi nilipata hedhi, Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akaniambia: “Wewe fanya analolifanya Haji isipokuwa usifanya twawaaf (kutufu Ka’bah) mpaka ukishatwahirika.”', '<p><strong>Kutoka kwa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) amesema Tulipofika mahali paitwapo Sarif, mimi nilipata hedhi, Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) akaniambia: “Wewe fanya analolifanya Haji isipokuwa usifanya twawaaf (kutufu Ka’bah) mpaka ukishatwahirika.” </strong></p>', 'swahili', 'ltr', 37, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3231, 460, 38, '” [Al-Bukhaariy, Muslim, na ni sehemu ya Hadiyth ndefu]', '<p><strong>” [Al-Bukhaariy, Muslim, na ni sehemu ya Hadiyth ndefu]</strong></p>', 'swahili', 'ltr', 38, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3232, 460, 39, 'وَعَنْ مُعَاذٍ  رضى الله عنه  {أَنَّهُ سَأَلَ اَلنَّبِيَّ  صلى الله عليه وسلم مَا يَحِلُّ لِلرَّجُلِ مِنِ اِمْرَأَتِهِ، وَهِيَ حَائِضٌ؟ قَالَ: \"مَا فَوْقَ اَلْإِزَارِ\"}', '<p><strong>وَعَنْ مُعَاذٍ  رضى الله عنه  {أَنَّهُ سَأَلَ اَلنَّبِيَّ  صلى الله عليه وسلم مَا يَحِلُّ لِلرَّجُلِ مِنِ اِمْرَأَتِهِ، وَهِيَ حَائِضٌ؟ قَالَ: \"مَا فَوْقَ اَلْإِزَارِ\"}</strong></p>', 'arabic', 'rtl', 39, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3233, 460, 40, 'رَوَاهُ أَبُو دَاوُدَ وَضَعَّفَهُ', '<p><strong>رَوَاهُ أَبُو دَاوُدَ وَضَعَّفَهُ</strong></p>', 'arabic', 'rtl', 40, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3234, 460, 41, 'Kutoka kwa Mu’aadh (رَضِيَ اللهُ عَنْهُ) alimuuliza Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kitu gani halali kwa mwanamume kwa mkewe wakati ana hedhi? Akasema: “Kilicho juu ya Izaar[13].”', '<p><strong>Kutoka kwa Mu’aadh (رَضِيَ اللهُ عَنْهُ) alimuuliza Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) kitu gani halali kwa mwanamume kwa mkewe wakati ana hedhi? Akasema: “Kilicho juu ya Izaar</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn13\"><strong>[13]</strong></a><strong>.”</strong></p>', 'swahili', 'ltr', 41, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3235, 460, 42, '[Imetolewa na Abuu Daawuwd na akaidhoofisha]', '<p><strong>[Imetolewa na Abuu Daawuwd na akaidhoofisha]</strong></p>', 'swahili', 'ltr', 42, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3236, 460, 43, '126.وَعَنْ أُمِّ سَلَمَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كَانَتِ اَلنُّفَسَاءُ تَقْعُدُ فِي عَهْدِ رَسُولِ اَللَّهِ  صلى الله عليه وسلم بَعْدَ نِفَاسِهَا أَرْبَعِينَ}', '<p><strong>126.</strong></p><p><strong>وَعَنْ أُمِّ سَلَمَةَ رَضِيَ اَللَّهُ عَنْهَا قَالَتْ: {كَانَتِ اَلنُّفَسَاءُ تَقْعُدُ فِي عَهْدِ رَسُولِ اَللَّهِ  صلى الله عليه وسلم بَعْدَ نِفَاسِهَا أَرْبَعِينَ}</strong></p>', 'arabic', 'rtl', 43, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3237, 460, 44, 'رَوَاهُ اَلْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَاللَّفْظُ لِأَبِي دَاوُدَوَفِي لَفْظٍ لَهُ:', '<p><strong>رَوَاهُ اَلْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَاللَّفْظُ لِأَبِي دَاوُدَ</strong></p><p><strong>وَفِي لَفْظٍ لَهُ:</strong></p>', 'arabic', 'rtl', 44, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3238, 460, 45, '{وَلَمْ يَأْمُرْهَا اَلنَّبِيُّ  صلى الله عليه وسلم بِقَضَاءِ صَلَاةِ اَلنِّفَاسِ}وَصَحَّحَهُ اَلْحَاكِمُ', '<p><strong>{وَلَمْ يَأْمُرْهَا اَلنَّبِيُّ  صلى الله عليه وسلم بِقَضَاءِ صَلَاةِ اَلنِّفَاسِ}</strong></p><p>وَصَحَّحَهُ اَلْحَاكِمُ</p>', 'arabic', 'rtl', 45, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3239, 460, 46, 'Kutoka kwa Ummu Salamah (رَضِيَ اللَّهُ عَنْهَا) amesema: “Wanawake wenye nifaas zama za Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) walikuwa wakikaa (bila kuswali) kwa siku arubaini[14].”', '<p><strong>Kutoka kwa Ummu Salamah (رَضِيَ اللَّهُ عَنْهَا) amesema: “Wanawake wenye nifaas zama za Rasuli wa Allaah (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) walikuwa wakikaa (bila kuswali) kwa siku arubaini</strong><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftn14\"><strong>[14]</strong></a><strong>.”</strong></p>', 'swahili', 'ltr', 46, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3240, 460, 47, '[Imetolewa na Al Khamsah isipokuwa An-Nisaaiy, na tamshi hili ni la Abuu Daawuwd] Na katika Riwaayah nyengine ya Abuu Daawuwd anasema:', '<p>[Imetolewa na Al Khamsah isipokuwa An-Nisaaiy, na tamshi hili ni la Abuu Daawuwd]</p><p> </p><p>Na katika Riwaayah nyengine ya Abuu Daawuwd anasema:<br> </p>', 'swahili', 'ltr', 47, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3241, 460, 48, '“Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) hakumuamrisha (mzazi) alipe Swalaah alizoacha wakati wa nifaas yake.” [Aliisahihisha Al Haakim]', '<p><strong>“Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) hakumuamrisha (mzazi) alipe Swalaah alizoacha wakati wa nifaas yake.” </strong>[Aliisahihisha Al Haakim]</p>', 'swahili', 'ltr', 48, '#c97b7b', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3242, 462, 1, '[1] Istihaadhwah (damu imtokayo mwanamke ukeni) ni damu inayodumu muda mrefu na inaweza kuwa ni damu ya uzazi au ya hedhi, na huhesabika kuwa ni kutokwa na damu kati kati ya vipindi. Kipindi cha hedhi, kwa mujibu wa ‘Ulamaa ni kutoka siku moja mpaka siku kumi na tano; na kwa mujibu wa wengine ni kutoka siku tatu mpaka siku kumi. Uzoefu unaonyesha kuwa huo usemi wa pili ni sahihi zaidi. Kila mwanamke huwa anafahamu vipindi vyake, na akitokwa damu zaidi ya wakati wake, basi hiyo ni Istihaadhwah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref1\"><strong>[1]</strong></a> Istihaadhwah (damu imtokayo mwanamke ukeni) ni damu inayodumu muda mrefu na inaweza kuwa ni damu ya uzazi au ya hedhi, na huhesabika kuwa ni kutokwa na damu kati kati ya vipindi. Kipindi cha hedhi, kwa mujibu wa ‘Ulamaa ni kutoka siku moja mpaka siku kumi na tano; na kwa mujibu wa wengine ni kutoka siku tatu mpaka siku kumi. Uzoefu unaonyesha kuwa huo usemi wa pili ni sahihi zaidi. Kila mwanamke huwa anafahamu vipindi vyake, na akitokwa damu zaidi ya wakati wake, basi hiyo ni Istihaadhwah.</p>', 'swahili', 'ltr', 1, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3243, 462, 2, '[2] Asmaa alikuwa mke wa Ja’far bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ). Alihajiri pamoja naye hadi Habashah (Abyssinia   Ethiopia), na alimzalia watoto watatu, na kati ya hao ni ‘Abdullaah. Baada ya Ja’far (رَضِيَ اللهُ عَنْهُ) kufa Shahidi katika vita vya Mut’a, Abuu Bakar Swiddiyq (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia mtoto mmoja Muhammad. Na baada ya kufariki Abuu Bakar (رَضِيَ اللهُ عَنْهُ), ‘Aliy bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia Yahyaa. ‘Umar (رَضِيَ اللهُ عَنْهُ) alizowea kumuuliza Asmaa tafsiri ya ndoto. Alikufa baada ya kifo cha ‘Aliy (رَضِيَ اللهُ عَنْهُ).', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref2\"><strong>[2]</strong></a> Asmaa alikuwa mke wa Ja’far bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ). Alihajiri pamoja naye hadi Habashah (Abyssinia   Ethiopia), na alimzalia watoto watatu, na kati ya hao ni ‘Abdullaah. Baada ya Ja’far (رَضِيَ اللهُ عَنْهُ) kufa Shahidi katika vita vya Mut’a, Abuu Bakar Swiddiyq (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia mtoto mmoja Muhammad. Na baada ya kufariki Abuu Bakar (رَضِيَ اللهُ عَنْهُ), ‘Aliy bin Abiy Twaalib (رَضِيَ اللهُ عَنْهُ) alimuoa Asmaa ambaye alimzalia Yahyaa. ‘Umar (رَضِيَ اللهُ عَنْهُ) alizowea kumuuliza Asmaa tafsiri ya ndoto. Alikufa baada ya kifo cha ‘Aliy (رَضِيَ اللهُ عَنْهُ).</p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3244, 462, 3, '[3] Hamnah bint Jahsh ni dada wa “Mama wa Waumini”, Zaynab bint Jahsh. Alioelewa na Musw’ab bin ‘Umayr ambaye alikufa Shahidi katika  vita vya Uhud, na baada ya hivyo akaolewa na Twalhah bin ‘Ubaydillaah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref3\"><strong>[3]</strong></a> Hamnah bint Jahsh ni dada wa “Mama wa Waumini”, Zaynab bint Jahsh. Alioelewa na Musw’ab bin ‘Umayr ambaye alikufa Shahidi katika  vita vya Uhud, na baada ya hivyo akaolewa na Twalhah bin ‘Ubaydillaah.</p>', 'swahili', 'ltr', 3, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3245, 462, 4, '[4] Katika Hadiyth hii Hamnah aliamriwa kuoga mara tatu kila siku. Aoge mara moja kwa ajili ya Swalaah za Adhuhuri na Alasiri, na aoge mara ya pili kwa Swalaah za Magharibi na ‘Ishaa, na aoge mara ya tatu kwa Swalaah ya Alfajiri. Katika Hadiyth iliyopita, Faatwimah binti Abiy Hubaysh aliamuriwa achukue wudhuu tu kabla ya kila Swalaah. Hii inamaanisha kuwa, kwa mwanamke anayekuwa na Istihaadhwah kuoga siyo lazima, lakini kuchukuwa wudhuu ni lazima kwa kila Swalaah. Kuoga ni bora ikiwa hali ya afya na ya hewa itaruhusu, vinginevyo hakuna haja ya kuoga.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref4\"><strong>[4]</strong></a> Katika Hadiyth hii Hamnah aliamriwa kuoga mara tatu kila siku. Aoge mara moja kwa ajili ya Swalaah za Adhuhuri na Alasiri, na aoge mara ya pili kwa Swalaah za Magharibi na ‘Ishaa, na aoge mara ya tatu kwa Swalaah ya Alfajiri. Katika Hadiyth iliyopita, Faatwimah binti Abiy Hubaysh aliamuriwa achukue wudhuu tu kabla ya kila Swalaah. Hii inamaanisha kuwa, kwa mwanamke anayekuwa na Istihaadhwah kuoga siyo lazima, lakini kuchukuwa wudhuu ni lazima kwa kila Swalaah. Kuoga ni bora ikiwa hali ya afya na ya hewa itaruhusu, vinginevyo hakuna haja ya kuoga.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3246, 462, 5, '[5] Habiybah bint Jahsh alikuwa dada mwingine wa “Mama wa Waumini” Zaynab bint Jahsh, naye aliolewa na ‘Abdur-Rahmaan bin ‘Awf. Mulsim alisimulia kuwa alikuwa na damu iliyodumu miaka saba. Alifariki mnamo mwaka wa 44 A.H.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref5\"><strong>[5]</strong></a> Habiybah bint Jahsh alikuwa dada mwingine wa “Mama wa Waumini” Zaynab bint Jahsh, naye aliolewa na ‘Abdur-Rahmaan bin ‘Awf. Mulsim alisimulia kuwa alikuwa na damu iliyodumu miaka saba. Alifariki mnamo mwaka wa 44 A.H.</p>', 'swahili', 'ltr', 5, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3247, 462, 6, '[6] Ilikuwa ni hatua ya hiari na ya tahadhari tu kwa Umm Habiybah kuoga kwa kila Swalaah. Uamuzi sahihi kuhusu kadhia hii ni kuoga baada ya hedhi na atawadhe. Kuhusu kutokwa damu kwa muda mrefu mno, ipo amri ya kuosha damu na kuchukua wudhuu katika kila Swalaah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref6\"><strong>[6]</strong></a> Ilikuwa ni hatua ya hiari na ya tahadhari tu kwa Umm Habiybah kuoga kwa kila Swalaah. Uamuzi sahihi kuhusu kadhia hii ni kuoga baada ya hedhi na atawadhe. Kuhusu kutokwa damu kwa muda mrefu mno, ipo amri ya kuosha damu na kuchukua wudhuu katika kila Swalaah.</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3248, 462, 7, '[7] Ummu ‘Atwiyyah ni jina la Nusaybah Ka’b bint Al-Haarith Al-Ansariyya. Alikuwa ni miongoni mwa Swahaba wa kike maarufu, na alikuwa akiongozana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) vitani akiwauguza wagonjwa na kuwatibu majeruhi. Alipigana katika Vita vya Uhud kama shujaa. Alishuhudia kuoshwa kwa maiti ya binti wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) ambako alieleza na alitusimulia, na Swahaba, Taabi’, ‘Ulamaa wa Basra walirikodi kutoka kwake. Hadiyth yake inahesabika kuwa ndiyo msingi wa kuosha maiti. Alikuwa mmoja wa Swahaba wa kike waliolowea kule Basra.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref7\"><strong>[7]</strong></a> Ummu ‘Atwiyyah ni jina la Nusaybah Ka’b bint Al-Haarith Al-Ansariyya. Alikuwa ni miongoni mwa Swahaba wa kike maarufu, na alikuwa akiongozana na Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) vitani akiwauguza wagonjwa na kuwatibu majeruhi. Alipigana katika Vita vya Uhud kama shujaa. Alishuhudia kuoshwa kwa maiti ya binti wa Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) ambako alieleza na alitusimulia, na Swahaba, Taabi’, ‘Ulamaa wa Basra walirikodi kutoka kwake. Hadiyth yake inahesabika kuwa ndiyo msingi wa kuosha maiti. Alikuwa mmoja wa Swahaba wa kike waliolowea kule Basra.</p>', 'swahili', 'ltr', 7, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3249, 462, 8, '[8] Katika usimulizi wa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) majimaji ya rangi ya njano au na vumbi yanahesabika kuwa ni damu ya hedhi, lakini Hadiyth hii inasema: “Tuliyahesabu kuwa siyo kitu.” Hadiyth hizi mbili zaelekea kujipinga, lakini zote mbili ni sahihi katika muktadha wa kila moja. Ikiwa majimaji ya rangi ya njano au ya vumbi yatajitokeza wakati wa kipindi cha hedhi, yatahesabika kuwa ni “damu ya hedhi.” Lakini yakijitokeza baada ya kipindi cha hedhi basi si chochote kama maneno ya Kiarabu ya بَعْدَ اَلطُّهْرِ yanavyodokeza.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref8\"><strong>[8]</strong></a> Katika usimulizi wa ‘Aaishah (رَضِيَ اللَّهُ عَنْهَا) majimaji ya rangi ya njano au na vumbi yanahesabika kuwa ni damu ya hedhi, lakini Hadiyth hii inasema: “Tuliyahesabu kuwa siyo kitu.” Hadiyth hizi mbili zaelekea kujipinga, lakini zote mbili ni sahihi katika muktadha wa kila moja. Ikiwa majimaji ya rangi ya njano au ya vumbi yatajitokeza wakati wa kipindi cha hedhi, yatahesabika kuwa ni “damu ya hedhi.” Lakini yakijitokeza baada ya kipindi cha hedhi basi si chochote kama maneno ya Kiarabu ya بَعْدَ اَلطُّهْرِ yanavyodokeza.</p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3250, 462, 9, '[9] Vazi linalovaliwa kutoka kiunoni kuenda chini kama gagulo au sketi.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref9\"><strong>[9]</strong></a> Vazi linalovaliwa kutoka kiunoni kuenda chini kama gagulo au sketi.</p>', 'swahili', 'ltr', 9, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3251, 462, 10, '[10] Wale ambao hawazisadiki Hadiyth, yaani wakanushaji wa Sunnah, wanaleta utata na mashaka hapa, na wanawafanya watu wazishuku Hadiyth. Wanasema kuwa tendo la ndoa katika kipindi cha hedhi limekatazwa na Qur-aan lakini kwa mujibu wa Hadiyth hii Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alifanya wakati ule, kwa hiyo Hadiyth hiyo siyo sahihi. Maana ya maneno ya ‘Mubaasharat’ ni kugusa na kuukanda mwili kwa mwili, na kwa kifumbo maana yake ni kufanya tendo la ndoa. Katika Hadiyth imewekwa wazi kwamba tendo la ndoa limekatazwa wakati ya hedhi ya mwanamke. Kwa hivyo ni udanganyifu tu kutafsiri neno hilo ‘mubashaarat’ kuwa ni ‘tendo la ndoa’ badala ya kulitafsiri kuwa ni ‘kushikashika kwa mahaba’ na kuleta mashaka.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref10\"><strong>[10]</strong></a> Wale ambao hawazisadiki Hadiyth, yaani wakanushaji wa Sunnah, wanaleta utata na mashaka hapa, na wanawafanya watu wazishuku Hadiyth. Wanasema kuwa tendo la ndoa katika kipindi cha hedhi limekatazwa na Qur-aan lakini kwa mujibu wa Hadiyth hii Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) alifanya wakati ule, kwa hiyo Hadiyth hiyo siyo sahihi. Maana ya maneno ya ‘Mubaasharat’ ni kugusa na kuukanda mwili kwa mwili, na kwa kifumbo maana yake ni kufanya tendo la ndoa. Katika Hadiyth imewekwa wazi kwamba tendo la ndoa limekatazwa wakati ya hedhi ya mwanamke. Kwa hivyo ni udanganyifu tu kutafsiri neno hilo ‘mubashaarat’ kuwa ni ‘tendo la ndoa’ badala ya kulitafsiri kuwa ni ‘kushikashika kwa mahaba’ na kuleta mashaka.</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3252, 462, 11, '[11] Hii ni Hadiyth dhaifu, kwa hivyo wengi wa ‘Ulamaa hawadhani kuwa ni lazima kufidia, ingawa baadhi ya ‘Ulamaa hudhani inafaa kufidia, lakini rai ya kwanza ni sahihi kwa kuwa amri hiyo ni kwa kuhamasisha Swadaqah.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref11\"><strong>[11]</strong></a> Hii ni Hadiyth dhaifu, kwa hivyo wengi wa ‘Ulamaa hawadhani kuwa ni lazima kufidia, ingawa baadhi ya ‘Ulamaa hudhani inafaa kufidia, lakini rai ya kwanza ni sahihi kwa kuwa amri hiyo ni kwa kuhamasisha Swadaqah.</p>', 'swahili', 'ltr', 11, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3253, 462, 12, '[12] Hii ni sehemu ndogo tu ya Hadiyth ndefu. Alipokuwa akitoa khutbah kwa wanawake Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) aliwaambia kuwa dini yao haijakamilika. Walipouliza kwa namna gani, kwa kusema maneno yanayomaanisha kuwa wanawake walio na hedhi wasiswali wala wasifunge Swawm.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref12\"><strong>[12]</strong></a> Hii ni sehemu ndogo tu ya Hadiyth ndefu. Alipokuwa akitoa khutbah kwa wanawake Nabiy (صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمْ) aliwaambia kuwa dini yao haijakamilika. Walipouliza kwa namna gani, kwa kusema maneno yanayomaanisha kuwa wanawake walio na hedhi wasiswali wala wasifunge Swawm.</p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3254, 462, 13, '[13] Kila kilicho juu ya Izaar (Nguo inayovaliwa chini ya kiuno) inaweza kuwa na maana mbili: kwanza inaweza kuwa na maana ya jimai. Kwa maneno mengine, kila kitu kinaruhusiwa isipokuwa jimai. Pili: ina maana ya ile sehemu inayovaliwa Izaar. Ila maana hii inaweza kupingana na Hadiyth isemayo: “Fanyeni kila kitu isipokuwa jimai.” Kwa hivyo basi ni vizuri kutumia maana ya kwanza.', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref13\"><strong>[13]</strong></a> Kila kilicho juu ya Izaar (Nguo inayovaliwa chini ya kiuno) inaweza kuwa na maana mbili: kwanza inaweza kuwa na maana ya jimai. Kwa maneno mengine, kila kitu kinaruhusiwa isipokuwa jimai. Pili: ina maana ya ile sehemu inayovaliwa Izaar. Ila maana hii inaweza kupingana na Hadiyth isemayo: “Fanyeni kila kitu isipokuwa jimai.” Kwa hivyo basi ni vizuri kutumia maana ya kwanza.</p>', 'swahili', 'ltr', 13, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3255, 462, 14, '[14] Hii inamaanisha ni kile kiwango cha juu cha siku za damu ya uzazi, na hakuna kiwango chake cha chini. Laiti ikiendelea zaidi ya siku arubaini, basi itakuwa ni Istihaadhwah (damu ya ugonjwa), ambayo siyo kizuizi kwa Swalaah, wala kufunga Swawm, wala kufanya tendo la ndoa. Kila amri kuhusu damu na uzazi ni sawa na ile ya damu ya hedhi', '<p><a href=\"https://www.alhidaaya.com/sw/10-buluwgh-al-maraam-kitabu-cha-twahaarah-mlango-wa-hedhi#_ftnref14\"><strong>[14]</strong></a> Hii inamaanisha ni kile kiwango cha juu cha siku za damu ya uzazi, na hakuna kiwango chake cha chini. Laiti ikiendelea zaidi ya siku arubaini, basi itakuwa ni Istihaadhwah (damu ya ugonjwa), ambayo siyo kizuizi kwa Swalaah, wala kufunga Swawm, wala kufanya tendo la ndoa. Kila amri kuhusu damu na uzazi ni sawa na ile ya damu ya hedhi</p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-08-29 09:20:47', '2026-08-29 09:20:47', NULL, NULL, NULL, 0),
(3383, 467, 1, 'بابٌ مَعْرِفَةِ عَلَامَاتِ الْإِعَرَابِ', '<p><strong>              بابٌ مَعْرِفَةِ عَلَامَاتِ الْإِعَرَابِ</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3384, 467, 2, 'لِلرَّفْعِ أَرْبَعُ عَلَامَاتٍ : الضَّمَّة،ُ وَالْوَاو،ُ وَالْأَلِفُ ، وَالنُّونُ', '<p>لِلرَّفْعِ أَرْبَعُ عَلَامَاتٍ : الضَّمَّة،ُ وَالْوَاو،ُ وَالْأَلِفُ ، وَالنُّونُ </p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3385, 467, 3, 'فَأَمَّا الضَّمَّةُ فَتَكُونُ عَلَامَةً لِلرَّفْعِ فِي أَرْبَعَةِ مَوَاضِعَ في الإِسْمِ الْمُفْرَد،ِ وَجَمع التكسير، وَجَمع المُوَنَّثِ السالم ، وَالفِعْلِ الْمُضَارِعِ الَّذِي لَمْ يَتَّصِل باخره شيء', '<p><strong>فَأَمَّا الضَّمَّةُ </strong>فَتَكُونُ عَلَامَةً لِلرَّفْعِ فِي أَرْبَعَةِ مَوَاضِعَ في الإِسْمِ الْمُفْرَد،ِ وَجَمع التكسير، وَجَمع المُوَنَّثِ السالم ، وَالفِعْلِ الْمُضَارِعِ الَّذِي لَمْ يَتَّصِل باخره شيء </p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3386, 467, 4, 'وَأَمَّا الْوَاوُ فَتَكُونُ عَلَامَةً لِلرَّفْعِ فِي مَوْضِعَيْنِ: فِي جَمْعِ الْمُذَكَّرِ السَّالِمِ، وَفِي الْأَسْمَاءِ الْخَمْسَةِ، وَهِيَ: أَبُوكَ، وَأَخُوكَ، وَحَمُوكَ، وَفُوكَ، وَذُو مَالٍ.', '<p><strong>وَأَمَّا الْوَاوُ</strong> فَتَكُونُ عَلَامَةً لِلرَّفْعِ فِي مَوْضِعَيْنِ: فِي جَمْعِ الْمُذَكَّرِ السَّالِمِ، وَفِي الْأَسْمَاءِ الْخَمْسَةِ، وَهِيَ: أَبُوكَ، وَأَخُوكَ، وَحَمُوكَ، وَفُوكَ، وَذُو مَالٍ.</p>', 'arabic', 'rtl', 4, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3387, 467, 5, 'وأما الْأَلِفُ فَتَكُونُ عَلَامَةً لِلْرَّفُعِ في تَثْنِيَةِ الأَسْمَاءِ خَاصَّة', '<p><strong>وأما الْأَلِفُ</strong> فَتَكُونُ عَلَامَةً لِلْرَّفُعِ في تَثْنِيَةِ الأَسْمَاءِ خَاصَّة</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3388, 467, 6, 'وَأَما النُّونُ فَتَكُونُ عَلَامَةُ لِلْرَّفْعِ فِي الْفِعْلِ الْمُضَارِع ، إِذَا أَنْصَلَ بِهِ ضَمِيرُ تَثْنِية،ِ أَوْ ضَمِيرُ جَمع ، أو ضَمِيرُ المُ نْتَةِ الْمُخَاطِبَة', '<p><strong>وَأَما النُّونُ</strong> فَتَكُونُ عَلَامَةُ لِلْرَّفْعِ فِي الْفِعْلِ الْمُضَارِع ، إِذَا أَنْصَلَ بِهِ ضَمِيرُ تَثْنِية،ِ أَوْ ضَمِيرُ جَمع ، أو ضَمِيرُ المُ نْتَةِ الْمُخَاطِبَة</p>', 'arabic', 'rtl', 6, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3389, 468, 1, 'وَالنَّصْبِ خَمْسٌ عَلَامَاتِ : الفَتْحَة،ُ وَالْآلِفُ ، وَالْكَسْرَة،ُ وَالْيَاء،ُ وَحَذْفُ النون', '<p><strong>وَالنَّصْبِ</strong> خَمْسٌ عَلَامَاتِ : الفَتْحَة،ُ وَالْآلِفُ ، وَالْكَسْرَة،ُ وَالْيَاء،ُ وَحَذْفُ النون</p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3390, 468, 2, 'فَأَمَّا الْفَتْحَةُ فَتَكُونُ عَلَامَةً لِلنَّصْبِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الْإِسْمِ الْمُفْرَدِ، وَجَمْعِ التَّكْسِيرِ، وَالْفِعْلِ الْمُضَارِعِ إِذَا دَخَلَ عَلَيْهِ نَاصِبٌ وَلَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ', '<p><strong>فَأَمَّا الْفَتْحَةُ</strong> فَتَكُونُ عَلَامَةً لِلنَّصْبِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الْإِسْمِ الْمُفْرَدِ، وَجَمْعِ التَّكْسِيرِ، وَالْفِعْلِ الْمُضَارِعِ إِذَا دَخَلَ عَلَيْهِ نَاصِبٌ وَلَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ</p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3391, 468, 3, 'وَأَمَّا الْأَلِفُ فَتَكُونُ عَلَامَةً لِلنَّصْبِ فِي الْأَسْمَاءِ الْخَمْسَةِ، نَحْوَ رَأَيْتُ أَبَاكَ وَأَخَاكَ وَمَا أَشْبَهَ ذَلِكَ.', '<p><strong>وَأَمَّا الْأَلِفُ</strong> فَتَكُونُ عَلَامَةً لِلنَّصْبِ فِي الْأَسْمَاءِ الْخَمْسَةِ، نَحْوَ رَأَيْتُ أَبَاكَ وَأَخَاكَ وَمَا أَشْبَهَ ذَلِكَ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3392, 468, 4, 'وَأَمَّا الْكَسْرَةُ فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي جَمْعِ الْمُؤَنَّثِ السَّالِمِ.', '<p><strong>وَأَمَّا الْكَسْرَةُ</strong> فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي جَمْعِ الْمُؤَنَّثِ السَّالِمِ.</p>', 'arabic', 'rtl', 4, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3393, 468, 5, 'وَأَمَّا الْيَاءُ فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي التَّثْنِيَةِ وَالْجَمْعِ.', '<p><strong>وَأَمَّا الْيَاءُ</strong> فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي التَّثْنِيَةِ وَالْجَمْعِ.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3394, 468, 6, 'وَأَمَّا حَذْفُ النُّونِ فَيَكُونُ عَلَامَةً لِلنَّصْبِ فِي الْأَفْعَالِ الْخَمْسَةِ الَّتِي رَفْعُهَا بِثَبَاتِ النُّونِ.', '<p><strong>وَأَمَّا حَذْفُ</strong> النُّونِ فَيَكُونُ عَلَامَةً لِلنَّصْبِ فِي الْأَفْعَالِ الْخَمْسَةِ الَّتِي رَفْعُهَا بِثَبَاتِ النُّونِ.</p>', 'arabic', 'rtl', 6, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3395, 469, 1, 'وَلِلْخَفْضِ ثَلَاثُ عَلَامَاتٍ.الكَسْرَةُ، وَالْيَاءُ، وَالْفَتْحَةُ.', '<p><strong>وَلِلْخَفْضِ ثَلَاثُ عَلَامَاتٍ</strong>.الكَسْرَةُ، وَالْيَاءُ، وَالْفَتْحَةُ.</p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3396, 469, 2, 'فَأَمَّا الْكَسْرَةُ فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الِاسْمِ الْمُفْرَدِ الْمُنْصَرِفِ، وَجَمْعِ التَّكْسِيرِ الْمُنْصَرِفِ، وَفِي جَمْعِ الْمُؤَنَّثِ السَّالِمِ.', '<p><strong>فَأَمَّا الْكَسْرَةُ</strong> فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الِاسْمِ الْمُفْرَدِ الْمُنْصَرِفِ، وَجَمْعِ التَّكْسِيرِ الْمُنْصَرِفِ، وَفِي جَمْعِ الْمُؤَنَّثِ السَّالِمِ.</p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3397, 469, 3, 'وَأَما اليَاءُ : فَتَكُونُ عَلَامَةٌ لِلْخَفْضَ فِي ثَلَاثَةِ مَوَاضِعَ فِي الْأَسْمَاءِ الخَمْسَة،ِ وَفِي الثنية، والجمع', '<p>وَأَما اليَاءُ : فَتَكُونُ عَلَامَةٌ لِلْخَفْضَ فِي ثَلَاثَةِ مَوَاضِعَ فِي الْأَسْمَاءِ الخَمْسَة،ِ وَفِي الثنية، والجمع</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3398, 469, 4, 'وَأَمَّا الْيَاءُ فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الْأَسْمَاءِ الْخَمْسَةِ، وَفِي التَّثْنِيَةِ، وَفِي الْجَمْعِ.', '<p><strong>وَأَمَّا الْيَاءُ</strong> فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي ثَلَاثَةِ مَوَاضِعَ: فِي الْأَسْمَاءِ الْخَمْسَةِ، وَفِي التَّثْنِيَةِ، وَفِي الْجَمْعِ.</p>', 'arabic', 'rtl', 4, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3399, 469, 5, 'وَأَمَّا الْفَتْحَةُ فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي الِاسْمِ الَّذِي لَا يَنْصَرِفُ', '<p><strong>وَأَمَّا الْفَتْحَةُ</strong> فَتَكُونُ عَلَامَةً لِلْخَفْضِ فِي الِاسْمِ الَّذِي لَا يَنْصَرِفُ</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3400, 470, 1, 'وَلِلْجَزْمِ عَلَامَتَانِ: السُّكُونُ، وَالْحَذْفُ.', '<p><strong>وَلِلْجَزْمِ</strong> عَلَامَتَانِ: السُّكُونُ، وَالْحَذْفُ.</p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3401, 470, 2, 'فَأَمَّا السُّكُونُ فَيَكُونُ عَلَامَةً لِلْجَزْمِ فِي الْفِعْلِ الْمُضَارِعِ الصَّحِيحِ الْآخِرِ.', '<p><strong>فَأَمَّا السُّكُونُ</strong> فَيَكُونُ عَلَامَةً لِلْجَزْمِ فِي الْفِعْلِ الْمُضَارِعِ الصَّحِيحِ الْآخِرِ.</p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3402, 470, 3, 'وَأَمَّا الْحَذْفُ فَيَكُونُ عَلَامَةً لِلْجَزْمِ فِي الْفِعْلِ الْمُضَارِعِ الْمُعْتَلِّ الْآخِرِ، وَفِي الْأَفْعَالِ الْخَمْسَةِ الَّتِي رَفْعُهَا بِثَبَاتِ النُّونِ.', '<p><strong>وَأَمَّا الْحَذْفُ </strong>فَيَكُونُ عَلَامَةً لِلْجَزْمِ فِي الْفِعْلِ الْمُضَارِعِ الْمُعْتَلِّ الْآخِرِ، وَفِي الْأَفْعَالِ الْخَمْسَةِ الَّتِي رَفْعُهَا بِثَبَاتِ النُّونِ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3403, 471, 1, 'فصل : المعربات', '<p><strong>                  فصل : المعربات</strong></p>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3404, 471, 2, 'الْمُعْرَبَاتُ قِسْمَانِ: قِسْمٌ يُعْرَبُ بِالْحَرَكَاتِ، وَقِسْمٌ يُعْرَبُ بِالْحُرُوفِ.', '<p><strong>الْمُعْرَبَاتُ قِسْمَانِ</strong>: قِسْمٌ يُعْرَبُ بِالْحَرَكَاتِ، وَقِسْمٌ يُعْرَبُ بِالْحُرُوفِ.</p>', 'arabic', 'rtl', 2, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3405, 471, 3, 'فَالَّذِي يُعْرَبُ بِالْحَرَكَاتِ أَرْبَعَةُ أَنْوَاعٍ: الْإِسْمُ الْمُفْرَدُ، وَجَمْعُ التَّكْسِيرِ، وَجَمْعُ الْمُؤَنَّثِ السَّالِمُ، وَالْفِعْلُ الْمُضَارِعُ الَّذِي لَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ.', '<p><strong>فَالَّذِي يُعْرَبُ بِالْحَرَكَاتِ أَرْبَعَةُ أَنْوَاعٍ</strong>: الْإِسْمُ الْمُفْرَدُ، وَجَمْعُ التَّكْسِيرِ، وَجَمْعُ الْمُؤَنَّثِ السَّالِمُ، وَالْفِعْلُ الْمُضَارِعُ الَّذِي لَمْ يَتَّصِلْ بِآخِرِهِ شَيْءٌ.</p>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3406, 471, 4, 'وَكُلُّهَا تُرْفَعُ بِالضَّمَّةِ، وَتُنْصَبُ بِالْفَتْحَةِ، وَتُخْفَضُ بِالْكَسْرَةِ، وَتُجْزَمُ بِالسُّكُونِ.', '<p>وَكُلُّهَا تُرْفَعُ بِالضَّمَّةِ، وَتُنْصَبُ بِالْفَتْحَةِ، وَتُخْفَضُ بِالْكَسْرَةِ، وَتُجْزَمُ بِالسُّكُونِ.</p>', 'arabic', 'rtl', 4, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3407, 471, 5, 'وَخَرَجَ عَنْ ذَلِكَ ثَلَاثَةُ أَشْيَاءَ: جَمْعُ الْمُؤَنَّثِ السَّالِمُ يُنْصَبُ بِالْكَسْرَةِ، وَالِاسْمُ الَّذِي لَا يَنْصَرِفُ يُخْفَضُ بِالْفَتْحَةِ، وَالْفِعْلُ الْمُضَارِعُ الْمُعْتَلُّ الْآخِرِ يُجْزَمُ بِحَذْفِ آخِرِهِ.', '<p><strong>وَخَرَجَ عَنْ ذَلِكَ ثَلَاثَةُ أَشْيَاءَ:</strong> جَمْعُ الْمُؤَنَّثِ السَّالِمُ يُنْصَبُ بِالْكَسْرَةِ، وَالِاسْمُ الَّذِي لَا يَنْصَرِفُ يُخْفَضُ بِالْفَتْحَةِ، وَالْفِعْلُ الْمُضَارِعُ الْمُعْتَلُّ الْآخِرِ يُجْزَمُ بِحَذْفِ آخِرِهِ.</p>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3408, 471, 6, 'وَالَّذِي يُعْرَبُ بِالْحُرُوفِ أَرْبَعَةُ أَنْوَاعٍ: التَّثْنِيَةُ، وَجَمْعُ الْمُذَكَّرِ السَّالِمُ، وَالْأَسْمَاءُ الْخَمْسَةُ، وَالْأَفْعَالُ الْخَمْسَةُ، وَهِيَ: يَفْعَلَانِ، وَتَفْعَلَانِ، وَيَفْعَلُونَ، وَتَفْعَلُونَ، وَتَفْعَلِينَ.', '<p><strong>وَالَّذِي يُعْرَبُ بِالْحُرُوفِ أَرْبَعَةُ أَنْوَاعٍ</strong>: التَّثْنِيَةُ، وَجَمْعُ الْمُذَكَّرِ السَّالِمُ، وَالْأَسْمَاءُ الْخَمْسَةُ، وَالْأَفْعَالُ الْخَمْسَةُ، وَهِيَ: يَفْعَلَانِ، وَتَفْعَلَانِ، وَيَفْعَلُونَ، وَتَفْعَلُونَ، وَتَفْعَلِينَ.</p>', 'arabic', 'rtl', 6, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3409, 471, 7, 'فَأَمَّا التَّثْنِيَةُ فَتَرْفَعُ بِالْأَلِفِ، وَتُنْصَبُ وَتُخْفَضُ بِالْيَاءِ.', '<p>فَأَمَّا التَّثْنِيَةُ فَتَرْفَعُ بِالْأَلِفِ، وَتُنْصَبُ وَتُخْفَضُ بِالْيَاءِ.</p>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3410, 471, 8, 'وَأَمَّا جَمْعُ الْمُذَكَّرِ السَّالِمُ فَيُرْفَعُ بِالْوَاوِ، وَيُنْصَبُ وَيُخْفَضُ بِالْيَاءِ.', '<p><strong>وَأَمَّا جَمْعُ الْمُذَكَّرِ السَّالِمُ</strong> فَيُرْفَعُ بِالْوَاوِ، وَيُنْصَبُ وَيُخْفَضُ بِالْيَاءِ.</p>', 'arabic', 'rtl', 8, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3411, 471, 9, 'وَأَمَّا الْأَسْمَاءُ الْخَمْسَةُ فَتَرْفَعُ بِالْوَاوِ، وَتُنْصَبُ بِالْأَلِفِ، وَتُخْفَضُ بِالْيَاءِ.', '<p><strong>وَأَمَّا الْأَسْمَاءُ الْخَمْسَةُ</strong> فَتَرْفَعُ بِالْوَاوِ، وَتُنْصَبُ بِالْأَلِفِ، وَتُخْفَضُ بِالْيَاءِ.</p>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3412, 471, 10, 'وَأَمَّا الْأَفْعَالُ الْخَمْسَةُ فَتُرْفَعُ بِالنُّونِ، وَتُنْصَبُ وَتُجْزَمُ بِحَذْفِهَا.', '<p><strong>وَأَمَّا الْأَفْعَالُ الْخَمْسَةُ</strong> فَتُرْفَعُ بِالنُّونِ، وَتُنْصَبُ وَتُجْزَمُ بِحَذْفِهَا.</p>', 'arabic', 'rtl', 10, '#1f2937', '#ffffff', '2026-09-06 09:14:22', '2026-09-06 09:14:22', NULL, NULL, NULL, 0),
(3438, 484, 1, 'الْقَاعِدَةُ الثَّانِيَةُ:', '<h3><strong>                                 الْقَاعِدَةُ الثَّانِيَةُ:</strong></h3>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3439, 484, 2, 'Kanuni Ya Pili:', '<p><strong>                         Kanuni Ya Pili:</strong></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3440, 484, 3, 'أُنَّهُمْ يَقُولُونَ: مَا دَعَوْنَاهُمْ وَتَوَجَّهْنَا إِلَيْهِمْ إِلا لِطَلَبِ الْقُرْبَةِ وَالشَّفَاعَةِ.', '<h3>أُنَّهُمْ يَقُولُونَ: مَا دَعَوْنَاهُمْ وَتَوَجَّهْنَا إِلَيْهِمْ إِلا لِطَلَبِ الْقُرْبَةِ وَالشَّفَاعَةِ.</h3>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3441, 484, 4, 'Kwamba wao (washirikina) wamesema: “Hatukuwaabudu wala kuelekea kwao isipokuwa tu kuomba kukurubia na shafaa’ah (uombezi wa Allaah).', '<p>Kwamba wao (washirikina) wamesema: “Hatukuwaabudu wala kuelekea kwao isipokuwa tu kuomba kukurubia na shafaa’ah (uombezi wa Allaah).</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3442, 484, 5, 'فَدَلِيلُ الْقُرْبَةِ؛ قَوْلُهُ تَعَالَى:', '<h3>فَدَلِيلُ الْقُرْبَةِ؛ قَوْلُهُ تَعَالَى:</h3>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3443, 484, 6, 'Na dalili ya kutafuta ukaribu ni kauli Yake Ta’aalaa:', '<p>Na dalili ya kutafuta ukaribu ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3444, 484, 7, 'وَالَّذِينَ اتَّخَذُوا مِن دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّـهِ زُلْفَىٰ إِنَّ اللَّـهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ اللَّـهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ ﴿٣﴾', '<h3> <strong>وَالَّذِينَ اتَّخَذُوا مِن دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّـهِ زُلْفَىٰ إِنَّ اللَّـهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ اللَّـهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ ﴿٣﴾</strong></h3>', 'arabic', 'rtl', 7, '#b99137', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(3445, 484, 8, '((Na wale waliojichukulia badala Yake walinzi (wakisema): “Hatuwaabudu isipokuwa ili wapate kutukurubisha kwa Allaah tumkaribie” Hakika Allaah Atahukumu baina yao katika yale waliyokhitilafiana nayo. Hakika Allaah Hamwongoi aliye muongo, kafiri)) [Az- Zumar (39: 3)]', '<p>((Na wale waliojichukulia badala Yake walinzi (wakisema): “Hatuwaabudu isipokuwa ili wapate kutukurubisha kwa Allaah tumkaribie” Hakika Allaah Atahukumu baina yao katika yale waliyokhitilafiana nayo. Hakika Allaah Hamwongoi aliye muongo, kafiri))<strong> </strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn5\"><strong>[Az- Zumar (39: 3)]</strong></a></p>', 'arabic', 'rtl', 8, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3446, 484, 9, 'وَدَلِيلُ الشَّفَاعَةِ، قَوْلُهُ تَعَالَى:', '<h3>وَدَلِيلُ الشَّفَاعَةِ، قَوْلُهُ تَعَالَى:</h3>', 'arabic', 'rtl', 9, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3447, 484, 10, 'Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3448, 484, 11, 'وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ', '<h3> <strong>وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ</strong></h3>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3449, 484, 12, '((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))[Yuwnus (10: 18)]', '<p>((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn6\">[Yuwnus (10: 18)]</a></p>', 'swahili', 'ltr', 12, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3450, 484, 13, 'وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.', '<h3>وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.</h3>', 'arabic', 'rtl', 13, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3451, 484, 14, 'Na ash-shafaa’ah (uombezi) ni aina mbili:i.                    Shafaa’ah iliyokatazwa (iliyoharamishwa katika Qur-aan na Sunnah)[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)] ii.                  Shafaa’ah iliyothibitishwa (inayokubalika katika Qur-aan na Sunnah)[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]', '<p>Na ash-shafaa’ah (uombezi) ni aina mbili:</p><p>i.                    <strong>Shafaa’ah iliyokatazwa</strong> (iliyoharamishwa katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn7\">[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)]</a> </p><p>ii.                 <strong> Shafaa’ah iliyothibitishwa</strong> (inayokubalika katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn8\">[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]</a></p>', 'swahili', 'ltr', 14, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3452, 484, 15, 'فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.', '<h3>فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.</h3>', 'arabic', 'rtl', 15, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3453, 484, 16, 'Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.', '<p>Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.</p>', 'swahili', 'ltr', 16, '#1f2937', '#ffffff', '2026-09-07 14:26:31', '2026-09-07 14:26:31', NULL, NULL, NULL, 0),
(3513, 486, 1, 'الْقَاعِدَةُ الرَّابِعَةُ:', '<h3><strong>                                الْقَاعِدَةُ الرَّابِعَةُ:</strong></h3>', 'arabic', 'rtl', 1, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3514, 486, 2, 'Kanuni Ya Nne:', '<p><strong>                         Kanuni Ya Nne:</strong></p>', 'swahili', 'ltr', 2, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3515, 486, 3, 'أَنَّ مُشْرِكِي زَمَانَنَا أَغْلَظُ شِرْكًا مِنَ الأَوَّلِينَ، لأَنَّ الأَوَّلِينَ يُشْرِكُونَ فِي الرَّخَاءِ، وَيُخْلِصُونَ فِي الشِّدَّةِ، وَمُشْرِكُو زَمَانَنَا شِرْكُهُمْ دَائِمٌ فِي الرَّخَاءِ وَالشِّدَة.', '<h3>أَنَّ مُشْرِكِي زَمَانَنَا أَغْلَظُ شِرْكًا مِنَ الأَوَّلِينَ، لأَنَّ الأَوَّلِينَ يُشْرِكُونَ فِي الرَّخَاءِ، وَيُخْلِصُونَ فِي الشِّدَّةِ، وَمُشْرِكُو زَمَانَنَا شِرْكُهُمْ دَائِمٌ فِي الرَّخَاءِ وَالشِّدَة.</h3>', 'arabic', 'rtl', 3, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3516, 486, 4, 'Kwamba washirikina wa zama zetu ni waovu zaidi katika shirki zao kuliko washirikina wa zamani kwa sababu, wa zamani walimshirikisha Allaah katika raha, lakini walitakasa (‘ibaadah zao) wakati wa shida. Ama washirikina wa sasa, shirki zao ni za kuendelea daima wakiwa katika raha au katika shida.', '<p>Kwamba washirikina wa zama zetu ni waovu zaidi katika shirki zao kuliko washirikina wa zamani kwa sababu, wa zamani walimshirikisha Allaah katika raha, lakini walitakasa (‘ibaadah zao) wakati wa shida. Ama washirikina wa sasa, shirki zao ni za kuendelea daima wakiwa katika raha au katika shida.</p>', 'swahili', 'ltr', 4, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3517, 486, 5, 'وَالدَّلِيلُ قَوْلُهُ تَعَالَى:', '<h3>وَالدَّلِيلُ قَوْلُهُ تَعَالَى:</h3>', 'arabic', 'rtl', 5, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3518, 486, 6, 'Na dalili ni kauli Yake Ta’aalaa:', '<p>Na dalili ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 6, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3519, 486, 7, 'فَإِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللَّـهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ إِذَا هُمْ يُشْرِكُونَ ﴿٦٥﴾', '<h3> <strong>فَإِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللَّـهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ إِذَا هُمْ يُشْرِكُونَ ﴿٦٥﴾</strong></h3>', 'arabic', 'rtl', 7, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3520, 486, 8, '((Wanapopanda merikebu humwomba Allaah wakiwa wenye kumtakasia Yeye Dini, lakini Anapowaokoa katika nchi kavu, tahamaki hao wanamshirikisha))[Al-‘Ankabuwt (29: 65)]', '<p><strong>((Wanapopanda merikebu humwomba Allaah wakiwa wenye kumtakasia Yeye Dini, lakini Anapowaokoa katika nchi kavu, tahamaki hao wanamshirikisha))</strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn17\"><strong>[Al-‘Ankabuwt (29: 65)]</strong></a></p>', 'swahili', 'ltr', 8, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3521, 486, 9, 'تمت وَصَلَّى اللهُ عَلَى مُحَمَّدٍ وعلى َآلِهِ وَصَحْبِهِ وَسَلَّمَ', '<h3><strong>تمت وَصَلَّى اللهُ عَلَى مُحَمَّدٍ وعلى َآلِهِ وَصَحْبِهِ وَسَلَّمَ</strong></h3>', 'arabic', 'rtl', 9, '#086304', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3522, 486, 10, 'Tammat Wa-Swalla Allaahu ‘alaa Muhammadin wa ‘alaa aalihi wa Swahbihi wa sallam.', '<p><strong>Tammat Wa-Swalla Allaahu ‘alaa Muhammadin wa ‘alaa aalihi</strong></p><p><strong> wa Swahbihi wa sallam.</strong></p>', 'swahili', 'ltr', 10, '#1f2937', '#ffffff', '2026-09-08 04:24:55', '2026-09-08 04:24:55', NULL, NULL, NULL, 0),
(3638, 408, 1, 'الْقَوَاعِدُ الأَرْبَع               للإمامِ مُحَمَّد بِن عَبْدِالوَهَّاب', '<p>                           الْقَوَاعِدُ الأَرْبَع<br>               للإمامِ مُحَمَّد بِن عَبْدِالوَهَّاب</p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3639, 408, 2, 'AL-QAWAAID AL-ARBA’                                (KANUNI NNE)    Imaam Muhammad Bin ‘Abdil-Wahhaab', '<p><strong>                      AL-QAWAAID AL-ARBA’</strong></p><p><strong>                                (KANUNI NNE)</strong><br>    <strong>Imaam Muhammad Bin ‘Abdil-Wahhaab</strong></p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3640, 408, 3, 'بِسْــــــمِ اللهِ الرَّحْمَٰنِ الرَّحِيـــــمِأَسْأَلُ اللهَ الْكَرِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَتَوَلاكَ فِي الدُّنْيَا وَالآخِرَةِ. وَأَنْ يَجْعَلَكَ مُبَارَكًا أَيْنَمَا كُنْتَ، وَأَنْ يَجْعَلَكَ مِمَّنْ إِذَا أُعْطِيَ شَكَرَ، وَإِذَا ابْتُلِيَ صَبَرَ، وَإِذَا أذَنبَ اسْتَغْفَرَ. فَإِنَّ هَؤُلاءِ الثَّلاثُ عُنْوَانُ السَّعَادَةِ.', '<p>                   بِسْــــــمِ اللهِ الرَّحْمَٰنِ الرَّحِيـــــمِ<br>أَسْأَلُ اللهَ الْكَرِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَتَوَلاكَ فِي الدُّنْيَا وَالآخِرَةِ. وَأَنْ يَجْعَلَكَ مُبَارَكًا أَيْنَمَا كُنْتَ، وَأَنْ يَجْعَلَكَ مِمَّنْ إِذَا أُعْطِيَ شَكَرَ، وَإِذَا ابْتُلِيَ صَبَرَ، وَإِذَا أذَنبَ اسْتَغْفَرَ. فَإِنَّ هَؤُلاءِ الثَّلاثُ عُنْوَانُ السَّعَادَةِ.</p>', 'arabic', 'rtl', 3, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3641, 408, 4, 'Kwa Jina la Allaah Ar-Rahmaan, Mwenye kurehemu.Namuomba Allaah Mkarimu, Rabb wa ‘Arshi Adhimu, Akuhifadhi duniani na Aakhirah, na Akujaalie mwenye baraka popote ulipo, na Akujaalie miongoni mwa wale; anapopewa hushukuru, na anapojaribiwa mitihani husubiri, na anapotenda dhambi huomba maghfirah, kwani mambo hayo matatu ni funguo za furaha.', '<p>Kwa Jina la Allaah Ar-Rahmaan, Mwenye kurehemu.</p><p>Namuomba Allaah Mkarimu, Rabb wa ‘Arshi Adhimu, Akuhifadhi duniani na Aakhirah, na Akujaalie mwenye baraka popote ulipo, na Akujaalie miongoni mwa wale; anapopewa hushukuru, na anapojaribiwa mitihani husubiri, na anapotenda dhambi huomba maghfirah, kwani mambo hayo matatu ni funguo za furaha.</p>', 'swahili', 'ltr', 4, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3642, 408, 5, 'إِعْلَمْ أَرْشَدَكَ اللهُ لِطَاعَتِهِ: أَنَّ الْحَنِيفِيَّةَ مِلَّةُ إِبْرَاهِيمَ: أَنْ تَعْبُدَ اللهَ، وَحْدَهُ مُخْلِصًا لَهُ الدِّينَ', '<p>إِعْلَمْ أَرْشَدَكَ اللهُ لِطَاعَتِهِ: أَنَّ الْحَنِيفِيَّةَ مِلَّةُ إِبْرَاهِيمَ: أَنْ تَعْبُدَ اللهَ، وَحْدَهُ مُخْلِصًا لَهُ الدِّينَ</p>', 'arabic', 'rtl', 5, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3643, 408, 6, 'Fahamu, Akuongoze Allaah katika utiifu Wake, kwamba Haniyfiyyah (Kuelemea katika Dini ya haki na kujiepusha na dini potofu) ni Dini ya Ibraahiym, umwabudu Allaah Pekee, ukiwa ni mwenye kumtakasia Dini Yake.', '<p>Fahamu, Akuongoze Allaah katika utiifu Wake, kwamba Haniyfiyyah (Kuelemea katika Dini ya haki na kujiepusha na dini potofu) ni Dini ya Ibraahiym, umwabudu Allaah Pekee, ukiwa ni mwenye kumtakasia Dini Yake.</p>', 'swahili', 'ltr', 6, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3644, 408, 7, 'كَمَا قَالَ تَعَالَى:', '<p>كَمَا قَالَ تَعَالَى:</p>', 'arabic', 'rtl', 7, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3645, 408, 8, 'kama Anavyosema Ta’aalaa:', '<p>kama Anavyosema Ta’aalaa:</p>', 'swahili', 'ltr', 8, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3646, 408, 9, 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾', '<p><strong>وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾</strong></p>', 'arabic', 'rtl', 9, '#b99137', '#ffffff', '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3647, 408, 10, '((Na Sikuumba majini na wanadamu isipokuwa waniabudu))[Adh-Dhaariyaat (51: 56)]', '<p><strong>((Na Sikuumba majini na wanadamu isipokuwa waniabudu))</strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn2\"><strong>[Adh-Dhaariyaat (51: 56)]</strong></a></p>', 'swahili', 'ltr', 10, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3648, 408, 11, 'فَإِذَا عَرَفْتَ أَنَّ اللهَ خَلَقَكَ لِعِبَادَتِهِ؛ فَاعْلَمْ أَنَّ الْعِبَادَةَ لا تُسَمَّى عِبَادَةً إِلا مَعَ التَّوْحِيدِ، كَمَا أَنَّ الصَّلاةَ لا تُسَمَّى صَلاةً إِلا مَعَ الطَّهَارَةِ.', '<p>فَإِذَا عَرَفْتَ أَنَّ اللهَ خَلَقَكَ لِعِبَادَتِهِ؛ فَاعْلَمْ أَنَّ الْعِبَادَةَ لا تُسَمَّى عِبَادَةً إِلا مَعَ التَّوْحِيدِ، كَمَا أَنَّ الصَّلاةَ لا تُسَمَّى صَلاةً إِلا مَعَ الطَّهَارَةِ.</p>', 'arabic', 'rtl', 11, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3649, 408, 12, 'Basi utakapojua kwamba Allaah Amekuumba kwa ajili ya kumwabudu Yeye, basi jua kwamba: ‘Ibaadah haiitwi ‘ibaadah isipokuwa pamoja na Tawhiyd (kumpwekesha Allaah), kama ambavyo Swalaah haiitwi Swalaah isipokuwa pamoja na twahaarah.', '<p>Basi utakapojua kwamba Allaah Amekuumba kwa ajili ya kumwabudu Yeye, basi jua kwamba: ‘Ibaadah haiitwi ‘ibaadah isipokuwa pamoja na Tawhiyd (kumpwekesha Allaah), kama ambavyo Swalaah haiitwi Swalaah isipokuwa pamoja na twahaarah.</p>', 'swahili', 'ltr', 12, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3650, 408, 13, 'فَإِذَا دَخَلَ الشِّرْكُ فِي الْعِبَادَةِ فَسَدَتْ، كَالْحَدَثِ إِذَا دَخَلَ فِي الطَّهَاَرِة.', '<p> فَإِذَا دَخَلَ الشِّرْكُ فِي الْعِبَادَةِ فَسَدَتْ، كَالْحَدَثِ إِذَا دَخَلَ فِي الطَّهَاَرِة.</p>', 'arabic', 'rtl', 13, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3651, 408, 14, 'Hivyo basi itakapoingia shirki katika ‘ibaadah inaharibika kama najsi inavyoingia katika twaaharah (inaitengua).', '<p>Hivyo basi itakapoingia shirki katika ‘ibaadah inaharibika kama najsi inavyoingia katika twaaharah (inaitengua).</p>', 'swahili', 'ltr', 14, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3652, 408, 15, 'فَإِذَا عَرَفْتَ أَنَّ الشِّرْكَ إِذَا خَالَطَ الْعِبَادَةِ أَفْسَدَهَا، وَأَحْبَطَ الْعَمَلَ، وَصَاَر صَاحِبُهُ، مِنَ الْخَالِدِينَ فِي النَّارِ عَرَفْتَ أَنَّ أَهَمَّ مَا عَلَيْكَ مَعْرِفَةُ ذَلِكَ لَعَلَّ اللهَ أَنْ يُخَلِّصَكَ مِنْ هَذِهِ الشَّبَكَةِ.', '<p> فَإِذَا عَرَفْتَ أَنَّ الشِّرْكَ إِذَا خَالَطَ الْعِبَادَةِ أَفْسَدَهَا، وَأَحْبَطَ الْعَمَلَ، وَصَاَر صَاحِبُهُ، مِنَ الْخَالِدِينَ فِي النَّارِ عَرَفْتَ أَنَّ أَهَمَّ مَا عَلَيْكَ مَعْرِفَةُ ذَلِكَ لَعَلَّ اللهَ أَنْ يُخَلِّصَكَ مِنْ هَذِهِ الشَّبَكَةِ.</p>', 'arabic', 'rtl', 15, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3653, 408, 16, 'Na utakapojua kwamba shirki inapochanganyika na ‘ibaadah inaiharibu na inaporomosha ‘amali, na mtendaji huwa ni miongoni mwa watakaodumu motoni, hapo utajua kwamba jambo muhimu kabisa kwako (la kuwajibika) ni utambuzi wa hilo, huenda Allaah Akuepushe katika utando wa utata huu.', '<p>Na utakapojua kwamba shirki inapochanganyika na ‘ibaadah inaiharibu na inaporomosha ‘amali, na mtendaji huwa ni miongoni mwa watakaodumu motoni, hapo utajua kwamba jambo muhimu kabisa kwako (la kuwajibika) ni utambuzi wa hilo, huenda Allaah Akuepushe katika utando wa utata huu.</p>', 'swahili', 'ltr', 16, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3654, 408, 17, 'وَهِيَ الشِّرْكُ بِاللهِ الَّذِي قَالَ الله تَعَالَى فِيهِ:', '<p>وَهِيَ الشِّرْكُ بِاللهِ الَّذِي قَالَ الله تَعَالَى فِيهِ:</p>', 'arabic', 'rtl', 17, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3655, 408, 18, 'Navyo ni kumshirikisha Allaah ambayo Allaah Ta’aalaa Anasema:', '<p>Navyo ni kumshirikisha Allaah ambayo Allaah Ta’aalaa Anasema:</p>', 'swahili', 'ltr', 18, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3656, 408, 19, 'إِنَّ اللَّـهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ ۚ وَمَن يُشْرِكْ بِاللَّـهِ فَقَدِ افْتَرَىٰ إِثْمًا عَظِيمًا﴿٤٨﴾', '<p><strong>إِنَّ اللَّـهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ ۚ وَمَن يُشْرِكْ بِاللَّـهِ فَقَدِ افْتَرَىٰ إِثْمًا عَظِيمًا﴿٤٨﴾</strong></p>', 'arabic', 'rtl', 19, '#b99137', '#ffffff', '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3657, 408, 20, '((Hakika Allaah Haghufuri kushirikishwa; lakini Anaghufuria yasiyokuwa hayo kwa Amtakae))[An-Nisaa (4: 48, 116)]', '<p><strong>((Hakika Allaah Haghufuri kushirikishwa; lakini Anaghufuria yasiyokuwa hayo kwa Amtakae))</strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn3\"><strong>[An-Nisaa (4: 48, 116)]</strong></a></p>', 'swahili', 'ltr', 20, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3658, 408, 21, 'وَذَلِكَ بِمَعْرِفَةِ أَرْبَعِ قَوَاعِدَ ذَكَرَهَا اللهُ تَعَالَى فِي كِتَابِهِ:', '<p>وَذَلِكَ بِمَعْرِفَةِ أَرْبَعِ قَوَاعِدَ ذَكَرَهَا اللهُ تَعَالَى فِي كِتَابِهِ:</p>', 'arabic', 'rtl', 21, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3659, 408, 22, 'Na (utambuzi) huo, ni kwa maarifa manne ya Kanuni Alizozitaja Allaah Ta’aalaa katika Kitabu Chake:', '<p>Na (utambuzi) huo, ni kwa maarifa manne ya Kanuni Alizozitaja Allaah Ta’aalaa katika Kitabu Chake:</p>', 'swahili', 'ltr', 22, NULL, NULL, '2026-09-09 18:50:00', '2026-09-09 18:50:00', NULL, NULL, NULL, 0),
(3660, 482, 1, 'الْقَاعِدَةُ الأُولَى:', '<h3><strong>                                 الْقَاعِدَةُ الأُولَى:</strong></h3>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-09 18:55:49', '2026-09-09 18:55:49', NULL, NULL, NULL, 0),
(3661, 482, 2, 'Kanuni Ya Kwanza:', '<p><strong>                               Kanuni Ya Kwanza:</strong></p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-09 18:55:49', '2026-09-09 18:55:49', NULL, NULL, NULL, 0),
(3662, 482, 3, 'أَنْ تَعْلَمَ أَنَّ الْكُفَّارَ الَّذِينَ قَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) مُقِرُّونَ بِأَنَّ اللهَ تَعَالَى هُوُ الْخَالِقُ، الْمُدَبِّرُ، وَأَنَّ ذَلِكَ لَمْ يُدْخِلَهُمْ فِي الإِسْلامِ.', '<h3>أَنْ تَعْلَمَ أَنَّ الْكُفَّارَ الَّذِينَ قَاتَلَهُمْ رَسُولُ اللهِ (صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ) مُقِرُّونَ بِأَنَّ اللهَ تَعَالَى هُوُ الْخَالِقُ، الْمُدَبِّرُ، وَأَنَّ ذَلِكَ لَمْ يُدْخِلَهُمْ فِي الإِسْلامِ.</h3>', 'arabic', 'rtl', 3, NULL, NULL, '2026-09-09 18:55:49', '2026-09-09 18:55:49', NULL, NULL, NULL, 0),
(3663, 482, 4, 'Ujue kwamba makafiri, ambao Rasuli wa Allaah (صلى الله عليه وآله وسلم) alipigana nao, walikiri kwamba Allaah Ta’aalaa ni Muumbaji na Mwendeshaji wa mambo yote. Lakini (kukiri) hivyo hakukuwaingiza katika Uislamu.', '<p>Ujue kwamba makafiri, ambao Rasuli wa Allaah (<strong>صلى الله عليه وآله وسلم</strong>) alipigana nao, walikiri kwamba Allaah Ta’aalaa ni Muumbaji na Mwendeshaji wa mambo yote. Lakini (kukiri) hivyo hakukuwaingiza katika Uislamu.</p>', 'swahili', 'ltr', 4, NULL, NULL, '2026-09-09 18:55:49', '2026-09-09 18:55:49', NULL, NULL, NULL, 0),
