(3693, 483, 10, 'Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:', '<p>Na dalili ya shafaa’ah (uombezi) ni kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 10, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3694, 483, 11, 'وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ', '<h3> <strong>وَيَعْبُدُونَ مِن دُونِ اللَّـهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّـهِ ۚ</strong></h3>', 'arabic', 'rtl', 11, '#b99137', '#ffffff', '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3695, 483, 12, '((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))[Yuwnus (10: 18)]', '<p>((Na wanaabudu pasi na Allaah ambavyo haviwadhuru wala haviwanufaishi na wanasema: “Hawa ni waombezi wetu mbele ya Allaah”))<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn6\">[Yuwnus (10: 18)]</a></p>', 'swahili', 'ltr', 12, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3696, 483, 13, 'وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.', '<h3>وَالشَّفَاعَةُ شَفَاعَتَانِ: شَفَاعَةٌ مَنْفِيَّةٌ، وَشَفَاعَةٌ مُثْبَتَةٌ.</h3>', 'arabic', 'rtl', 13, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3697, 483, 14, 'Na ash-shafaa’ah (uombezi) ni aina mbili:i.                    Shafaa’ah iliyokatazwa (iliyoharamishwa katika Qur-aan na Sunnah)[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)] ii.                  Shafaa’ah iliyothibitishwa (inayokubalika katika Qur-aan na Sunnah)[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]', '<p>Na ash-shafaa’ah (uombezi) ni aina mbili:</p><p>i.                    <strong>Shafaa’ah iliyokatazwa</strong> (iliyoharamishwa katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn7\">[Uombezi unaoombwa bila ya idhini ya Allaah (سبحانه وتعالى) nao ni wa washirikina (wanaomshirikisha Allaah (سبحانه وتعالى)]</a> </p><p>ii.                 <strong> Shafaa’ah iliyothibitishwa</strong> (inayokubalika katika Qur-aan na Sunnah)<a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn8\">[Uombezi unaoombwa baada ya idhini ya Allaah (سبحانه وتعالى) na ni watu wa Tawhiyd (wanaompwekesha Allaah سبحانه وتعالى)]</a></p>', 'swahili', 'ltr', 14, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3698, 483, 15, 'فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.', '<h3>فَالشَّفَاعَةُ الْمَنْفِيَّةُ: مَا كَانَتْ تُطْلَبُ مِنْ غَيْرِ اللهِ فِيمَا لا يَقْدِرُ عَلَيْهِ إِلا اللهُ.</h3>', 'arabic', 'rtl', 15, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
(3699, 483, 16, 'Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.', '<p>Basi Ash-Shafaa’ah iliyokatazwa ni kumwomba asiyekuwa Allaah jambo ambalo hakuna mwenye uwezo nalo isipokuwa Allaah.</p>', 'swahili', 'ltr', 16, NULL, NULL, '2026-09-09 18:58:06', '2026-09-09 18:58:06', NULL, NULL, NULL, 0),
