(3756, 485, 27, 'أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّىٰ ﴿١٩﴾ وَمَنَاةَ الثَّالِثَةَ الْأُخْرَىٰ ﴿٢٠﴾', '<h3><strong>أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّىٰ ﴿١٩﴾ وَمَنَاةَ الثَّالِثَةَ الْأُخْرَىٰ ﴿٢٠﴾</strong></h3>', 'arabic', 'rtl', 27, '#b99137', '#ffffff', '2026-09-09 19:04:10', '2026-09-09 19:04:10', NULL, NULL, NULL, 0),
(3757, 485, 28, '((Je, mmeona Laata na ‘Uzzaa?  Na Manaata mwengine wa tatu?))[An-Najm (53: 19-20)]', '<p><strong> ((Je, mmeona Laata na ‘Uzzaa?  Na Manaata mwengine wa tatu?))</strong><a href=\"https://www.alhidaaya.com/sw/al-qawaaid-al-arba-kanuni-nne-alqawaaidu-alaarba-word-doc-chapisho-la-5-kimehaririwa-1438h-2017m#_ftn16\"><strong>[An-Najm (53: 19-20)]</strong></a><strong> </strong></p>', 'swahili', 'ltr', 28, NULL, NULL, '2026-09-09 19:04:10', '2026-09-09 19:04:10', NULL, NULL, NULL, 0),
(3758, 485, 29, 'وَحَدِيُث أَبِي وَاقٍد اللَّيْثِيِّ (رضي الله عنه) قَالَ: خَرَجْنَا مَعَ النَّبِيِّ (صلى الله عليه وسلم) إِلَى حُنَيْنٍ وَنَحْنُ حُدَثَاءُ عَهْدٍ بِكُفْرٍ، وَلِلِمُشْرِكِينَ سِدْرَةٌ، يَعْكُفُونَ عِنْدَهَا وَيُنَوِّطُونَ بِهَا أَسْلِحَتَهُمْ، يُقَالَ لَهَا ذَاتُ أَنْوَاطٍ، فَمَرَرْنَا بِسِدْرَةٍ فَقُلْنَا: يَا رَسُولَ اللهِ اجْعَلْ لَنَا ذَاتَ أَنْوَاطٍ كَمَا لَهُمْ ذَاتُ أَنْوَاط ... الحَدِيثَ', '<h3>وَحَدِيُث أَبِي وَاقٍد اللَّيْثِيِّ (رضي الله عنه) قَالَ: خَرَجْنَا مَعَ النَّبِيِّ (صلى الله عليه وسلم) إِلَى حُنَيْنٍ وَنَحْنُ حُدَثَاءُ عَهْدٍ بِكُفْرٍ، وَلِلِمُشْرِكِينَ سِدْرَةٌ، يَعْكُفُونَ عِنْدَهَا وَيُنَوِّطُونَ بِهَا أَسْلِحَتَهُمْ، يُقَالَ لَهَا ذَاتُ أَنْوَاطٍ، فَمَرَرْنَا بِسِدْرَةٍ فَقُلْنَا: يَا رَسُولَ اللهِ اجْعَلْ لَنَا ذَاتَ أَنْوَاطٍ كَمَا لَهُمْ ذَاتُ أَنْوَاط ... الحَدِيثَ  </h3>', 'arabic', 'rtl', 29, '#255dad', '#ffffff', '2026-09-09 19:04:10', '2026-09-09 19:04:10', NULL, NULL, NULL, 0),
(3759, 485, 30, 'Na Hadiyth ya Abuu Waaqid Al-Laythiyy (رضي الله عنه) amesema: “Tulitoka pamoja na Nabiy (صلى الله عليه وآله وسلم) kwenda (vitani) Hunayn nasi ndio kwanza tumetoka katika ukafiri, na washirikina walikuwa na mkunazi wakijisabilia nao kufanya ‘ibaadah na walikuwa wakitundika silaha zao (kutafuta baraka). Wakiuita ‘Dhaatu-Anwaatw’. Tukapita mbele ya mkunazi tukasema: “Ee Rasuli wa Allaah! Tufanyie nasi Dhaatu-Anwaatw kama walivyokuwa nao (makafiri) Dhaatu-Anwaatw” …  Al-Hadiyth', '<p><strong>Na Hadiyth ya Abuu Waaqid Al-Laythiyy (رضي الله عنه) amesema: “Tulitoka pamoja na Nabiy (صلى الله عليه وآله وسلم) kwenda (vitani) Hunayn nasi ndio kwanza tumetoka katika ukafiri, na washirikina walikuwa na mkunazi wakijisabilia nao kufanya ‘ibaadah na walikuwa wakitundika silaha zao (kutafuta baraka). Wakiuita ‘Dhaatu-Anwaatw’. Tukapita mbele ya mkunazi tukasema: “Ee Rasuli wa Allaah! Tufanyie nasi Dhaatu-Anwaatw kama walivyokuwa nao (makafiri) Dhaatu-Anwaatw” …  Al-Hadiyth</strong></p>', 'swahili', 'ltr', 30, NULL, NULL, '2026-09-09 19:04:10', '2026-09-09 19:04:10', NULL, NULL, NULL, 0),
(3760, 463, 1, 'بسم الله الرحمن الرحيم                            أنواع الكلام', '<p>                  <strong> بسم الله الرحمن الرحيم</strong><br><strong>                            أنواع الكلام </strong></p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-09 20:01:12', '2026-09-09 20:01:12', NULL, NULL, NULL, 0),
(3761, 463, 2, 'الكلام: هُوَ اللَّفْظُ الْمُرَكَبُ الْمُفِيدُ بِالْوَضْعِ وَأَقْسَامُهُ ثَلَاثَةَ : اسْم، وَفِعْلٌ ، وَحَرْفُ جَاءَ لِمَعْنَى', '<p><strong>الكلام</strong>: هُوَ اللَّفْظُ الْمُرَكَبُ الْمُفِيدُ بِالْوَضْعِ<br> وَأَقْسَامُهُ ثَلَاثَةَ : <strong>اسْم</strong>، وَ<strong>فِعْلٌ</strong> ، وَ<strong>حَرْفُ جَاءَ لِمَعْنَى</strong></p>', 'arabic', 'rtl', 2, NULL, NULL, '2026-09-09 20:01:12', '2026-09-09 20:01:12', NULL, NULL, NULL, 0),
(3762, 463, 3, 'فالاسم يُعْرَفُ : بالخفض ، والتنوين، وَدُخُولِ الْأَلِفِ وَاللَّام ، وَحُرُوفِ الخَفْضِ ، وَهِيَ : مِنْ وَإِلَى، وَعَن،ْ وَعَلَى وَفِي ، وَرُبِّ ، وَالْبَاء،ُ وَالْكَافُ ، وَاللَّم،ُ وَحُرُوفُ الْقَسَمِ ، وَهِيَ : الْوَاو،ُ وَالْبَاء،ُ وَالنَّاء.ُ', '<p> <strong>فالاسم</strong> يُعْرَفُ : بالخفض ، والتنوين، وَدُخُولِ الْأَلِفِ وَاللَّام ، وَحُرُوفِ الخَفْضِ ، وَهِيَ : مِنْ وَإِلَى، وَعَن،ْ وَعَلَى وَفِي ، وَرُبِّ ، وَالْبَاء،ُ وَالْكَافُ ، وَاللَّم،ُ وَحُرُوفُ الْقَسَمِ ، وَهِيَ : الْوَاو،ُ وَالْبَاء،ُ وَالنَّاء.ُ</p>', 'arabic', 'rtl', 3, NULL, NULL, '2026-09-09 20:01:12', '2026-09-09 20:01:12', NULL, NULL, NULL, 0),
(3763, 463, 4, 'وَالْفِعْلُ يُعْرَفُ بِقَدْ ، والسين وَسَوْفَ وَاءِ التَّأْنيثِ السَّاكِنَة.ِ', '<p><strong>وَالْفِعْلُ</strong> يُعْرَفُ بِقَدْ ، والسين وَسَوْفَ وَاءِ التَّأْنيثِ السَّاكِنَة.ِ</p>', 'arabic', 'rtl', 4, NULL, NULL, '2026-09-09 20:01:12', '2026-09-09 20:01:12', NULL, NULL, NULL, 0),
(3764, 463, 5, 'وَالْخَرْفُ مَا لَا يَصْلُحُ مَعَهُ دَلِيلُ الْإِسْمِ وَلَا ذَلِيلُ الْفِعْلِ', '<p> <strong>وَالْخَرْفُ</strong> مَا لَا يَصْلُحُ مَعَهُ دَلِيلُ الْإِسْمِ وَلَا ذَلِيلُ الْفِعْلِ</p>', 'arabic', 'rtl', 5, NULL, NULL, '2026-09-09 20:01:12', '2026-09-09 20:01:12', NULL, NULL, NULL, 0),
(3770, 466, 1, 'باب الإعراب', '<p><strong>                    باب الإعراب</strong></p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-09 20:02:04', '2026-09-09 20:02:04', NULL, NULL, NULL, 0),
(3771, 466, 2, 'الإعْرَابُ هُوَ تَغيير أواخِرِ الكَلِمِ لاختلافِ العَوَامِلِ الدَّاخِلَةِ عَلَيْهَا لفظاً أوْ تَقْدِيراً', '<p><strong>الإعْرَابُ</strong> هُوَ تَغيير أواخِرِ الكَلِمِ لاختلافِ العَوَامِلِ الدَّاخِلَةِ عَلَيْهَا لفظاً أوْ تَقْدِيراً </p>', 'arabic', 'rtl', 2, NULL, NULL, '2026-09-09 20:02:04', '2026-09-09 20:02:04', NULL, NULL, NULL, 0),
(3772, 466, 3, 'وَأَقْسَامُهُ أَرْبَعَةُ : رَفْعُ ، وَنَصْبُ ، وَخَفْسٍ ، وَجَزْمٌ ،', '<p><strong>وَأَقْسَامُهُ أَرْبَعَةُ</strong> : رَفْعُ ، وَنَصْبُ ، وَخَفْسٍ ، وَجَزْمٌ ،</p>', 'arabic', 'rtl', 3, NULL, NULL, '2026-09-09 20:02:04', '2026-09-09 20:02:04', NULL, NULL, NULL, 0),
(3773, 466, 4, 'فَلِلْأَسْمَاءِ مِنْ ذَلِكَ الرَّفْعُ وَالنَّصْبُ وَالْخَفْضُ، وَلَا جَزْمَ فِيهَا.', '<p><strong>فَلِلْأَسْمَاءِ</strong> مِنْ ذَلِكَ الرَّفْعُ وَالنَّصْبُ وَالْخَفْضُ، وَلَا جَزْمَ فِيهَا.</p>', 'arabic', 'rtl', 4, NULL, NULL, '2026-09-09 20:02:04', '2026-09-09 20:02:04', NULL, NULL, NULL, 0),
(3774, 466, 5, 'وَلِافْعَالَ مِنْ ذَلِكَ الرَّفْعُ ، وَالنَّصْب،ُ وَالجَزْم،ُ وَلَا خَفْضَ فِيهَا', '<p><strong> وَلِافْعَالَ</strong> مِنْ ذَلِكَ الرَّفْعُ ، وَالنَّصْب،ُ وَالجَزْم،ُ وَلَا خَفْضَ فِيهَا</p>', 'arabic', 'rtl', 5, NULL, NULL, '2026-09-09 20:02:04', '2026-09-09 20:02:04', NULL, NULL, NULL, 0),
(3845, 456, 1, 'فَضْلُ اَلتَّوْحِيدِ', '<p>                                فَضْلُ اَلتَّوْحِيدِ</p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3846, 456, 2, 'Fadhila Za Tawhiyd', '<p>                          Fadhila Za Tawhiyd</p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3847, 456, 3, 'وَقَوْلُ اَللَّهِ تَعَالَى:', '<p>وَقَوْلُ اَللَّهِ تَعَالَى:</p>', 'arabic', 'rtl', 3, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3848, 456, 4, 'Na kauli Ya Allaah Ta’aalaa:', '<p>Na kauli Ya Allaah Ta’aalaa:</p>', 'swahili', 'ltr', 4, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3849, 456, 5, 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾', '<p><strong> وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿٥٦﴾</strong></p>', 'arabic', 'rtl', 5, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3850, 456, 6, '((Na Sikuumba majini na wana Aadam isipokuwa waniabudu)) [Adh-Dhaariyaat (51: 56)]', '<p><strong>((Na Sikuumba majini na wana Aadam isipokuwa waniabudu)) [Adh-Dhaariyaat (51: 56)]</strong></p>', 'swahili', 'ltr', 6, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3851, 456, 7, 'وَقَوْلُهُ تَعَالَى:', '<p>وَقَوْلُهُ تَعَالَى:</p>', 'arabic', 'rtl', 7, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3852, 456, 8, 'Na kauli Yake Ta’aalaa:', '<p>Na kauli Yake Ta’aalaa:</p>', 'swahili', 'ltr', 8, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3853, 456, 9, 'وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّـهَ وَاجْتَنِبُوا الطَّاغُوتَ ۖ', '<p><strong>وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّـهَ وَاجْتَنِبُوا الطَّاغُوتَ ۖ</strong></p>', 'arabic', 'rtl', 9, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3854, 456, 10, '((Na kwa yakini Tulituma katika kila ummah Rasuli (alinganie) kwamba: “Mwabuduni Allaah na jiepusheni na twaghuti)) [An-Nahl (16: 36).]', '<p><strong>((Na kwa yakini Tulituma katika kila ummah Rasuli (alinganie) kwamba: “Mwabuduni Allaah na jiepusheni na twaghuti)) [An-Nahl (16: 36).]</strong></p>', 'swahili', 'ltr', 10, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3855, 456, 11, 'وَقَوْلُهُ:', '<p> وَقَوْلُهُ:</p>', 'arabic', 'rtl', 11, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3856, 456, 12, 'Na kauli Yake:', '<p>Na kauli Yake:</p>', 'swahili', 'ltr', 12, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3857, 456, 13, 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا ۚ', '<p><strong>  وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا ۚ</strong></p>', 'arabic', 'rtl', 13, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3858, 456, 14, '((Na Rabb wako Amehukumu kwamba: “Msiabudu isipokuwa Yeye Pekee na (Ameamrisha) kuwafanyia ihsaan wazazi wawili)) [Al-Israa (17: 23)]', '<p><strong>((Na Rabb wako Amehukumu kwamba: “Msiabudu isipokuwa Yeye Pekee na (Ameamrisha) kuwafanyia ihsaan wazazi wawili)) [Al-Israa (17: 23)]</strong></p>', 'swahili', 'ltr', 14, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3859, 456, 15, 'وَقَوْلُهُ:', '<p>وَقَوْلُهُ:</p>', 'arabic', 'rtl', 15, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0);
INSERT INTO `part_sections` (`id`, `part_id`, `section_number`, `content`, `content_html`, `language`, `direction`, `sort_order`, `text_color`, `background_color`, `created_at`, `updated_at`, `video_path`, `video_url`, `video_caption`, `display_separate`) VALUES
(3860, 456, 16, 'Na kauli Yake:', '<p>Na kauli Yake:</p>', 'swahili', 'ltr', 16, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3861, 456, 17, 'وَاعْبُدُوا اللَّـهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا ۖ', '<p><strong> وَاعْبُدُوا اللَّـهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا ۖ  </strong></p>', 'arabic', 'rtl', 17, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3862, 456, 18, '((Na mwabuduni Allaah na wala msimshirikishe na chochote))  [An-Nisaa (4: 36)]', '<p><strong>((Na mwabuduni Allaah na wala msimshirikishe na chochote))  [An-Nisaa (4: 36)] </strong></p>', 'swahili', 'ltr', 18, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3863, 456, 19, 'وَقَوْلُهُ:', '<p>وَقَوْلُهُ:</p>', 'arabic', 'rtl', 19, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3864, 456, 20, 'Na kauli Yake:', '<p>Na kauli Yake:</p>', 'swahili', 'ltr', 20, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3865, 456, 21, 'قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا بِهِ شَيْئًا ۖ وَبِالْوَالِدَيْنِ إِحْسَانًا ۖ وَلَا تَقْتُلُوا أَوْلَادَكُم مِّنْ إِمْلَاقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّـهُ إِلَّا بِالْحَقِّ ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَعْقِلُونَ ﴿١٥١﴾', '<p><strong>قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا بِهِ شَيْئًا ۖ وَبِالْوَالِدَيْنِ إِحْسَانًا ۖ وَلَا تَقْتُلُوا أَوْلَادَكُم مِّنْ إِمْلَاقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّـهُ إِلَّا بِالْحَقِّ ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَعْقِلُونَ ﴿١٥١﴾</strong></p>', 'arabic', 'rtl', 21, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3866, 456, 22, '((Sema: “Njooni nikusomeeni yale Aliyoyaharamisha Rabb wenu kwenu. Kwamba msimshirikishe na chochote, na muwafanyie ihsaan wazazi wawili, na wala msiwaue auladi wenu kutokana na umasikini. Sisi Tunakuruzukuni pamoja nao. Na wala msikaribie machafu yaliyo dhahiri na yaliyofichika. Na wala msiue nafsi ambayo Ameiharamisha Allaah (kuiua) isipokuwa kwa haki (ya shariy’ah). Hivyo ndivyo Alivyokuusieni kwayo mpate kutia akilini”))', '<p><strong>((Sema: “Njooni nikusomeeni yale Aliyoyaharamisha Rabb wenu kwenu. Kwamba msimshirikishe na chochote, na muwafanyie ihsaan wazazi wawili, na wala msiwaue auladi wenu kutokana na umasikini. Sisi Tunakuruzukuni pamoja nao. Na wala msikaribie machafu yaliyo dhahiri na yaliyofichika. Na wala msiue nafsi ambayo Ameiharamisha Allaah (kuiua) isipokuwa kwa haki (ya shariy’ah). Hivyo ndivyo Alivyokuusieni kwayo mpate kutia akilini”))</strong></p>', 'swahili', 'ltr', 22, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3867, 456, 23, 'وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُ ۖ وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ اللَّـهِ أَوْفُوا ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَذَكَّرُونَ ﴿١٥٢﴾', '<p><strong>وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُ ۖ وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ اللَّـهِ أَوْفُوا ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَذَكَّرُونَ ﴿١٥٢﴾</strong></p>', 'arabic', 'rtl', 23, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3868, 456, 24, '((“Na wala msiikaribie mali ya yatima isipokuwa kwa njia ya ihsaan mpaka afikie umri wa kupevuka. Na timizeni kipimo na mizani kwa uadilifu. Hatukalifishi nafsi isipokuwa kadiri ya uwezo wake. Na mnaposema basi fanyeni uadilifu japokuwa ni jamaa wa karibu. Na timizeni ahadi ya Allaah. Hivyo ndivyo Alivyokuusieni (Allaah) kwayo mpate kukumbuka))', '<p><strong>((“Na wala msiikaribie mali ya yatima isipokuwa kwa njia ya ihsaan mpaka afikie umri wa kupevuka. Na timizeni kipimo na mizani kwa uadilifu. Hatukalifishi nafsi isipokuwa kadiri ya uwezo wake. Na mnaposema basi fanyeni uadilifu japokuwa ni jamaa wa karibu. Na timizeni ahadi ya Allaah. Hivyo ndivyo Alivyokuusieni (Allaah) kwayo mpate kukumbuka))</strong></p>', 'swahili', 'ltr', 24, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3869, 456, 25, 'وَأَنَّ هَـٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَتَّقُونَ ﴿١٥٣﴾', '<p><strong> وَأَنَّ هَـٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ ۚ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَتَّقُونَ ﴿١٥٣﴾</strong></p>', 'arabic', 'rtl', 25, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3870, 456, 26, '((“Na kwamba hii njia Yangu iliyonyooka, basi ifuateni. Na wala msifuate njia nyinginezo zitakufarikisheni na njia Yake. Hivyo ndivyo Alivyokuusieni (Allaah) kwayo mpate kuwa na taqwa”)) [Al-An-‘aam (6: 151-153)]', '<p><strong>((“Na kwamba hii njia Yangu iliyonyooka, basi ifuateni. Na wala msifuate njia nyinginezo zitakufarikisheni na njia Yake. Hivyo ndivyo Alivyokuusieni (Allaah) kwayo mpate kuwa na taqwa”)) [Al-An-‘aam (6: 151-153)]</strong></p>', 'swahili', 'ltr', 26, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3871, 456, 27, 'قَالَ اِبْنُ مَسْعُود (رضي الله عنه): مَنْ أَرَادَ أَنْ يَنْظُرَ إِلَى وَصِيَّةِ مُحَمَّدٍ (صَلَّى اَللَّهُ عَلَيْهِ وَسَلَّمَ) اَلَّتِي عَلَيْهَا خَاتَمُهُ فَلْيَقْرَأْ قَوْلَهُ تَعَالَى:', '<p>قَالَ اِبْنُ مَسْعُود (رضي الله عنه): مَنْ أَرَادَ أَنْ يَنْظُرَ إِلَى وَصِيَّةِ مُحَمَّدٍ (صَلَّى اَللَّهُ عَلَيْهِ وَسَلَّمَ) اَلَّتِي عَلَيْهَا خَاتَمُهُ فَلْيَقْرَأْ قَوْلَهُ تَعَالَى:</p>', 'arabic', 'rtl', 27, '#1254af', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3872, 456, 28, '((قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا بِهِ شَيْئًا ۖ ))', '<p><strong>((قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا بِهِ شَيْئًا ۖ ))</strong></p>', 'arabic', 'rtl', 28, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3873, 456, 29, 'إِلَى قَوْلِهِ', '<p>إِلَى قَوْلِهِ</p>', 'arabic', 'rtl', 29, '#0b3d84', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3874, 456, 30, '((وَأَنَّ هَـٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ ۚ...)) الآيَةَ.', '<p>((وَأَنَّ هَـٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ ۚ...)) الآيَةَ.</p>', 'arabic', 'rtl', 30, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3875, 456, 31, 'Amesema Ibn Mas’uwd (رضي الله عنه): “Anayetaka kuangalia wasiya wa Muhammad (صلى الله عليه وآله وسلم) ambao ulikuwa na muhuri wake, basi asome kauli za Allaah: ((Sema: “Njooni nikusomeeni yale Aliyoyaharamisha Rabb wenu kwenu. Kwamba msimshirikishe na chochote…)) hadi kauli Yake: ((Na kwamba hii njia Yangu iliyonyooka, basi ifuateni. Na wala msifuate njia nyinginezo zitakufarikisheni na njia Yake. … ))  mpaka mwisho wa Aayah [At-Tirmidhiy (3080) At-Twabaraaniy katika Mu’jam Al-Awsatw (1208) na amesema At-Tirmidhiy : Hii ni Hadiyth Hasan Ghariyb]', '<p>Amesema Ibn Mas’uwd (رضي الله عنه): “Anayetaka kuangalia wasiya wa Muhammad (صلى الله عليه وآله وسلم) ambao ulikuwa na muhuri wake, basi asome kauli za Allaah<strong>: ((Sema: “Njooni nikusomeeni yale Aliyoyaharamisha Rabb wenu kwenu. Kwamba msimshirikishe na chochote…)) </strong>hadi kauli Yake<strong>: ((Na kwamba hii njia Yangu iliyonyooka, basi ifuateni. Na wala msifuate njia nyinginezo zitakufarikisheni na njia Yake. … ))  mpaka mwisho wa Aayah [At-Tirmidhiy (3080) At-Twabaraaniy katika Mu’jam Al-Awsatw (1208) na amesema At-Tirmidhiy : Hii ni Hadiyth Hasan Ghariyb]</strong></p>', 'swahili', 'ltr', 31, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3876, 456, 32, 'عَنْ مُعَاذِ بْنِ جَبَلٍ (رَضِيَ اَللَّهُ عَنْهُ) قَالَ: كُنْتُ رَدِيفَ اَلنَّبِيِّ (صَلَّى اَللَّهُ عَلَيْهِ وَسَلَّمَ) عَلَى حِمَارٍ فَقَالَ لِي: ((يَا مُعَاذُ؟ أَتَدْرِي مَا حَقُّ اَللَّهِ عَلَى الْعِبَادِ، وَمَا حَقُّ الْعِبَادِ عَلَى اَللَّهِ؟)) قُلْتُ اَللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ((حَقُّ اَللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ، وَلاَ يُشْرِكُوا بِهِ شَيْئًا، وَحَقُّ الْعِبَادِ عَلَى اَللَّهِ أَنْ لاَ يُعَذِّبَ مَنْ لاَ يُشْرِكُ بِهِ شَيْئًا)) قُلْتُ يَا رَسُولَ اَللَّهِ أَفَلاَ أُبَشِّرُ اَلنَّاسَ؟ قَالَ: ((لاَ تُبَشِّرْهُمْ فَيَتَّكِلُوا)) أَخْرَجَاهُ فِي اَلصَّحِيحَيْنِ', '<p><strong>عَنْ مُعَاذِ بْنِ جَبَلٍ (رَضِيَ اَللَّهُ عَنْهُ) قَالَ: كُنْتُ رَدِيفَ اَلنَّبِيِّ (صَلَّى اَللَّهُ عَلَيْهِ وَسَلَّمَ) عَلَى حِمَارٍ فَقَالَ لِي: ((يَا مُعَاذُ؟ أَتَدْرِي مَا حَقُّ اَللَّهِ عَلَى الْعِبَادِ، وَمَا حَقُّ الْعِبَادِ عَلَى اَللَّهِ؟)) قُلْتُ اَللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: ((حَقُّ اَللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ، وَلاَ يُشْرِكُوا بِهِ شَيْئًا، وَحَقُّ الْعِبَادِ عَلَى اَللَّهِ أَنْ لاَ يُعَذِّبَ مَنْ لاَ يُشْرِكُ بِهِ شَيْئًا)) قُلْتُ يَا رَسُولَ اَللَّهِ أَفَلاَ أُبَشِّرُ اَلنَّاسَ؟ قَالَ: ((لاَ تُبَشِّرْهُمْ فَيَتَّكِلُوا)) </strong>أَخْرَجَاهُ فِي اَلصَّحِيحَيْنِ</p>', 'arabic', 'rtl', 32, '#1056b7', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3877, 456, 33, 'Imepokelewa kutoka kwa Mu’aadh bin Jabal (رضي الله عنه) amesema: Nilikuwa nyuma ya Nabiy (صلى الله عليه وآله وسلم) juu ya punda akasema: ((Ee Mu’aadh! Unajua nini haki ya Allaah juu ya waja Wake, na nini haki ya waja juu ya Allaah?)) Nikajibu: Allaah na Rasuli Wake wanajua zaidi: Akasema: ((Haki ya Allaah kwa waja wake ni kwamba wamwabudu na wasimshirikishe na chochote. Na haki ya waja kwa Allaah ni kwamba Hatomwadhibu yeyote ambaye hamshirikishi na chochote)). Nikasema: Ee Rasuli wa Allaah! Niwabashirie watu? Akasema: ((Usiwabashirie wasije kuitegemea)) [wakaacha kufanya juhudi katika ‘ibaadah])) [Al-Bukhaariy na Muslim]', '<p><strong>Imepokelewa kutoka kwa Mu’aadh bin Jabal (رضي الله عنه) amesema: Nilikuwa nyuma ya Nabiy (صلى الله عليه وآله وسلم) juu ya punda akasema: ((Ee Mu’aadh! Unajua nini haki ya Allaah juu ya waja Wake, na nini haki ya waja juu ya Allaah?)) Nikajibu: Allaah na Rasuli Wake wanajua zaidi: Akasema: ((Haki ya Allaah kwa waja wake ni kwamba wamwabudu na wasimshirikishe na chochote. Na haki ya waja kwa Allaah ni kwamba Hatomwadhibu yeyote ambaye hamshirikishi na chochote)). Nikasema: Ee Rasuli wa Allaah! Niwabashirie watu? Akasema: ((Usiwabashirie wasije kuitegemea)) </strong>[wakaacha kufanya juhudi katika ‘ibaadah])) [Al-Bukhaariy na Muslim]</p>', 'swahili', 'ltr', 33, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3878, 457, 1, '1-Hekima ya kuumbwa majini na wana Aadam.', '<p>1-Hekima ya kuumbwa majini na wana Aadam.<br> </p>', 'swahili', 'ltr', 1, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3879, 457, 2, '2-Al-‘Ibaadah inamaanisha (hususani) Tawhiyd kwani ndio mada kuu ya hoja (hapo juu) na kinyume chake ni shirki ambayo humbaidisha mtu na Allaah (سبحانه وتعالى) na ndio jambo walotatizana Rusu3-Asiyetekeleza masharti ya Tawhiyd, atakuwa hajamwabudu Allaah (سبحانه وتعالى) ipasavyo kwa sababu katika Tawhiyd tu ndio huthibitika maana ya kauli Yake Allaah (سبحانه وتعالى):li na washirikina.', '<p>2-Al-‘Ibaadah inamaanisha (hususani) Tawhiyd kwani ndio mada kuu ya hoja (hapo juu) na kinyume chake ni shirki ambayo humbaidisha mtu na Allaah (سبحانه وتعالى) na ndio jambo walotatizana Rusu3-Asiyetekeleza masharti ya Tawhiyd, atakuwa hajamwabudu Allaah (سبحانه وتعالى) ipasavyo kwa sababu katika Tawhiyd tu ndio huthibitika maana ya kauli Yake Allaah (سبحانه وتعالى):li na washirikina.</p><p> </p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3880, 457, 3, '3-Asiyetekeleza masharti ya Tawhiyd, atakuwa hajamwabudu Allaah (سبحانه وتعالى) ipasavyo kwa sababu katika Tawhiyd tu ndio huthibitika maana ya kauli Yake Allaah (سبحانه وتعالى):', '<p>3-Asiyetekeleza masharti ya Tawhiyd, atakuwa hajamwabudu Allaah (سبحانه وتعالى) ipasavyo kwa sababu katika Tawhiyd tu ndio huthibitika maana ya kauli Yake Allaah (سبحانه وتعالى):</p><p> </p>', 'swahili', 'ltr', 3, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3881, 457, 4, 'وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾', '<p><strong>وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾</strong></p>', 'arabic', 'rtl', 4, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3882, 457, 5, '((“Na wala nyinyi si wenye kuabudu Yule Ninayemwabudu)) [Al-Kaafiruwn (109: 3)]', '<p><strong>((“Na wala nyinyi si wenye kuabudu Yule Ninayemwabudu)) [Al-Kaafiruwn (109: 3)]</strong></p>', 'swahili', 'ltr', 5, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3883, 457, 6, '4-Hekima ya kutumwa Mtume', '<p>4-Hekima ya kutumwa Mtume</p>', 'swahili', 'ltr', 6, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3884, 457, 7, '5-Ujumbe huo (wa Tawhiyd) umefikishwa kwa kila ummah.', '<p>5-Ujumbe huo (wa Tawhiyd) umefikishwa kwa kila ummah.</p><p> </p>', 'swahili', 'ltr', 7, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3885, 457, 8, '6-Dini ya Mitume ni moja (haitofautiani).', '<p>6-Dini ya Mitume ni moja (haitofautiani).</p><p> </p>', 'swahili', 'ltr', 8, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3886, 457, 9, '7-Suala lenye umuhimu mkubwa hapa ni kwamba, kumwabudu Allaah hakutambuliki pasina kukanusha twaghuti. Hapo ndipo kwenye maana ya kauli Yake Allaah (سبحانه وتعالى):', '<p>7-Suala lenye umuhimu mkubwa hapa ni kwamba, kumwabudu Allaah hakutambuliki pasina kukanusha twaghuti. Hapo ndipo kwenye maana ya kauli Yake Allaah (سبحانه وتعالى):</p><p> </p>', 'swahili', 'ltr', 9, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3887, 457, 10, 'فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّـهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ', '<p><strong>فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّـهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ</strong></p>', 'arabic', 'rtl', 10, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3888, 457, 11, '((Basi atakayemkanusha twaghuti na akamwamini Allaah kwa hakika atakuwa ameshikilia imara kishikilio madhubuti kisichovunjika)) [Al-Baqarah (2: 256)]', '<p><strong>((Basi atakayemkanusha twaghuti na akamwamini Allaah kwa hakika atakuwa ameshikilia imara kishikilio madhubuti kisichovunjika)) [Al-Baqarah (2: 256)]</strong></p><p> </p>', 'swahili', 'ltr', 11, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3889, 457, 12, '8-Neno ‘twaghuti’ humaanisha kwa ujumla kila kitu kinachoabudiwa asiyekuwa Allaah (سبحانه وتعالى), (na kinachovuka mipaka katika ‘ibaadah).', '<p>8-Neno ‘twaghuti’ humaanisha kwa ujumla kila kitu kinachoabudiwa asiyekuwa Allaah (سبحانه وتعالى), (na kinachovuka mipaka katika ‘ibaadah).</p><p> </p>', 'swahili', 'ltr', 12, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3890, 457, 13, '9-Salaf walitambua umuhimu mkubwa wa Aayah tatu katika Suwrat Al-An’aam kwamba ni Muhkamaat. Aayah hizi zimejumuisha mambo kumi na la awali ni kukatazwa shirki.', '<p>9-Salaf walitambua umuhimu mkubwa wa Aayah tatu katika Suwrat Al-An’aam kwamba ni Muhkamaat. Aayah hizi zimejumuisha mambo kumi na la awali ni kukatazwa shirki.</p><p> </p>', 'swahili', 'ltr', 13, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3891, 457, 14, '10-Aayah za Muhkamaat katika Suwrat Al-Israa ambazo ni kuanzia Aayah 22 hadi 39, zina mambo kumi na nane, na Allaah (سبحانه وتعالى) Anaanza kwa kauli Yake:', '<p>10-Aayah za Muhkamaat katika Suwrat Al-Israa ambazo ni kuanzia Aayah 22 hadi 39, zina mambo kumi na nane, na Allaah (سبحانه وتعالى) Anaanza kwa kauli Yake:</p><p> </p>', 'swahili', 'ltr', 14, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3892, 457, 15, 'لَّا تَجْعَلْ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا ﴿٢٢﴾', '<p><strong>لَّا تَجْعَلْ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا ﴿٢٢﴾</strong></p>', 'arabic', 'rtl', 15, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3893, 457, 16, '((Usifanye pamoja na Allaah muabudiwa mwengine, ukaja kushutumiwa na mwenye kutelekezwa mbali (motoni)) [Al-Israa (17: 22)]', '<p><strong>((Usifanye pamoja na Allaah muabudiwa mwengine, ukaja kushutumiwa na mwenye kutelekezwa mbali (motoni)) [Al-Israa (17: 22)]</strong></p>', 'swahili', 'ltr', 16, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3894, 457, 17, 'Na Anayahitimisha kwa kusema:', '<p>Na Anayahitimisha kwa kusema:</p>', 'swahili', 'ltr', 17, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3895, 457, 18, 'وَلَا تَجْعَلْ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ فَتُلْقَىٰ فِي جَهَنَّمَ مَلُومًا مَّدْحُورًا ﴿٣٩﴾', '<p><strong>وَلَا تَجْعَلْ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ فَتُلْقَىٰ فِي جَهَنَّمَ مَلُومًا مَّدْحُورًا ﴿٣٩﴾</strong></p>', 'swahili', 'ltr', 18, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3896, 457, 19, '((Na wala usifanye pamoja na Allaah muabudiwa mwengine ukaja kutupwa katika Jahannam hali ya kuwa mwenye kulaumiwa na kuwa mardudi (na rahmah ya Allaah)) [Al-Israa (17: 39)] Na Allaah Ametubainishia umuhimu wake kwa kauli Yake:', '<p><strong>((Na wala usifanye pamoja na Allaah muabudiwa mwengine ukaja kutupwa katika Jahannam hali ya kuwa mwenye kulaumiwa na kuwa mardudi (na rahmah ya Allaah)) [Al-Israa (17: 39)]</strong><br><strong> </strong>Na Allaah Ametubainishia umuhimu wake kwa kauli Yake:</p>', 'swahili', 'ltr', 19, NULL, NULL, '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
(3897, 457, 20, 'ذَٰلِكَ مِمَّا أَوْحَىٰ إِلَيْكَ رَبُّكَ مِنَ الْحِكْمَةِ ۗ', '<p><strong>ذَٰلِكَ مِمَّا أَوْحَىٰ إِلَيْكَ رَبُّكَ مِنَ الْحِكْمَةِ ۗ</strong></p>', 'arabic', 'rtl', 20, '#b99137', '#ffffff', '2026-09-11 05:10:45', '2026-09-11 05:10:45', NULL, NULL, NULL, 0),
