(3987, 441, 9, '“Akukose mama yako”: Ni Neno linalotamkwa na Waarabu katika hali ya kukemea bila ya kukusudiwa maana yake.', '<p><strong>“Akukose mama yako”: Ni Neno linalotamkwa na Waarabu katika hali ya kukemea bila ya kukusudiwa maana yake.</strong></p>', 'swahili', 'ltr', 9, NULL, NULL, '2026-09-16 20:47:17', '2026-09-16 20:47:17', NULL, NULL, NULL, 0),
(3988, 442, 1, 'عَنْ أَبيِ ثَعْلَبَةَ الخُشَنِيِّ جُرْثُومِ بْن نَاشرٍ رضي الله عنه عَنْ رَسُولِ اللهِ صلى الله عليه وسلم قَالَ: ((إنّ اللهَ تَعَالى فَرَضَ فَرَائِضَ فَلاَ تُضَيّعوهاَ وَحَدَّ حُدُودَاً فَلاتَعْتَدُوهَا وَحَرّمَ أَشْياءَ فَلاَتَنْتَهِكُوهَا وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيانٍ فَلا تَبْحَثُوا عَنْهَا)) حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيّ وَغَيْرُهُ', '<p>عَنْ أَبيِ ثَعْلَبَةَ الخُشَنِيِّ جُرْثُومِ بْن نَاشرٍ رضي الله عنه عَنْ رَسُولِ اللهِ صلى الله عليه وسلم قَالَ: ((إنّ اللهَ تَعَالى فَرَضَ فَرَائِضَ فَلاَ تُضَيّعوهاَ وَحَدَّ حُدُودَاً فَلاتَعْتَدُوهَا وَحَرّمَ أَشْياءَ فَلاَتَنْتَهِكُوهَا وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيانٍ فَلا تَبْحَثُوا عَنْهَا)) حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيّ وَغَيْرُهُ</p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-16 20:47:34', '2026-09-16 20:47:34', NULL, NULL, NULL, 0),
(3989, 442, 2, 'Imepokelewa kutoka kwa Abuu Tha\'alabah Al-Khushaniyy Jurthuwm bin Naashir (Radhwiya Allaahu \'anhu) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: ”Hakika Allaah Amefaridhisha faraaidhw (Mambo ya kuwajibika katika Dini) hivyo msiyapoteze. Na Akaweka mipaka basi msiivuke. Na Ameharamisha mambo kwa hivyo msiyahalifu. Na Amenyamazia mambo kutokana na rahmah (Yake) kwenu wala hakusahau kwa hivyo msiyadadisi.”  [Hadiyth Hasan Ad-Daaraqutwniy na wengineo]', '<p><strong>Imepokelewa kutoka kwa Abuu Tha\'alabah Al-Khushaniyy Jurthuwm bin Naashir (Radhwiya Allaahu \'anhu) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: ”Hakika Allaah Amefaridhisha faraaidhw (Mambo ya kuwajibika katika Dini) hivyo msiyapoteze. Na Akaweka mipaka basi msiivuke. Na Ameharamisha mambo kwa hivyo msiyahalifu. Na Amenyamazia mambo kutokana na rahmah (Yake) kwenu wala hakusahau kwa hivyo msiyadadisi.”  </strong>[Hadiyth Hasan Ad-Daaraqutwniy na wengineo]</p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-16 20:47:34', '2026-09-16 20:47:34', NULL, NULL, NULL, 0),
(3990, 443, 1, 'عَنْ أَبِي العَبّاسِ سَهلِ بْن سَعْدٍ السّاعِدِيِّ رضي الله عنه  قَالَ : جَاءَ رَجُلُ إِلى النَبِي صلى الله عليه وسلم  فَقَالَ : يَا رَسُولَ اللَّهِ دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ أَحَبَّنِي اللَّهُ وَأَحَبَّنِي النَّاسُ . فَقَالَ: (( ازْهَدْ فِي الدُّنْيَا يُحِبُّكَ اللَّهُ وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبُّكَ النّاسُ)) رَوَاهُ ابْنُ مَاجَهْ  وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ.', '<p><strong>عَنْ أَبِي العَبّاسِ سَهلِ بْن سَعْدٍ السّاعِدِيِّ رضي الله عنه  قَالَ : جَاءَ رَجُلُ إِلى النَبِي صلى الله عليه وسلم  فَقَالَ : يَا رَسُولَ اللَّهِ دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ أَحَبَّنِي اللَّهُ وَأَحَبَّنِي النَّاسُ . فَقَالَ: (( ازْهَدْ فِي الدُّنْيَا يُحِبُّكَ اللَّهُ وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبُّكَ النّاسُ)) </strong>رَوَاهُ ابْنُ مَاجَهْ  وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ.</p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-16 20:47:47', '2026-09-16 20:47:47', NULL, NULL, NULL, 0),
(3991, 443, 2, 'Imepokelewa kutoka kwa Sahl bin Sa\'ad As-Saa’idiyy (Radhwiya Allaahu \'anhu) kwamba: “Alikuja mtu kwa Nabiy (Swalla Allaahu \'alayhi wa aalihi wa sallam) akasema: Ee Rasuli wa Allaah! Nijulishe ‘amali ambayo nikiifanya Allaah Atanipenda na watu pia watanipenda.  Akasema: “Ipe mgongo dunia Allaah Atakupenda, na vipe mgongo vilivyomo kwa watu, watu watakupenda.” [Ibn Maajah na wengineo kwa mtiririko mzuri wa isnaad]*', '<p><strong>Imepokelewa kutoka kwa Sahl bin Sa\'ad As-Saa’idiyy (Radhwiya Allaahu \'anhu) kwamba: “Alikuja mtu kwa Nabiy (Swalla Allaahu \'alayhi wa aalihi wa sallam) akasema: Ee Rasuli wa Allaah! Nijulishe ‘amali ambayo nikiifanya Allaah Atanipenda na watu pia watanipenda.  Akasema: “Ipe mgongo dunia Allaah Atakupenda, na vipe mgongo vilivyomo kwa watu, watu watakupenda.”</strong> [Ibn Maajah na wengineo kwa mtiririko mzuri wa isnaad]*</p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-16 20:47:47', '2026-09-16 20:47:47', NULL, NULL, NULL, 0),
(3992, 443, 3, '*Hata hivyo Wanavyuoni wa Hadiyth wameeleza kuwa Hadiyth hii ni dhaifu kutokana na udhaifu wa sanad yake japo An-Nawawiy kaitumia na kasema ina sanad nzuri.', '<p><strong>*Hata hivyo Wanavyuoni wa Hadiyth wameeleza kuwa Hadiyth hii ni dhaifu kutokana na udhaifu wa sanad yake japo An-Nawawiy kaitumia na kasema ina sanad nzuri.</strong></p>', 'swahili', 'ltr', 3, NULL, NULL, '2026-09-16 20:47:47', '2026-09-16 20:47:47', NULL, NULL, NULL, 0),
(3993, 444, 1, 'عنْ أَبىِ سَعيدٍ سَعْدِ بْن مَالكِ بْن سِنَانٍ الْخُدريِّ رضي الله عنه  أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم  قَالَ :(( لاَ ضَرَرَ وَلاَ ضِرَارَ)) حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ وَالدَّارَقُطْنِيّ، وَغَيْرُهُمَا مُسْنَدًا. وَرَوَاهُ مَالِكٌ فِي  الْمُوَطَّإِ مُرْسَلاً عَنْ عَمْرِو بْنِ يَحْيَى عَنْ أَبِيهِ عَنْ النَّبِيِّ صلى الله عليه وسلم  مُرْسَلًا، فَأَسْقَطَ أَبَا سَعِيدٍ، وَلَهُ طُرُقٌ يُقَوِّي بَعْضُهَا بَعْضًا.', '<p><strong>عنْ أَبىِ سَعيدٍ سَعْدِ بْن مَالكِ بْن سِنَانٍ الْخُدريِّ رضي الله عنه  أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم  قَالَ :(( لاَ ضَرَرَ وَلاَ ضِرَارَ)) حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ وَالدَّارَقُطْنِيّ، وَغَيْرُهُمَا مُسْنَدًا. وَرَوَاهُ مَالِكٌ فِي  الْمُوَطَّإِ مُرْسَلاً عَنْ عَمْرِو بْنِ يَحْيَى عَنْ أَبِيهِ عَنْ النَّبِيِّ صلى الله عليه وسلم  مُرْسَلًا، فَأَسْقَطَ أَبَا سَعِيدٍ، وَلَهُ طُرُقٌ يُقَوِّي بَعْضُهَا بَعْضًا. </strong></p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-16 20:48:00', '2026-09-16 20:48:00', NULL, NULL, NULL, 0),
(3994, 444, 2, 'Imepokelewa kutoka kwa Abuu Sa’iyd Sa’d bin Maalik bin Sinaan Alkhudriyy (Radhwiya Allaahu \'anhu) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: “Kusiwe na kudhuriana wala kulipizana madhara.” [Imesimuliwa na Ibn Maajah, Ad-Daaraqutwniy na wengineo na ina kiwango cha \'Musnad\'. Vile vile imesimuliwa na Maalik katika Al-Muwatwaa kama \'Mursal\'. Inayo mtiririko wa mapokezi kutoka kwa \'Amr bin Yahyaa, kutoka kwa baba yake, kutoka kwa Nabiy (Swalla Allaahu \'alayhi wa aalihi wa sallam) hata ukimuacha Abuu Sa\'iyd bado inayo mtiririko wa mapokezi unayoiunga mkono.]', '<p>Imepokelewa kutoka kwa Abuu Sa’iyd Sa’d bin Maalik bin Sinaan Alkhudriyy (Radhwiya Allaahu \'anhu) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: “Kusiwe na kudhuriana wala kulipizana madhara.” <strong>[Imesimuliwa na Ibn Maajah, Ad-Daaraqutwniy na wengineo na ina kiwango cha \'Musnad\'. Vile vile imesimuliwa na Maalik katika Al-Muwatwaa kama \'Mursal\'. Inayo mtiririko wa mapokezi kutoka kwa \'Amr bin Yahyaa, kutoka kwa baba yake, kutoka kwa Nabiy (Swalla Allaahu \'alayhi wa aalihi wa sallam) hata ukimuacha Abuu Sa\'iyd bado inayo mtiririko wa mapokezi unayoiunga mkono.]</strong></p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-16 20:48:00', '2026-09-16 20:48:00', NULL, NULL, NULL, 0),
(3995, 445, 1, 'عن ابن عَبَّاسٍ رضي اللُه عنهما: أن رسولَ الله صلى الله عليه وسلم قال: ((لَو يُعْطَى النَّاسُ بِدَعْوَاهُمْ لادَّعَى رِجَالٌ أموالَ قَوْمٍ ودِماءَهُمْ لَكِنِ البَيِّنَةُ على المُدَّعِى والْيَمينُ على من أَنْكَرَ))  حَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيّ وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي  الصَّحِيحَيْنِ', '<p><strong>عن ابن عَبَّاسٍ رضي اللُه عنهما: أن رسولَ الله صلى الله عليه وسلم قال: ((لَو يُعْطَى النَّاسُ بِدَعْوَاهُمْ لادَّعَى رِجَالٌ أموالَ قَوْمٍ ودِماءَهُمْ لَكِنِ البَيِّنَةُ على المُدَّعِى والْيَمينُ على من أَنْكَرَ))  </strong>حَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيّ وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي  الصَّحِيحَيْنِ</p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-16 20:48:15', '2026-09-16 20:48:15', NULL, NULL, NULL, 0),
(3996, 445, 2, 'Imepokelewa kutoka kwa Ibn ‘Abbaas (Radhwiya Allaahu ‘anhumaa) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: “Kama watu wangelipewa kwa mujibu  wa madai yao, watu wangelidai mali na damu za wenzao (uhai) lakini jukumu la ushahidi liko kwa yule anayedai na kula kiapo kunawajibika kwa yule anayekanusha (kuwa hakutenda)”  [Al-Bayhaqiy na wengineo. Ni Hadiyth Hasan na baadhi yake imo katika Asw-Swahiyhayni]', '<p><strong>Imepokelewa kutoka kwa Ibn ‘Abbaas (Radhwiya Allaahu ‘anhumaa) kwamba Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) amesema: “Kama watu wangelipewa kwa mujibu  wa madai yao, watu wangelidai mali na damu za wenzao (uhai) lakini jukumu la ushahidi liko kwa yule anayedai na kula kiapo kunawajibika kwa yule anayekanusha (kuwa hakutenda)” </strong> [Al-Bayhaqiy na wengineo. Ni Hadiyth Hasan na baadhi yake imo katika Asw-Swahiyhayni]</p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-16 20:48:15', '2026-09-16 20:48:15', NULL, NULL, NULL, 0),
(3997, 446, 1, 'عن أبي سعيدٍ الْخُدْرِيِّ رضي الله عنه قال: سمعتُ رسولَ الله صلى الله عليه وسلم يقوُل: ((مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ، فَإنْ لمَ يَسْتَطِعْ فَبلِسانِهِ، فَإنْ لَمْ يَسْتَطِعْ فَبقَلْبِهِ، وَذَلِكَ أضْعَفُ اْلإِيمَانِ)) رَوَاهُ مُسْلِمٌ', '<p><strong>عن أبي سعيدٍ الْخُدْرِيِّ رضي الله عنه قال: سمعتُ رسولَ الله صلى الله عليه وسلم يقوُل: ((مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ، فَإنْ لمَ يَسْتَطِعْ فَبلِسانِهِ، فَإنْ لَمْ يَسْتَطِعْ فَبقَلْبِهِ، وَذَلِكَ أضْعَفُ اْلإِيمَانِ))</strong> رَوَاهُ مُسْلِمٌ <strong> </strong></p>', 'arabic', 'rtl', 1, NULL, NULL, '2026-09-16 20:48:34', '2026-09-16 20:48:34', NULL, NULL, NULL, 0),
(3998, 446, 2, 'Imepokelewa kutoka kwa Abuu Sa’iyd Al-Khudriyy (Radhwiya Allaahu \'anhu) kwamba amemsikia Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) akisema: “Atakayeona munkari basi aondoshe kwa mkono wake, ikiwa hawezi basi kwa ulimi wake (akataze), na ikiwa hawezi basi kwa moyo wake (achukie) na huo (yaani kutokukataza) ni udhaifu wa iymaan.”  [Muslim]', '<p><strong>Imepokelewa kutoka kwa Abuu Sa’iyd Al-Khudriyy (Radhwiya Allaahu \'anhu) kwamba amemsikia Rasuli wa Allaah (Swalla Allaahu \'alayhi wa aalihi wa sallam) akisema: “Atakayeona munkari basi aondoshe kwa mkono wake, ikiwa hawezi basi kwa ulimi wake (akataze), na ikiwa hawezi basi kwa moyo wake (achukie) na huo (yaani kutokukataza) ni udhaifu wa iymaan.”</strong>  [Muslim]</p>', 'swahili', 'ltr', 2, NULL, NULL, '2026-09-16 20:48:34', '2026-09-16 20:48:34', NULL, NULL, NULL, 0);
