--
-- Table structure for table `quiz_questions`
--

CREATE TABLE `quiz_questions` (
  `id` int NOT NULL,
  `quiz_id` int NOT NULL,
  `monthly_exam_id` int DEFAULT NULL,
  `question_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_type` enum('multiple_choice','true_false','explanation') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'multiple_choice',
  `points` int NOT NULL DEFAULT '1',
  `negative_points` int NOT NULL DEFAULT '0',
  `difficulty` enum('easy','medium','hard') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `expected_answer` text COLLATE utf8mb4_unicode_ci COMMENT 'Model answer for explanation questions',
  `keywords_json` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of keywords with optional weights'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

